INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回到原处。", "primary_collocate": null, "pronunciation": "fǎn huí", "ipa": "fan˨˩˦ xweɪ˧˥", "syllable_count": 2, "sentences": [{"text": "飞机因为天气,返回了机场。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点这个键,就能返回上一页。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小船出海后,又返回原来的码头。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞船完成任务后,返回了地球。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看完地图,请返回首页。", "target_word": "返回", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "按错了,你可以返回原来的页面。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公交车到了终点,又返回起点。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关闭窗口前，要先返回桌面。", "target_word": "返回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼游向大海,几年后又返回河里。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "程序出错时,会自动返回开始的画面。", "target_word": "返回", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "返回了", "label": "完成体"}, {"form": "返回过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "返回:交通工具、页面、程序等回到原处或起点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c4d128-43e8-4390-b92a-c10afdd8f3f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "返回", "is_correct": true, "explanation": "正确答案。返回，fǎnhuí，意思是回到原处，多指交通工具、页面等回到原处或起点。"}, {"text": "反悔", "is_correct": false, "explanation": "huǐ（第三声）与 huí（第二声）声调不同，意思是后悔、反悔。"}, {"text": "反馈", "is_correct": false, "explanation": "kuì 与 huí 声母不同（k 与 h），意思是把信息反映回去。"}, {"text": "反胃", "is_correct": false, "explanation": "wèi 与 huí 声母、韵母和声调都不同，意思是恶心、想吐。"}], "explanations": {"返回": "正确答案。返回，fǎnhuí，意思是回到原处，多指交通工具、页面等回到原处或起点。", "反悔": "huǐ（第三声）与 huí（第二声）声调不同，意思是后悔、反悔。", "反馈": "kuì 与 huí 声母不同（k 与 h），意思是把信息反映回去。", "反胃": "wèi 与 huí 声母、韵母和声调都不同，意思是恶心、想吐。"}, "sentence_index": null, "correct_answer": "返回"}, "level_3": {"options": [{"text": "起飞", "is_correct": false, "explanation": "配价：“起飞”是不及物动词，后面不能直接带“机场”作宾语，要说“从机场起飞”。"}, {"text": "装载", "is_correct": false, "explanation": "语义：“装载”的对象是货物，机场不能被装载，句意不通。"}, {"text": "返回", "is_correct": true, "explanation": "正确答案。“飞机因为天气，返回了机场”表示飞机因天气原因回到机场。"}, {"text": "滑行", "is_correct": false, "explanation": "语义：“滑行”是沿地面移动，不能表示飞机因天气而回到机场。"}], "explanations": {"起飞": "配价：“起飞”是不及物动词，后面不能直接带“机场”作宾语，要说“从机场起飞”。", "装载": "语义：“装载”的对象是货物，机场不能被装载，句意不通。", "返回": "正确答案。“飞机因为天气，返回了机场”表示飞机因天气原因回到机场。", "滑行": "语义：“滑行”是沿地面移动，不能表示飞机因天气而回到机场。"}, "sentence_index": 0, "correct_answer": "返回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快返回了十个俯卧撑。", "explanation": "这里应该用〈做〉。返回指回到原处，做俯卧撑要用“做”。"}, {"text": "他终于返回了这首诗。", "explanation": "这里应该用〈写出〉。返回指回到原处，诗是创作出来的，不能说返回这首诗。"}, {"text": "这部电影返回三个小时。", "explanation": "这里应该用〈长达〉。返回不表示时长，电影的时长要用“长达”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "漂流", "is_correct": false, "explanation": "语义：“漂流”指随水流漂动，与公交车的行驶路线无关。"}, {"text": "行驶", "is_correct": false, "explanation": "配价：“行驶”是不及物动词，后面不能直接带“起点”作宾语，要说“行驶到起点”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复，与“又……起点”的行驶路线不符。"}, {"text": "返回", "is_correct": true, "explanation": "正确答案。“公交车到了终点，又返回起点”表示车辆沿原路回到起点。"}], "explanations": {"漂流": "语义：“漂流”指随水流漂动，与公交车的行驶路线无关。", "行驶": "配价：“行驶”是不及物动词，后面不能直接带“起点”作宾语，要说“行驶到起点”。", "修理": "语义：“修理”指修复，与“又……起点”的行驶路线不符。", "返回": "正确答案。“公交车到了终点，又返回起点”表示车辆沿原路回到起点。"}, "sentence_index": 6, "correct_answer": "返回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "服务员把多收的钱返回给了客人。", "explanation": "这里应该用〈退还〉。返回指交通工具、页面等回到原处，把钱退给客人要用“退还”。"}, {"text": "他把捡到的证件返回给了失主。", "explanation": "这里应该用〈交还〉。返回不用于把捡到的东西还给失主，要用“交还”。"}, {"text": "他把借来的外套返回给了同学。", "explanation": "这里应该用〈送还〉。返回不用于把借来的物品还给别人，归还外套要用“送还”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火车因为大雪，返回着车站。", "corrected_sentence": "火车因为大雪，返回了车站。", "error_description": "错误：“返回”是一次性完成的动作，后面不能加表示持续的“着”。正确：应用“了”。“因为大雪”只是原因，不决定能否用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出租车送完客人，马上返回过市区。", "corrected_sentence": "出租车送完客人，马上返回了市区。", "error_description": "错误：“返回”后用了“过”，表示经历。正确：应用“了”。“马上”描述的是紧接着发生的已完成动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2ed89d-3c92-4cf3-bb19-bdfc26db4f95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
