INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90003, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "产是生出来,或者做出来。", "primary_collocate": null, "pronunciation": "chǎn", "ipa": "tʂʰan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这只母鸡每天产一个蛋。", "target_word": "产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这头奶牛一天能产二十斤奶。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只猫昨晚产了四只小猫。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只母狗昨天产了五只小狗。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂产的蜜又香又甜。", "target_word": "产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种鸭子一年能产两百个蛋。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "母羊一般在春天产小羊。", "target_word": "产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台机器一小时能产一百个零件。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农场里的母牛刚产了一头小牛。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只鸡病了,这几天一个蛋也不产。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "產", "label": "繁体"}, {"form": "产了", "label": "体标"}], "register": "中性", "sense_fingerprint": "动物下蛋、产仔、人生孩子,或机器做出东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116634ea-fcb5-448e-abe0-203c2273568d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90003, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "产", "is_correct": true, "explanation": "产：生出来或做出来，本词条。"}, {"text": "厂", "is_correct": false, "explanation": "chǎng 与 chǎn 韵母不同（ang 与 an），意思是工厂。"}, {"text": "颤", "is_correct": false, "explanation": "chàn（第四声）与 chǎn（第三声）声调不同，意思是颤抖。"}, {"text": "惨", "is_correct": false, "explanation": "cǎn 与 chǎn 声母不同（c 与 ch），意思是悲惨、严重。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn 与 chǎn 声母不同（sh 与 ch），意思是闪光、躲开。"}, {"text": "馋", "is_correct": false, "explanation": "chán（第二声）与 chǎn（第三声）声调不同，意思是贪吃。"}], "explanations": {"产": "产：生出来或做出来，本词条。", "厂": "chǎng 与 chǎn 韵母不同（ang 与 an），意思是工厂。", "颤": "chàn（第四声）与 chǎn（第三声）声调不同，意思是颤抖。", "惨": "cǎn 与 chǎn 声母不同（c 与 ch），意思是悲惨、严重。", "闪": "shǎn 与 chǎn 声母不同（sh 与 ch），意思是闪光、躲开。", "馋": "chán（第二声）与 chǎn（第三声）声调不同，意思是贪吃。"}, "sentence_index": null, "correct_answer": "产"}, "level_3": {"options": [{"text": "产", "is_correct": true, "explanation": "产：生出蛋来，母鸡下蛋的说法，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示食用，与“母鸡每天……一个蛋”的生产语境不符。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”是购买行为，句中的母鸡不是买者，句意不通。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”多用于信件、包裹，不能与“蛋”搭配。"}], "explanations": {"产": "产：生出蛋来，母鸡下蛋的说法，符合句意。", "吃": "语义：“吃”表示食用，与“母鸡每天……一个蛋”的生产语境不符。", "买": "语义：“买”是购买行为，句中的母鸡不是买者，句意不通。", "拆": "搭配：“拆”多用于信件、包裹，不能与“蛋”搭配。"}, "sentence_index": 0, "correct_answer": "产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树去年产了很多叶子。", "explanation": "这里应该用〈长〉。产用于动物生育或工厂、机器制造东西，植物长出枝叶要用长。"}, {"text": "他每月产两万块钱。", "explanation": "这里应该用〈挣〉。产指生出或制造出东西，收入要用挣。"}, {"text": "工人们产了一座桥。", "explanation": "这里应该用〈建造〉。产多指生育或出产物品，建筑物要用建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90003, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "产", "is_correct": true, "explanation": "产：生出来或做出来，本词条。"}, {"text": "缠", "is_correct": false, "explanation": "chán（第二声）与 chǎn（第三声）声调不同，意思是缠绕。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn 与 chǎn 声母不同（zh 与 ch），意思是展开、展览。"}, {"text": "掺", "is_correct": false, "explanation": "chān（第一声）与 chǎn（第三声）声调不同，意思是混合。"}], "explanations": {"产": "产：生出来或做出来，本词条。", "缠": "chán（第二声）与 chǎn（第三声）声调不同，意思是缠绕。", "展": "zhǎn 与 chǎn 声母不同（zh 与 ch），意思是展开、展览。", "掺": "chān（第一声）与 chǎn（第三声）声调不同，意思是混合。"}, "sentence_index": null, "correct_answer": "产"}, "level_3": {"options": [{"text": "产", "is_correct": true, "explanation": "产：生出小羊，符合母羊春天生育的语境。"}, {"text": "挤", "is_correct": false, "explanation": "搭配：“挤”用于奶、汁液等，不能与“小羊”搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬小羊”指伤害小羊，与“春天”生育的语境不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与生育的意思相反。"}], "explanations": {"产": "产：生出小羊，符合母羊春天生育的语境。", "挤": "搭配：“挤”用于奶、汁液等，不能与“小羊”搭配。", "咬": "语义：“咬小羊”指伤害小羊，与“春天”生育的语境不符。", "扔": "语义：“扔”表示丢弃，与生育的意思相反。"}, "sentence_index": 6, "correct_answer": "产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树这几天产花了。", "explanation": "这里应该用〈开〉。产用于生出或制造东西，花朵开放要用开。"}, {"text": "他产了一声叫喊。", "explanation": "这里应该用〈发出〉。产只用于生出或制造东西，发出声音要用发出。"}, {"text": "学校每年产一次运动会。", "explanation": "这里应该用〈举行〉。产指生出或制造，活动、比赛要用举行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只母鸡一天能产了一个蛋。", "corrected_sentence": "这只母鸡一天能产一个蛋。", "error_description": "错误：“能”表示能力，后面的动词不再加动态助词“了”，“能产了”是错误的，应说“能产一个蛋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90003, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器一天能产两百个出零件。", "corrected_sentence": "这台机器一天能产两百个零件。", "error_description": "错误：多了一个“出”，插在“两百个”和“零件”之间。“产”后面直接接宾语，“出”只能紧跟“产”构成“产出”，这里应说“产两百个零件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
