INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90004, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出产;制造。", "primary_collocate": null, "pronunciation": "chǎn", "ipa": "tʂʰan˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个地方产茶,很有名。", "target_word": "产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "云南产很多好茶。", "target_word": "产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "海南岛产香蕉和椰子。", "target_word": "产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家工厂只产自行车。", "target_word": "产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北方产小麦,南方产大米。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家不产石油,要从外国买。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座岛上不产水果,都要从外面运来。", "target_word": "产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种红酒是法国产的,不是中国产的。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们村子产的米又白又香。", "target_word": "产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山东产苹果,也产梨。", "target_word": "产", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某地出产物品,或工厂制造产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116634ea-fcb5-448e-abe0-203c2273568d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90004, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "产", "is_correct": true, "explanation": "产：出产某种物品，本词条。"}, {"text": "厂", "is_correct": false, "explanation": "chǎng 与 chǎn 韵母不同（ang 与 an），意思是工厂。"}, {"text": "颤", "is_correct": false, "explanation": "chàn（第四声）与 chǎn（第三声）声调不同，意思是颤抖。"}, {"text": "惨", "is_correct": false, "explanation": "cǎn 与 chǎn 声母不同（c 与 ch），意思是悲惨、严重。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn 与 chǎn 声母不同（sh 与 ch），意思是闪光、躲开。"}, {"text": "馋", "is_correct": false, "explanation": "chán（第二声）与 chǎn（第三声）声调不同，意思是贪吃。"}], "explanations": {"产": "产：出产某种物品，本词条。", "厂": "chǎng 与 chǎn 韵母不同（ang 与 an），意思是工厂。", "颤": "chàn（第四声）与 chǎn（第三声）声调不同，意思是颤抖。", "惨": "cǎn 与 chǎn 声母不同（c 与 ch），意思是悲惨、严重。", "闪": "shǎn 与 chǎn 声母不同（sh 与 ch），意思是闪光、躲开。", "馋": "chán（第二声）与 chǎn（第三声）声调不同，意思是贪吃。"}, "sentence_index": null, "correct_answer": "产"}, "level_3": {"options": [{"text": "产", "is_correct": true, "explanation": "产：出产，指这个地方出产茶叶，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬茶”不是出产的意思，与“很有名”的语境不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“很有名”的出产语境不符。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”多用于信件、包裹，不能与“茶”搭配。"}], "explanations": {"产": "产：出产，指这个地方出产茶叶，符合句意。", "咬": "语义：“咬茶”不是出产的意思，与“很有名”的语境不符。", "扔": "语义：“扔”表示丢弃，与“很有名”的出产语境不符。", "拆": "搭配：“拆”多用于信件、包裹，不能与“茶”搭配。"}, "sentence_index": 0, "correct_answer": "产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们在课上产了一篇作文。", "explanation": "这里应该用〈写〉。产指生育、出产或制造，写作文不属于这些，要用写。"}, {"text": "她昨天产了很多眼泪。", "explanation": "这里应该用〈流〉。产指生育、出产或制造，眼泪从眼睛里流出要用流。"}, {"text": "工人们产了一座桥。", "explanation": "这里应该用〈建造〉。产指出产或制造物品，建筑物要用建造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90004, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "产", "is_correct": true, "explanation": "产：出产某种物品，本词条。"}, {"text": "缠", "is_correct": false, "explanation": "chán（第二声）与 chǎn（第三声）声调不同，意思是缠绕。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn 与 chǎn 声母不同（zh 与 ch），意思是展开、展览。"}, {"text": "掺", "is_correct": false, "explanation": "chān（第一声）与 chǎn（第三声）声调不同，意思是混合。"}], "explanations": {"产": "产：出产某种物品，本词条。", "缠": "chán（第二声）与 chǎn（第三声）声调不同，意思是缠绕。", "展": "zhǎn 与 chǎn 声母不同（zh 与 ch），意思是展开、展览。", "掺": "chān（第一声）与 chǎn（第三声）声调不同，意思是混合。"}, "sentence_index": null, "correct_answer": "产"}, "level_3": {"options": [{"text": "产", "is_correct": true, "explanation": "产：出产，指岛上出产水果，符合句意。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”表示践踏，与“都要从外面运来”的语境不符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”表示扯开，与出产水果的语境不符。"}, {"text": "碾", "is_correct": false, "explanation": "搭配：“碾”多用于粮食、药材，不能与“水果”搭配。"}], "explanations": {"产": "产：出产，指岛上出产水果，符合句意。", "踩": "语义：“踩”表示践踏，与“都要从外面运来”的语境不符。", "撕": "语义：“撕”表示扯开，与出产水果的语境不符。", "碾": "搭配：“碾”多用于粮食、药材，不能与“水果”搭配。"}, "sentence_index": 6, "correct_answer": "产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵树这几天产花了。", "explanation": "这里应该用〈开〉。产指出产或制造物品，花朵开放要用开。"}, {"text": "他产了一声叫喊。", "explanation": "这里应该用〈发出〉。产只用于出产或制造东西，发出声音要用发出。"}, {"text": "学校每年产一次运动会。", "explanation": "这里应该用〈举行〉。产指出产或制造，活动、比赛要用举行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地方一年能产很多出茶。", "corrected_sentence": "这个地方一年能产很多茶。", "error_description": "错误：多了一个“出”，插在“很多”和“茶”之间。“产”后直接接宾语，应说“产很多茶”；若要带结果补语，应说“产出很多茶”，“出”须紧跟“产”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个县去年把产了很多棉花。", "corrected_sentence": "这个县去年产了很多棉花。", "error_description": "错误：“把”字句的“把”后面没有宾语，结构不完整。这里应直接说“产了很多棉花”，不用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
