INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90006, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示较远的一边或处所。", "primary_collocate": null, "pronunciation": "nà biān", "ipa": "nɑ˥˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "那边有一家商店。", "target_word": "那边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "书在那边的桌子上。", "target_word": "那边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你去那边坐。", "target_word": "那边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那边的人是我的朋友。", "target_word": "那边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们在那边玩。", "target_word": "那边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校就在那边，不太远。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去那边看看，你在这儿等我。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那边太吵了，我们换个地方吧。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在河那边，一直在向我招手。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车站在马路那边，我们走过去只要五分钟。", "target_word": "那边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那边儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "指示代词，指离说话人较远的处所或一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c8e5f0-0406-4b36-85f5-8cace11e88a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那边", "is_correct": true, "explanation": "正确。那边指较远的一边或处所，可以作「有一家商店」的处所。"}, {"text": "那个", "is_correct": false, "explanation": "语义：「那个」指人或物，不指处所，不能说「那个有一家商店」。"}, {"text": "这个", "is_correct": false, "explanation": "语义：「这个」同样指物，不指处所，句子说的是某处有商店。"}, {"text": "那些", "is_correct": false, "explanation": "配价：「那些」是限定词，后面必须接名词，不能单独作「有」的主语。"}], "explanations": {"那边": "正确。那边指较远的一边或处所，可以作「有一家商店」的处所。", "那个": "语义：「那个」指人或物，不指处所，不能说「那个有一家商店」。", "这个": "语义：「这个」同样指物，不指处所，句子说的是某处有商店。", "那些": "配价：「那些」是限定词，后面必须接名词，不能单独作「有」的主语。"}, "sentence_index": 0, "correct_answer": "那边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那边我还在上大学。", "explanation": "这里应该用〈那时〉。那边指地方，不能表示时间，表示当时要用「那时」。"}, {"text": "他买了三个那边。", "explanation": "这里应该用〈苹果〉。「那边」指地方，不能用量词计数，应说「三个苹果」。"}, {"text": "我的名字叫那边。", "explanation": "这里应该用人名，如〈小王〉。那边指地方，不能用作人名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那边", "is_correct": true, "explanation": "正确。那边指较远的地方，与「你在这儿等我」形成对照，符合语境。"}, {"text": "那个", "is_correct": false, "explanation": "语义：「那个」指人或物，不指处所，不能单独作「去」的处所。"}, {"text": "哪边", "is_correct": false, "explanation": "语义：「哪边」是疑问或任指词，此处说的是要去的具体一边，应说「那边」。"}, {"text": "它", "is_correct": false, "explanation": "配价：「去」后要接处所，「它」是指物代词，不能作去的处所。"}], "explanations": {"那边": "正确。那边指较远的地方，与「你在这儿等我」形成对照，符合语境。", "那个": "语义：「那个」指人或物，不指处所，不能单独作「去」的处所。", "哪边": "语义：「哪边」是疑问或任指词，此处说的是要去的具体一边，应说「那边」。", "它": "配价：「去」后要接处所，「它」是指物代词，不能作去的处所。"}, "sentence_index": 6, "correct_answer": "那边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他等了那边久，还没有来。", "explanation": "这里应该用〈那么〉。那边指地方，不能表示时间长短，应说等了那么久。"}, {"text": "他把那边抱起来了。", "explanation": "这里应该用〈孩子〉。那边指地方，不能作「抱」的对象，应说把孩子抱起来。"}, {"text": "他把那边搬走了。", "explanation": "这里应该用〈箱子〉之类的物件名词。那边是地方，不能作「搬」的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的车停了那边。", "corrected_sentence": "我的车停在那边。", "error_description": "错误：「停了那边」；正确：「停在那边」。表示停放的处所要用介词「在」，「了」不能代替「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他门口那边走了。", "corrected_sentence": "他往门口那边走了。", "error_description": "错误：「门口那边走了」漏掉了介词「往」。正确：「往门口那边走了」。「那边」表示去向时，前面要加介词「往」引出方向。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
