INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90007, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "留下是不走,放在这里。", "primary_collocate": null, "pronunciation": "liú xià", "ipa": "ljoʊ˧˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "你留下，我去买点吃的。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把行李留下，一个人出去了。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让他下课后留下。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想让我留下，不要去外地工作。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸先留下，我看完再还你。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累了，就在我家留下来休息吧。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把孩子留下，自己去上班了。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱先留下，东西明天给你送去。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都想留下，不想回家。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花不要带走，留下放在桌上。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "留下了", "label": "完成体"}, {"form": "留下过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不走，或把人、物放在这里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90007, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "留下", "is_correct": true, "explanation": "「留下」是本词，表示不走，或把人、物放在这里。"}, {"text": "楼下", "is_correct": false, "explanation": "lóu（第二声）与 liú（第二声）声调相同，只有韵母不同（ou 与 iu），意思是楼的下面。"}, {"text": "立下", "is_correct": false, "explanation": "lì（第四声）与 liú（第二声）声调和韵母都不同，意思是订立、定下。"}, {"text": "留香", "is_correct": false, "explanation": "xiāng（第一声）与 xià（第四声）声调和韵母都不同，意思是香气留存。"}, {"text": "留心", "is_correct": false, "explanation": "xīn（第一声）与 xià（第四声）韵母和声调都不同，意思是注意、留意。"}], "explanations": {"留下": "「留下」是本词，表示不走，或把人、物放在这里。", "楼下": "lóu（第二声）与 liú（第二声）声调相同，只有韵母不同（ou 与 iu），意思是楼的下面。", "立下": "lì（第四声）与 liú（第二声）声调和韵母都不同，意思是订立、定下。", "留香": "xiāng（第一声）与 xià（第四声）声调和韵母都不同，意思是香气留存。", "留心": "xīn（第一声）与 xià（第四声）韵母和声调都不同，意思是注意、留意。"}, "sentence_index": null, "correct_answer": "留下"}, "level_3": {"options": [{"text": "留下", "is_correct": true, "explanation": "「留下」表示不走，与“我去买点吃的”形成分工，句意通顺。"}, {"text": "送", "is_correct": false, "explanation": "配价：送需要宾语（送什么、送给谁），单独说“你送”不成句。"}, {"text": "放", "is_correct": false, "explanation": "配价：放需要宾语和处所（放什么、放在哪里），“你放”不成句。"}, {"text": "懂", "is_correct": false, "explanation": "语义：「你懂」与后句「去买点吃的」没有关联，句意不通。"}], "explanations": {"留下": "「留下」表示不走，与“我去买点吃的”形成分工，句意通顺。", "送": "配价：送需要宾语（送什么、送给谁），单独说“你送”不成句。", "放": "配价：放需要宾语和处所（放什么、放在哪里），“你放”不成句。", "懂": "语义：「你懂」与后句「去买点吃的」没有关联，句意不通。"}, "sentence_index": 0, "correct_answer": "留下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议终于留下了。", "explanation": "这里应该用〈结束〉。留下指人或物不离开、放在原处，会议中止要用〈结束〉。"}, {"text": "这篇文章留下了大家的注意。", "explanation": "这里应该用〈引起〉。留下不能用于说“注意”，说引起关注要用〈引起〉。"}, {"text": "他跑完比赛，留下了第一名。", "explanation": "这里应该用〈取得〉。留下表示不离开或放在原处，不能用来说赢得名次，说取得第一名要用〈取得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留下", "is_correct": true, "explanation": "「留下」表示孩子不跟着走，留在家里，与“自己去上班”形成对照。"}, {"text": "哄", "is_correct": false, "explanation": "配价：哄需要补语（如哄睡）或其他成分，只说“她把孩子哄”不完整。"}, {"text": "喂", "is_correct": false, "explanation": "配价：喂需要补语（如喂饱）或宾语，“她把孩子喂”不成句。"}, {"text": "交", "is_correct": false, "explanation": "配价：「交」需要补语或宾语（交给谁），「她把孩子交」不完整。"}], "explanations": {"留下": "「留下」表示孩子不跟着走，留在家里，与“自己去上班”形成对照。", "哄": "配价：哄需要补语（如哄睡）或其他成分，只说“她把孩子哄”不完整。", "喂": "配价：喂需要补语（如喂饱）或宾语，“她把孩子喂”不成句。", "交": "配价：「交」需要补语或宾语（交给谁），「她把孩子交」不完整。"}, "sentence_index": 6, "correct_answer": "留下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的歌声留下了整个宿舍。", "explanation": "这里应该用〈吵醒〉。留下表示不离开或放在原处，不能用来说声音让整个宿舍的人醒来，这要用〈吵醒〉。"}, {"text": "他这个月留下了五场。", "explanation": "这里应该用〈表演〉。留下不能用于计算演出的场次，说表演了几场要用〈表演〉。"}, {"text": "他留下了窗户，走了出去。", "explanation": "这里应该用〈打开〉。留下不能用于开窗的动作，说开窗要用〈打开〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先留下把行李，然后出门了。", "corrected_sentence": "他先把行李留下，然后出门了。", "error_description": "语序错误：「把行李」必须放在动词「留下」前面，应说「把行李留下」，不能说「留下把行李」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧书先留下了来，以后给孩子看。", "corrected_sentence": "这些旧书先留下来，以后给孩子看。", "error_description": "错误：“了”插在补语“下”和“来”之间，成了“留下了来”。应为“留下来”，“了”不能插在复合补语中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
