INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90008, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不离开;把东西放在原处。", "primary_collocate": null, "pronunciation": "liú xià", "ipa": "ljoʊ˧˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "天太晚了，你就留下吧。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的包留下，我帮你看着。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他决定留下，不跟大家去了。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钥匙留下就行，你可以走了。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人想走，但主人请他留下吃饭。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书先留下，我明天再来拿。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都走了，只有小王留下。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把电话号码留下，有事找我。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨，你留下住一晚吧。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧盒子别扔，留下放在柜子里。", "target_word": "留下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "留下了", "label": "完成体"}, {"form": "留下过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "人不离开，或东西放着不带走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90008, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "留下", "is_correct": true, "explanation": "「留下」是本词，表示不离开，或把东西放在原处。"}, {"text": "楼下", "is_correct": false, "explanation": "lóu（第二声）与 liú（第二声）声调相同，只有韵母不同（ou 与 iu），意思是楼的下面。"}, {"text": "立下", "is_correct": false, "explanation": "lì（第四声）与 liú（第二声）声调和韵母都不同，意思是订立、定下，如立下誓言。"}, {"text": "留香", "is_correct": false, "explanation": "xiāng（第一声）与 xià（第四声）声调和韵母都不同，意思是香气留存。"}, {"text": "留学", "is_correct": false, "explanation": "xué（第二声）与 xià（第四声）韵母和声调都不同，意思是到外国求学。"}], "explanations": {"留下": "「留下」是本词，表示不离开，或把东西放在原处。", "楼下": "lóu（第二声）与 liú（第二声）声调相同，只有韵母不同（ou 与 iu），意思是楼的下面。", "立下": "lì（第四声）与 liú（第二声）声调和韵母都不同，意思是订立、定下，如立下誓言。", "留香": "xiāng（第一声）与 xià（第四声）声调和韵母都不同，意思是香气留存。", "留学": "xué（第二声）与 xià（第四声）韵母和声调都不同，意思是到外国求学。"}, "sentence_index": null, "correct_answer": "留下"}, "level_3": {"options": [{"text": "留下", "is_correct": true, "explanation": "「留下」表示不离开，与「天太晚了，你就……吧」劝人留宿的语气相符。"}, {"text": "买", "is_correct": false, "explanation": "配价：买需要宾语（买什么），“你就买吧”缺少宾语，与留宿语境不合。"}, {"text": "挽留", "is_correct": false, "explanation": "配价：挽留需要宾语（挽留某人），“你就挽留吧”缺少宾语，句子不完整。"}, {"text": "带走", "is_correct": false, "explanation": "配价：带走需要宾语（带走什么），“你就带走吧”缺少宾语，不能成立。"}], "explanations": {"留下": "「留下」表示不离开，与「天太晚了，你就……吧」劝人留宿的语气相符。", "买": "配价：买需要宾语（买什么），“你就买吧”缺少宾语，与留宿语境不合。", "挽留": "配价：挽留需要宾语（挽留某人），“你就挽留吧”缺少宾语，句子不完整。", "带走": "配价：带走需要宾语（带走什么），“你就带走吧”缺少宾语，不能成立。"}, "sentence_index": 0, "correct_answer": "留下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电梯突然留下了。", "explanation": "这里应该用〈停下〉。留下指人或物不离开、放在原处，正在运行的电梯突然中止要用〈停下〉。"}, {"text": "这次旅行留下了我的见识。", "explanation": "这里应该用〈增长〉。留下表示不离开、放在原处或给人留下印象，不能说“留下见识”，说见识变多要用〈增长〉。"}, {"text": "这个月我的体重留下了三公斤。", "explanation": "这里应该用〈增加〉。留下不能用来说体重变多，说体重增加要用〈增加〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "留下", "is_correct": true, "explanation": "「留下」表示不随大家离开，与“大家都走了，只有小王”的对比语境相符。"}, {"text": "到达", "is_correct": false, "explanation": "语义：前句说“大家都走了”讲的是离开，“到达”是抵达，与离开的语境冲突。"}, {"text": "送", "is_correct": false, "explanation": "配价：送需要宾语（送谁、送什么），单独说“只有小王送”不成句。"}, {"text": "放", "is_correct": false, "explanation": "配价：放需要宾语和处所（放什么、放在哪里），“只有小王放”不成句。"}], "explanations": {"留下": "「留下」表示不随大家离开，与“大家都走了，只有小王”的对比语境相符。", "到达": "语义：前句说“大家都走了”讲的是离开，“到达”是抵达，与离开的语境冲突。", "送": "配价：送需要宾语（送谁、送什么），单独说“只有小王送”不成句。", "放": "配价：放需要宾语和处所（放什么、放在哪里），“只有小王放”不成句。"}, "sentence_index": 6, "correct_answer": "留下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨终于留下了。", "explanation": "这里应该用〈停止〉。留下指人或物不离开、放在原处，不用于雨的中止，说雨停要用〈停止〉。"}, {"text": "这次考试他留下了五十分。", "explanation": "这里应该用〈得〉。留下表示不离开或放在原处，不能用来说考试得分，说得了多少分要用〈得〉。"}, {"text": "他留下了门，走了进去。", "explanation": "这里应该用〈推开〉。留下不能用于开门的动作，说推门要用〈推开〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没把钥匙留下了，你先走吧。", "corrected_sentence": "我没把钥匙留下，你先走吧。", "error_description": "否定错误：“没”与完成体“了”不能同用。否定已发生的动作应说“没留下”，去掉“了”；肯定说“留下了”，不能加“没”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "走的时候我伞把留下了。", "corrected_sentence": "走的时候我把伞留下了。", "error_description": "错误：把字句中“把”的位置错了。“把”应放在处置对象“伞”的前面，正确为“我把伞留下了”，不能放在“伞”的后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
