INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90009, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水晶是像冰一样透明、亮闪闪的石头。", "primary_collocate": null, "pronunciation": "shuǐ jīng", "ipa": "ʂweɪ˨˩˦ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "这条项链是用水晶做的。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水晶像冰一样，在阳光下闪闪发光。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送了我一块漂亮的水晶。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一块紫色的水晶。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在河边捡到了一块水晶。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块水晶很透明，能看见里面的花纹。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈戴的耳环是用白色水晶做的。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里有人专门找水晶。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有红色和白色的水晶。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块水晶太小了，不能做项链。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块水晶", "label": "量词"}, {"form": "水晶球", "label": "复合"}], "register": "中性", "sense_fingerprint": "像冰一样透明闪亮的石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90009, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水晶", "is_correct": true, "explanation": "正确答案。水晶指像冰一样透明、亮闪闪的石头。"}, {"text": "水井", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。"}, {"text": "税警", "is_correct": false, "explanation": "shuì jǐng 与 shuǐ jīng 声母韵母相同，声调不同，意思是税务警察。"}, {"text": "水星", "is_correct": false, "explanation": "xīng 与 jīng 声母不同，意思是太阳系中的水星。"}], "explanations": {"水晶": "正确答案。水晶指像冰一样透明、亮闪闪的石头。", "水井": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。", "税警": "shuì jǐng 与 shuǐ jīng 声母韵母相同，声调不同，意思是税务警察。", "水星": "xīng 与 jīng 声母不同，意思是太阳系中的水星。"}, "sentence_index": null, "correct_answer": "水晶"}, "level_3": {"options": [{"text": "水晶", "is_correct": true, "explanation": "正确。「用……做的」后接材料名词，水晶可以用来做项链。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是物质材料，不能用来做项链。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是液体，不能做成项链。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话不是材料，不能用来做项链。"}], "explanations": {"水晶": "正确。「用……做的」后接材料名词，水晶可以用来做项链。", "时间": "语义：时间不是物质材料，不能用来做项链。", "眼泪": "语义：眼泪是液体，不能做成项链。", "电话": "语义：电话不是材料，不能用来做项链。"}, "sentence_index": 0, "correct_answer": "水晶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块水晶放进火里，很快就燃烧起来了。", "explanation": "这里应该用〈木炭〉。水晶是石英，不会燃烧，不能当燃料。"}, {"text": "我早上出门，总要先用水晶开门。", "explanation": "这里应该用〈钥匙〉。水晶是石英，不能当作钥匙开门。"}, {"text": "我昨天用水晶洗了手。", "explanation": "这里应该用〈肥皂〉。水晶是石头，不能用来洗手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水晶", "is_correct": true, "explanation": "正确。水晶是耳环的材料，与「白色」相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能用来做耳环。"}, {"text": "烟雾", "is_correct": false, "explanation": "语义：烟雾不是可以加工成首饰的材料。"}, {"text": "墨汁", "is_correct": false, "explanation": "体貌：墨汁是黑色的，与句中的「白色」矛盾。"}], "explanations": {"水晶": "正确。水晶是耳环的材料，与「白色」相符。", "天空": "语义：天空不能用来做耳环。", "烟雾": "语义：烟雾不是可以加工成首饰的材料。", "墨汁": "体貌：墨汁是黑色的，与句中的「白色」矛盾。"}, "sentence_index": 6, "correct_answer": "水晶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天用水晶煮了一锅粥。", "explanation": "语义：水晶是石英，不能用来煮粥，这里把它当作了食材。"}, {"text": "我每天用水晶看新闻。", "explanation": "这里应该用〈手机〉。水晶是石头，不能当作电子设备使用。"}, {"text": "她每天用水晶擦桌子。", "explanation": "这里应该用〈抹布〉。水晶是石头，不能当作擦拭用具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐给我买了一张漂亮的水晶。", "corrected_sentence": "姐姐给我买了一块漂亮的水晶。", "error_description": "量词错误：水晶应该用「块」，不用「张」。「张」用于纸、桌子等平面物品。正确说法是「一块漂亮的水晶」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥在山上找到了一本水晶。", "corrected_sentence": "哥哥在山上找到了一块水晶。", "error_description": "量词错误：〈一本水晶〉。「本」用于书本，水晶应该用「块」，应为〈一块水晶〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
