INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90010, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "无色透明的石英晶体，可做装饰品和光学材料。", "primary_collocate": null, "pronunciation": "shuǐ jīng", "ipa": "ʂweɪ˨˩˦ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "水晶是一种无色透明的石英。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用水晶做成了镜片。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水晶可以用来做光学仪器。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水晶经过打磨，变得更加明亮。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水晶放进了盒子里。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览馆里有很多天然水晶。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水晶很硬，不容易划坏。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂买了大量水晶当材料。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块水晶是从矿山里挖出来的。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板喜欢用水晶装饰房间。", "target_word": "水晶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块水晶", "label": "量词"}, {"form": "水晶球", "label": "复合"}], "register": "中性", "sense_fingerprint": "无色透明的石英晶体，用作装饰品和光学材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90010, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水晶", "is_correct": true, "explanation": "正确答案。水晶指无色透明的石英晶体。"}, {"text": "水井", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。"}, {"text": "水清", "is_correct": false, "explanation": "qīng 与 jīng 声母不同，意思是水很清澈。"}, {"text": "水星", "is_correct": false, "explanation": "xīng 与 jīng 声母不同，意思是太阳系中的水星。"}], "explanations": {"水晶": "正确答案。水晶指无色透明的石英晶体。", "水井": "jǐng（第三声）与 jīng（第一声）声调不同，意思是水井。", "水清": "qīng 与 jīng 声母不同，意思是水很清澈。", "水星": "xīng 与 jīng 声母不同，意思是太阳系中的水星。"}, "sentence_index": null, "correct_answer": "水晶"}, "level_3": {"options": [{"text": "水晶", "is_correct": true, "explanation": "正确。水晶本身就是无色透明的石英。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是矿物，不能说它是石英。"}, {"text": "墨汁", "is_correct": false, "explanation": "体貌：墨汁是黑色的，与句中的「无色透明」矛盾。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是液体，不是石英。"}], "explanations": {"水晶": "正确。水晶本身就是无色透明的石英。", "时间": "语义：时间不是矿物，不能说它是石英。", "墨汁": "体貌：墨汁是黑色的，与句中的「无色透明」矛盾。", "眼泪": "语义：眼泪是液体，不是石英。"}, "sentence_index": 0, "correct_answer": "水晶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块水晶放进炉子里，很快就烧起来了。", "explanation": "这里应该用〈煤〉。水晶是石英，不会燃烧，不能当燃料。"}, {"text": "妈妈买了一块水晶，放在桌上当早餐。", "explanation": "这里应该用〈面包〉。水晶是石英，不能当早餐食用。"}, {"text": "妈妈用水晶烧开了一壶水。", "explanation": "这里应该用〈炉子〉。水晶是石英，不能用来加热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水晶", "is_correct": true, "explanation": "正确。水晶很硬，符合句意。"}, {"text": "棉花", "is_correct": false, "explanation": "体貌：棉花很软，与「很硬」矛盾。"}, {"text": "烟雾", "is_correct": false, "explanation": "语义：烟雾没有硬度，不能说「很硬」。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有固体的硬度，不能说「很硬」。"}], "explanations": {"水晶": "正确。水晶很硬，符合句意。", "棉花": "体貌：棉花很软，与「很硬」矛盾。", "烟雾": "语义：烟雾没有硬度，不能说「很硬」。", "空气": "语义：空气没有固体的硬度，不能说「很硬」。"}, "sentence_index": 6, "correct_answer": "水晶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板喜欢用水晶切菜。", "explanation": "语义：水晶是石英，不能用来切菜。"}, {"text": "老板喜欢用水晶煮汤。", "explanation": "语义：水晶是石头，不能用来煮汤。"}, {"text": "老板喜欢把水晶当作小狗养。", "explanation": "语义：水晶是矿物，不能当作宠物饲养。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂用两条水晶做成了镜片。", "corrected_sentence": "工厂用两块水晶做成了镜片。", "error_description": "量词错误：水晶应该用「块」，不用「条」。正确说法是「两块水晶」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂买了一头水晶当材料。", "corrected_sentence": "工厂买了一块水晶当材料。", "error_description": "量词错误：水晶是块状的石头，应该用「块」，不能用「头」（「头」用于牛、猪等动物）。正确说法是「一块水晶」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
