INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90011, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "白白亮亮的金属，可以做首饰和钱。", "primary_collocate": null, "pronunciation": "yín", "ipa": "in˧˥", "syllable_count": 1, "sentences": [{"text": "这个戒指是银做的。", "target_word": "银", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条项链是银的。", "target_word": "银", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "以前的人用银买东西。", "target_word": "银", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "银比铜贵很多。", "target_word": "银", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她买了一个银做的杯子。", "target_word": "银", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些首饰都是用银做的。", "target_word": "银", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈的手镯是银的，不是金的。", "target_word": "银", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用银给孩子打了一把小锁。", "target_word": "银", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块银很白，也很亮。", "target_word": "银", "complexity_tier": "T3", "furigana": "zhè kuài yín hěn bái, yě hěn liàng.", "sentence_source": "generated"}, {"text": "古时候，人们把银当钱用。", "target_word": "银", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "銀", "label": "繁体"}, {"form": "银子", "label": "复合"}, {"form": "银币", "label": "复合"}], "register": "中性", "sense_fingerprint": "银：白亮的金属，用来做首饰和钱币", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90011, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "银", "is_correct": true, "explanation": "银（yín）：白亮的金属，可以做首饰和钱币，是目标词。"}, {"text": "因", "is_correct": false, "explanation": "yīn（第一声）与 yín（第二声）声调不同，意思是因为。"}, {"text": "迎", "is_correct": false, "explanation": "yíng 与 yín 韵母不同（ing 与 in），意思是迎接。"}, {"text": "盐", "is_correct": false, "explanation": "yán 与 yín 主要元音不同（a 与 i），意思是食盐。"}, {"text": "引", "is_correct": false, "explanation": "yǐn（第三声）与 yín（第二声）声调不同，意思是引导。"}], "explanations": {"银": "银（yín）：白亮的金属，可以做首饰和钱币，是目标词。", "因": "yīn（第一声）与 yín（第二声）声调不同，意思是因为。", "迎": "yíng 与 yín 韵母不同（ing 与 in），意思是迎接。", "盐": "yán 与 yín 主要元音不同（a 与 i），意思是食盐。", "引": "yǐn（第三声）与 yín（第二声）声调不同，意思是引导。"}, "sentence_index": null, "correct_answer": "银"}, "level_3": {"options": [{"text": "银", "is_correct": true, "explanation": "银：白亮的金属，可以做成戒指，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不能做成戒指，句意不通。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟没有固定形状，不能做成戒指。"}, {"text": "油", "is_correct": false, "explanation": "搭配：首饰的材料一般说金、银、铜、玉，不说“油做的”戒指。"}], "explanations": {"银": "银：白亮的金属，可以做成戒指，符合句意。", "水": "语义：水是液体，不能做成戒指，句意不通。", "烟": "语义：烟没有固定形状，不能做成戒指。", "油": "搭配：首饰的材料一般说金、银、铜、玉，不说“油做的”戒指。"}, "sentence_index": 0, "correct_answer": "银"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯银。", "explanation": "这里应该用〈牛奶〉。银是金属，不能喝，应说“喝一杯牛奶”。"}, {"text": "他用银煮了一锅粥，很好喝。", "explanation": "这里应该用〈米〉。银是金属，不能用来煮粥，粥要用米煮。"}, {"text": "妈妈每天用银洗碗。", "explanation": "这里应该用〈洗碗布〉。银是贵重金属，不能当洗碗的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90011, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "银", "is_correct": true, "explanation": "银（yín）：白亮的金属，可以做首饰和钱币，是目标词。"}, {"text": "印", "is_correct": false, "explanation": "yìn（第四声）与 yín 声调不同，意思是印刷、印章。"}, {"text": "音", "is_correct": false, "explanation": "yīn（第一声）与 yín（第二声）声调不同，意思是声音。"}, {"text": "研", "is_correct": false, "explanation": "yán 与 yín 主要元音不同（a 与 i），意思是研究。"}, {"text": "赢", "is_correct": false, "explanation": "yíng 与 yín 韵母不同（ing 与 in），意思是赢得比赛。"}], "explanations": {"银": "银（yín）：白亮的金属，可以做首饰和钱币，是目标词。", "印": "yìn（第四声）与 yín 声调不同，意思是印刷、印章。", "音": "yīn（第一声）与 yín（第二声）声调不同，意思是声音。", "研": "yán 与 yín 主要元音不同（a 与 i），意思是研究。", "赢": "yíng 与 yín 韵母不同（ing 与 in），意思是赢得比赛。"}, "sentence_index": null, "correct_answer": "银"}, "level_3": {"options": [{"text": "银", "is_correct": true, "explanation": "银：白亮的金属，手镯可以用它做，符合句意。"}, {"text": "汤", "is_correct": false, "explanation": "语义：汤是液体，不能做成手镯，句意不通。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：说手镯的材料一般用金属、玉石等，不说“雨的手镯”。"}, {"text": "风", "is_correct": false, "explanation": "语义：风没有实体，无法做成手镯，句子不成立。"}], "explanations": {"银": "银：白亮的金属，手镯可以用它做，符合句意。", "汤": "语义：汤是液体，不能做成手镯，句意不通。", "雨": "搭配：说手镯的材料一般用金属、玉石等，不说“雨的手镯”。", "风": "语义：风没有实体，无法做成手镯，句子不成立。"}, "sentence_index": 6, "correct_answer": "银"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去银取了钱。", "explanation": "这里应该用〈银行〉。“银”是金属，不指存取钱的地方。"}, {"text": "我早饭吃了两碗银。", "explanation": "这里应该用〈米饭〉。银是金属，不能吃，应说“吃了两碗米饭”。"}, {"text": "她用银写字，每天写一页。", "explanation": "这里应该用〈笔〉。银是金属，不能当笔用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一只银，准备打首饰。", "corrected_sentence": "他买了一块银，准备打首饰。", "error_description": "错误形式：“一只银”；正确形式：“一块银”。“只”一般用于动物或成对的东西，银块要用量词“块”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他送了妹妹一个银做杯子。", "corrected_sentence": "他送了妹妹一个银做的杯子。", "error_description": "错误形式：「银做杯子」；正确形式：「银做的杯子」。「银做」修饰名词「杯子」时，中间要加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
