INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种白色有光泽的贵金属。", "primary_collocate": null, "pronunciation": "yín", "ipa": "in˧˥", "syllable_count": 1, "sentences": [{"text": "银是一种白色的金属。", "target_word": "银", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "银比金便宜，但比铜贵。", "target_word": "银", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银放久了会变黑。", "target_word": "银", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银在灯光下很亮。", "target_word": "银", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "银的质地柔软，所以人们喜欢用它做首饰。", "target_word": "银", "complexity_tier": "T3", "furigana": "yín de zhì dì róu ruǎn, suǒ yǐ rén men xǐ huan yòng tā zuò shǒu shi.", "sentence_source": "generated"}, {"text": "这块银很重，一定是真的。", "target_word": "银", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "金、银、铜都是金属。", "target_word": "银", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "银能导电，也能导热。", "target_word": "银", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银可以用来做刀和叉子。", "target_word": "银", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把银擦得很亮。", "target_word": "银", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "銀", "label": "繁体"}, {"form": "银子", "label": "复合"}, {"form": "银币", "label": "复合"}], "register": "中性", "sense_fingerprint": "银：白色有光泽的贵金属，强调其物质性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4de93c19-9eac-449b-96e7-31ed056a2812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90012, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "银", "is_correct": true, "explanation": "银：一种白色有光泽的贵金属，是目标词。"}, {"text": "因", "is_correct": false, "explanation": "yīn（第一声）与 yín（第二声）声调不同，意思是因为。"}, {"text": "颜", "is_correct": false, "explanation": "yán 与 yín 主要元音不同（a 与 i），意思是颜色。"}, {"text": "盐", "is_correct": false, "explanation": "yán 与 yín 主要元音不同（a 与 i），意思是食盐。"}], "explanations": {"银": "银：一种白色有光泽的贵金属，是目标词。", "因": "yīn（第一声）与 yín（第二声）声调不同，意思是因为。", "颜": "yán 与 yín 主要元音不同（a 与 i），意思是颜色。", "盐": "yán 与 yín 主要元音不同（a 与 i），意思是食盐。"}, "sentence_index": null, "correct_answer": "银"}, "level_3": {"options": [{"text": "银", "is_correct": true, "explanation": "银：一种白色的金属，符合句意。"}, {"text": "铜", "is_correct": false, "explanation": "体貌：铜是红色的，不是白色的，与“白色”的描述不符。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不是金属，“是一种白色的金属”句子不成立。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐是调味品，不是金属，句意不通。"}], "explanations": {"银": "银：一种白色的金属，符合句意。", "铜": "体貌：铜是红色的，不是白色的，与“白色”的描述不符。", "纸": "语义：纸不是金属，“是一种白色的金属”句子不成立。", "盐": "语义：盐是调味品，不是金属，句意不通。"}, "sentence_index": 0, "correct_answer": "银"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用银刷牙。", "explanation": "这里应该用〈牙膏〉。银是金属，不能用来刷牙。"}, {"text": "妈妈用银炒了一盘菜，很好吃。", "explanation": "这里应该用〈油〉。银是金属，不能用来炒菜，炒菜要用油。"}, {"text": "他去银存了一百块钱。", "explanation": "这里应该用〈银行〉。“银”是金属，不指存钱的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90012, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "银", "is_correct": true, "explanation": "银：一种白色有光泽的贵金属，是目标词。"}, {"text": "音", "is_correct": false, "explanation": "yīn（第一声）与 yín（第二声）声调不同，意思是声音。"}, {"text": "迎", "is_correct": false, "explanation": "yíng 与 yín 韵母不同（ing 与 in），意思是迎接。"}, {"text": "印", "is_correct": false, "explanation": "yìn（第四声）与 yín 声调不同，意思是印刷、印章。"}, {"text": "研", "is_correct": false, "explanation": "yán 与 yín 主要元音不同（a 与 i），意思是研究。"}], "explanations": {"银": "银：一种白色有光泽的贵金属，是目标词。", "音": "yīn（第一声）与 yín（第二声）声调不同，意思是声音。", "迎": "yíng 与 yín 韵母不同（ing 与 in），意思是迎接。", "印": "yìn（第四声）与 yín 声调不同，意思是印刷、印章。", "研": "yán 与 yín 主要元音不同（a 与 i），意思是研究。"}, "sentence_index": null, "correct_answer": "银"}, "level_3": {"options": [{"text": "银", "is_correct": true, "explanation": "银：白色有光泽的金属，列举的金属中应该是它，符合句意。"}, {"text": "木", "is_correct": false, "explanation": "语义：木不是金属，“金、木、铜都是金属”句子不成立。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不属于金属，句意不通。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：“金属”一般指金、银、铜、铁等，不能与“糖”并列。"}], "explanations": {"银": "银：白色有光泽的金属，列举的金属中应该是它，符合句意。", "木": "语义：木不是金属，“金、木、铜都是金属”句子不成立。", "水": "语义：水是液体，不属于金属，句意不通。", "糖": "搭配：“金属”一般指金、银、铜、铁等，不能与“糖”并列。"}, "sentence_index": 6, "correct_answer": "银"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他往汤里放了一点银，汤就咸了。", "explanation": "这里应该用〈盐〉。让汤变咸的是盐，银是金属，不能调味。"}, {"text": "他把银喝了，味道很好。", "explanation": "这里应该用〈茶〉。“银”是金属，不能当茶来喝。"}, {"text": "他用银洗手，很干净。", "explanation": "这里应该用〈肥皂〉。银是贵重金属，不能当洗手的东西用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
