INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把银擦很干净。", "corrected_sentence": "他把银擦得很干净。", "error_description": "错误形式：“擦很干净”；正确形式：“擦得很干净”。动词后接“很”加形容词作补语时，动词和补语之间要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '032cd596-2b0f-4a6c-91ad-4a7e0673820c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
