INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90013, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "发展中是正在慢慢变大变好。", "primary_collocate": null, "pronunciation": "fā zhǎn zhōng", "ipa": "fa˥ ʈʂan˨˩˦ ʈʂʊŋ˥", "syllable_count": 3, "sentences": [{"text": "这个发展中的小镇，每年都有新变化。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家乡还在发展中，路越来越好。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展中的公司需要更多年轻人。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一家发展中的小店，生意越来越好。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一带还在发展中，商店和餐厅越来越多。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展中的城市，到处都在盖新楼。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发展中的行业，工作机会很多。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的新生意正处在发展中，请大家多帮忙。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个发展中的村子，新房子越来越多。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座发展中的城市，空气一年比一年好。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物正在慢慢变大变好的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90013, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发展中", "is_correct": true, "explanation": "正确：“发展中”指正在变大变好，与“每年都有新变化”相合。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“静止”指不动，与“每年都有新变化”矛盾。"}, {"text": "固定", "is_correct": false, "explanation": "语义：“固定”指不变，与“每年都有新变化”矛盾。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”指不再前进，与“每年都有新变化”矛盾。"}], "explanations": {"发展中": "正确：“发展中”指正在变大变好，与“每年都有新变化”相合。", "静止": "语义：“静止”指不动，与“每年都有新变化”矛盾。", "固定": "语义：“固定”指不变，与“每年都有新变化”矛盾。", "停滞": "语义：“停滞”指不再前进，与“每年都有新变化”矛盾。"}, "sentence_index": 0, "correct_answer": "发展中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大桥去年就通车了，是一座发展中的桥。", "explanation": "这里应该用〈建成〉。发展中指仍在变大变好、尚未完成，与“去年就通车”的已完工状态矛盾。"}, {"text": "这套房子去年就装修完了，是一套发展中的房子。", "explanation": "这里应该用〈竣工〉。发展中指仍在变化、尚未完工，与“装修完了”的状态矛盾。"}, {"text": "这辆车已经开了五年，是一辆发展中的车。", "explanation": "这里应该用〈陈旧〉。发展中指仍在变大变好，不用来形容已经用了五年、需要更新的旧车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发展中", "is_correct": true, "explanation": "正确：“发展中”指正在变大变好，与“工作机会很多”相合。"}, {"text": "饱和", "is_correct": false, "explanation": "语义：“饱和”指已经容纳不下，与“工作机会很多”矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指没有人气，与“工作机会很多”矛盾。"}, {"text": "陡峭", "is_correct": false, "explanation": "体貌：“陡峭”形容山坡等地形，不用来形容行业。"}], "explanations": {"发展中": "正确：“发展中”指正在变大变好，与“工作机会很多”相合。", "饱和": "语义：“饱和”指已经容纳不下，与“工作机会很多”矛盾。", "冷清": "语义：“冷清”指没有人气，与“工作机会很多”矛盾。", "陡峭": "体貌：“陡峭”形容山坡等地形，不用来形容行业。"}, "sentence_index": 6, "correct_answer": "发展中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座百年古塔早已修好，是一座发展中的塔。", "explanation": "这里应该用〈完工〉。发展中指仍在变化、尚未完成，与“早已修好”的状态矛盾。"}, {"text": "这家店的生意十年没变，是一家发展中的店。", "explanation": "这里应该用〈稳定〉。发展中指仍在变化、尚未完善，与“十年没变”的稳定状态矛盾。"}, {"text": "这个产业早已定型，不会再有大变化，是一个发展中的产业。", "explanation": "这里应该用〈成熟〉。发展中指尚未发展完全，与“早已定型”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇还发展中，每年都有新商店。", "corrected_sentence": "这个小镇还在发展中，每年都有新商店。", "error_description": "漏字：“还在发展中”少了“在”，正确说法是“还在发展中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个发展中地行业，机会很多。", "corrected_sentence": "这是一个发展中的行业，机会很多。", "error_description": "助词错误：修饰名词“行业”应用“的”，不用“地”（“地”用于修饰动词），正确说法是“发展中的行业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
