INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90014, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正在发展的;尚未发展完全的。", "primary_collocate": null, "pronunciation": "fā zhǎn zhōng", "ipa": "fa˥ ʈʂan˨˩˦ ʈʂʊŋ˥", "syllable_count": 3, "sentences": [{"text": "很多发展中的国家，都想让孩子多读书。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展中的国家，常常需要别人帮助。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家还在发展中，路和桥都不多。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是发展中的地区，医院还不够多。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展中的经济，需要很多钱和人。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些发展中的城市，水电都还不够用。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展中的技术还不成熟，价格也很高。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国家还处在发展中，还有很多事要做。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她来自一个发展中的小国家。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发展中的市场，法律和规则还不够完善。", "target_word": "发展中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "正在发展、还不完善的国家、地区或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发展中", "is_correct": true, "explanation": "正确：“发展中”指正在发展、尚未完善的国家，与“都想让孩子多读书”的语境相合。"}, {"text": "单身", "is_correct": false, "explanation": "语义：“单身”指个人未婚，不用来形容国家。"}, {"text": "透明", "is_correct": false, "explanation": "体貌：“透明”形容物体，不用来形容国家。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来说国家。"}], "explanations": {"发展中": "正确：“发展中”指正在发展、尚未完善的国家，与“都想让孩子多读书”的语境相合。", "单身": "语义：“单身”指个人未婚，不用来形容国家。", "透明": "体貌：“透明”形容物体，不用来形容国家。", "甜": "搭配：“甜”形容味道，不用来说国家。"}, "sentence_index": 0, "correct_answer": "发展中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家很富有，各方面都很完善，是一个发展中的国家。", "explanation": "这里应该用〈发达〉。发展中指尚未发展完全，与“各方面都很完善”的富有国家矛盾。"}, {"text": "这套制度三年前就完成了修订，是一套发展中的制度。", "explanation": "这里应该用〈完善〉。发展中指尚未发展完全，与“完成了修订”的状态矛盾。"}, {"text": "这项技术已经用了几十年，非常成熟，是一项发展中的技术。", "explanation": "这里应该用〈成熟〉。发展中指尚未发展完全，与“已经用了几十年，非常成熟”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发展中", "is_correct": true, "explanation": "正确：“发展中”指还不完善、仍在发展，与“技术还不成熟”相合。"}, {"text": "老式", "is_correct": false, "explanation": "语义：“老式”指旧式的样子，与“技术还不成熟”的状态不合。"}, {"text": "晴朗", "is_correct": false, "explanation": "体貌：“晴朗”形容天气，不用来形容技术。"}, {"text": "幽默", "is_correct": false, "explanation": "搭配：“幽默”形容人或言语，不用来形容技术。"}], "explanations": {"发展中": "正确：“发展中”指还不完善、仍在发展，与“技术还不成熟”相合。", "老式": "语义：“老式”指旧式的样子，与“技术还不成熟”的状态不合。", "晴朗": "体貌：“晴朗”形容天气，不用来形容技术。", "幽默": "搭配：“幽默”形容人或言语，不用来形容技术。"}, "sentence_index": 6, "correct_answer": "发展中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家早就很富裕，经济非常发达，是一个发展中的国家。", "explanation": "这里应该用〈发达〉。发展中指尚未发展完全，与“经济非常发达”矛盾。"}, {"text": "这家老店十年没换过菜单，是一家发展中的店。", "explanation": "这里应该用〈稳定〉。发展中指尚未发展完全、仍在变化，与“十年没换过菜单”矛盾。"}, {"text": "这个市场早已定型，价格也从不变动，是一个发展中的市场。", "explanation": "这里应该用〈成熟〉。发展中指尚未发展完全，与“早已定型”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区仍发展中，城市建设还不完善。", "corrected_sentence": "这个地区仍在发展中，城市建设还不完善。", "error_description": "漏字：“仍在发展中”少了“在”，正确说法是“仍在发展中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个发展中地国家，经济发展很快。", "corrected_sentence": "这是一个发展中的国家，经济发展很快。", "error_description": "助词错误：修饰名词“国家”应用“的”，不用“地”（“地”用于修饰动词），正确说法是“发展中的国家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90015, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音或情绪平和，与“沮丧”不是反义关系。"}, {"text": "振奋", "is_correct": true, "explanation": "“振奋”指精神饱满、情绪高涨，与“沮丧”意思相反。"}, {"text": "冷清", "is_correct": false, "explanation": "“冷清”指冷落、没有人气，与“沮丧”不是反义关系。"}, {"text": "高明", "is_correct": false, "explanation": "“高明”指水平高、见解好，与“沮丧”没有反义关系。"}], "correct_answer": "振奋", "explanations": {"安静": "“安静”指没有声音或情绪平和，与“沮丧”不是反义关系。", "振奋": "“振奋”指精神饱满、情绪高涨，与“沮丧”意思相反。", "冷清": "“冷清”指冷落、没有人气，与“沮丧”不是反义关系。", "高明": "“高明”指水平高、见解好，与“沮丧”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90015, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多、有声音，与“沮丧”不是反义关系。"}, {"text": "振奋", "is_correct": true, "explanation": "“振奋”指精神饱满、情绪高涨，与“沮丧”意思相反。"}, {"text": "正确", "is_correct": false, "explanation": "“正确”指符合事实或标准，与“沮丧”没有反义关系。"}, {"text": "富裕", "is_correct": false, "explanation": "“富裕”指钱财多，与“沮丧”没有反义关系。"}], "correct_answer": "振奋", "explanations": {"热闹": "“热闹”指人多、有声音，与“沮丧”不是反义关系。", "振奋": "“振奋”指精神饱满、情绪高涨，与“沮丧”意思相反。", "正确": "“正确”指符合事实或标准，与“沮丧”没有反义关系。", "富裕": "“富裕”指钱财多，与“沮丧”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90015, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "沮丧是说心里很难过，什么也不想做。", "primary_collocate": null, "pronunciation": "jǔ sàng", "ipa": "tɕy˨˩˦ sɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "考试没考好，他很沮丧。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她沮丧地坐在床上，什么也不想做。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，大家都很沮丧。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他丢了工作，心情特别沮丧。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到成绩，弟弟沮丧得不想吃饭。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别沮丧，明天会更好。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友走了，她沮丧了好几天。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沮丧地低着头，一句话也不说。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天很沮丧，不想出门。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让他沮丧过，但他没有放弃。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很沮丧", "label": "程度副词+形容词"}, {"form": "沮丧地", "label": "状语形式"}, {"form": "沮丧了", "label": "体标（了）"}, {"form": "沮丧过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "沮丧：心里难过，提不起劲做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开心", "is_correct": false, "explanation": "语义：“开心”表示高兴，与“没考好”的情绪相反。"}, {"text": "沮丧", "is_correct": true, "explanation": "“沮丧”表示心里难过、提不起劲，与“没考好”的情绪相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌好看，不能用来形容心情。"}, {"text": "得意", "is_correct": false, "explanation": "语义：“得意”表示自满、高兴，考试没考好时不会这样形容。"}], "explanations": {"开心": "语义：“开心”表示高兴，与“没考好”的情绪相反。", "沮丧": "“沮丧”表示心里难过、提不起劲，与“没考好”的情绪相符。", "漂亮": "体貌：“漂亮”形容外貌好看，不能用来形容心情。", "得意": "语义：“得意”表示自满、高兴，考试没考好时不会这样形容。"}, "sentence_index": 0, "correct_answer": "沮丧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛赢了，大家都很沮丧。", "explanation": "这里应该用〈兴奋〉。“沮丧”表示心里难过、什么也不想做，与赢了比赛的欢快场面矛盾，应该用“兴奋”。"}, {"text": "收到录取通知书，他很沮丧。", "explanation": "这里应该用〈高兴〉。收到录取通知是好消息，“沮丧”表示灰心低落，与此矛盾，应该用“高兴”。"}, {"text": "全家人为这个好消息沮丧地庆祝起来。", "explanation": "这里应该用〈欢欣〉。“沮丧”表示灰心低落，与“庆祝”的喜悦矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多形容表演、比赛，不能用来形容人的心情。"}, {"text": "沮丧", "is_correct": true, "explanation": "“沮丧”表示心里难过，符合朋友离开后的情绪。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说的是智力，不是心情，与“朋友走了”的情境不符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来形容心情。"}], "explanations": {"精彩": "搭配：“精彩”多形容表演、比赛，不能用来形容人的心情。", "沮丧": "“沮丧”表示心里难过，符合朋友离开后的情绪。", "聪明": "语义：“聪明”说的是智力，不是心情，与“朋友走了”的情境不符。", "高大": "体貌：“高大”形容身材，不能用来形容心情。"}, "sentence_index": 6, "correct_answer": "沮丧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面试前，他很沮丧，满脸都是自信。", "explanation": "这里应该用〈自信〉。“沮丧”表示灰心失望，与“满脸自信”的神情矛盾。"}, {"text": "看到蛇，她沮丧得大叫起来。", "explanation": "这里应该用〈害怕〉。“沮丧”是灰心失望，不表示受惊，描写看到蛇时的反应要用“害怕”。"}, {"text": "生日那天，他笑得合不拢嘴，满脸沮丧。", "explanation": "这里应该用〈开心〉。“沮丧”表示灰心低落，与笑得合不拢嘴的样子矛盾，这种场合要用“开心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她沮丧了地躺在床上，什么也不想做。", "corrected_sentence": "她沮丧地躺在床上，什么也不想做。", "error_description": "“了”表示变化或完成，不能插在状语“地”之前；“沮丧地”之后不用“了”，应去掉“了”，改为“沮丧地躺在床上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我曾经为这件事沮丧了过。", "corrected_sentence": "我曾经为这件事沮丧过。", "error_description": "表示经历的“过”前面不能再加“了”，“沮丧”后只用“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
