INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90016, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "灰心失望，精神不振。", "primary_collocate": null, "pronunciation": "jǔ sàng", "ipa": "tɕy˨˩˦ sɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "失败以后，他的样子很沮丧。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一脸沮丧，没有一点精神。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队输了，球员们沮丧地回家了。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没找到工作，她感到有些沮丧。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话让沮丧的学生又有了信心。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，爸爸的声音很沮丧。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沮丧地说：“我又失败了。”", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么沮丧，再试一次吧。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们输了比赛，心里十分沮丧。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她因为没得奖而沮丧了一整天。", "target_word": "沮丧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "很沮丧", "label": "程度副词+形容词"}, {"form": "沮丧地", "label": "状语形式"}, {"form": "沮丧了", "label": "体标（了）"}, {"form": "十分沮丧", "label": "程度副词+形容词"}], "register": "中性", "sense_fingerprint": "沮丧：灰心失望，没有精神", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb690da-b4fb-44a8-8915-e03b8c08ddd6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得意", "is_correct": false, "explanation": "语义：“得意”表示自满、高兴，失败以后不会这样形容样子。"}, {"text": "沮丧", "is_correct": true, "explanation": "“沮丧”表示灰心失望，与“失败以后”的样子相符。"}, {"text": "神气", "is_correct": false, "explanation": "语义：“神气”形容意气风发，与“失败以后”的情境矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌好看，与“失败以后”的情境矛盾。"}], "explanations": {"得意": "语义：“得意”表示自满、高兴，失败以后不会这样形容样子。", "沮丧": "“沮丧”表示灰心失望，与“失败以后”的样子相符。", "神气": "语义：“神气”形容意气风发，与“失败以后”的情境矛盾。", "漂亮": "体貌：“漂亮”形容外貌好看，与“失败以后”的情境矛盾。"}, "sentence_index": 0, "correct_answer": "沮丧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到获奖的消息，沮丧得说不出话。", "explanation": "这里应该用〈激动〉。“沮丧”表示灰心失望、精神不振，与获奖的喜讯矛盾，表达兴奋的心情要用“激动”。"}, {"text": "孩子看到新玩具，沮丧得蹦了起来。", "explanation": "这里应该用〈高兴〉。“沮丧”表示灰心失望，不能描写看到新玩具时蹦跳的样子，那种欢喜要用“高兴”。"}, {"text": "她接到录取电话，沮丧地跳了起来。", "explanation": "这里应该用〈惊喜〉。“沮丧”表示灰心失望、精神不振，与接到录取电话时跳起来的情形矛盾，应该用“惊喜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欢快", "is_correct": false, "explanation": "语义：“欢快”表示轻松愉快，与“我又失败了”的情绪相反。"}, {"text": "沮丧", "is_correct": true, "explanation": "“沮丧”修饰说话的样子，表示失落地说，与“我又失败了”相符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来修饰说话的样子。"}, {"text": "精彩", "is_correct": false, "explanation": "搭配：“精彩”多形容表演、比赛，不用来修饰说话的方式。"}], "explanations": {"欢快": "语义：“欢快”表示轻松愉快，与“我又失败了”的情绪相反。", "沮丧": "“沮丧”修饰说话的样子，表示失落地说，与“我又失败了”相符。", "高大": "体貌：“高大”形容身材，不能用来修饰说话的样子。", "精彩": "搭配：“精彩”多形容表演、比赛，不用来修饰说话的方式。"}, "sentence_index": 6, "correct_answer": "沮丧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他提前交了卷，神情沮丧，笑个不停。", "explanation": "这里应该用〈开心〉。“沮丧”表示灰心失望，与“笑个不停”的神情矛盾。"}, {"text": "听到巨响，她沮丧得大叫起来。", "explanation": "这里应该用〈害怕〉。“沮丧”是灰心失望，不表示受惊，听到巨响时的反应要用“害怕”。"}, {"text": "他在比赛中大获全胜，神情沮丧。", "explanation": "这里应该用〈兴奋〉。“沮丧”表示灰心失望、精神不振，与大获全胜的场面矛盾，应该用“兴奋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直沮丧了地坐着，说不出话来。", "corrected_sentence": "他一直沮丧地坐着，说不出话来。", "error_description": "“了”表示变化或完成，不能插在状语“地”之前；“沮丧地”之后不用“了”，应去掉“了”，改为“沮丧地坐着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经为这次失败沮丧了过。", "corrected_sentence": "他曾经为这次失败沮丧过。", "error_description": "表示经历的“过”前面不能再加“了”，“沮丧”后只用“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76607606-6e39-4c84-a6b7-1de66783a6f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90020, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90020, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90020, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示已经明白或收到消息。", "primary_collocate": null, "pronunciation": "zhī dào le", "ipa": "tʂʅ˥ taʊ˥˩ lə", "syllable_count": 3, "sentences": [{"text": "老师说:“明天八点上课。”我说:“知道了。”", "target_word": "知道了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈发来短信:“晚上不回家吃饭。”我回:“知道了。”", "target_word": "知道了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“请把文件今天发给我。”“知道了,马上发。”", "target_word": "知道了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说会议改到下午,小王回了一句“知道了”。", "target_word": "知道了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生告诉他:“药要饭后吃。”他点点头说:“知道了。”", "target_word": "知道了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说:“别忘了带伞。”我答:“知道了,谢谢。”", "target_word": "知道了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在群里看到通知,回了一句:知道了。", "target_word": "知道了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“楼下有人找你。”“知道了,我马上下去。”", "target_word": "知道了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说:“这份报告明天要交。”小李说:“知道了。”", "target_word": "知道了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说:“六点前回家。”我说:“知道了。”", "target_word": "知道了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "收到别人的通知或吩咐后的回答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116634ea-fcb5-448e-abe0-203c2273568d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "知道了", "is_correct": true, "explanation": "正确。表示收到通知、明白了，与老师“明天八点上课”的通知相呼应。"}, {"text": "不知道", "is_correct": false, "explanation": "语义：说“不知道”表示没有接收到信息，与收到通知后的回应相反。"}, {"text": "对不起", "is_correct": false, "explanation": "语义：对不起用于道歉，老师只是通知时间，没有需要道歉的事。"}, {"text": "请问", "is_correct": false, "explanation": "配价：请问要引出一个问题，而这里是对通知的回答，没有问题可问。"}], "explanations": {"知道了": "正确。表示收到通知、明白了，与老师“明天八点上课”的通知相呼应。", "不知道": "语义：说“不知道”表示没有接收到信息，与收到通知后的回应相反。", "对不起": "语义：对不起用于道歉，老师只是通知时间，没有需要道歉的事。", "请问": "配价：请问要引出一个问题，而这里是对通知的回答，没有问题可问。"}, "sentence_index": 0, "correct_answer": "知道了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师问我这道题做不做得出来，我说：知道了。", "explanation": "这里应该用〈能〉。知道了表示已明白或收到消息，不表示有能力把题做出来。"}, {"text": "我不小心踩了他一脚，赶紧说：知道了。", "explanation": "这里应该用〈对不起〉。知道了是收到消息后的回应，不能用来道歉。"}, {"text": "我问他这道菜好不好吃，他只说：知道了。", "explanation": "这里应该用〈好吃〉。知道了只表示收到消息，不能用来回答对味道的评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "知道了", "is_correct": true, "explanation": "正确。表示看到通知后已经明白，与“回了一句”的简短回复相符。"}, {"text": "哼", "is_correct": false, "explanation": "语义：哼表示不满或轻蔑，用来回应一条普通通知语义不合。"}, {"text": "呸", "is_correct": false, "explanation": "语义：呸表示唾弃、厌恶，与平静地看到通知后的回应完全不符。"}, {"text": "嘿", "is_correct": false, "explanation": "语义：嘿多用于招呼或引起注意，不是对通知内容的回应。"}], "explanations": {"知道了": "正确。表示看到通知后已经明白，与“回了一句”的简短回复相符。", "哼": "语义：哼表示不满或轻蔑，用来回应一条普通通知语义不合。", "呸": "语义：呸表示唾弃、厌恶，与平静地看到通知后的回应完全不符。", "嘿": "语义：嘿多用于招呼或引起注意，不是对通知内容的回应。"}, "sentence_index": 6, "correct_answer": "知道了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "第一次见到新同事，我笑着说：知道了。", "explanation": "这里应该用〈你好〉。知道了是对通知或吩咐的回应，不能用来打招呼。"}, {"text": "你是不是去过北京？他只回了一句：知道了。", "explanation": "这里应该用〈是〉。知道了不能直接回答是非问题，要回答是或不是。"}, {"text": "我送他一份礼物，他只说了一句：知道了。", "explanation": "这里应该用〈谢谢〉。知道了是对消息的回应，不能用来表达对礼物的感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长通知我们下午开会，我回答：“知道了了。”", "corrected_sentence": "班长通知我们下午开会，我回答：“知道了。”", "error_description": "“知道了”后多加了一个“了”，错误形式是“知道了了”，正确形式是“知道了”。叹词“知道了”本身已含完成语气，不能再叠加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "值日表贴出来了，我抬头回答：“知道了的。”", "corrected_sentence": "值日表贴出来了，我抬头回答：“知道了。”", "error_description": "错误：“知道了”后多加了“的”，写成“知道了的”。叹词“知道了”已是完整的应答语，不能再接“的”，应说“知道了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
