INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90021, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法名是和尚或尼姑出家以后起的新名字。", "primary_collocate": null, "pronunciation": "fǎ míng", "ipa": "fa²¹⁴ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "小明的叔叔出家当了和尚，有了法名。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个法名很好听，意思也很好。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还没有法名，大家叫他小师父。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问问师父，您的法名是什么？", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出家后，家人只能叫她的法名。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大师的法名很少有人知道。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法名是出家人的新名字。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的法名是师父亲自起的。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上写着这位高僧的法名。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受戒那天，她得到了一个法名。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "和尚或尼姑出家后起的新名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '473ad9c2-ea4f-48b1-a923-c5dcf69bac63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90021, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学号", "is_correct": false, "explanation": "语义：“学号”是学生的编号，出家当和尚的人不会有学号。"}, {"text": "书号", "is_correct": false, "explanation": "语义：“书号”是图书的编号，不是人的称谓，与出家情境不符。"}, {"text": "法名", "is_correct": true, "explanation": "法名是和尚出家后起的新名字，与“出家当了和尚”相合。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：“芳名”是敬称他人姓名的书面用语，用在叙述叔叔出家的句子里不协调。"}], "explanations": {"学号": "语义：“学号”是学生的编号，出家当和尚的人不会有学号。", "书号": "语义：“书号”是图书的编号，不是人的称谓，与出家情境不符。", "法名": "法名是和尚出家后起的新名字，与“出家当了和尚”相合。", "芳名": "语域：“芳名”是敬称他人姓名的书面用语，用在叙述叔叔出家的句子里不协调。"}, "sentence_index": 0, "correct_answer": "法名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想问问这只猫，它的法名是什么？", "explanation": "这里应该用〈名字〉。法名只用于出家人，动物的名字要说名字。"}, {"text": "这本书的法名很有意思，大家都爱读。", "explanation": "这里应该用〈书名〉。法名只用于出家人，书的名称要说书名。"}, {"text": "这首歌的法名很好听，大家都爱唱。", "explanation": "这里应该用〈歌名〉。法名只用于出家人，歌曲的名称要说歌名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90021, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "账号", "is_correct": false, "explanation": "语义：“账号”是网络或银行使用的号码，不能作为出家人的新名字。"}, {"text": "车牌", "is_correct": false, "explanation": "语义：“车牌”是车辆登记的牌照，与出家人的名字无关。"}, {"text": "尊姓", "is_correct": false, "explanation": "语域：“尊姓”是敬辞，用于询问或称呼他人的姓氏，不能指出家人的新名字。"}, {"text": "法名", "is_correct": true, "explanation": "法名是出家人的新名字，与“出家人的新名字”这一定义相合。"}], "explanations": {"账号": "语义：“账号”是网络或银行使用的号码，不能作为出家人的新名字。", "车牌": "语义：“车牌”是车辆登记的牌照，与出家人的名字无关。", "尊姓": "语域：“尊姓”是敬辞，用于询问或称呼他人的姓氏，不能指出家人的新名字。", "法名": "法名是出家人的新名字，与“出家人的新名字”这一定义相合。"}, "sentence_index": 6, "correct_answer": "法名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那天，我家的小狗得到了一个法名。", "explanation": "这里应该用〈名字〉。法名只授予出家人，给小狗起的叫名字。"}, {"text": "那天，我的新车得到了一个法名。", "explanation": "这里应该用〈昵称〉。法名只授予出家人，车的昵称要说昵称。"}, {"text": "那天，院子里的那棵树得到了一个法名。", "explanation": "这里应该用〈别名〉。法名只授予出家人，植物的别名要说别名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90021, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经有了一只法名，大家都叫他师兄。", "corrected_sentence": "他已经有了一个法名，大家都叫他师兄。", "error_description": "量词用错：“法名”应用量词“个”，“只”多用于动物或成对的东西，不能修饰法名。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90021, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她刚出家，师父就给她取了一块法名。", "corrected_sentence": "她刚出家，师父就给她取了一个法名。", "error_description": "量词用错：“法名”应用量词“个”，“块”用于块状的东西，不能修饰法名。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
