INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "出家人皈依佛门后另取的名字。", "primary_collocate": null, "pronunciation": "fǎ míng", "ipa": "fa²¹⁴ miŋ³⁵", "syllable_count": 2, "sentences": [{"text": "他出家以后，师父给他起了一个法名。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老和尚的法名叫慧明。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在寺里受戒后有了新的法名。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这位尼姑的法名吗？", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他俗名叫王强，法名叫净空。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师父为什么给你取这个法名？", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寺里的僧人都用法名，不用以前的名字。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的法名里有一个“慧”字。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还俗以后，就不再用法名了。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上写着很多僧人的法名。", "target_word": "法名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "出家人皈依佛门后所取的新名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '473ad9c2-ea4f-48b1-a923-c5dcf69bac63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书名", "is_correct": false, "explanation": "语义：“书名”是书的名称，不能用来称呼人，师父不会给僧人起书名。"}, {"text": "法名", "is_correct": true, "explanation": "法名是出家人皈依佛门后另取的名字，与“出家以后，师父给他起了一个”相合。"}, {"text": "学号", "is_correct": false, "explanation": "语义：“学号”是学生的编号，与出家人由师父取名的情境不相关。"}, {"text": "车牌", "is_correct": false, "explanation": "搭配：“起”后接名字、名号，不说“起车牌”，车牌是登记后发放的。"}], "explanations": {"书名": "语义：“书名”是书的名称，不能用来称呼人，师父不会给僧人起书名。", "法名": "法名是出家人皈依佛门后另取的名字，与“出家以后，师父给他起了一个”相合。", "学号": "语义：“学号”是学生的编号，与出家人由师父取名的情境不相关。", "车牌": "搭配：“起”后接名字、名号，不说“起车牌”，车牌是登记后发放的。"}, "sentence_index": 0, "correct_answer": "法名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他给家里的小狗取了一个法名，每天都这么叫它。", "explanation": "这里应该用〈名字〉。法名只授予出家人，给宠物取的名字要说名字。"}, {"text": "这辆老车的法名很有意思，大家都叫它老伙计。", "explanation": "这里应该用〈外号〉。法名只授予出家人，车辆的别称要说外号。"}, {"text": "这家饭馆的法名很响亮，大家都记得。", "explanation": "这里应该用〈店名〉。法名只授予出家人，饭馆的名称要说店名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工号", "is_correct": false, "explanation": "语义：“工号”是员工的编号，僧人不用工号，与“不用以前的名字”的对照也不成立。"}, {"text": "门牌", "is_correct": false, "explanation": "搭配：“用”后接的是名字或称呼，“门牌”是挂在门上的标牌，不能用来称呼僧人。"}, {"text": "法名", "is_correct": true, "explanation": "法名是出家人皈依后另取的名字，与“寺里的僧人”“不用以前的名字”相合。"}, {"text": "账号", "is_correct": false, "explanation": "语义：“账号”是网络或银行使用的号码，与僧人的称谓无关。"}], "explanations": {"工号": "语义：“工号”是员工的编号，僧人不用工号，与“不用以前的名字”的对照也不成立。", "门牌": "搭配：“用”后接的是名字或称呼，“门牌”是挂在门上的标牌，不能用来称呼僧人。", "法名": "法名是出家人皈依后另取的名字，与“寺里的僧人”“不用以前的名字”相合。", "账号": "语义：“账号”是网络或银行使用的号码，与僧人的称谓无关。"}, "sentence_index": 6, "correct_answer": "法名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座村子的法名很好听，是村里的老人起的。", "explanation": "这里应该用〈地名〉。法名只授予出家人，村庄的名字要说地名。"}, {"text": "这株牡丹的法名很好听，是园丁起的。", "explanation": "这里应该用〈名字〉。法名只授予出家人，园丁给花起的叫名字。"}, {"text": "这辆车的法名很响亮，每天都有人来看。", "explanation": "这里应该用〈品牌〉。法名只授予出家人，汽车的牌子要说品牌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位僧人刚出家，还没有一条法名。", "corrected_sentence": "这位僧人刚出家，还没有一个法名。", "error_description": "量词用错：“法名”的量词应为“个”，“条”用于细长的东西，不能修饰法名。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位僧人在寺里有了一位法名。", "corrected_sentence": "这位僧人在寺里有了一个法名。", "error_description": "量词用错：“法名”不指人，应用量词“个”；“位”用于人，不能修饰法名。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90024, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "资本主义", "is_correct": true, "explanation": "正确：资本主义与社会主义在所有制和制度上相对，是一对反义词。"}, {"text": "经济", "is_correct": false, "explanation": "与社会主义无反义关系，“经济”是宽泛的概念，不构成对立。"}, {"text": "语言", "is_correct": false, "explanation": "与社会主义无反义关系，二者不构成对立。"}, {"text": "历史", "is_correct": false, "explanation": "与社会主义无反义关系，不是对立概念。"}], "correct_answer": "资本主义", "explanations": {"资本主义": "正确：资本主义与社会主义在所有制和制度上相对，是一对反义词。", "经济": "与社会主义无反义关系，“经济”是宽泛的概念，不构成对立。", "语言": "与社会主义无反义关系，二者不构成对立。", "历史": "与社会主义无反义关系，不是对立概念。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90024, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "资本主义", "is_correct": true, "explanation": "正确：资本主义与社会主义在所有制和制度上相对，是一对反义词。"}, {"text": "数学", "is_correct": false, "explanation": "与社会主义无反义关系，二者属于不同领域，不构成对立。"}, {"text": "文学", "is_correct": false, "explanation": "与社会主义无反义关系，不是对立概念。"}, {"text": "教育", "is_correct": false, "explanation": "与社会主义无反义关系，不是对立概念。"}], "correct_answer": "资本主义", "explanations": {"资本主义": "正确：资本主义与社会主义在所有制和制度上相对，是一对反义词。", "数学": "与社会主义无反义关系，二者属于不同领域，不构成对立。", "文学": "与社会主义无反义关系，不是对立概念。", "教育": "与社会主义无反义关系，不是对立概念。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以生产资料公有制为基础的社会制度及其理论。", "primary_collocate": null, "pronunciation": "shè huì zhǔ yì", "ipa": "ʂɤ˥˩ xweɪ˥˩ ʈʂu˨˩˦ i˥˩", "syllable_count": 4, "sentences": [{"text": "社会主义是一种社会制度。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里学习社会主义理论。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国实行社会主义制度。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会主义以公有制为基础。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了社会主义的历史。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会主义和资本主义有什么不同？", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家曾经实行过社会主义。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社会主义思想在很多国家出现过。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，社会主义理论来自一百多年前。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对社会主义理论很有研究。", "target_word": "社会主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "社會主義", "label": "繁体"}, {"form": "社会主义国家", "label": "复合"}, {"form": "社会主义制度", "label": "复合"}], "register": "书面", "sense_fingerprint": "以公有制为基础的社会制度和理论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bac65704-61f2-44c4-864d-746c99e18fbc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "社会主义", "is_correct": true, "explanation": "正确：“社会主义是一种社会制度”说明它是社会制度，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是社会制度，“天气是一种社会制度”不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，不能说是社会制度。"}, {"text": "书法", "is_correct": false, "explanation": "搭配：“社会制度”不能与“书法”这类技艺搭配，“书法是一种社会制度”不成立。"}], "explanations": {"社会主义": "正确：“社会主义是一种社会制度”说明它是社会制度，与句意相符。", "天气": "语义：天气是自然现象，不是社会制度，“天气是一种社会制度”不通。", "水果": "语义：水果是食物，不能说是社会制度。", "书法": "搭配：“社会制度”不能与“书法”这类技艺搭配，“书法是一种社会制度”不成立。"}, "sentence_index": 0, "correct_answer": "社会主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天骑社会主义上班。", "explanation": "这里应该用〈自行车〉。社会主义是制度或理论，不能被骑；“他每天骑自行车上班”才自然。"}, {"text": "他擅长修社会主义。", "explanation": "这里应该用〈汽车〉。社会主义是制度或理论，不能用来修理；“他擅长修汽车”才自然。"}, {"text": "社会主义是用木头盖的。", "explanation": "这里应该用〈房子〉。社会主义是制度或理论，不能说它是用木头盖的；“这座房子是用木头盖的”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "社会主义", "is_correct": true, "explanation": "正确：“曾经实行过社会主义”指这个国家实行过这一制度，与句意相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能被“实行”，句子要求的是制度或政策。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：篮球是体育运动，不能说“实行篮球”，句子要求的是制度或政策。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能被“实行”，句子要求的是制度或政策。"}], "explanations": {"社会主义": "正确：“曾经实行过社会主义”指这个国家实行过这一制度，与句意相符。", "钢琴": "语义：钢琴是乐器，不能被“实行”，句子要求的是制度或政策。", "篮球": "搭配：篮球是体育运动，不能说“实行篮球”，句子要求的是制度或政策。", "饺子": "语义：饺子是食物，不能被“实行”，句子要求的是制度或政策。"}, "sentence_index": 6, "correct_answer": "社会主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都弹社会主义。", "explanation": "这里应该用〈钢琴〉。社会主义是制度或理论，不能弹奏；“他每天都弹钢琴”才自然。"}, {"text": "这个国家的社会主义很多，城市也很大。", "explanation": "这里应该用〈人口〉。社会主义是制度或理论，不能用“很多”来计数；“这个国家的人口很多”才自然。"}, {"text": "他的研究重点是社会主义的习性。", "explanation": "这里应该用〈猫〉。社会主义是制度与理论，没有习性，不能作为研究对象这样搭配；“他的研究重点是猫的习性”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中国实行的是一只社会主义。", "corrected_sentence": "中国实行的是一种社会主义。", "error_description": "错误：量词用错。“社会主义”前应用“种”，“只”不能用于抽象名词。正确说法：中国实行的是一种社会主义。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对一座社会主义有研究。", "corrected_sentence": "他对一种社会主义有研究。", "error_description": "错误：量词用错。“社会主义”前应用“种”，“座”用于山、房屋等大型物体，不能用于它。正确说法：他对一种社会主义有研究。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c9bbf2c-48dd-4bf0-bde4-881af9f8d7f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
