INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消化是吃下去的东西在肚子里变成身体需要的东西。", "primary_collocate": null, "pronunciation": "xiāo huà", "ipa": "ɕjɑʊ˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "吃得太快，东西不容易消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上吃太多，胃很难消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶喝多了，他消化不好。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人胃口差，消化也慢。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭走一走，帮助消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米饭比面包好消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果能帮助消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肚子里的饭还没消化完。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了药，东西才消化了。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子刚吃过饭，不要马上跑步，让食物慢慢消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消化了", "label": "体标"}, {"form": "消化过", "label": "体标"}, {"form": "消化不良", "label": "复合"}, {"form": "消化系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "食物在肚子里被身体吸收，常说好消化、不容易消化、帮助消化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90027, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消化", "is_correct": true, "explanation": "消化：食物在肚子里被分解，变成身体需要的东西。"}, {"text": "笑话", "is_correct": false, "explanation": "xiào（第四声）与 xiāo（第一声）声调不同，意思是可笑的话或故事。"}, {"text": "小花", "is_correct": false, "explanation": "xiǎo huā 与 xiāo huà 两个字声调都不同，意思是小的花朵。"}, {"text": "乡话", "is_correct": false, "explanation": "xiāng 与 xiāo 韵母不同（ang 与 ao），意思是某地的土话或方言。"}], "explanations": {"消化": "消化：食物在肚子里被分解，变成身体需要的东西。", "笑话": "xiào（第四声）与 xiāo（第一声）声调不同，意思是可笑的话或故事。", "小花": "xiǎo huā 与 xiāo huà 两个字声调都不同，意思是小的花朵。", "乡话": "xiāng 与 xiāo 韵母不同（ang 与 ao），意思是某地的土话或方言。"}, "sentence_index": null, "correct_answer": "消化"}, "level_3": {"options": [{"text": "消化", "is_correct": true, "explanation": "消化：食物在肚子里被分解吸收，“不容易消化”说的正是这种情况。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“消失”指不见了，不是食物在肠胃里的变化。"}, {"text": "消毒", "is_correct": false, "explanation": "搭配：“消毒”针对细菌或器具，不用来指吃进肚子里的食物的变化。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：“消灭”指彻底去除，与食物在肚子里的变化不符。"}], "explanations": {"消化": "消化：食物在肚子里被分解吸收，“不容易消化”说的正是这种情况。", "消失": "语义：“消失”指不见了，不是食物在肠胃里的变化。", "消毒": "搭配：“消毒”针对细菌或器具，不用来指吃进肚子里的食物的变化。", "消灭": "语义：“消灭”指彻底去除，与食物在肚子里的变化不符。"}, "sentence_index": 0, "correct_answer": "消化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块海绵很快就消化了很多水。", "explanation": "这里应该用〈吸收〉。消化指食物在消化器官里被分解，海绵没有消化器官，不能说“消化水”。"}, {"text": "跑步会消化很多能量。", "explanation": "这里应该用〈消耗〉。消化是食物被分解吸收，跑步用掉能量要说消耗。"}, {"text": "木头在炉子里慢慢消化成灰。", "explanation": "这里应该用〈燃烧〉。木头变成灰是燃烧的结果，消化只指食物在消化器官里被分解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消化", "is_correct": true, "explanation": "消化：食物在消化器官中分解吸收，“帮助消化”正指这一过程。"}, {"text": "消散", "is_correct": false, "explanation": "语义：“消散”指散开不见，不能用来说明水果对肠胃的作用。"}, {"text": "消磨", "is_correct": false, "explanation": "语义：“消磨”指耗费时间或意志，与水果帮助肠胃的作用不符。"}, {"text": "消沉", "is_correct": false, "explanation": "语义：“消沉”形容情绪低落，不能用来说明水果对肠胃的作用。"}], "explanations": {"消化": "消化：食物在消化器官中分解吸收，“帮助消化”正指这一过程。", "消散": "语义：“消散”指散开不见，不能用来说明水果对肠胃的作用。", "消磨": "语义：“消磨”指耗费时间或意志，与水果帮助肠胃的作用不符。", "消沉": "语义：“消沉”形容情绪低落，不能用来说明水果对肠胃的作用。"}, "sentence_index": 6, "correct_answer": "消化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "身体会把没用的东西消化出去。", "explanation": "这里应该用〈排泄〉。消化是把食物分解吸收，把没用的东西排出体外要说排泄。"}, {"text": "冰糖在热水里很快就消化了。", "explanation": "这里应该用〈溶解〉。消化指食物在体内被分解，糖在水里变化要说溶解。"}, {"text": "妈妈用扫帚消化了地上的落叶。", "explanation": "这里应该用〈清扫〉。落叶被扫走要说清扫，消化只指食物在体内被分解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种肉太硬，老人消化了不了。", "corrected_sentence": "这种肉太硬，老人消化不了。", "error_description": "补语位置错误：可能补语应说“消化不了”，“了”不能插在“消化”和“不”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "油腻的东西他消化不。", "corrected_sentence": "油腻的东西他消化不了。", "error_description": "可能补语缺失：表示做不到应说“消化不了”，只说“消化不”不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
