INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消化是把学到的知识或内容真正理解、吸收，变成自己的东西。", "primary_collocate": null, "pronunciation": "xiāo huà", "ipa": "ɕjɑʊ˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "这些知识太多，我还没消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课上讲的内容，回家要慢慢消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一课的内容很多，我要消化几天。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我读了三遍，才消化书里的内容。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书太难，我一时消化不了。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些新词太多，一天消化不了。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么难的理论，他要花很久才能消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学过的东西要自己消化，才是你的。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学东西很快，新知识一听就能消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完讲座，大家都需要时间消化。", "target_word": "消化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "消化了", "label": "体标"}, {"form": "消化过", "label": "体标"}, {"form": "消化不良", "label": "复合"}, {"form": "消化系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "把学到的知识或内容理解吸收，常说需要时间消化、一时消化不了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da2b175-0892-4efa-beb2-764e85380c6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90028, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "消化", "is_correct": true, "explanation": "消化：理解并吸收所学的知识。"}, {"text": "笑话", "is_correct": false, "explanation": "xiào（第四声）与 xiāo（第一声）声调不同，意思是可笑的话或故事。"}, {"text": "小花", "is_correct": false, "explanation": "xiǎo huā 与 xiāo huà 两个字声调都不同，意思是小的花朵。"}, {"text": "乡话", "is_correct": false, "explanation": "xiāng 与 xiāo 韵母不同（ang 与 ao），意思是某地的土话或方言。"}], "explanations": {"消化": "消化：理解并吸收所学的知识。", "笑话": "xiào（第四声）与 xiāo（第一声）声调不同，意思是可笑的话或故事。", "小花": "xiǎo huā 与 xiāo huà 两个字声调都不同，意思是小的花朵。", "乡话": "xiāng 与 xiāo 韵母不同（ang 与 ao），意思是某地的土话或方言。"}, "sentence_index": null, "correct_answer": "消化"}, "level_3": {"options": [{"text": "消化", "is_correct": true, "explanation": "消化：理解并吸收知识，“还没消化”正指这一过程。"}, {"text": "消散", "is_correct": false, "explanation": "语义：“消散”指散开不见，不能用来说知识没有被理解吸收。"}, {"text": "消遣", "is_correct": false, "explanation": "语义：“消遣”指用来打发时间，与“还没消化”的意思不符。"}, {"text": "消费", "is_correct": false, "explanation": "搭配：“消费”指花钱或用掉物资，不说“还没消费知识”。"}], "explanations": {"消化": "消化：理解并吸收知识，“还没消化”正指这一过程。", "消散": "语义：“消散”指散开不见，不能用来说知识没有被理解吸收。", "消遣": "语义：“消遣”指用来打发时间，与“还没消化”的意思不符。", "消费": "搭配：“消费”指花钱或用掉物资，不说“还没消费知识”。"}, "sentence_index": 0, "correct_answer": "消化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用抹布很快就消化了桌上的污渍。", "explanation": "这里应该用〈擦掉〉。污渍被擦去要说擦掉或清除，消化只指食物被分解或知识被理解。"}, {"text": "土壤很快把雨水消化了。", "explanation": "这里应该用〈吸收〉。土壤吸收雨水要说吸收，消化用于食物被分解或知识被理解。"}, {"text": "他连续工作，体力慢慢被消化了。", "explanation": "这里应该用〈消耗〉。体力被用掉要说消耗，消化用于食物被分解或知识被理解。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "消化", "is_correct": true, "explanation": "消化：理解并吸收知识，“要花很久才能消化”正指这一过程。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是把东西分成块，不能用来指理解知识。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤是加热使食物变熟，不能用来指理解知识。"}, {"text": "消毒", "is_correct": false, "explanation": "搭配：“消毒”针对细菌或器具，不用来指理解知识。"}], "explanations": {"消化": "消化：理解并吸收知识，“要花很久才能消化”正指这一过程。", "切": "语义：切是把东西分成块，不能用来指理解知识。", "烤": "语义：烤是加热使食物变熟，不能用来指理解知识。", "消毒": "搭配：“消毒”针对细菌或器具，不用来指理解知识。"}, "sentence_index": 6, "correct_answer": "消化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽油在发动机里慢慢消化。", "explanation": "这里应该用〈燃烧〉。汽油在发动机里是燃烧释放能量，消化只指食物在消化器官里被分解或知识被理解。"}, {"text": "冰糖在水里慢慢消化。", "explanation": "这里应该用〈溶解〉。冰糖在水里变化要说溶解，消化只用于食物在体内被分解或知识被理解。"}, {"text": "雾气慢慢消化了。", "explanation": "这里应该用〈消散〉。雾气散开要说消散，消化不能用于雾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我要被这一课的内容消化掉。", "corrected_sentence": "我要把这一课的内容消化掉。", "error_description": "“被”误用：“消化”的施事是“我”，应用“把”，说“把这一课的内容消化掉”，不能用“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些知识他消化了得很好。", "corrected_sentence": "这些知识他消化得很好。", "error_description": "体标位置错误：补语“得很好”前不能加“了”，应说“消化得很好”，“消化了得”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4990b749-f19e-4a09-9028-7101cb396695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
