INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90029, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家里爷爷、爸爸、我是不同的一辈，一辈就是一代。", "primary_collocate": null, "pronunciation": "yí dài", "ipa": "i˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我和堂哥是一代人，他只比我大一点。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷和爸爸不是一代人。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家一代比一代高。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家这一代有三个男孩。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的表姐和我是一代人。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家一代传一代，都做老师。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你和你的堂弟是一代人吗？", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这一代孩子都叫他叔叔。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们家，我这一代只有两个人。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和叔叔是一代，我和堂弟是一代。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一代人", "label": "复合词"}, {"form": "下一代", "label": "复合词"}, {"form": "上一代", "label": "复合词"}], "register": "中性", "sense_fingerprint": "家族中的一辈人，如爷爷、爸爸、我各是一代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90029, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一代", "is_correct": true, "explanation": "一代（yí dài）：家族中同一辈的人，如爷爷、爸爸、我各是一代。"}, {"text": "衣袋", "is_correct": false, "explanation": "yī dài 与 yí dài 声调不同，意思是衣服上的口袋。"}, {"text": "一到", "is_correct": false, "explanation": "yí dào 与 yí dài 韵母不同（ao 与 ai），意思是一到达。"}, {"text": "一对", "is_correct": false, "explanation": "yí duì 与 yí dài 韵母不同（ui 与 ai），意思是一双、一对。"}], "explanations": {"一代": "一代（yí dài）：家族中同一辈的人，如爷爷、爸爸、我各是一代。", "衣袋": "yī dài 与 yí dài 声调不同，意思是衣服上的口袋。", "一到": "yí dào 与 yí dài 韵母不同（ao 与 ai），意思是一到达。", "一对": "yí duì 与 yí dài 韵母不同（ui 与 ai），意思是一双、一对。"}, "sentence_index": null, "correct_answer": "一代"}, "level_3": {"options": [{"text": "家族", "is_correct": false, "explanation": "语义：“家族”指整个家族，不能说“是家族人”来表示同一辈。"}, {"text": "一代", "is_correct": true, "explanation": "一代：家族中同一辈的人，我和堂哥同辈，所以是“一代人”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：不能说“是年龄人”。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”指人生阶段，与“一辈人”的概念不同。"}], "explanations": {"家族": "语义：“家族”指整个家族，不能说“是家族人”来表示同一辈。", "一代": "一代：家族中同一辈的人，我和堂哥同辈，所以是“一代人”。", "年龄": "搭配：不能说“是年龄人”。", "童年": "语义：“童年”指人生阶段，与“一辈人”的概念不同。"}, "sentence_index": 0, "correct_answer": "一代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的一代很矮，只到我的肩。", "explanation": "这里应该用〈身高〉。一代不能用来形容个人的身高。"}, {"text": "他在这个厂里干了一代，直到退休。", "explanation": "这里应该用〈一辈子〉。一代指一辈人或某一时期的人，不能表示一个人一生的时间；“干一辈子”要说“一辈子”。"}, {"text": "这份报告的一代很长，没人想读完。", "explanation": "这里应该用〈篇幅〉。一代指一辈人，不能用来形容报告的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年级", "is_correct": false, "explanation": "语义：“年级”指学校的学习阶段，与家族中的一辈人不是同一概念。"}, {"text": "一代", "is_correct": true, "explanation": "一代：家族中同一辈的人，与“你和你的堂弟是……人吗”相符。"}, {"text": "班级", "is_correct": false, "explanation": "语义：“班级”指学校的集体单位，与家族辈分的概念不同。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“性别”不能与“人”组成“是性别人”这样的说法。"}], "explanations": {"年级": "语义：“年级”指学校的学习阶段，与家族中的一辈人不是同一概念。", "一代": "一代：家族中同一辈的人，与“你和你的堂弟是……人吗”相符。", "班级": "语义：“班级”指学校的集体单位，与家族辈分的概念不同。", "性别": "搭配：“性别”不能与“人”组成“是性别人”这样的说法。"}, "sentence_index": 6, "correct_answer": "一代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个县的一代很多。", "explanation": "这里应该用〈人口〉。一代不能用来表示一个地区的总人数。"}, {"text": "他一代大了，腿脚不灵。", "explanation": "这里应该用〈年纪〉。一代不能用来表示个人的年纪大小。"}, {"text": "这台冰箱的一代很大，放不下东西。", "explanation": "这里应该用〈容量〉。一代指家族中的一辈人或同一时期的人，不能用来形容冰箱的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和堂哥是一代个人。", "corrected_sentence": "我和堂哥是一代人。", "error_description": "“一代个人”错误：“一代人”是固定说法，“一代”和“人”之间不能插入量词“个”，应说“一代人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸和叔叔是一代们。", "corrected_sentence": "爸爸和叔叔是一代人。", "error_description": "“一代们”错误：“们”只加在指人的名词或代词后，“一代”后面不能加“们”，应说“一代人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
