INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同一时期的人；一个时代。", "primary_collocate": null, "pronunciation": "yí dài", "ipa": "i˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他们是看动画片长大的一代。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的一代更爱用手机。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老一代人都很节约。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一代年轻人很少写信。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上一代人吃过很多苦。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是那一代最好的歌手。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "八零后是很特别的一代。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每一代人都有自己的故事。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是改变这个城市的一代。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新一代的孩子从小就会上网。", "target_word": "一代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一代人", "label": "复合词"}, {"form": "新一代", "label": "复合词"}, {"form": "老一代", "label": "复合词"}], "register": "中性", "sense_fingerprint": "社会上同一时期出生、成长的人群或一个时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90030, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一代", "is_correct": true, "explanation": "一代（yí dài）：同一时期出生、成长的一批人，或一个时代的人。"}, {"text": "衣袋", "is_correct": false, "explanation": "yī dài 与 yí dài 声调不同，意思是衣服上的口袋。"}, {"text": "一到", "is_correct": false, "explanation": "yí dào 与 yí dài 韵母不同（ao 与 ai），意思是一到达。"}, {"text": "一对", "is_correct": false, "explanation": "yí duì 与 yí dài 韵母不同（ui 与 ai），意思是一双、一对。"}], "explanations": {"一代": "一代（yí dài）：同一时期出生、成长的一批人，或一个时代的人。", "衣袋": "yī dài 与 yí dài 声调不同，意思是衣服上的口袋。", "一到": "yí dào 与 yí dài 韵母不同（ao 与 ai），意思是一到达。", "一对": "yí duì 与 yí dài 韵母不同（ui 与 ai），意思是一双、一对。"}, "sentence_index": null, "correct_answer": "一代"}, "level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能与“长大的”组成指人的名词，句子不成立。"}, {"text": "一代", "is_correct": true, "explanation": "一代：同一时期出生、成长的一批人，与“看动画片长大的”相符。"}, {"text": "家乡", "is_correct": false, "explanation": "语义：“家乡”指出生或居住的地方，不能指一批看动画片长大的人。"}, {"text": "地区", "is_correct": false, "explanation": "语义：“地区”指地理范围，与“看动画片长大的”指人的说法不合。"}], "explanations": {"年龄": "搭配：“年龄”不能与“长大的”组成指人的名词，句子不成立。", "一代": "一代：同一时期出生、成长的一批人，与“看动画片长大的”相符。", "家乡": "语义：“家乡”指出生或居住的地方，不能指一批看动画片长大的人。", "地区": "语义：“地区”指地理范围，与“看动画片长大的”指人的说法不合。"}, "sentence_index": 0, "correct_answer": "一代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一代天气很热，大家都在出汗。", "explanation": "这里应该用〈一带〉。一代指同一时期的人或一个时代，不能用来指某个地方的范围；指地区要说“一带”。"}, {"text": "这段路的一代很长，走了一个小时。", "explanation": "这里应该用〈路程〉。一代不能用来形容路的长短。"}, {"text": "这块地的一代很大，种不完。", "explanation": "这里应该用〈面积〉。一代指同一时期的人或一个时代，不能用来形容土地的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星座", "is_correct": false, "explanation": "语义：“星座”指天文或占星概念，不能指一批在某个时代成长的人。"}, {"text": "一代", "is_correct": true, "explanation": "一代：同一时期出生、成长的一批人，与“八零后是很特别的……”相符。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“性别”不能与“很特别的”组成指一群人的说法，句子不成立。"}, {"text": "品牌", "is_correct": false, "explanation": "语义：“品牌”指商品标识，与“八零后”这类人群的说法不合。"}], "explanations": {"星座": "语义：“星座”指天文或占星概念，不能指一批在某个时代成长的人。", "一代": "一代：同一时期出生、成长的一批人，与“八零后是很特别的……”相符。", "性别": "搭配：“性别”不能与“很特别的”组成指一群人的说法，句子不成立。", "品牌": "语义：“品牌”指商品标识，与“八零后”这类人群的说法不合。"}, "sentence_index": 6, "correct_answer": "一代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的一代很高，比篮球还高。", "explanation": "这里应该用〈身高〉。一代不能用来形容个人的身高。"}, {"text": "他一代大了，腿脚不灵。", "explanation": "这里应该用〈年纪〉。一代不能用来表示个人的年纪大小。"}, {"text": "这个县的一代很多。", "explanation": "这里应该用〈人口〉。一代不能用来表示一个地区的总人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老一代们很看重家庭。", "corrected_sentence": "老一代人很看重家庭。", "error_description": "“老一代们”错误：“们”不能加在“一代”后面，应说“老一代人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个一代人经历了很多变化。", "corrected_sentence": "这一代人经历了很多变化。", "error_description": "“这个一代人”错误：“这一代”是固定的指示结构，中间不能加“个”，应说“这一代人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
