INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "温泉是从地下冒出来的热水，可以泡澡。", "primary_collocate": "泡", "pronunciation": "wēn quán", "ipa": "wən˥ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "冬天，我们去山里泡温泉。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的温泉很热，要小心。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本有很多有名的温泉。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温泉旁边有一家小旅馆。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈周末去了温泉。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢泡完温泉后喝冷牛奶。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪的时候泡温泉最舒服。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市附近有一处温泉。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这个温泉对皮肤很好。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在温泉里聊了一个小时。", "target_word": "温泉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处温泉", "label": "量词"}, {"form": "温泉水", "label": "复合"}], "register": "中性", "sense_fingerprint": "从地下冒出来、可以泡澡的热水", "collocate_grounding": {"status": "corpus_validated", "reason": "corpus_collocations PMI 12.28 >= 5.0", "source": "corpus_collocations", "score": 12.275}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "温泉", "is_correct": true, "explanation": "温泉是从地下冒出的热水，可以泡澡，与“去山里泡”的语境相符。"}, {"text": "海滩", "is_correct": false, "explanation": "语义：海滩在海边，与“去山里”矛盾，也不能被泡。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：“泡”不能搭配“冰”，冰不能被人泡在里面。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“泡”不能搭配“电脑”，电脑不能被人泡在里面，与“去山里泡”不符。"}], "explanations": {"温泉": "温泉是从地下冒出的热水，可以泡澡，与“去山里泡”的语境相符。", "海滩": "语义：海滩在海边，与“去山里”矛盾，也不能被泡。", "冰": "搭配：“泡”不能搭配“冰”，冰不能被人泡在里面。", "电脑": "搭配：“泡”不能搭配“电脑”，电脑不能被人泡在里面，与“去山里泡”不符。"}, "sentence_index": 0, "correct_answer": "温泉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天很热，我们在山里找到一眼温泉，水冰冷刺骨，大家都来洗脸降温。", "explanation": "这里应该用〈冷泉〉。温泉是温度较高的热水，水冰冷刺骨的应称冷泉，不能说成温泉。"}, {"text": "这眼温泉的表面结了一层厚冰，孩子们在上面滑冰。", "explanation": "这里应该用〈冰湖〉。温泉水温较高，不会结成厚冰，能在上面滑冰的应是冰湖。"}, {"text": "冬天很冷，我们在屋里生了一眼温泉取暖。", "explanation": "这里应该用〈火炉〉。生起来取暖的是火炉，温泉是地下涌出的热水，不能像火炉一样生起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温泉", "is_correct": true, "explanation": "温泉是可以泡澡的热水，下雪天泡最舒服，与“下雪”和“舒服”相符。"}, {"text": "棉被", "is_correct": false, "explanation": "搭配：“泡澡”的对象是水，“棉被”不能用来泡，与“泡温泉”的语境不符。"}, {"text": "雪人", "is_correct": false, "explanation": "搭配：“泡”不能搭配“雪人”，雪人不能被泡。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“泡”不能搭配“石头”，石头不能被泡。"}], "explanations": {"温泉": "温泉是可以泡澡的热水，下雪天泡最舒服，与“下雪”和“舒服”相符。", "棉被": "搭配：“泡澡”的对象是水，“棉被”不能用来泡，与“泡温泉”的语境不符。", "雪人": "搭配：“泡”不能搭配“雪人”，雪人不能被泡。", "石头": "搭配：“泡”不能搭配“石头”，石头不能被泡。"}, "sentence_index": 6, "correct_answer": "温泉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我渴了，从冰箱里拿出一瓶温泉喝。", "explanation": "这里应该用〈矿泉水〉。温泉是从地下冒出来的热水，是一个地方，不能装在冰箱里的瓶子里喝。"}, {"text": "妈妈在厨房里烧了一锅温泉做饭。", "explanation": "这里应该用〈开水〉。温泉是地下自然冒出的热水，不是在厨房烧出来的。"}, {"text": "下雨以后，路上积了很多温泉。", "explanation": "这里应该用〈雨水〉。路上的积水来自下雨，温泉是从地下冒出来的热水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上有一只温泉。", "corrected_sentence": "山上有一处温泉。", "error_description": "量词错误：温泉指地点，应用量词“处”。“只”用于动物或成对的东西，不能用于温泉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村子后面有一张温泉。", "corrected_sentence": "村子后面有一处温泉。", "error_description": "量词错误：温泉应用量词“处”计数。“张”用于平面的东西，不能用来数温泉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90033, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
