INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90033, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "纪念是想起过去的人或事,不忘记。", "primary_collocate": null, "pronunciation": "jì niàn", "ipa": "tɕi⁵¹ njɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "我们永远纪念那些帮助过我们的人。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日让人们纪念过去的那场战争。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不会忘记，会一直纪念他。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年九月三日，人们都会纪念那次胜利。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们站在碑前，纪念死去的战士。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要纪念老一辈人，别忘了他们。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直纪念着去世的妻子。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了不忘过去，大家每年都纪念这一天。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人一直纪念这位救过大家的医生。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每年清明都会纪念亲人。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纪念了", "label": "体标"}, {"form": "纪念着", "label": "体标"}, {"form": "纪念过", "label": "体标"}, {"form": "纪念品", "label": "复合"}, {"form": "纪念日", "label": "复合"}, {"form": "紀念", "label": "繁体"}], "register": "中性", "sense_fingerprint": "想起过去的人或事而不忘记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62640798-92c2-46f8-9980-a0d08bce8395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90033, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纪念", "is_correct": true, "explanation": "纪念（jì niàn）：想起过去的人或事而不忘记，是本题要听的词。"}, {"text": "几年", "is_correct": false, "explanation": "几年（jǐ nián）与纪念（jì niàn）两个音节的声调都不同，意思是“几年”。"}, {"text": "纪年", "is_correct": false, "explanation": "纪年（jì nián）与纪念（jì niàn）只有第二音节的声调不同（nián 与 niàn），意思是“纪年”。"}, {"text": "意念", "is_correct": false, "explanation": "意念（yì niàn）与纪念（jì niàn）只有声母不同（y 与 j），意思是“念头”。"}], "explanations": {"纪念": "纪念（jì niàn）：想起过去的人或事而不忘记，是本题要听的词。", "几年": "几年（jǐ nián）与纪念（jì niàn）两个音节的声调都不同，意思是“几年”。", "纪年": "纪年（jì nián）与纪念（jì niàn）只有第二音节的声调不同（nián 与 niàn），意思是“纪年”。", "意念": "意念（yì niàn）与纪念（jì niàn）只有声母不同（y 与 j），意思是“念头”。"}, "sentence_index": null, "correct_answer": "纪念"}, "level_3": {"options": [{"text": "惩罚", "is_correct": false, "explanation": "语义：“惩罚”针对过错，与“帮助过我们”的语境相反。"}, {"text": "纪念", "is_correct": true, "explanation": "纪念：对帮助过我们的人表示感念与怀想，与句意相符。"}, {"text": "利用", "is_correct": false, "explanation": "语义：“利用”含有把人当工具的意思，用在帮助过我们的人身上不合句意。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”与受人帮助后的感激语境相反，说永远欺骗恩人不符合句意。"}], "explanations": {"惩罚": "语义：“惩罚”针对过错，与“帮助过我们”的语境相反。", "纪念": "纪念：对帮助过我们的人表示感念与怀想，与句意相符。", "利用": "语义：“利用”含有把人当工具的意思，用在帮助过我们的人身上不合句意。", "欺骗": "语义：“欺骗”与受人帮助后的感激语境相反，说永远欺骗恩人不符合句意。"}, "sentence_index": 0, "correct_answer": "纪念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在工厂里纪念每天生产的零件。", "explanation": "这里应该用〈清点〉。纪念只用于想起过去的人或事，不能指计数生产的零件，计数要用清点。"}, {"text": "我们去医院纪念受伤的工人。", "explanation": "这里应该用〈慰问〉。纪念用于缅怀已逝者或事件，对活着的伤员表示关怀要用慰问。"}, {"text": "我们纪念明天的考试。", "explanation": "这里应该用〈准备〉。纪念只用于想起过去的人或事，不能用于尚未发生的考试，备考明天的考试要用准备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”需要身体接触，去世的妻子无法被拥抱。"}, {"text": "纪念", "is_correct": true, "explanation": "纪念：想起已故的妻子而不忘记，与句意相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语域：“嘲笑”对逝者不尊敬，与一直怀念妻子的语境相反。"}, {"text": "追赶", "is_correct": false, "explanation": "配价：“追赶”需要能移动的对象，去世的妻子不能被追赶。"}], "explanations": {"拥抱": "语义：“拥抱”需要身体接触，去世的妻子无法被拥抱。", "纪念": "纪念：想起已故的妻子而不忘记，与句意相符。", "嘲笑": "语域：“嘲笑”对逝者不尊敬，与一直怀念妻子的语境相反。", "追赶": "配价：“追赶”需要能移动的对象，去世的妻子不能被追赶。"}, "sentence_index": 6, "correct_answer": "纪念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们纪念即将到来的客人。", "explanation": "这里应该用〈迎接〉。纪念只用于想起过去的人或事，不能用于尚未到来的客人，迎接即将到来的客人要用迎接。"}, {"text": "我们纪念下周的约会。", "explanation": "这里应该用〈安排〉。纪念只用于想起过去的人或事，不能用于尚未发生的约会，安排下周的约会要用安排。"}, {"text": "妈妈纪念我要早点回家。", "explanation": "这里应该用〈嘱咐〉。纪念是想起过去的人或事，不能表示叮咛别人做某事，嘱咐孩子要用嘱咐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们站在碑前了纪念这些老兵。", "corrected_sentence": "我们站在碑前纪念这些老兵。", "error_description": "错误：动态助词“了”被放在动词“纪念”前面。正确：去掉这个“了”，说“我们站在碑前纪念这些老兵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天都了纪念去世的妻子。", "corrected_sentence": "他每天都纪念去世的妻子。", "error_description": "错误：动态助词“了”被放在“都”和动词“纪念”之间。正确：去掉“了”，说“每天都纪念去世的妻子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
