INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90034, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用事物或行动表示对人或事的怀念。", "primary_collocate": null, "pronunciation": "jì niàn", "ipa": "tɕi⁵¹ njɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "学生们种了一棵树来纪念老校长。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了纪念这位英雄，人们修了一座塔。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年五月，村里人都唱歌纪念他。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一首诗纪念去世的朋友。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了奶奶爱吃的菜来纪念她。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办了一次展览纪念建校一百年。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把照片挂在墙上，用它纪念爷爷。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学低头默哀，纪念那位老师。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们送了花来纪念这些老兵。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一束白花，纪念自己的母亲。", "target_word": "纪念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纪念了", "label": "体标"}, {"form": "纪念着", "label": "体标"}, {"form": "纪念过", "label": "体标"}, {"form": "纪念品", "label": "复合"}, {"form": "纪念日", "label": "复合"}, {"form": "紀念", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用物品或行动表示对逝者或往事的怀念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62640798-92c2-46f8-9980-a0d08bce8395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纪念", "is_correct": true, "explanation": "纪念（jì niàn）：表示对人或事的怀念，是本题要听的词。"}, {"text": "几年", "is_correct": false, "explanation": "几年（jǐ nián）与纪念（jì niàn）两个音节的声调都不同，意思是“几年”。"}, {"text": "纪年", "is_correct": false, "explanation": "纪年（jì nián）与纪念（jì niàn）只有第二音节的声调不同（nián 与 niàn），意思是“纪年”。"}, {"text": "意念", "is_correct": false, "explanation": "意念（yì niàn）与纪念（jì niàn）只有声母不同（y 与 j），意思是“念头”。"}], "explanations": {"纪念": "纪念（jì niàn）：表示对人或事的怀念，是本题要听的词。", "几年": "几年（jǐ nián）与纪念（jì niàn）两个音节的声调都不同，意思是“几年”。", "纪年": "纪年（jì nián）与纪念（jì niàn）只有第二音节的声调不同（nián 与 niàn），意思是“纪年”。", "意念": "意念（yì niàn）与纪念（jì niàn）只有声母不同（y 与 j），意思是“念头”。"}, "sentence_index": null, "correct_answer": "纪念"}, "level_3": {"options": [{"text": "惩罚", "is_correct": false, "explanation": "语义：“惩罚”针对过错，种树不能用来惩罚老校长。"}, {"text": "纪念", "is_correct": true, "explanation": "纪念：用种树的行动表示对老校长的怀念，与句意相符。"}, {"text": "利用", "is_correct": false, "explanation": "语域：“利用”含有把人当工具的贬义，与学生敬重老校长的语境不符。"}, {"text": "教导", "is_correct": false, "explanation": "语义：“教导”是施教者对受教者的教育，学生种树不能用来教导校长。"}], "explanations": {"惩罚": "语义：“惩罚”针对过错，种树不能用来惩罚老校长。", "纪念": "纪念：用种树的行动表示对老校长的怀念，与句意相符。", "利用": "语域：“利用”含有把人当工具的贬义，与学生敬重老校长的语境不符。", "教导": "语义：“教导”是施教者对受教者的教育，学生种树不能用来教导校长。"}, "sentence_index": 0, "correct_answer": "纪念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他常常纪念明年的生日。", "explanation": "这里应该用〈筹备〉。纪念是对已逝之人或往事的怀念，不能用于尚未到来的生日，筹备生日要用筹备。"}, {"text": "学校纪念了这次期末考试的成绩。", "explanation": "这里应该用〈公布〉。纪念是对已逝之人或重大事件的缅怀，不能用于宣布成绩，公布考试成绩要用公布。"}, {"text": "周末我去医院纪念生病的奶奶。", "explanation": "这里应该用〈看望〉。纪念针对已经去世的人或重大事件，探望生病的亲人要用看望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”需要身体接触，照片不能拥抱爷爷。"}, {"text": "纪念", "is_correct": true, "explanation": "纪念：挂照片表示对爷爷的怀念，与句意相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语域：“嘲笑”对已故长辈不尊敬，与挂照片缅怀的语境相反。"}, {"text": "追赶", "is_correct": false, "explanation": "配价：“追赶”需要能移动的施事，照片无法追赶爷爷。"}], "explanations": {"拥抱": "语义：“拥抱”需要身体接触，照片不能拥抱爷爷。", "纪念": "纪念：挂照片表示对爷爷的怀念，与句意相符。", "嘲笑": "语域：“嘲笑”对已故长辈不尊敬，与挂照片缅怀的语境相反。", "追赶": "配价：“追赶”需要能移动的施事，照片无法追赶爷爷。"}, "sentence_index": 6, "correct_answer": "纪念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班纪念新来的转学生。", "explanation": "这里应该用〈欢迎〉。纪念是对已逝之人或重大事件的缅怀，不能用于迎接刚来的人，欢迎新同学要用欢迎。"}, {"text": "老师纪念了迟到的学生。", "explanation": "这里应该用〈批评〉。纪念是对已逝之人或重大事件的缅怀，不能表示指出错误，批评迟到的学生要用批评。"}, {"text": "妈妈纪念我别忘了带伞。", "explanation": "这里应该用〈叮嘱〉。纪念是缅怀的意思，不能表示反复叮咛别人做某事，叮嘱孩子要用叮嘱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们画了一幅画了来纪念老校长。", "corrected_sentence": "同学们画了一幅画来纪念老校长。", "error_description": "错误：“一幅画”后面多了一个“了”，打断了“画画来纪念”的连动结构。正确：删去多余的“了”，说“画了一幅画来纪念老校长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用这张照片了纪念爷爷。", "corrected_sentence": "他用这张照片纪念爷爷。", "error_description": "错误：动态助词“了”被放在动词“纪念”前面。正确：删去这个“了”，说“他用这张照片纪念爷爷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
