INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "双方之中的一方。", "primary_collocate": null, "pronunciation": "yì fāng", "ipa": "i˥˩ fɑŋ˥", "syllable_count": 2, "sentences": [{"text": "吵架时，一方应该先说对不起。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时一方赢了，另一方输了。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有一方同意，合同不能签。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一方想搬家，另一方不想。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不能只听一方的话。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分开了，孩子跟其中一方生活。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谈判时，一方提出了新条件。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买卖双方，一方要钱，一方要货。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人说话，一方太着急就容易吵架。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间，不能总是一方帮助另一方。", "target_word": "一方", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "另一方", "label": "复合词"}], "register": "中性", "sense_fingerprint": "相对的两方中的一个当事方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一方", "is_correct": true, "explanation": "正确答案“一方”（yì fāng），意思是双方之中的一方。"}, {"text": "以防", "is_correct": false, "explanation": "以防（yǐ fáng）与“一方”声调不同（第三声、第二声 vs 第四声、第一声），意思是“为了防止”。"}, {"text": "一房", "is_correct": false, "explanation": "“房”（fáng，第二声）与“方”（fāng，第一声）声调不同，“一房”意思是一间房。"}, {"text": "一封", "is_correct": false, "explanation": "“封”（fēng）与“方”（fāng）韵母不同（-eng 与 -ang），“一封”是数量词组，意思是一封（信）。"}], "explanations": {"一方": "正确答案“一方”（yì fāng），意思是双方之中的一方。", "以防": "以防（yǐ fáng）与“一方”声调不同（第三声、第二声 vs 第四声、第一声），意思是“为了防止”。", "一房": "“房”（fáng，第二声）与“方”（fāng，第一声）声调不同，“一房”意思是一间房。", "一封": "“封”（fēng）与“方”（fāng）韵母不同（-eng 与 -ang），“一封”是数量词组，意思是一封（信）。"}, "sentence_index": null, "correct_answer": "一方"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是吵架的人，不能说对不起。"}, {"text": "旁观者", "is_correct": false, "explanation": "语义：旁观者不是吵架的当事人，不会需要先道歉。"}, {"text": "一方", "is_correct": true, "explanation": "正确。“一方”指争执双方中的一个当事人，符合句意。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判不是吵架的一方，句中不能指他。"}], "explanations": {"天气": "语义：天气不是吵架的人，不能说对不起。", "旁观者": "语义：旁观者不是吵架的当事人，不会需要先道歉。", "一方": "正确。“一方”指争执双方中的一个当事人，符合句意。", "裁判": "语义：裁判不是吵架的一方，句中不能指他。"}, "sentence_index": 0, "correct_answer": "一方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "十个队中的一方赢了比赛。", "explanation": "这里应该用〈其中一个队〉。“一方”只指双方中的一个，十个队之间不能用它指其中一个。"}, {"text": "两家公司都满意，这份协议一方都签了字。", "explanation": "这里应该用〈双方〉。“一方”只指两者中的一个，与表示全体的“都”搭配时说法矛盾。"}, {"text": "一方都同意了这个计划。", "explanation": "这里应该用〈大家〉。“一方”指双方中的一个，不能指全体成员，全体同意应说“大家都同意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是东西，不能在谈判中提出条件。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众不是谈判的当事人，不能提出条件。"}, {"text": "一方", "is_correct": true, "explanation": "正确。“一方”指谈判中的一个当事方，符合句意。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不能代表谈判一方提出条件。"}], "explanations": {"桌子": "语义：桌子是东西，不能在谈判中提出条件。", "观众": "语义：观众不是谈判的当事人，不能提出条件。", "一方": "正确。“一方”指谈判中的一个当事方，符合句意。", "小孩": "语义：小孩不能代表谈判一方提出条件。"}, "sentence_index": 6, "correct_answer": "一方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个结果，一方都很满意。", "explanation": "这里应该用〈两人〉。“一方”只指其中一个，与表示全体的“都”搭配时说法矛盾。"}, {"text": "朋友之间，一方应该互相帮助。", "explanation": "这里应该用〈彼此〉。“互相”要求双方都参与，“一方”只指一个，二者不能搭配。"}, {"text": "这次考试有五个学生，一方考得很好。", "explanation": "这里应该用〈有人〉。“一方”只指双方中的一个，不能用来指五人中的一个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吵架时，一方们应该先向对方道歉。", "corrected_sentence": "吵架时，一方应该先向对方道歉。", "error_description": "错误：“一方们”；正确：“一方”。“一方”指双方中的一个，是单个的当事人，不能加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "谈判时，一方都提出了新条件。", "corrected_sentence": "谈判时，一方先提出了新条件。", "error_description": "错误：“一方都”；正确：“一方先”。“都”表示全体，与只指双方中一个的“一方”矛盾；这里表示先后顺序，应用“先”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
