INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90037, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "烟草是一种植物，叶子可以做成香烟。", "primary_collocate": null, "pronunciation": "yān cǎo", "ipa": "jɛn⁵⁵ tsʰaʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这里的农民种了很多烟草。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟草的叶子很大。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟草田在山的那边。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家世世代代都种烟草。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟草要晒干以后才能做香烟。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟草是一种植物，不是树。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，农民把烟草种在田里。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次看见烟草开花。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟草的叶子可以做成香烟。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个地方的天气很适合烟草生长。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "煙草", "label": "繁体"}, {"form": "烟草公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "叶子可做香烟的一种植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '473ad9c2-ea4f-48b1-a923-c5dcf69bac63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90037, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "搭配：“种”的对象是植物或作物，“汽车”不能种植，与“种了很多”搭配不当。"}, {"text": "烟草", "is_correct": true, "explanation": "烟草是可以种植的植物，与“农民种了很多”搭配，句意通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不是农民能种植的东西，与句中“种”的语义矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“手机”不能被种植，动词“种”与它不能搭配。"}], "explanations": {"汽车": "搭配：“种”的对象是植物或作物，“汽车”不能种植，与“种了很多”搭配不当。", "烟草": "烟草是可以种植的植物，与“农民种了很多”搭配，句意通顺。", "钢琴": "语义：钢琴是乐器，不是农民能种植的东西，与句中“种”的语义矛盾。", "手机": "搭配：“手机”不能被种植，动词“种”与它不能搭配。"}, "sentence_index": 0, "correct_answer": "烟草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他家世世代代都在河里养烟草。", "explanation": "这里应该用〈鱼〉。烟草是种在地里的植物，不能在河里养。"}, {"text": "厨房里冒出了一股烟草，菜烧糊了。", "explanation": "这里应该用〈黑烟〉。烟草是植物，不是烧东西冒出的烟。"}, {"text": "他口渴了，倒了一杯烟草喝。", "explanation": "这里应该用〈茶〉。烟草是植物，叶子用来做香烟，不能泡来喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90037, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钟表", "is_correct": false, "explanation": "语义：钟表是计时的器具，不是能种在田里的东西，与“种在田里”语义矛盾。"}, {"text": "烟草", "is_correct": true, "explanation": "烟草是植物，可以种在田里，与“农民把……种在田里”搭配，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“种在田里”只用于植物或作物，“空气”不能种植，搭配不当。"}, {"text": "自行车", "is_correct": false, "explanation": "语义：自行车是交通工具，不能种在田里，与句中的“种”语义矛盾。"}], "explanations": {"钟表": "语义：钟表是计时的器具，不是能种在田里的东西，与“种在田里”语义矛盾。", "烟草": "烟草是植物，可以种在田里，与“农民把……种在田里”搭配，句意通顺。", "空气": "搭配：“种在田里”只用于植物或作物，“空气”不能种植，搭配不当。", "自行车": "语义：自行车是交通工具，不能种在田里，与句中的“种”语义矛盾。"}, "sentence_index": 6, "correct_answer": "烟草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天抽一根烟草。", "explanation": "这里应该用〈香烟〉。烟草是植物，不是一根一根抽的成品，每天抽的一根应是香烟。"}, {"text": "火灾现场，烟草滚滚地冲上了天空。", "explanation": "这里应该用〈浓烟〉。烟草是植物，不是烟雾；“滚滚”形容冲上天空的浓烟，不能说烟草。"}, {"text": "他点燃了一支烟草。", "explanation": "这里应该用〈雪茄〉。烟草是植物，不能像雪茄那样一支一支点燃来抽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90037, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在院子里种了两只烟草。", "corrected_sentence": "我在院子里种了两株烟草。", "error_description": "量词错误：烟草是植物，计量应用“株”，“只”用于动物，不能用来数烟草。应说“两株烟草”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90037, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把烟草喝干了，再切成烟丝。", "corrected_sentence": "工人把烟草晒干了，再切成烟丝。", "error_description": "动词错误：烟草不能“喝”，应说“晒干了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
