INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "茄科植物，叶子可晒制成香烟、烟丝等。", "primary_collocate": null, "pronunciation": "yān cǎo", "ipa": "jɛn⁵⁵ tsʰaʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "烟草属于茄科植物。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把晒好的烟草切成了烟丝。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，农民把烟草晒在院子里。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟草经过加工，才能变成香烟。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些烟草是去年从云南运来的。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用烟草做烟丝。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟草的花是淡粉色的。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用烟草卷了一根烟。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种烟草在南方很常见。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟草和西红柿都属于茄科。", "target_word": "烟草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "煙草", "label": "繁体"}, {"form": "烟草公司", "label": "复合"}], "register": "中性", "sense_fingerprint": "茄科植物，叶可晒制成香烟、烟丝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '473ad9c2-ea4f-48b1-a923-c5dcf69bac63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头是矿物，不是植物，不能属于茄科植物。"}, {"text": "烟草", "is_correct": true, "explanation": "烟草是茄科植物，与“属于茄科植物”搭配，句意通顺。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米来自禾本科的水稻，不属于茄科植物。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“属于”后接的是植物类别，“汽车”不是植物，搭配不当。"}], "explanations": {"石头": "语义：石头是矿物，不是植物，不能属于茄科植物。", "烟草": "烟草是茄科植物，与“属于茄科植物”搭配，句意通顺。", "大米": "语义：大米来自禾本科的水稻，不属于茄科植物。", "汽车": "搭配：“属于”后接的是植物类别，“汽车”不是植物，搭配不当。"}, "sentence_index": 0, "correct_answer": "烟草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂里新进了一批烟草，用来织布。", "explanation": "这里应该用〈棉花〉。烟草的叶子用来做香烟、烟丝，不能织布。"}, {"text": "他每天早上都吃一碗烟草。", "explanation": "这里应该用〈米饭〉。烟草是做香烟的植物，不是吃的食物。"}, {"text": "烟草在天上飞来飞去。", "explanation": "这里应该用〈小鸟〉。烟草是长在地里的植物，不会飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不会开花，不能说“的花是淡粉色的”。"}, {"text": "烟草", "is_correct": true, "explanation": "烟草是会开花的植物，与“的花是淡粉色的”搭配，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的气体，不会开花，与“的花是淡粉色的”语义矛盾。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不会开花，与“的花是淡粉色的”语义矛盾。"}], "explanations": {"小狗": "语义：小狗是动物，不会开花，不能说“的花是淡粉色的”。", "烟草": "烟草是会开花的植物，与“的花是淡粉色的”搭配，句意通顺。", "空气": "语义：空气是无形的气体，不会开花，与“的花是淡粉色的”语义矛盾。", "大海": "语义：大海不会开花，与“的花是淡粉色的”语义矛盾。"}, "sentence_index": 6, "correct_answer": "烟草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天抽两根烟草。", "explanation": "这里应该用〈香烟〉。烟草是植物，不是一根一根抽的成品，抽的一根应是香烟。"}, {"text": "山谷里升起一缕烟草，慢慢飘向天空。", "explanation": "这里应该用〈炊烟〉。烟草是植物或烟叶制品，不是升起的烟；“一缕”形容的是飘向天空的炊烟。"}, {"text": "他点燃了一支烟草。", "explanation": "这里应该用〈雪茄〉。烟草是植物，不能像雪茄那样一支一支点燃来抽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民把烟草喝完了。", "corrected_sentence": "农民把烟草收完了。", "error_description": "动词错误：烟草不能“喝”，应用“收”，说“收完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们运走了一只烟草。", "corrected_sentence": "他们运走了一批烟草。", "error_description": "量词错误：“只”用于动物等，烟草要用“批”来计量，应说“运走了一批烟草”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b796b802-e30f-4dc9-9a1a-e53bfb8219e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
