INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90040, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "自身指事物本身，与外部条件相对。", "primary_collocate": null, "pronunciation": "zì shēn", "ipa": "tsɿ˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "这个办法自身没有问题,问题在使用的人。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产品自身的质量比价格更重要。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市自身的特点很明显。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱自身并不能带来快乐。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事自身不难,难的是坚持。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药自身没有毒,吃多了才有问题。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作自身很简单,只是时间太紧。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书自身的价值很高。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题自身不大,别太担心。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司自身的条件不错,所以很多人想去。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自身:指事物本身,与外部条件相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84adf9-f7e5-4676-ae12-1e74b754fae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自身", "is_correct": true, "explanation": "正确：“自身”指办法本身，与“问题在使用的人”的语境相合。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指人，办法是事物，不能说“这个办法他没有问题”。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指人，办法是事物，不能说“这个办法他们没有问题”。"}, {"text": "外部", "is_correct": false, "explanation": "语义：“外部”指事物外面的条件，正好与“办法本身”相对，句子说的是办法本身没有问题。"}], "explanations": {"自身": "正确：“自身”指办法本身，与“问题在使用的人”的语境相合。", "他": "语义：“他”指人，办法是事物，不能说“这个办法他没有问题”。", "他们": "语义：“他们”指人，办法是事物，不能说“这个办法他们没有问题”。", "外部": "语义：“外部”指事物外面的条件，正好与“办法本身”相对，句子说的是办法本身没有问题。"}, "sentence_index": 0, "correct_answer": "自身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的自身朋友都很支持我。", "explanation": "这里“自身”不能修饰表示其他人的名词“朋友”，说“自己的朋友”不能用“自身”。"}, {"text": "他很自身，从不愿意帮忙。", "explanation": "这里“自身”是名词，不能作形容词说人“自私”，应说“自私”。"}, {"text": "他的情绪很自身，总是很快就好。", "explanation": "这里“自身”不能形容情绪，应说“平静”或“稳定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自身", "is_correct": true, "explanation": "正确：“自身”指工作本身，与“很简单”的评价相合。"}, {"text": "本人", "is_correct": false, "explanation": "语义：“本人”指人，工作是事物，不能说“工作本人很简单”。"}, {"text": "同事", "is_correct": false, "explanation": "语义：“同事”指人，不能说“工作同事很简单”。"}, {"text": "别人", "is_correct": false, "explanation": "搭配：“别人”指他人，与说工作本身难易的语境不符。"}], "explanations": {"自身": "正确：“自身”指工作本身，与“很简单”的评价相合。", "本人": "语义：“本人”指人，工作是事物，不能说“工作本人很简单”。", "同事": "语义：“同事”指人，不能说“工作同事很简单”。", "别人": "搭配：“别人”指他人，与说工作本身难易的语境不符。"}, "sentence_index": 6, "correct_answer": "自身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的自身喜欢音乐。", "explanation": "这里“自身”不能作主语的定语，说“我”即可，不能用“我的自身”。"}, {"text": "他总是和自身的家人一起吃饭。", "explanation": "这里“自身”不能修饰“家人”这类指其他人的名词，它只表示自己。"}, {"text": "他的自身很热情，喜欢帮助别人。", "explanation": "这里“自身”不能形容性格，应说“热情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器自身地速度很快。", "corrected_sentence": "这台机器自身的速度很快。", "error_description": "错误：修饰名词“速度”的结构助词写成了“地”。“地”用于修饰动词或形容词，正确应为“自身的速度”，用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑自身们的速度很快，不需要升级。", "corrected_sentence": "这台电脑自身的速度很快，不需要升级。", "error_description": "错误：“自身”后不能加“们”。“们”只用于指人的复数，“自身”不带复数形式，正确应为“自身很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
