INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90041, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很短很短的一段时间。", "primary_collocate": null, "pronunciation": "yíhuìr", "ipa": "i˧˥ xweɪ˥˩ ɚ", "syllable_count": 2, "sentences": [{"text": "你先坐一会儿，饭马上就好。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在门口等了一会儿，就走了。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想在公园里走一会儿。", "target_word": "一会儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请再等我一会儿，我马上来。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈出去了，一会儿就回来。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子哭了一会儿，慢慢睡着了。", "target_word": "一会儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过一会儿，雨就停了。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我累了，想躺一会儿。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视看了一会儿，他就关了。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着窗外，发了一会儿呆。", "target_word": "一会儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一会", "label": "口语省略形式"}, {"form": "一會兒", "label": "繁体"}], "register": "口语", "sense_fingerprint": "极短的一段时间，常与等、坐、过、休息等动作搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '472a9012-31ef-4449-9907-721337a9f32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90041, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一辈子", "is_correct": false, "explanation": "语义：一辈子指一生，与“饭马上就好”所说的短时等待矛盾。"}, {"text": "一会儿", "is_correct": true, "explanation": "正确。一会儿表示很短的一段时间，与“饭马上就好”的语境相符。"}, {"text": "一整天", "is_correct": false, "explanation": "搭配：“马上就好”的紧迫语境不与“坐一整天”这样的长时段搭配。"}, {"text": "一年", "is_correct": false, "explanation": "语义：一年远远超出“饭马上就好”所暗示的等待时间。"}], "explanations": {"一辈子": "语义：一辈子指一生，与“饭马上就好”所说的短时等待矛盾。", "一会儿": "正确。一会儿表示很短的一段时间，与“饭马上就好”的语境相符。", "一整天": "搭配：“马上就好”的紧迫语境不与“坐一整天”这样的长时段搭配。", "一年": "语义：一年远远超出“饭马上就好”所暗示的等待时间。"}, "sentence_index": 0, "correct_answer": "一会儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一会儿笑，一会儿哭，像个小孩子。", "explanation": "语义：这里的〈一会儿…一会儿…〉表示情绪交替出现，不是“很短的时间”的意思，不能按时长义理解。"}, {"text": "我这一会儿正忙着，你晚点再来吧。", "explanation": "语义：这里的〈这一会儿〉指此刻、眼下，是时间点，不是“很短的一段时间”，与“一会儿”的时长义不同。"}, {"text": "天气一会儿晴，一会儿阴，真让人没办法。", "explanation": "语义：这里的〈一会儿…一会儿…〉表示变化交替，并非“很短的时间”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90041, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一整年", "is_correct": false, "explanation": "语义：一整年太长，与“过…，雨就停了”所说的短暂变化不符。"}, {"text": "一会儿", "is_correct": true, "explanation": "正确。一会儿表示很短的一段时间，与“过一会儿，雨就停了”的短时变化相符。"}, {"text": "一个世纪", "is_correct": false, "explanation": "语义：一个世纪远超过雨停所需的时间，与“过”后接的短暂变化不符。"}, {"text": "一百年", "is_correct": false, "explanation": "语义：一百年太长，雨停这样的短时变化不需要这么久。"}], "explanations": {"一整年": "语义：一整年太长，与“过…，雨就停了”所说的短暂变化不符。", "一会儿": "正确。一会儿表示很短的一段时间，与“过一会儿，雨就停了”的短时变化相符。", "一个世纪": "语义：一个世纪远超过雨停所需的时间，与“过”后接的短暂变化不符。", "一百年": "语义：一百年太长，雨停这样的短时变化不需要这么久。"}, "sentence_index": 6, "correct_answer": "一会儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一会儿他站在那儿，什么也不说。", "explanation": "语义：这里的〈这一会儿〉指此刻，是时间点，不是很短的一段时间。"}, {"text": "孩子们一会儿跑，一会儿跳，玩得很开心。", "explanation": "语义：这里的〈一会儿…一会儿…〉表示动作交替反复，不是“很短的时间”的意思。"}, {"text": "这一会儿外面没人，我们快出去吧。", "explanation": "语义：这里的〈这一会儿〉指眼下这个时刻，与“很短的一段时间”的时长义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90041, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想坐很一会儿，再决定去哪儿。", "corrected_sentence": "他想坐一会儿，再决定去哪儿。", "error_description": "错误：“一会儿”是时量词组，前面不能加程度副词“很”。应说“坐一会儿”，不能说“坐很一会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在门口等了的一会儿，就进去了。", "corrected_sentence": "他在门口等了一会儿，就进去了。", "error_description": "错误：“一会儿”前不能插入结构助词“的”，“了”应直接接在动词后。应说“等了一会儿”，不能说“等了的一会儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
