INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90042, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90042, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "短时间；片刻。", "primary_collocate": null, "pronunciation": "yíhuìr", "ipa": "i˧˥ xweɪ˥˩ ɚ", "syllable_count": 2, "sentences": [{"text": "老师说了一会儿，大家都听懂了。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先休息一会儿，再继续做作业吧。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想了一会儿，才回答我。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把行李放下，站了一会儿才说话。", "target_word": "一会儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们聊了一会儿天，就回家了。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在这里玩一会儿，我去买水。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她只睡了一会儿，就醒了。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等一会儿，我给你倒杯茶。", "target_word": "一会儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "车坏了，我们在路边停了一会儿。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在那儿看了一会儿，没说话。", "target_word": "一会儿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一会", "label": "口语省略形式"}, {"form": "一會兒", "label": "繁体"}], "register": "口语", "sense_fingerprint": "片刻，短暂的时间，可表动作持续不久或状态很快变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '472a9012-31ef-4449-9907-721337a9f32d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一刹那", "is_correct": false, "explanation": "语义：一刹那太短，不足以讲完并让大家都听懂。"}, {"text": "一会儿", "is_correct": true, "explanation": "正确。一会儿表示短时间，与“老师说了…，大家都听懂了”的讲解过程相符。"}, {"text": "一整年", "is_correct": false, "explanation": "语义：老师讲一整年才让大家听懂，与这句话的短时讲解语境不符。"}, {"text": "一个世纪", "is_correct": false, "explanation": "语义：一个世纪远超一次讲解所需的时间，与“大家都听懂了”的常规语境不符。"}], "explanations": {"一刹那": "语义：一刹那太短，不足以讲完并让大家都听懂。", "一会儿": "正确。一会儿表示短时间，与“老师说了…，大家都听懂了”的讲解过程相符。", "一整年": "语义：老师讲一整年才让大家听懂，与这句话的短时讲解语境不符。", "一个世纪": "语义：一个世纪远超一次讲解所需的时间，与“大家都听懂了”的常规语境不符。"}, "sentence_index": 0, "correct_answer": "一会儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一会儿站着，一会儿坐着，不知道在等什么。", "explanation": "语义：这里的〈一会儿…一会儿…〉表示姿态交替变化，不是“短时间”的意思。"}, {"text": "这一会儿雨停了，我们出去走走吧。", "explanation": "语义：这里的〈这一会儿〉指眼下这个时刻，是时间点，不是一段短时间。"}, {"text": "他一会儿高兴，一会儿难过，情绪变化很大。", "explanation": "语义：这里的〈一会儿…一会儿…〉表示情绪交替出现，与“片刻”的时长义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一辈子", "is_correct": false, "explanation": "语义：一辈子指一生，“只睡了……就醒了”的短时描述与之矛盾。"}, {"text": "一会儿", "is_correct": true, "explanation": "正确。一会儿表示短时间，与“只睡了一会儿，就醒了”相符。"}, {"text": "一生", "is_correct": false, "explanation": "语义：一生就是漫长的一辈子，睡了一生再醒与“就醒了”的语境冲突。"}, {"text": "一百年", "is_correct": false, "explanation": "语义：一百年远超一次睡眠的时间，与“只睡了…就醒了”矛盾。"}], "explanations": {"一辈子": "语义：一辈子指一生，“只睡了……就醒了”的短时描述与之矛盾。", "一会儿": "正确。一会儿表示短时间，与“只睡了一会儿，就醒了”相符。", "一生": "语义：一生就是漫长的一辈子，睡了一生再醒与“就醒了”的语境冲突。", "一百年": "语义：一百年远超一次睡眠的时间，与“只睡了…就醒了”矛盾。"}, "sentence_index": 6, "correct_answer": "一会儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一会儿路上没车，我们快过去吧。", "explanation": "语义：这里的〈这一会儿〉指此刻，是时间点，不是“片刻”的时长义。"}, {"text": "她一会儿笑，一会儿叹气，让人猜不透。", "explanation": "语义：这里的〈一会儿…一会儿…〉表示情绪交替变化，不是“短时间”的意思。"}, {"text": "这一会儿人多，我们先别进去。", "explanation": "语义：这里的〈这一会儿〉指眼下的时刻，与“片刻”的时长义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她盯着窗外，坐了很一会儿才开口。", "corrected_sentence": "她盯着窗外，坐了一会儿才开口。", "error_description": "错误：“一会儿”是时量补语，前面不能加程度副词“很”。应说“坐了一会儿”，不能说“坐了很一会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他推开门，站了的一会儿才进屋。", "corrected_sentence": "他推开门，站了一会儿才进屋。", "error_description": "错误：“一会儿”前不能插入结构助词“的”，“了”应直接接在动词后。应说“站了一会儿”，不能说“站了的一会儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7943fc8c-1ab8-4a76-8d58-70871352dcfd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
