INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "物业是房屋和它的配套设施，也就是房产。", "primary_collocate": null, "pronunciation": "wù yè", "ipa": "u⁵¹ jɛ⁵¹", "syllable_count": 2, "sentences": [{"text": "他在城里有两处物业，一处自己住。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的物业包括办公楼和商店。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把旧物业卖掉，再买新房子。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的物业有一半已经租给了商店。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在郊区有三处物业，都租给了外地人。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片物业有楼房、花园和停车场。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这处物业离地铁站很近，交通很方便。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把自己的物业留给了两个孩子。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一带的物业价格高得惊人，很少有人买得起。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这处物业一楼开商店，二楼住人。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物业费", "label": "复合"}, {"form": "物业公司", "label": "复合"}, {"form": "物业管理", "label": "复合"}], "register": "中性", "sense_fingerprint": "房屋及其配套设施，即房产(名词)；一处物业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4c97b3d-121f-4d28-8ae3-bc63fe5c388b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物业", "is_correct": true, "explanation": "正确答案。物业指房屋及其配套设施。"}, {"text": "无业", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，无业意思是没有工作。"}, {"text": "午夜", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，午夜意思是半夜。"}, {"text": "树叶", "is_correct": false, "explanation": "shù 与 wù 声母不同（sh 与 w），树叶意思是树上的叶子。"}, {"text": "副业", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），副业意思是主业之外的工作。"}], "explanations": {"物业": "正确答案。物业指房屋及其配套设施。", "无业": "wù（第四声）与 wú（第二声）声调不同，无业意思是没有工作。", "午夜": "wù（第四声）与 wǔ（第三声）声调不同，午夜意思是半夜。", "树叶": "shù 与 wù 声母不同（sh 与 w），树叶意思是树上的叶子。", "副业": "fù 与 wù 声母不同（f 与 w），副业意思是主业之外的工作。"}, "sentence_index": null, "correct_answer": "物业"}, "level_3": {"options": [{"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游玩的场所，不能「自己住」。"}, {"text": "物业", "is_correct": true, "explanation": "正确答案。物业指房产，可以住人，符合「两处，一处自己住」。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不是用来居住的地方。"}, {"text": "股票", "is_correct": false, "explanation": "搭配：量词「处」用于场所，不能说「两处股票」。"}], "explanations": {"公园": "语义：公园是供人游玩的场所，不能「自己住」。", "物业": "正确答案。物业指房产，可以住人，符合「两处，一处自己住」。", "工厂": "语义：工厂是生产场所，不是用来居住的地方。", "股票": "搭配：量词「处」用于场所，不能说「两处股票」。"}, "sentence_index": 0, "correct_answer": "物业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的物业包括汽车、存款和股票。", "explanation": "这里应该用〈财产〉。汽车、存款和股票都不属于房屋及配套设施，物业这里指的是房产。"}, {"text": "他把所有的物业都存进了银行。", "explanation": "这里应该用〈钱〉。存进银行的是钱，物业是房屋，不能存进银行。"}, {"text": "这家公司的物业大部分是设备和现金。", "explanation": "这里应该用〈资产〉。设备和现金不属于房屋及配套设施，物业这里指的是房产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物业", "is_correct": true, "explanation": "正确答案。物业指房屋及其配套设施。"}, {"text": "牧业", "is_correct": false, "explanation": "mù 与 wù 声母不同（m 与 w），牧业意思是放养牲畜的行业。"}, {"text": "入夜", "is_correct": false, "explanation": "rù 与 wù 声母不同（r 与 w），入夜意思是天黑以后。"}, {"text": "复业", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），复业意思是恢复营业。"}], "explanations": {"物业": "正确答案。物业指房屋及其配套设施。", "牧业": "mù 与 wù 声母不同（m 与 w），牧业意思是放养牲畜的行业。", "入夜": "rù 与 wù 声母不同（r 与 w），入夜意思是天黑以后。", "复业": "fù 与 wù 声母不同（f 与 w），复业意思是恢复营业。"}, "sentence_index": null, "correct_answer": "物业"}, "level_3": {"options": [{"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不能说「这处饭菜离地铁站很近」。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，不是地方，不能用「处」，也谈不上交通方便。"}, {"text": "物业", "is_correct": true, "explanation": "正确答案。物业指房屋及配套设施，用「处」计量，可以说离地铁站近。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是钱，不是地方，不能说「这处工资」。"}], "explanations": {"饭菜": "语义：饭菜是食物，不能说「这处饭菜离地铁站很近」。", "考试": "语义：考试是测验，不是地方，不能用「处」，也谈不上交通方便。", "物业": "正确答案。物业指房屋及配套设施，用「处」计量，可以说离地铁站近。", "工资": "语义：工资是钱，不是地方，不能说「这处工资」。"}, "sentence_index": 6, "correct_answer": "物业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天开着自己的物业去上班。", "explanation": "这里应该用〈汽车〉。能开着去上班的是汽车，物业是房屋，不能开。"}, {"text": "他把物业借给朋友，朋友看了一晚上。", "explanation": "这里应该用〈书〉。能借来看的是书，物业是房屋。"}, {"text": "他的物业包括手机、电脑和衣服。", "explanation": "这里应该用〈东西〉。手机、电脑和衣服不是房屋或配套设施，不属于物业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在城里买了一只物业。", "corrected_sentence": "他在城里买了一处物业。", "error_description": "量词错误：物业作为房产应该用「处」计量，不能用「只」。错误形式是「一只物业」，正确形式是「一处物业」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把物业卖了掉。", "corrected_sentence": "他把物业卖掉了。", "error_description": "补语位置错误：「卖掉」是结果补语，「了」要放在补语之后，应说「卖掉了」，不能说「卖了掉」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431050b8-5ee4-46cf-a8fc-f29ff9762507') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
