INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天空正中间。", "primary_collocate": null, "pronunciation": "zhōng tiān", "ipa": "ʈʂʊŋ tʰiɛn", "syllable_count": 2, "sentences": [{"text": "十五的月亮正好在中天。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳走到中天，影子变得很短。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，北斗星挂在中天。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正午时，太阳高悬中天。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中天有一朵白云，一动不动。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬头望着中天的月亮。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜，月亮到了中天。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中天的太阳照得人睁不开眼。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟花在中天亮了一下。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮在中天，路上很亮。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日当中天", "label": "复合"}, {"form": "月到中天", "label": "复合"}], "register": "书面", "sense_fingerprint": "天空最中间的位置，常指月亮或太阳所在处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c8e5f0-0406-4b36-85f5-8cace11e88a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中天", "is_correct": true, "explanation": "正确。中天：天空正中间。"}, {"text": "冲天", "is_correct": false, "explanation": "zh（中）与 ch（冲）声母不同，「冲天」意思是向上直冲天空，不是天空正中间。"}, {"text": "种田", "is_correct": false, "explanation": "zhōng（中）与 zhòng（种）声调不同，tiān（天）与 tián（田）声调也不同，「种田」意思是耕种田地。"}, {"text": "中听", "is_correct": false, "explanation": "tiān（天）与 tīng（听）韵母不同（ian/ing），「中听」意思是听起来悦耳。"}], "explanations": {"中天": "正确。中天：天空正中间。", "冲天": "zh（中）与 ch（冲）声母不同，「冲天」意思是向上直冲天空，不是天空正中间。", "种田": "zhōng（中）与 zhòng（种）声调不同，tiān（天）与 tián（田）声调也不同，「种田」意思是耕种田地。", "中听": "tiān（天）与 tīng（听）韵母不同（ian/ing），「中听」意思是听起来悦耳。"}, "sentence_index": null, "correct_answer": "中天"}, "level_3": {"options": [{"text": "中天", "is_correct": true, "explanation": "正确。中天指天空正中间，「正好在」这里的月亮所在位置符合语境。"}, {"text": "地底", "is_correct": false, "explanation": "语义：地底在地下，月亮不可能在那里，与“十五的月亮”所处的高空位置相反。"}, {"text": "河底", "is_correct": false, "explanation": "语义：河底在水下，月亮不可能在那里。"}, {"text": "井底", "is_correct": false, "explanation": "语义：井底在地下，月亮不可能在那里。"}], "explanations": {"中天": "正确。中天指天空正中间，「正好在」这里的月亮所在位置符合语境。", "地底": "语义：地底在地下，月亮不可能在那里，与“十五的月亮”所处的高空位置相反。", "河底": "语义：河底在水下，月亮不可能在那里。", "井底": "语义：井底在地下，月亮不可能在那里。"}, "sentence_index": 0, "correct_answer": "中天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕阳落在中天后面，天色渐渐暗了。", "explanation": "这里应该用〈西山〉。中天指天空正中，夕阳落下时应落在西山后面，不能落在中天后面。"}, {"text": "月亮倒映在中天上，波光粼粼。", "explanation": "这里应该用〈水面〉。倒映需要有水面，中天在天空，不能倒映月亮。"}, {"text": "一只猫躺在中天上晒太阳。", "explanation": "这里应该用〈房顶〉。中天只表示天空正中的位置，猫不能躺在那里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中天", "is_correct": true, "explanation": "正确。中天指天空正中间，「到了」这里的月亮是升到天空正中。"}, {"text": "地面", "is_correct": false, "explanation": "语义：月亮在夜空中升起，「到了地面」与月亮的位置相反。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底在水下，月亮不会到海底。"}, {"text": "锅底", "is_correct": false, "explanation": "搭配：「到了」后可以接地点，但「锅底」与「月亮」不搭，不能说月亮到了锅底。"}], "explanations": {"中天": "正确。中天指天空正中间，「到了」这里的月亮是升到天空正中。", "地面": "语义：月亮在夜空中升起，「到了地面」与月亮的位置相反。", "海底": "语义：海底在水下，月亮不会到海底。", "锅底": "搭配：「到了」后可以接地点，但「锅底」与「月亮」不搭，不能说月亮到了锅底。"}, "sentence_index": 6, "correct_answer": "中天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在操场的中天。", "explanation": "这里应该用〈中央〉。中天指天空正中，不能表示操场上的位置，应说站在操场的中央。"}, {"text": "学校在中天。", "explanation": "这里应该用〈河对岸〉。中天是天空中的位置，学校不可能在那里。"}, {"text": "地铁在中天。", "explanation": "这里应该用〈地下〉。地铁在地下运行，中天在天空，二者不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "月亮的升到中天了，路上亮起来了。", "corrected_sentence": "月亮升到中天了，路上亮起来了。", "error_description": "错误：“月亮的升到中天了”多出结构助词“的”，主语与动词之间不能插入“的”。正确：“月亮升到中天了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "月亮升了中天，路上亮起来了。", "corrected_sentence": "月亮升到了中天，路上亮起来了。", "error_description": "错误：“升了中天”缺少“到”。正确：“升到了中天”。表示到达某个位置要用“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
