INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90047, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90047, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "要之是把话说短,意思是总的来说。", "primary_collocate": null, "pronunciation": "yào zhī", "ipa": "jaʊ˥˩ tʂʅ˥", "syllable_count": 2, "sentences": [{"text": "天气不好,路又很远,要之,今天不宜出门。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会说英语,会说日语,要之,语言不是问题。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房时看价格、看地点，要之，还需量力而行。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店菜好,服务好,价格也低,要之,值得一去。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书可以借,电影可以看,要之,学习的办法很多。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说太贵,有人说太远,要之,大家都不满意。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作讲认真，做人讲诚实，要之，凡事不可马虎。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上起得晚，下午迟到，要之，是个不守时的人。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树需浇水，花需施肥，要之，养花贵在耐心。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天多雨,夏天太热,要之,这里不适合种茶。", "target_word": "要之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "列举之后用一句话总括,相当于总之", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116634ea-fcb5-448e-abe0-203c2273568d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要之", "is_correct": true, "explanation": "正确。书面连词，总括前面的两个理由，引出“今天不宜出门”的结论。"}, {"text": "但是", "is_correct": false, "explanation": "语义：但是表示转折，而前面两个理由都指向不出门，并不对立。"}, {"text": "然而", "is_correct": false, "explanation": "语义：然而表示转折，与前文同向的理由不相合。"}, {"text": "可是", "is_correct": false, "explanation": "语义：可是表示转折，而前面两个理由都指向不出门，并无对立。"}], "explanations": {"要之": "正确。书面连词，总括前面的两个理由，引出“今天不宜出门”的结论。", "但是": "语义：但是表示转折，而前面两个理由都指向不出门，并不对立。", "然而": "语义：然而表示转折，与前文同向的理由不相合。", "可是": "语义：可是表示转折，而前面两个理由都指向不出门，并无对立。"}, "sentence_index": 0, "correct_answer": "要之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学习认真才能进步，要之，就会落后。", "explanation": "这里应该用〈反之〉。要之只用于总括前面列举的几点，不能表示相反的结果。"}, {"text": "天气突然冷了，要之，我们多穿了衣服。", "explanation": "这里应该用〈所以〉。要之只用来总括前面列举的几点，引出结论，不能表示因果关系。"}, {"text": "他先吃了饭，要之，去散步了。", "explanation": "这里应该用〈然后〉。然后表示动作的先后顺序，要之只用于总括，不能表示动作的接续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要之", "is_correct": true, "explanation": "正确。书面连词，总括前面两点要求，引出“凡事不可马虎”的结论。"}, {"text": "相反", "is_correct": false, "explanation": "语义：相反表示对立，而前面两点都是同向的要求，并不对立。"}, {"text": "不过", "is_correct": false, "explanation": "语义：不过表示让步转折，这里并没有需要让步的内容。"}, {"text": "反之", "is_correct": false, "explanation": "搭配：反之需接在条件之后表示相反情况，前面并没有条件句。"}], "explanations": {"要之": "正确。书面连词，总括前面两点要求，引出“凡事不可马虎”的结论。", "相反": "语义：相反表示对立，而前面两点都是同向的要求，并不对立。", "不过": "语义：不过表示让步转折，这里并没有需要让步的内容。", "反之": "搭配：反之需接在条件之后表示相反情况，前面并没有条件句。"}, "sentence_index": 6, "correct_answer": "要之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很想去看看，要之没有时间。", "explanation": "这里应该用〈但是〉。要之只用于总括前面的内容，不能表示转折。"}, {"text": "他连续熬夜，要之，生了病。", "explanation": "这里应该用〈因此〉。因此表示因果，而要之只总括前面的内容，不能表示熬夜导致生病。"}, {"text": "他先练习，要之，参加了比赛。", "explanation": "这里应该用〈接着〉。接着表示动作相继发生，要之只用于总括，不能表示动作的接续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书又贵，店又远，要之了，这次不买了。", "corrected_sentence": "书又贵，店又远，要之，这次不买了。", "error_description": "“要之”后多加了“了”。要之是书面总括连词，不带动态助词“了”，正确形式是“书又贵，店又远，要之，这次不买了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "读书要专心，练字要耐心，很要之，学习贵在坚持。", "corrected_sentence": "读书要专心，练字要耐心，要之，学习贵在坚持。", "error_description": "错误：“要之”是书面连词，前面不能加程度副词“很”。正确形式是“读书要专心，练字要耐心，要之，学习贵在坚持。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90049, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亏本", "is_correct": true, "explanation": "正确。「获利」的反义是「亏本」，指做生意赔钱。"}, {"text": "寻找", "is_correct": false, "explanation": "寻找指努力去找，与「获利」没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理指把坏了的东西弄好，与「获利」没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞指随音乐做动作，与「获利」没有反义关系。"}], "correct_answer": "亏本", "explanations": {"亏本": "正确。「获利」的反义是「亏本」，指做生意赔钱。", "寻找": "寻找指努力去找，与「获利」没有反义关系。", "修理": "修理指把坏了的东西弄好，与「获利」没有反义关系。", "跳舞": "跳舞指随音乐做动作，与「获利」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
