INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90049, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "获利是做生意后，赚到了钱。", "primary_collocate": null, "pronunciation": "huò lì", "ipa": "xuo˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "他开饭馆第一年就获利了。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店每个月获利三千元。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卖水果的老王今年获利不少。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要先想办法获利。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的公司三年没获利，只好关门了。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在网上卖衣服，一个月获利五千元。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次生意获利很少，只赚了一点钱。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的商店在春节获利最多。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做小生意，每天获利一百元就不错了。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司去年没有获利，今年得想办法。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "获利了", "label": "体标"}, {"form": "获利过", "label": "体标"}, {"form": "獲利", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "做生意之后赚到钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90049, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获利", "is_correct": true, "explanation": "正确答案。获利指做生意后赚到钱。"}, {"text": "活力", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是精力、生命力。"}, {"text": "火力", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是火力、火炮的威力。"}, {"text": "互利", "is_correct": false, "explanation": "hù 与 huò 的韵母不同（少一个 o），意思是双方互相有利。"}, {"text": "握力", "is_correct": false, "explanation": "wò 与 huò 声母不同，意思是握紧东西的力量。"}], "explanations": {"获利": "正确答案。获利指做生意后赚到钱。", "活力": "huó（第二声）与 huò（第四声）声调不同，意思是精力、生命力。", "火力": "huǒ（第三声）与 huò（第四声）声调不同，意思是火力、火炮的威力。", "互利": "hù 与 huò 的韵母不同（少一个 o），意思是双方互相有利。", "握力": "wò 与 huò 声母不同，意思是握紧东西的力量。"}, "sentence_index": null, "correct_answer": "获利"}, "level_3": {"options": [{"text": "获利", "is_correct": true, "explanation": "正确。开饭馆第一年赚到了钱，符合「获利」的意思。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与开饭馆的经营结果无关，句意不通。"}, {"text": "失去", "is_correct": false, "explanation": "配价：「失去」需要宾语，句子缺少宾语，不成句。"}, {"text": "鼓掌", "is_correct": false, "explanation": "语义：鼓掌与开饭馆的经营结果不相关，句意不通。"}], "explanations": {"获利": "正确。开饭馆第一年赚到了钱，符合「获利」的意思。", "唱歌": "语义：唱歌与开饭馆的经营结果无关，句意不通。", "失去": "配价：「失去」需要宾语，句子缺少宾语，不成句。", "鼓掌": "语义：鼓掌与开饭馆的经营结果不相关，句意不通。"}, "sentence_index": 0, "correct_answer": "获利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在超市获利了一瓶水。", "explanation": "这里应该用〈得到〉。获利指赚到钱，不能用于一瓶水。"}, {"text": "今年我在工作中获利了很多汗水。", "explanation": "这里应该用〈流〉。获利指赚到钱，不能用于汗水。"}, {"text": "这次旅行，我获利了一把沙子。", "explanation": "这里应该用〈带回〉。获利指赚到钱，不能用于沙子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获利", "is_correct": true, "explanation": "正确。生意收益很少，符合「获利」的意思。"}, {"text": "亏损", "is_correct": false, "explanation": "语义：亏损与句末「只赚了一点钱」的意思相矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步与做生意的收益无关，句意不通。"}, {"text": "闲逛", "is_correct": false, "explanation": "语义：闲逛与做生意的收益无关，句意不通。"}], "explanations": {"获利": "正确。生意收益很少，符合「获利」的意思。", "亏损": "语义：亏损与句末「只赚了一点钱」的意思相矛盾。", "散步": "语义：散步与做生意的收益无关，句意不通。", "闲逛": "语义：闲逛与做生意的收益无关，句意不通。"}, "sentence_index": 6, "correct_answer": "获利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去年在学校获利了很多朋友。", "explanation": "这里应该用〈结交〉。获利指赚到钱，不用于朋友。"}, {"text": "她每天都获利了很多眼泪。", "explanation": "这里应该用〈流〉。获利指赚到钱，不能用于眼泪。"}, {"text": "这次比赛他获利了一个冠军。", "explanation": "这里应该用〈获得〉。获利指赚到钱，不用于比赛名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她开小店第一年就获利着。", "corrected_sentence": "她开小店第一年就获利了。", "error_description": "体标错误：「获利」表示结果已经完成，应用「了」，不用「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
