INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得到利润或好处。", "primary_collocate": null, "pronunciation": "huò lì", "ipa": "xuo˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这次合作，两家公司都获利了。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从这笔交易中获利不少。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有真正做好产品，公司才能长期获利。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民通过合作卖菜，获利比以前多。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店靠网上卖货获利。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家都想从贸易中获利。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法让谁获利，大家都很清楚。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司获利后，会分给大家一部分。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这笔生意里没获利，反而赔了钱。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都想知道，谁在这件事里获利最多。", "target_word": "获利", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "获利了", "label": "体标"}, {"form": "获利过", "label": "体标"}, {"form": "獲利", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "从交易、合作等事情中得到利润或好处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90050, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "获利", "is_correct": true, "explanation": "正确答案。获利指得到利润或好处。"}, {"text": "活力", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是精力、生命力。"}, {"text": "火力", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是火力、火炮的威力。"}, {"text": "互利", "is_correct": false, "explanation": "hù 与 huò 的韵母不同（少一个 o），意思是双方互相有利。"}, {"text": "握力", "is_correct": false, "explanation": "wò 与 huò 声母不同，意思是握紧东西的力量。"}], "explanations": {"获利": "正确答案。获利指得到利润或好处。", "活力": "huó（第二声）与 huò（第四声）声调不同，意思是精力、生命力。", "火力": "huǒ（第三声）与 huò（第四声）声调不同，意思是火力、火炮的威力。", "互利": "hù 与 huò 的韵母不同（少一个 o），意思是双方互相有利。", "握力": "wò 与 huò 声母不同，意思是握紧东西的力量。"}, "sentence_index": null, "correct_answer": "获利"}, "level_3": {"options": [{"text": "获利", "is_correct": true, "explanation": "正确。合作的结果是两家公司都得到了利益。"}, {"text": "失去", "is_correct": false, "explanation": "配价：「失去」需要宾语，句子缺少宾语，不成句。"}, {"text": "鼓掌", "is_correct": false, "explanation": "语义：公司不会鼓掌，与「合作」的结果不相关。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气，与两家公司的合作结果无关，句意不通。"}], "explanations": {"获利": "正确。合作的结果是两家公司都得到了利益。", "失去": "配价：「失去」需要宾语，句子缺少宾语，不成句。", "鼓掌": "语义：公司不会鼓掌，与「合作」的结果不相关。", "下雨": "语义：下雨是天气，与两家公司的合作结果无关，句意不通。"}, "sentence_index": 0, "correct_answer": "获利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈生日那天，我获利了一块石头。", "explanation": "这里应该用〈捡到〉。获利指得到利润或好处，不能用于石头。"}, {"text": "他在考试中获利了一百分。", "explanation": "这里应该用〈得了〉。获利指得到利润或好处，不能用于考试分数。"}, {"text": "我们在公园里获利了一片落叶。", "explanation": "这里应该用〈捡到〉。获利指得到利润或好处，不能用于落叶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "获利", "is_correct": true, "explanation": "正确。「让谁……」后接表示利益的动词。"}, {"text": "拿", "is_correct": false, "explanation": "配价：「拿」需要宾语，「让谁拿」不成句。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：吃饭与做法带来的利益无关，句意不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌不是利益，句意不通。"}], "explanations": {"获利": "正确。「让谁……」后接表示利益的动词。", "拿": "配价：「拿」需要宾语，「让谁拿」不成句。", "吃饭": "语义：吃饭与做法带来的利益无关，句意不通。", "唱歌": "语义：唱歌不是利益，句意不通。"}, "sentence_index": 6, "correct_answer": "获利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在雨里走了半天，获利了一身水。", "explanation": "这里应该用〈淋了〉。获利指得到利润或好处，不能用于雨水。"}, {"text": "老师在课堂上获利了很多粉笔灰。", "explanation": "这里应该用〈沾上〉。获利指得到利润或好处，不能用于粉笔灰。"}, {"text": "我们在公园里获利了一场大雨。", "explanation": "这里应该用〈遇到〉。获利是得到利益，不用于天气现象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
