INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90051, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "用来说“结果”，后面要讲为什么。", "primary_collocate": null, "pronunciation": "zhī suǒ yǐ", "ipa": "ʈʂɨ˥ suɔ˨˩˦ i˨˩˦", "syllable_count": 3, "sentences": [{"text": "这里的水果之所以便宜，是因为是自己种的。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我之所以喜欢冬天，是因为可以滑雪。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他之所以汉语好，是因为在北京住过。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗之所以叫，是因为外面有人。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她之所以搬家，是因为离公司太远。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王之所以早起，是因为要锻炼身体。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机之所以晚点，是因为天气不好。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们之所以相信他，是因为他从不说谎。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜之所以很辣，是因为放了很多辣椒。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈之所以生气，是因为我没做作业。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "先说结果，再解释原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90051, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之所以", "is_correct": true, "explanation": "正确：“之所以”引出结果，后面用“是因为”说明原因。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表让步，与后面“是自己种的”这一原因说明冲突。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”需要前文已有原因，句首不能直接说“这里的水果因此便宜”。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表递进补充，不能与“是因为”的因果说明并列。"}], "explanations": {"之所以": "正确：“之所以”引出结果，后面用“是因为”说明原因。", "尽管": "语义：“尽管”表让步，与后面“是自己种的”这一原因说明冲突。", "因此": "搭配：“因此”需要前文已有原因，句首不能直接说“这里的水果因此便宜”。", "而且": "语义：“而且”表递进补充，不能与“是因为”的因果说明并列。"}, "sentence_index": 0, "correct_answer": "之所以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗叫，之所以外面有人。", "explanation": "这里应该用〈因为〉。“之所以”引出的是要解释的结果，不能直接接原因；说明原因要用“因为”或“是因为”。"}, {"text": "天气好，之所以我们散步。", "explanation": "这里应该用〈所以〉。前面先说原因“天气好”，后面接结果要用“所以”；“之所以”只放在结果前，并要和“是因为”配合。"}, {"text": "之所以下雨，我没出门。", "explanation": "这里应该用〈由于〉。“之所以”不能引出前置的原因分句，原因应放在结果前，用“由于”引出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90051, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之所以", "is_correct": true, "explanation": "正确：“之所以”引出结果，与后面的“是因为”呼应。"}, {"text": "即使", "is_correct": false, "explanation": "语义：“即使”表假设让步，与后面“是因为天气不好”的原因说明冲突。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”需要前文已有原因，句首不能直接说“飞机所以晚点”。"}, {"text": "并且", "is_correct": false, "explanation": "语义：“并且”表并列，不能与“是因为”的因果说明搭配。"}], "explanations": {"之所以": "正确：“之所以”引出结果，与后面的“是因为”呼应。", "即使": "语义：“即使”表假设让步，与后面“是因为天气不好”的原因说明冲突。", "所以": "搭配：“所以”需要前文已有原因，句首不能直接说“飞机所以晚点”。", "并且": "语义：“并且”表并列，不能与“是因为”的因果说明搭配。"}, "sentence_index": 6, "correct_answer": "之所以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我没做作业，之所以妈妈生气。", "explanation": "这里应该用〈因为〉。“之所以”引出的是要解释的结果，不能放在原因分句之前；原因要用“因为”引出。"}, {"text": "妈妈生气，因为之所以我没做作业。", "explanation": "这里应该用〈是因为〉。原因分句要用“是因为”引出，不能在其中嵌入“之所以”。"}, {"text": "妈妈发脾气，之所以我没做作业。", "explanation": "这里应该用〈是因为〉。“我没做作业”是原因，原因要用“是因为”引出；“之所以”只能放在要解释的结果前，不能引出原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90051, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我之所以没接电话，所以手机没电。", "corrected_sentence": "我之所以没接电话，是因为手机没电。", "error_description": "“之所以”后面说明原因要用“是因为”，不能再接“所以”，这里误用了“所以”。错误形式：“我之所以没接电话，所以手机没电”；正确形式：“我之所以没接电话，是因为手机没电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90051, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我之所以迟到，所以公交车没来。", "corrected_sentence": "我之所以迟到，是因为公交车没来。", "error_description": "“之所以”后面说明原因要用“是因为”，不能再接“所以”。错误形式：“之所以迟到，所以公交车没来”；正确形式：“之所以迟到，是因为公交车没来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
