INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90052, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，引出结果，常与“是因为”搭配。", "primary_collocate": null, "pronunciation": "zhī suǒ yǐ", "ipa": "ʈʂɨ˥ suɔ˨˩˦ i˨˩˦", "syllable_count": 3, "sentences": [{"text": "他之所以迟到，是因为路上堵车。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我之所以学中文，是因为喜欢中国文化。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她之所以很累，是因为昨晚没睡好。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们之所以去海边，是因为天气很好。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他之所以不来，是因为生病了。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店之所以有名，是因为菜好吃。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子之所以哭，是因为想妈妈。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我之所以买这本书，是因为老师说它很好。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他之所以成功，是因为一直很努力。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李之所以没去，是因为要加班。", "target_word": "之所以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "引出结果，后面常用“是因为”说明原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之所以", "is_correct": true, "explanation": "正确：“之所以”引出结果，与后面的“是因为”呼应。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表让步，与后面“是因为”说明原因的语境冲突。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”需要前文已有原因，句首不能直接说“他因此迟到”。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表递进补充，不能与“是因为”的因果说明并列。"}], "explanations": {"之所以": "正确：“之所以”引出结果，与后面的“是因为”呼应。", "虽然": "语义：“虽然”表让步，与后面“是因为”说明原因的语境冲突。", "因此": "搭配：“因此”需要前文已有原因，句首不能直接说“他因此迟到”。", "而且": "语义：“而且”表递进补充，不能与“是因为”的因果说明并列。"}, "sentence_index": 0, "correct_answer": "之所以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去海边，之所以天气很好。", "explanation": "这里应该用〈是因为〉。“之所以”引出要解释的结果，后面的原因要用“是因为”引出，不能直接用“之所以”接原因分句。"}, {"text": "天气很好，之所以我们去海边。", "explanation": "这里应该用〈所以〉。“之所以”需与“是因为”配合，先说结果再说原因；这里只有结果，应直接用“所以”引出。"}, {"text": "之所以天气很好，我们去海边。", "explanation": "这里应该用〈由于〉。“之所以”不能引出前置的原因分句，原因应放在结果前，用“由于”引出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之所以", "is_correct": true, "explanation": "正确：“之所以”引出结果，与后面的“是因为”呼应。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表让步，与后面“是因为”说明原因的语境冲突。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”需要前文已有原因，句首不能直接说“孩子所以哭”。"}, {"text": "并且", "is_correct": false, "explanation": "语义：“并且”表并列，不能与“是因为”的因果说明搭配。"}], "explanations": {"之所以": "正确：“之所以”引出结果，与后面的“是因为”呼应。", "尽管": "语义：“尽管”表让步，与后面“是因为”说明原因的语境冲突。", "所以": "搭配：“所以”需要前文已有原因，句首不能直接说“孩子所以哭”。", "并且": "语义：“并且”表并列，不能与“是因为”的因果说明搭配。"}, "sentence_index": 6, "correct_answer": "之所以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小李加班，之所以没去。", "explanation": "这里应该用〈因此〉。“之所以”要先说明结果，再用“是因为”说明原因，原因分句不能直接接“之所以”。"}, {"text": "小李没去，因为之所以要加班。", "explanation": "这里应该用〈是因为〉。原因分句要用“是因为”引出，不能在其中嵌入“之所以”。"}, {"text": "他要加班，之所以小李没去。", "explanation": "这里应该用〈导致〉。前面“他要加班”是原因，后面引出它造成的结果要用“导致”或“所以”；“之所以”只能放在要解释的结果前，并和“是因为”配合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈之所以早睡，所以明天要早起。", "corrected_sentence": "妈妈之所以早睡，是因为明天要早起。", "error_description": "“之所以”后面说明原因要用“是因为”，不能再接“所以”，这里误用了“所以”。错误形式：“妈妈之所以早睡，所以明天要早起”；正确形式：“妈妈之所以早睡，是因为明天要早起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
