INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90056, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "男高音的简称，指男声中最高的声部或歌手。", "primary_collocate": null, "pronunciation": "nán gāo", "ipa": "nan˧˥ kɑʊ˥˥", "syllable_count": 2, "sentences": [{"text": "合唱团里有两位男高。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们学校的男高。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男高的声音比男低高。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌需要一个男高来唱。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位男高在台上唱得很好。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男高的声音又高又亮。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们团里的男高今天感冒了。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢听男高唱歌。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我适合当男高。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐队找了一位新男高。", "target_word": "男高", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "男高音的简称，指合唱中最高的男声声部或唱这个声部的歌手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "男高", "is_correct": true, "explanation": "男高指男声中最高的声部或歌手，合唱团里可以有两位。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不是合唱团的成员，与“合唱团里”矛盾。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判不在合唱团里唱歌，与“合唱团里”矛盾。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“合唱团里有”后接的是成员，“厨师”不搭配合唱团。"}], "explanations": {"男高": "男高指男声中最高的声部或歌手，合唱团里可以有两位。", "小偷": "语义：小偷不是合唱团的成员，与“合唱团里”矛盾。", "裁判": "语义：裁判不在合唱团里唱歌，与“合唱团里”矛盾。", "厨师": "搭配：“合唱团里有”后接的是成员，“厨师”不搭配合唱团。"}, "sentence_index": 0, "correct_answer": "男高"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌需要一只男高来唱。", "explanation": "这里应该用〈个〉或〈位〉。“只”用于动物，指人的男高要用“位”或“个”。"}, {"text": "这首歌需要一把男高来唱。", "explanation": "这里应该用〈个〉或〈位〉。“把”用于有柄的器具，不能用来数人。"}, {"text": "这首歌需要一张男高来唱。", "explanation": "这里应该用〈个〉或〈位〉。“张”用于平面的东西，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "男高", "is_correct": true, "explanation": "男高是唱歌的人，能够感冒，与“感冒了”的语境相符。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器不会感冒，与“感冒了”的主语是人矛盾。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会感冒，与“感冒了”的主语是人矛盾。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“感冒”的主语须是人或动物，“厨房”不搭配“感冒”。"}], "explanations": {"男高": "男高是唱歌的人，能够感冒，与“感冒了”的语境相符。", "乐器": "语义：乐器不会感冒，与“感冒了”的主语是人矛盾。", "汽车": "语义：汽车不会感冒，与“感冒了”的主语是人矛盾。", "厨房": "搭配：“感冒”的主语须是人或动物，“厨房”不搭配“感冒”。"}, "sentence_index": 6, "correct_answer": "男高"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是男高，唱不上高音。", "explanation": "这里应该用〈男中音〉。男高是声音最高的声部，唱不上高音的人不能称男高。"}, {"text": "这位男高的音域很低，能唱到最低的音。", "explanation": "这里应该用〈男低〉。男高指声音最高的声部，音域很低、能唱最低音的应称男低。"}, {"text": "她是男高，音色很清亮。", "explanation": "这里应该用〈女高〉。男高指男声，不能用来称呼女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "乐队的主唱是一只男高。", "corrected_sentence": "乐队的主唱是一位男高。", "error_description": "量词错误：指人的“男高”应用量词“位”或“个”，“只”用于动物，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一位出色的男高们。", "corrected_sentence": "他是一位出色的男高。", "error_description": "词尾错误：“们”不能与数量词“一位”同现，应去掉“们”，说“男高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90057, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现在", "is_correct": true, "explanation": "反义：“现在”与“以往”相对，指当前的时间。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与“以往”的时间义不构成反义。"}, {"text": "老师", "is_correct": false, "explanation": "无关：“老师”指人，与“以往”的时间义没有反义关系。"}, {"text": "公园", "is_correct": false, "explanation": "无关：“公园”是场所，与“以往”的时间义不构成反义。"}], "correct_answer": "现在", "explanations": {"现在": "反义：“现在”与“以往”相对，指当前的时间。", "河流": "无关：“河流”是地理事物，与“以往”的时间义不构成反义。", "老师": "无关：“老师”指人，与“以往”的时间义没有反义关系。", "公园": "无关：“公园”是场所，与“以往”的时间义不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90057, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现在", "is_correct": true, "explanation": "反义：“现在”与“以往”相对，指当前的时间。"}, {"text": "书包", "is_correct": false, "explanation": "无关：“书包”是物品，与“以往”的时间义没有反义关系。"}, {"text": "学生", "is_correct": false, "explanation": "无关：“学生”指人，与“以往”的时间义没有反义关系。"}, {"text": "医院", "is_correct": false, "explanation": "无关：“医院”是场所，与“以往”的时间义不构成反义。"}], "correct_answer": "现在", "explanations": {"现在": "反义：“现在”与“以往”相对，指当前的时间。", "书包": "无关：“书包”是物品，与“以往”的时间义没有反义关系。", "学生": "无关：“学生”指人，与“以往”的时间义没有反义关系。", "医院": "无关：“医院”是场所，与“以往”的时间义不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以前，过去的时候。", "primary_collocate": null, "pronunciation": "yǐ wǎng", "ipa": "i˨˩ uɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "以往这里是一片农田。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往我很少做饭，现在常做。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往下班后，他都去跑步。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往爸爸每天坐公共汽车上班。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往冬天，这条河都会结冰。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往我们见面，总是在周末。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往这个时候，街上人很多。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往他不喜欢吃鱼，现在爱吃了。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往我们住在小城市。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往学校里没有电脑。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "过去的时候，常放在句首作时间状语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不能作句首的时间状语。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能表示时间，与“这里是一片农田”也不搭。"}, {"text": "甲方", "is_correct": false, "explanation": "语域：“甲方”是合同用语，不用于描述地方的变化。"}, {"text": "以往", "is_correct": true, "explanation": "正确。“以往”作句首时间状语，指过去的时候，符合句意。"}], "explanations": {"咖啡": "语义：咖啡是饮料，不能作句首的时间状语。", "书包": "语义：书包是物品，不能表示时间，与“这里是一片农田”也不搭。", "甲方": "语域：“甲方”是合同用语，不用于描述地方的变化。", "以往": "正确。“以往”作句首时间状语，指过去的时候，符合句意。"}, "sentence_index": 0, "correct_answer": "以往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "以往我明年就要去北京工作了。", "explanation": "这里应该用〈今后〉。“以往”指过去，与“明年就要去”的将来时间矛盾。"}, {"text": "以往他给我打了电话，就在五分钟前。", "explanation": "这里应该用〈刚才〉。“以往”指较远的过去，不能与“五分钟前”这种刚刚发生的事搭配。"}, {"text": "以往我们明天就去北京。", "explanation": "这里应该用〈以后〉。“以往”指过去，不能与“明天就去”这种将来的安排搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "语义：地图不是时间，不能作句首的时间状语。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是物品，不能表示时间。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是物品，不能表示时间，不能作句首的时间状语。"}, {"text": "以往", "is_correct": true, "explanation": "正确。“以往这个时候”指过去的这个时段，符合句意。"}], "explanations": {"地图": "语义：地图不是时间，不能作句首的时间状语。", "钱包": "语义：钱包是物品，不能表示时间。", "椅子": "语义：椅子是物品，不能表示时间，不能作句首的时间状语。", "以往": "正确。“以往这个时候”指过去的这个时段，符合句意。"}, "sentence_index": 6, "correct_answer": "以往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "以往学校马上就有电脑了。", "explanation": "这里应该用〈现在〉。“以往”指过去，不能与“马上就有”这种即将发生的事搭配。"}, {"text": "以往学校明年会有电脑。", "explanation": "这里应该用〈将来〉。“以往”指过去，“明年会有”指将来，二者时间方向矛盾。"}, {"text": "以往学校以后要买电脑。", "explanation": "这里应该用〈今后〉。“以往”指过去，不能用来说将要发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "以往了下班后，他常常去跑步。", "corrected_sentence": "以往下班后，他常常去跑步。", "error_description": "错误：“以往”后加了“了”；正确：去掉“了”。“以往”作时间状语时不带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以往着学校里的电脑很少。", "corrected_sentence": "以往学校里的电脑很少。", "error_description": "错误：“以往”后加了“着”；正确：去掉“着”。“着”表示状态持续，不能附在表示过去的“以往”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90058, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现在", "is_correct": true, "explanation": "反义：“现在”与“以往”相对，指当前的时间。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”是物品，与“以往”的时间义没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”是地理事物，与“以往”的时间义不构成反义。"}, {"text": "老师", "is_correct": false, "explanation": "无关：“老师”指人，与“以往”的时间义没有反义关系。"}], "correct_answer": "现在", "explanations": {"现在": "反义：“现在”与“以往”相对，指当前的时间。", "桌子": "无关：“桌子”是物品，与“以往”的时间义没有反义关系。", "河流": "无关：“河流”是地理事物，与“以往”的时间义不构成反义。", "老师": "无关：“老师”指人，与“以往”的时间义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90058, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现在", "is_correct": true, "explanation": "反义：“现在”与“以往”相对，指当前的时间。"}, {"text": "书包", "is_correct": false, "explanation": "无关：“书包”是物品，与“以往”的时间义没有反义关系。"}, {"text": "医院", "is_correct": false, "explanation": "无关：“医院”是场所，与“以往”的时间义不构成反义。"}, {"text": "学生", "is_correct": false, "explanation": "无关：“学生”指人，与“以往”的时间义没有反义关系。"}], "correct_answer": "现在", "explanations": {"现在": "反义：“现在”与“以往”相对，指当前的时间。", "书包": "无关：“书包”是物品，与“以往”的时间义没有反义关系。", "医院": "无关：“医院”是场所，与“以往”的时间义不构成反义。", "学生": "无关：“学生”指人，与“以往”的时间义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从前；过去。", "primary_collocate": null, "pronunciation": "yǐ wǎng", "ipa": "i˨˩ uɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "今年的天气比以往冷。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往的经验告诉我们，下雨要带伞。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天比以往来得早。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试比以往难多了。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往的老师都很严格。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和以往一样，笑着打招呼。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只看以往的成绩。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以往的做法已经不合适了。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末的人比以往多。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语比以往好多了。", "target_word": "以往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "过去的时间，常作定语或用于比较", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e3767db-869b-4eb4-be40-437719540b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”指尚未到来的时间，不能与今年的天气作过去的比较。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，不能用来比较天气的冷热。"}, {"text": "以往", "is_correct": true, "explanation": "正确。“以往”指过去的时间，与“今年”形成对比，符合句意。"}, {"text": "年代", "is_correct": false, "explanation": "搭配：“年代”指一段时期，不能与“天气”比较冷热。"}], "explanations": {"明天": "语义：“明天”指尚未到来的时间，不能与今年的天气作过去的比较。", "咖啡": "语义：咖啡是饮料，不能用来比较天气的冷热。", "以往": "正确。“以往”指过去的时间，与“今年”形成对比，符合句意。", "年代": "搭配：“年代”指一段时期，不能与“天气”比较冷热。"}, "sentence_index": 0, "correct_answer": "以往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "以往我要去北京工作，明年就出发。", "explanation": "这里应该用〈今后〉。“以往”指过去，与“明年就出发”的将来时间矛盾。"}, {"text": "以往他来过我们家，就在十分钟前。", "explanation": "这里应该用〈刚才〉。“以往”指较远的过去，不能与“十分钟前”这种刚刚发生的事搭配。"}, {"text": "以往我们下周见面。", "explanation": "这里应该用〈以后〉。“以往”指过去，不能与将来的“下周”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "语义：地图不是成绩，句中“成绩”不能指地图。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是物品，不能作成绩的对象。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不是考核的对象，不能说“饭菜的成绩”。"}, {"text": "以往", "is_correct": true, "explanation": "正确。“以往的成绩”指过去的成绩，符合句意。"}], "explanations": {"地图": "语义：地图不是成绩，句中“成绩”不能指地图。", "钱包": "语义：钱包是物品，不能作成绩的对象。", "饭菜": "语义：饭菜不是考核的对象，不能说“饭菜的成绩”。", "以往": "正确。“以往的成绩”指过去的成绩，符合句意。"}, "sentence_index": 6, "correct_answer": "以往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我以往马上要出发去机场了。", "explanation": "这里应该用〈现在〉。“以往”指过去，不能与“马上要出发”这种即将发生的事搭配。"}, {"text": "以往的汉语课下个月开始。", "explanation": "这里应该用〈以后〉。“以往”指过去，不能与“下个月开始”这种将来的事搭配。"}, {"text": "他以往的汉语会比现在好。", "explanation": "“以往”指过去，句中用“会”和“现在”表示将来或当下，时间方向矛盾，应当用〈将来〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛比以往了难多了。", "corrected_sentence": "这次比赛比以往难多了。", "error_description": "错误：“以往”后多了“了”；正确：去掉“了”。“以往”是表示过去的时间词，“了”不能附着在它后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以往着的做法如今已经不合适了。", "corrected_sentence": "以往的做法如今已经不合适了。", "error_description": "错误：“以往”后加“着”；正确：去掉“着”。“以往”指过去，“着”表示状态持续，二者不能搭配；“以往的做法”是正确说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2af19692-952a-45e7-a69d-7909346243cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
