INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：与“集中”构成反义，指把注意力或东西分开、散开。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：指闭眼休息，与“集中”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：指用声音表达乐曲，与“集中”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指随意地走走，与“集中”没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散：与“集中”构成反义，指把注意力或东西分开、散开。", "睡觉": "睡觉：指闭眼休息，与“集中”没有反义关系。", "唱歌": "唱歌：指用声音表达乐曲，与“集中”没有反义关系。", "散步": "散步：指随意地走走，与“集中”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "集中是把心思或注意力放到一件事上，专心不分散。", "primary_collocate": null, "pronunciation": "jí zhōng", "ipa": "tɕi³⁵ ʈʂʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "上课时，请把注意力集中在黑板上。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候，他把心思全集中在题目上。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习的时候，我很难集中精神。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要集中想一想，这道题不难。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她集中精力读完了这本书。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要集中注意力，你就能听懂老师的话。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时要集中注意，不能看手机。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把心思集中到工作上，不想别的。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里太吵了，我没办法集中精神。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把注意力集中在画上，忘了吃饭。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集中了", "label": "体标"}, {"form": "集中着", "label": "体标"}, {"form": "集中过", "label": "体标"}, {"form": "集中营", "label": "复合"}], "register": "中性", "sense_fingerprint": "把心思或注意力专注到一件事上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62640798-92c2-46f8-9980-a0d08bce8395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集中", "is_correct": true, "explanation": "集中（jí zhōng）：把注意力放到一件事上，是本题要听的词。"}, {"text": "击中", "is_correct": false, "explanation": "击中（jī zhòng）与集中（jí zhōng）两个音节的声调都不同，意思是“打中”。"}, {"text": "击钟", "is_correct": false, "explanation": "击钟（jī zhōng）与集中（jí zhōng）只有第一音节的声调不同，意思是“敲钟”。"}, {"text": "季中", "is_correct": false, "explanation": "季中（jì zhōng）与集中（jí zhōng）只有第一音节的声调不同（jì 与 jí），意思是“一个季度或赛季的中间”。"}], "explanations": {"集中": "集中（jí zhōng）：把注意力放到一件事上，是本题要听的词。", "击中": "击中（jī zhòng）与集中（jí zhōng）两个音节的声调都不同，意思是“打中”。", "击钟": "击钟（jī zhōng）与集中（jí zhōng）只有第一音节的声调不同，意思是“敲钟”。", "季中": "季中（jì zhōng）与集中（jí zhōng）只有第一音节的声调不同（jì 与 jí），意思是“一个季度或赛季的中间”。"}, "sentence_index": null, "correct_answer": "集中"}, "level_3": {"options": [{"text": "挂", "is_correct": false, "explanation": "搭配：“挂”的对象是具体物件，注意力不能挂在黑板上。"}, {"text": "集中", "is_correct": true, "explanation": "集中：把心思专注在一处，与上课看黑板的语境相符。"}, {"text": "贴", "is_correct": false, "explanation": "搭配：“贴”要求把东西附着在表面上，注意力不能贴在黑板上。"}, {"text": "撒", "is_correct": false, "explanation": "语义：“撒”指把颗粒或液体散落开来，与抽象的注意力无关。"}], "explanations": {"挂": "搭配：“挂”的对象是具体物件，注意力不能挂在黑板上。", "集中": "集中：把心思专注在一处，与上课看黑板的语境相符。", "贴": "搭配：“贴”要求把东西附着在表面上，注意力不能贴在黑板上。", "撒": "语义：“撒”指把颗粒或液体散落开来，与抽象的注意力无关。"}, "sentence_index": 0, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的情绪很集中，一点都不着急。", "explanation": "这里应该用〈稳定〉。集中指把心思或东西聚到一处，不能用来形容情绪的平稳，形容情绪要用稳定。"}, {"text": "书架上的书按大小集中。", "explanation": "这里应该用〈排列〉。集中强调把分散的东西聚到一处，不能指按一定顺序摆放，按大小摆放要用排列。"}, {"text": "他一直集中良好的状态。", "explanation": "这里应该用〈保持〉。集中是把分散的东西或心思聚到一处，不能用于维持某种状态，维持良好状态要用保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放大", "is_correct": false, "explanation": "搭配：“放大”多用于图像或声音，注意力不能被放大到开车的状态。"}, {"text": "集中", "is_correct": true, "explanation": "集中：全神贯注地注意前方，与开车时不能看手机的要求一致。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少”指数量变少，与开车时要专注的要求相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指不再坚持，开车时放弃注意会有危险，与句意不符。"}], "explanations": {"放大": "搭配：“放大”多用于图像或声音，注意力不能被放大到开车的状态。", "集中": "集中：全神贯注地注意前方，与开车时不能看手机的要求一致。", "减少": "语义：“减少”指数量变少，与开车时要专注的要求相反。", "放弃": "语义：“放弃”指不再坚持，开车时放弃注意会有危险，与句意不符。"}, "sentence_index": 6, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上课累了，请大家集中身体休息一下。", "explanation": "这里应该用〈放松〉。集中是把分散的东西或心思聚到一处，不能用于让身体休息，放松身体要用放松。"}, {"text": "一开门，人群就集中离开了。", "explanation": "这里应该用〈散开〉。集中是聚拢的意思，不能表示向四处离去，人群四散要用散开。"}, {"text": "他的脾气很集中，发起火来很吓人。", "explanation": "这里应该用〈暴躁〉。集中是把分散的东西或心思放到一起，不能用来形容脾气，形容脾气不好要用暴躁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把全部精力集中学习上。", "corrected_sentence": "他把全部精力集中在学习上。", "error_description": "错误：“集中”后缺少介词“在”。正确：引进处所时要用“在”，说“集中在学习上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把注意力集中给书本上。", "corrected_sentence": "他把注意力集中在书本上。", "error_description": "错误：引进处所的介词用了“给”，“给”表示给予，与“集中”的意思不搭。正确：应用“在”，说“集中在书本上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
