INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把分散的人、物或精力聚在一起。", "primary_collocate": null, "pronunciation": "jí zhōng", "ipa": "tɕi³⁵ ʈʂʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "老师把全班同学集中在操场上。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把旧书集中放到了一个房间。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要集中力量完成这个新计划。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要把时间和精力集中用在学习上。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的年轻人都集中在工厂里工作。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们集中在门口，等着导游。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家下午三点在门口集中，然后一起出发。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把水平差不多的学生集中在一个班。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们都集中到了这家医院，帮助生病的人。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的大学大多集中在东边。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集中了", "label": "体标"}, {"form": "集中着", "label": "体标"}, {"form": "集中过", "label": "体标"}, {"form": "集中营", "label": "复合"}], "register": "中性", "sense_fingerprint": "把分散的人、物或精力聚到一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62640798-92c2-46f8-9980-a0d08bce8395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90060, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集中", "is_correct": true, "explanation": "集中（jí zhōng）：把分散的人、物或精力聚在一起，是本题要听的词。"}, {"text": "击中", "is_correct": false, "explanation": "击中（jī zhòng）与集中（jí zhōng）两个音节的声调都不同，意思是“打中”。"}, {"text": "击钟", "is_correct": false, "explanation": "击钟（jī zhōng）与集中（jí zhōng）只有第一音节的声调不同，意思是“敲钟”。"}, {"text": "季中", "is_correct": false, "explanation": "季中（jì zhōng）与集中（jí zhōng）只有第一音节的声调不同（jì 与 jí），意思是“一个季度或赛季的中间”。"}], "explanations": {"集中": "集中（jí zhōng）：把分散的人、物或精力聚在一起，是本题要听的词。", "击中": "击中（jī zhòng）与集中（jí zhōng）两个音节的声调都不同，意思是“打中”。", "击钟": "击钟（jī zhōng）与集中（jí zhōng）只有第一音节的声调不同，意思是“敲钟”。", "季中": "季中（jì zhōng）与集中（jí zhōng）只有第一音节的声调不同（jì 与 jí），意思是“一个季度或赛季的中间”。"}, "sentence_index": null, "correct_answer": "集中"}, "level_3": {"options": [{"text": "扔", "is_correct": false, "explanation": "语域：“扔”带有轻慢的意思，不适合描述老师对学生的安排。"}, {"text": "集中", "is_correct": true, "explanation": "集中：把人聚到一处，与“老师把全班同学安排在操场上”的句意相符。"}, {"text": "埋", "is_correct": false, "explanation": "语义：“埋”指把东西藏入土中，同学不能被埋在操场上。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”一般用于球等物体，不能说把人踢到某处。"}], "explanations": {"扔": "语域：“扔”带有轻慢的意思，不适合描述老师对学生的安排。", "集中": "集中：把人聚到一处，与“老师把全班同学安排在操场上”的句意相符。", "埋": "语义：“埋”指把东西藏入土中，同学不能被埋在操场上。", "踢": "搭配：“踢”一般用于球等物体，不能说把人踢到某处。"}, "sentence_index": 0, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校集中了一次运动会。", "explanation": "这里应该用〈组织〉。集中指把人或物聚到一处，不能用于举办活动，举办活动要用组织。"}, {"text": "他集中了一个好习惯。", "explanation": "这里应该用〈培养〉。集中指把分散的东西聚到一处，不能用于养成习惯，养成习惯要用培养。"}, {"text": "他很快集中好了书包。", "explanation": "这里应该用〈收拾〉。集中是把散落的东西聚到一起，不是整理好，整理物品要用收拾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解散", "is_correct": false, "explanation": "语义：“解散”是各自散去，与后面“一起出发”的句意矛盾。"}, {"text": "集中", "is_correct": true, "explanation": "集中：在门口聚到一起，与“然后一起出发”的安排相符。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”是各自走开，与“一起出发”的安排不符。"}, {"text": "投掷", "is_correct": false, "explanation": "搭配：“投掷”的对象是物体，不能用来描述人在门口聚合。"}], "explanations": {"解散": "语义：“解散”是各自散去，与后面“一起出发”的句意矛盾。", "集中": "集中：在门口聚到一起，与“然后一起出发”的安排相符。", "离开": "语义：“离开”是各自走开，与“一起出发”的安排不符。", "投掷": "搭配：“投掷”的对象是物体，不能用来描述人在门口聚合。"}, "sentence_index": 6, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很集中，坐着很舒服。", "explanation": "这里应该用〈舒适〉。集中是把分散的人或物聚到一处，不能用来形容椅子的坐感，形容坐着舒服要用舒适。"}, {"text": "这只猫的毛很集中，摸起来很软。", "explanation": "这里应该用〈密集〉。集中是把分散的东西聚到一处，不能用来形容毛发的疏密，形容毛发疏密要用密集。"}, {"text": "他的鞋子很集中，穿起来很舒服。", "explanation": "这里应该用〈合脚〉。集中是把分散的东西或心思聚到一处，不能用来形容鞋子的大小，形容鞋子大小合适要用合脚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把全班同学集中教室里。", "corrected_sentence": "老师把全班同学集中在教室里。", "error_description": "错误：“集中”后缺少介词“在”。正确：引进处所时要用“在”，说“集中在教室里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把书都集中往一起了。", "corrected_sentence": "他把书都集中到一起了。", "error_description": "错误：引进补语的介词用了“往”，“往”表示朝向某个方向，不能表示聚拢到一处。正确：应用“到”，说“集中到一起了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
