INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "到外国学习的学生。", "primary_collocate": null, "pronunciation": "liú xué shēng", "ipa": "liou̯˧˥ ɕɥe˧˥ ʂəŋ˥˥", "syllable_count": 3, "sentences": [{"text": "我们班有三个留学生。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位留学生来自日本。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "留学生需要办理签证。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是在北京大学学习的留学生。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给留学生准备了汉语课。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多留学生周末去爬山。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个留学生汉语说得很好。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "留学生们在中国过了春节。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是去美国学习的留学生。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请留学生介绍自己的国家。", "target_word": "留学生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "女留学生", "label": "复合词"}, {"form": "留學生", "label": "繁体"}], "register": "中性", "sense_fingerprint": "到外国学习的学生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，不能说“三个空气”。"}, {"text": "留学生", "is_correct": true, "explanation": "正确：“留学生”指到外国学习的学生，是人，可以用“三个”计数，符合“我们班有”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“我们班”指一群人，“天气”不能被班里拥有或数量化。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“我们班”是一群人，“月亮”不能在班里被计数。"}], "explanations": {"空气": "搭配：“空气”是不可数名词，不能说“三个空气”。", "留学生": "正确：“留学生”指到外国学习的学生，是人，可以用“三个”计数，符合“我们班有”的语境。", "天气": "语义：“我们班”指一群人，“天气”不能被班里拥有或数量化。", "月亮": "语义：“我们班”是一群人，“月亮”不能在班里被计数。"}, "sentence_index": 0, "correct_answer": "留学生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只小狗是我们班的留学生。", "explanation": "这里应该用〈宠物〉。留学生指到外国学习的人，小狗不能是留学生。"}, {"text": "我哥哥在北京大学读留学生，专业是历史。", "explanation": "这里应该用〈研究生〉。“读”后面接的是学位或学历，留学生表示身份，不能说“读留学生”。"}, {"text": "她从没去过国外，却是一名留学生。", "explanation": "这里应该用〈在国内上学的人〉。留学生指到外国学习的人，从没出过国的人不能称为留学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教室", "is_correct": false, "explanation": "语义：“教室”不会说汉语，句子的主语必须是能说话的人。"}, {"text": "留学生", "is_correct": true, "explanation": "正确：“留学生”是人，能“汉语说得很好”，量词“个”也搭配。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“歌曲”的量词是“首”，不说“这个歌曲”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不会说话，不能“汉语说得很好”。"}], "explanations": {"教室": "语义：“教室”不会说汉语，句子的主语必须是能说话的人。", "留学生": "正确：“留学生”是人，能“汉语说得很好”，量词“个”也搭配。", "歌曲": "搭配：“歌曲”的量词是“首”，不说“这个歌曲”。", "窗户": "语义：“窗户”不会说话，不能“汉语说得很好”。"}, "sentence_index": 6, "correct_answer": "留学生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他七十岁了，在家养花，是一名留学生。", "explanation": "这里应该用〈退休老人〉。留学生指到外国学习的学生，在家养花的老人不是留学生。"}, {"text": "他在国内的银行工作了十年，是一名留学生。", "explanation": "这里应该用〈职员〉。留学生指到外国学习的学生，在银行工作多年的人不能称为留学生。"}, {"text": "他去年考上了留学生。", "explanation": "这里应该用〈大学〉。“考上”接的是学校或专业，留学生指人，不能说考上留学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一名来自法国留学生。", "corrected_sentence": "他是一名来自法国的留学生。", "error_description": "“来自法国”修饰“留学生”时要加“的”，应说“来自法国的留学生”，不能省略“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有三个留学生们在学汉语。", "corrected_sentence": "我们班有三个留学生在学汉语。", "error_description": "数量词“三个”后面不能再加“们”，应说“三个留学生”。“们”只用于不带数量词的复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
