INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90063, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "和以前一样，没有变。", "primary_collocate": null, "pronunciation": "yī jiù", "ipa": "i˥ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这么多年，他的家依旧很简单。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年不见，她依旧那么年轻。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市变大了，老街依旧热闹。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜，味道依旧很好。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子里的房子依旧是老样子。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了工作，性格依旧很温和。", "target_word": "依旧", "complexity_tier": "T3", "furigana": "tā huàn le gōngzuò, xìnggé yījiù hěn wēnhé.", "sentence_source": "generated"}, {"text": "过了二十年，那棵树依旧站在门口。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年不见，你笑起来依旧那么好看。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的操场依旧是我记得的样子。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年后回来，这里的空气依旧很好。", "target_word": "依旧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示事物的状态、样子和以前一样，没有改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3028915b-04fc-4478-8fb7-63277b2eed09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90063, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依旧", "is_correct": true, "explanation": "依旧 yī jiù：和以前一样，没有变。"}, {"text": "已久", "is_correct": false, "explanation": "已久 yǐ jiǔ：声调不同（依旧为第一、第四声，已久为第三、第三声），意思是时间很长，不是没有变。"}, {"text": "衣袖", "is_correct": false, "explanation": "xiù 与 jiù 声母不同（x 与 j），意思是衣服的袖子。"}, {"text": "依据", "is_correct": false, "explanation": "jù 与 jiù 韵母不同（少了 i），意思是根据。"}, {"text": "一句", "is_correct": false, "explanation": "jù 与 jiù 韵母不同（少了 i），意思是一句话。"}], "explanations": {"依旧": "依旧 yī jiù：和以前一样，没有变。", "已久": "已久 yǐ jiǔ：声调不同（依旧为第一、第四声，已久为第三、第三声），意思是时间很长，不是没有变。", "衣袖": "xiù 与 jiù 声母不同（x 与 j），意思是衣服的袖子。", "依据": "jù 与 jiù 韵母不同（少了 i），意思是根据。", "一句": "jù 与 jiù 韵母不同（少了 i），意思是一句话。"}, "sentence_index": null, "correct_answer": "依旧"}, "level_3": {"options": [{"text": "依旧", "is_correct": true, "explanation": "依旧：和以前一样，这么多年家里仍然很简单，符合句意。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，不能描述一直保持的状态。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急忙，不能用来描述家的状态。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”后接庆幸的结果，不说“这么多年，幸好他的家很简单”。"}], "explanations": {"依旧": "依旧：和以前一样，这么多年家里仍然很简单，符合句意。", "偶尔": "语义：“偶尔”表示有时，不能描述一直保持的状态。", "赶紧": "语义：“赶紧”表示急忙，不能用来描述家的状态。", "幸好": "搭配：“幸好”后接庆幸的结果，不说“这么多年，幸好他的家很简单”。"}, "sentence_index": 0, "correct_answer": "依旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他依旧搬走了。", "explanation": "这里应该用〈已经〉。“依旧”表示和以前一样、没有变，不能用来说明已经完成的动作（搬走）。"}, {"text": "他第一次来这家饭馆，依旧觉得味道很好。", "explanation": "这里不能用〈依旧〉。“依旧”表示和以前一样，句中是“第一次”来，没有以前的情况可以延续，应说“刚来这家饭馆，觉得味道很好”。"}, {"text": "这家饭馆的菜味道依旧变了很多。", "explanation": "这里应该用〈不再〉。“依旧”表示和以前一样、没有变，与“变了很多”相矛盾，句意应是味道已经不再是以前的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依旧", "is_correct": true, "explanation": "依旧：和以前一样，过了二十年树仍然站在门口，符合句意。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，不能描述树二十年来一直保持的状态。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”多接即时的动作，不能与“过了二十年”搭配来描述站立的状态。"}, {"text": "赶忙", "is_correct": false, "explanation": "语义：“赶忙”表示急忙去做，不能用来描述树的状态。"}], "explanations": {"依旧": "依旧：和以前一样，过了二十年树仍然站在门口，符合句意。", "忽然": "语义：“忽然”表示突然发生，不能描述树二十年来一直保持的状态。", "立即": "搭配：“立即”多接即时的动作，不能与“过了二十年”搭配来描述站立的状态。", "赶忙": "语义：“赶忙”表示急忙去做，不能用来描述树的状态。"}, "sentence_index": 6, "correct_answer": "依旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他依旧考上了大学。", "explanation": "这里应该用〈终于〉。“依旧”表示和以前一样，不能用来说明一件以前没有发生过的事终于实现。"}, {"text": "这座城市变得很大，依旧是他离开时的老样子。", "explanation": "这里应该用〈不再〉。“依旧”表示没有变，与“变得很大”冲突，句意应是城市已不再是原来的样子。"}, {"text": "他昨天第一次来这里，依旧很喜欢这里。", "explanation": "这里不能用〈依旧〉。“依旧”表示和以前一样，句中是“第一次”来，没有以前的情况可以延续，应去掉“依旧”，说“很喜欢这里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小镇的夜晚很依旧安静。", "corrected_sentence": "这个小镇的夜晚依旧安静。", "error_description": "错误：“依旧”前多加了程度副词“很”（很依旧安静）。正确：“依旧”是副词，不能被“很”修饰，应说“夜晚依旧安静”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他退休以后，不依旧每天早上散步。", "corrected_sentence": "他退休以后，依旧每天早上散步。", "error_description": "错误：“依旧”前多加了否定词“不”（不依旧每天早上散步）。正确：“依旧”表示延续，不能被“不”否定，应说“依旧每天早上散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7c04cce-fd6a-41d9-b5b1-ad2416b38eb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
