INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90066, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同的意见，不赞成的看法。", "primary_collocate": null, "pronunciation": "yì yì", "ipa": "i˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "他的异议很有道理。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这项规定，不少市民有异议。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理认真听了大家的异议。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定没有遇到任何异议。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的异议让会议停了下来。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们对新方案提出了几个异议。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小声说出了自己的异议。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这篇文章的说法有异议。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有异议，可以马上说。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的异议都写在了这张纸上。", "target_word": "异议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "异议：不赞成的看法、不同的意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a0ab2c6-267b-46f6-963b-75f6b1d7240e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "异议", "is_correct": true, "explanation": "正确：“很有道理”修饰的是不同的看法，只有“异议”合适。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“很有道理”修饰看法、意见，不修饰“体重”。"}, {"text": "门牌", "is_correct": false, "explanation": "语义：“门牌”不能“有道理”，与句意冲突。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”不能“有道理”，与句意冲突。"}], "explanations": {"异议": "正确：“很有道理”修饰的是不同的看法，只有“异议”合适。", "体重": "搭配：“很有道理”修饰看法、意见，不修饰“体重”。", "门牌": "语义：“门牌”不能“有道理”，与句意冲突。", "面包": "语义：“面包”不能“有道理”，与句意冲突。"}, "sentence_index": 0, "correct_answer": "异议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他提出了一根异议。", "explanation": "这里应该用〈个〉或〈项〉。“根”用于细长的物体，不能计量异议。"}, {"text": "她提出了一面异议。", "explanation": "这里应该用〈个〉或〈项〉。“面”用于平面物，不能计量异议。"}, {"text": "他提出了一台异议。", "explanation": "这里应该用〈个〉或〈项〉。“台”用于机器、设备，不能计量异议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "异议", "is_correct": true, "explanation": "正确：她小声说出的是自己的不同意见，只有“异议”合适。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“说出”接想法、意见，不接“眼睛”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不能被“说出”，与句意冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不能被“说出”，与句意冲突。"}], "explanations": {"异议": "正确：她小声说出的是自己的不同意见，只有“异议”合适。", "眼睛": "搭配：“说出”接想法、意见，不接“眼睛”。", "手机": "语义：“手机”不能被“说出”，与句意冲突。", "冰箱": "语义：“冰箱”不能被“说出”，与句意冲突。"}, "sentence_index": 6, "correct_answer": "异议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他提出了一扇异议。", "explanation": "这里应该用〈个〉或〈项〉。“扇”用于门窗等，不能计量异议。"}, {"text": "她提出了一把异议。", "explanation": "这里应该用〈个〉或〈项〉。“把”用于有柄的物品，不能计量异议。"}, {"text": "他提出了一颗异议。", "explanation": "这里应该用〈个〉或〈项〉。“颗”用于颗粒状的小物件，不能计量异议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这份合同提出了三只异议。", "corrected_sentence": "他对这份合同提出了三项异议。", "error_description": "“异议”的量词错误。“只”用于动物，计量异议应说“三项异议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对这个计划提出了两张异议。", "corrected_sentence": "她对这个计划提出了两项异议。", "error_description": "“异议”的量词错误。“张”用于纸、桌子等平面物，计量异议应说“两项异议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'debdafb8-2282-4276-b12c-3214e8a84f19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
