INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90067, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "说一件还没有发生的事，如果它发生了会怎么样。", "primary_collocate": null, "pronunciation": "jiǎ rú", "ipa": "tɕja˨˩ ʐu˧˥", "syllable_count": 2, "sentences": [{"text": "假如明天下雨，我们不去公园了。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如我有很多钱，我想环游世界。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如你是我，你会怎么做？", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如明天不上班，我想睡到中午。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如他不来，我们先开始吧。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如我会飞，我想去看妈妈。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如时间可以回去，你想做什么？", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如你有一天假，你想去哪里？", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如这次考试没通过，我再考一次。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如天气好，我们周末去爬山。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "假设还没发生的事，引出可能的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90067, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假如", "is_correct": true, "explanation": "正确答案。“假如”是连词，表示假设，引出可能的结果。"}, {"text": "加入", "is_correct": false, "explanation": "jiā rù 与 jiǎ rú 的声调都不同（第一声、第四声与第三声、第二声），意思是参加进去。"}, {"text": "嫁入", "is_correct": false, "explanation": "jià rù 与 jiǎ rú 的声调都不同，意思是女子结婚后成为某家的人。"}, {"text": "夹入", "is_correct": false, "explanation": "jiā rù 与 jiǎ rú 声母韵母相同，声调不同，意思是夹进去。"}], "explanations": {"假如": "正确答案。“假如”是连词，表示假设，引出可能的结果。", "加入": "jiā rù 与 jiǎ rú 的声调都不同（第一声、第四声与第三声、第二声），意思是参加进去。", "嫁入": "jià rù 与 jiǎ rú 的声调都不同，意思是女子结婚后成为某家的人。", "夹入": "jiā rù 与 jiǎ rú 声母韵母相同，声调不同，意思是夹进去。"}, "sentence_index": null, "correct_answer": "假如"}, "level_3": {"options": [{"text": "假如", "is_correct": true, "explanation": "正确答案。“假如”引出假设条件，“假如明天下雨”成立。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，后文应与之相对，“虽然明天下雨，我们不去公园了”逻辑不通。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”要连接并列的动作或分句，不能开头，“并且明天下雨”不成立。"}, {"text": "从而", "is_correct": false, "explanation": "语义：“从而”表示由前文的行为导致的结果，句首没有前文，“从而明天下雨”不通。"}], "explanations": {"假如": "正确答案。“假如”引出假设条件，“假如明天下雨”成立。", "虽然": "语义：“虽然”表示让步，后文应与之相对，“虽然明天下雨，我们不去公园了”逻辑不通。", "并且": "搭配：“并且”要连接并列的动作或分句，不能开头，“并且明天下雨”不成立。", "从而": "语义：“从而”表示由前文的行为导致的结果，句首没有前文，“从而明天下雨”不通。"}, "sentence_index": 0, "correct_answer": "假如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "假如他怎么说，我都不相信。", "explanation": "这里应该用〈无论〉。假如表示假设条件，不能表示“不管怎样都”的意思，“无论”才对。"}, {"text": "假如他很累，却还在工作。", "explanation": "这里应该用〈虽然〉。假如表示假设，不能表示让步，“虽然”才对。"}, {"text": "假如天很冷，我们没去公园。", "explanation": "这里应该用〈因为〉。假如表示假设，不能说明已经发生的原因，“因为”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90067, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "假如", "is_correct": true, "explanation": "正确答案。“假如”是连词，表示假设，引出可能的结果。"}, {"text": "家人", "is_correct": false, "explanation": "jiā rén 与 jiǎ rú 的声调不同，第二音节韵母也不同（én／ú），意思是家庭成员。"}, {"text": "假日", "is_correct": false, "explanation": "jià rì 与 jiǎ rú 声调不同，第二音节韵母也不同（ì／ú），意思是假期的日子。"}, {"text": "假人", "is_correct": false, "explanation": "jiǎ rén 与 jiǎ rú 的第二音节韵母不同（én／ú），意思是模拟人形的假人。"}], "explanations": {"假如": "正确答案。“假如”是连词，表示假设，引出可能的结果。", "家人": "jiā rén 与 jiǎ rú 的声调不同，第二音节韵母也不同（én／ú），意思是家庭成员。", "假日": "jià rì 与 jiǎ rú 声调不同，第二音节韵母也不同（ì／ú），意思是假期的日子。", "假人": "jiǎ rén 与 jiǎ rú 的第二音节韵母不同（én／ú），意思是模拟人形的假人。"}, "sentence_index": null, "correct_answer": "假如"}, "level_3": {"options": [{"text": "假如", "is_correct": true, "explanation": "正确答案。“假如时间可以回去”表示假设，后文问“你想做什么”，前后连贯。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出的是已成立的原因，而时间能否回去是假设，“因为时间可以回去”不符合事实。"}, {"text": "所以", "is_correct": false, "explanation": "配价：“所以”需要接在前面的原因之后，句首没有原因可承接。"}, {"text": "然而", "is_correct": false, "explanation": "配价：“然而”表示转折，需要接在前文之后，句首没有上文可转。"}], "explanations": {"假如": "正确答案。“假如时间可以回去”表示假设，后文问“你想做什么”，前后连贯。", "因为": "语义：“因为”引出的是已成立的原因，而时间能否回去是假设，“因为时间可以回去”不符合事实。", "所以": "配价：“所以”需要接在前面的原因之后，句首没有原因可承接。", "然而": "配价：“然而”表示转折，需要接在前文之后，句首没有上文可转。"}, "sentence_index": 6, "correct_answer": "假如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他假如很聪明，只是不努力。", "explanation": "这里应该用〈其实〉。假如表示假设，不能用来陈述已知的事实，“其实”才对。"}, {"text": "他假如没有生气，反而笑了。", "explanation": "这里应该用〈不但〉。假如表示假设，不能和“反而”构成递进转折，“不但……反而”才对。"}, {"text": "他很聪明，假如很努力。", "explanation": "这里应该用〈而且〉。假如表示假设，不能表示并列的补充，“而且”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "假如你有时间吗，来帮我吧。", "corrected_sentence": "假如你有时间，来帮我吧。", "error_description": "多余的“吗”：“假如”引出假设条件，分句不能用“吗”表示疑问。应说“假如你有时间，来帮我吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "假如你想学汉语，所以来北京吧。", "corrected_sentence": "假如你想学汉语，就来北京吧。", "error_description": "结果词错误：“假如”引出的假设结果要用“就”呼应，不能用表示因果的“所以”。应说“假如你想学汉语，就来北京吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
