INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90068, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示假设的连词，如果。", "primary_collocate": null, "pronunciation": "jiǎ rú", "ipa": "tɕja˨˩ ʐu˧˥", "syllable_count": 2, "sentences": [{"text": "假如你累了，先休息一下吧。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如他同意，我们明天出发。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如路上堵车，你给我打电话。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如你找不到我，请发信息。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如我迟到了，你们先吃饭。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如有问题，请问老师。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如你喜欢这本书，我送给你。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如明天太冷，我们在家看电影。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如他不在家，请你等一下。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假如你有时间，我们一起去吃饭。", "target_word": "假如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示假设条件的连词，相当于如果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f614a37e-859d-480a-acef-93c3977707a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90068, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假如", "is_correct": true, "explanation": "假如（jiǎ rú）是正确答案，表示假设条件的连词。"}, {"text": "加入", "is_correct": false, "explanation": "加入（jiā rù）与假如两个音节的声调都不同，意思是参加或加进去，不是连词。"}, {"text": "嫁入", "is_correct": false, "explanation": "嫁入（jià rù）与假如两个音节的声调都不同，意思是女子嫁到某家，不是假设。"}, {"text": "夹入", "is_correct": false, "explanation": "夹入（jiā rù）与假如两个音节的声调都不同，意思是夹进去，不是假设。"}], "explanations": {"假如": "假如（jiǎ rú）是正确答案，表示假设条件的连词。", "加入": "加入（jiā rù）与假如两个音节的声调都不同，意思是参加或加进去，不是连词。", "嫁入": "嫁入（jià rù）与假如两个音节的声调都不同，意思是女子嫁到某家，不是假设。", "夹入": "夹入（jiā rù）与假如两个音节的声调都不同，意思是夹进去，不是假设。"}, "sentence_index": null, "correct_answer": "假如"}, "level_3": {"options": [{"text": "假如", "is_correct": true, "explanation": "假如表示假设条件，与后面“先休息一下”的建议相符。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”要与前面的“不是”对应，句首没有否定成分，不成立。"}, {"text": "从而", "is_correct": false, "explanation": "语义：“从而”表示由前文导致的结果，句首没有前文可承接，“从而你累了”不通。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”要连接并列的成分，句首没有可并列的谓语，不成立。"}], "explanations": {"假如": "假如表示假设条件，与后面“先休息一下”的建议相符。", "而是": "搭配：“而是”要与前面的“不是”对应，句首没有否定成分，不成立。", "从而": "语义：“从而”表示由前文导致的结果，句首没有前文可承接，“从而你累了”不通。", "并且": "搭配：“并且”要连接并列的成分，句首没有可并列的谓语，不成立。"}, "sentence_index": 0, "correct_answer": "假如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨天没复习，假如考试没及格。", "explanation": "这里应该用〈因此〉。因此表示由前面的情况导致的结果，考试已经发生；假如只表示尚未发生的假设，用在已经发生的结果上就不对了。"}, {"text": "假如他病了，所以今天没来上课。", "explanation": "这里应该用〈因为〉。因为说明已经发生的原因，和后面的“所以”配合；假如只表示假设，不能和“所以”一起说明已发生的事。"}, {"text": "假如下雨，我们还是去了。", "explanation": "这里应该用〈虽然〉。虽然表示让步，先承认前面的情况，再说结果不受影响；假如只表示假设，不能表示让步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假如", "is_correct": true, "explanation": "假如表示假设条件，符合“我送给你”以对方喜欢为前提的句意。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，这句的关系是假设条件，不是时间先后。"}, {"text": "可是", "is_correct": false, "explanation": "语义：“可是”表示转折，句中没有与“喜欢”相反的内容可以对照。"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”表示否则，这句要表达的是条件，不是否则会怎样。"}], "explanations": {"假如": "假如表示假设条件，符合“我送给你”以对方喜欢为前提的句意。", "然后": "语义：“然后”表示先后顺序，这句的关系是假设条件，不是时间先后。", "可是": "语义：“可是”表示转折，句中没有与“喜欢”相反的内容可以对照。", "不然": "语义：“不然”表示否则，这句要表达的是条件，不是否则会怎样。"}, "sentence_index": 6, "correct_answer": "假如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天下了大雨，假如路上很滑。", "explanation": "这里应该用〈所以〉。所以表示由前面的原因得出的结果，下雨已经发生；假如只表示假设，不能引出已经出现的结果。"}, {"text": "他很聪明，假如很努力。", "explanation": "这里应该用〈而且〉。而且表示递进，连接同一个人的两种性质；假如是假设连词，这里把它说成假设就不通。"}, {"text": "假如你提醒我，我才没忘。", "explanation": "这里应该用〈幸亏〉。幸亏表示因某人某事避免了不好的结果，是已经发生的事；假如只是假设，说不清避免了什么。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "假如如果你饿了，就先吃点东西吧。", "corrected_sentence": "假如你饿了，就先吃点东西吧。", "error_description": "错误：“假如”与“如果”叠用，连词重复了。正确：只用“假如”，写成“假如你饿了”。两者同义，不能并用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "假如的你有空，我们就去吧。", "corrected_sentence": "假如你有空，我们就去吧。", "error_description": "错误：“假如”后面多加了“的”。正确：“假如你有空”。“假如”后直接接假设的主语或分句，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6969dd0-3d6c-439a-8c87-78a0fd421eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
