INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90069, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面前是在你脸对着的前面。", "primary_collocate": null, "pronunciation": "miàn qián", "ipa": "mi̯ɛn˥˩ tɕʰi̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他走到我面前,笑着说你好。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员把菜放在我面前。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你站在我面前,我什么都看不见。", "target_word": "面前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗跑到你面前,不停地叫。", "target_word": "面前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把那封信放到我面前,让我看。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师来到我面前,问我怎么了。", "target_word": "面前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一辆红色的车停在我面前。", "target_word": "面前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你坐到我面前来。", "target_word": "面前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈把热汤端到我面前。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子走到你面前,拉了拉你的手。", "target_word": "面前", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "面前:自己脸朝向的前方,常与走到、放到等动作连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84adf9-f7e5-4676-ae12-1e74b754fae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90069, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面前", "is_correct": true, "explanation": "正确：面前 miàn qián，即题目所给词。"}, {"text": "免签", "is_correct": false, "explanation": "miǎn qiān 与 miàn qián 声母韵母相同，只是声调不同，意思是不用办签证。"}, {"text": "现钱", "is_correct": false, "explanation": "xiàn 与 miàn 只有声母不同（x 与 m），意思是现金。"}, {"text": "棉签", "is_correct": false, "explanation": "mián 与 miàn 声调不同，qiān 与 qián 声调也不同，意思是棉花做的细棒。"}], "explanations": {"面前": "正确：面前 miàn qián，即题目所给词。", "免签": "miǎn qiān 与 miàn qián 声母韵母相同，只是声调不同，意思是不用办签证。", "现钱": "xiàn 与 miàn 只有声母不同（x 与 m），意思是现金。", "棉签": "mián 与 miàn 声调不同，qiān 与 qián 声调也不同，意思是棉花做的细棒。"}, "sentence_index": null, "correct_answer": "面前"}, "level_3": {"options": [{"text": "面前", "is_correct": true, "explanation": "正确：“他走到我面前”中表示人所在前方的位置，与“笑着说你好”相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是可以走到的地点，“走到我天空”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是身体部位，不能作“走到”的终点。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，“走到我书包”说不通。"}], "explanations": {"面前": "正确：“他走到我面前”中表示人所在前方的位置，与“笑着说你好”相符。", "天空": "语义：“天空”不是可以走到的地点，“走到我天空”说不通。", "眼睛": "体貌：“眼睛”是身体部位，不能作“走到”的终点。", "书包": "语义：“书包”是物品，“走到我书包”说不通。"}, "sentence_index": 0, "correct_answer": "面前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们是在三年面前认识的。", "explanation": "这里应该用〈以前〉。面前只表示空间位置，不表示时间，不能说“三年面前”。"}, {"text": "他擦了擦面前，转身走了。", "explanation": "这里应该用〈脸〉。擦的是脸，面前只表示位置，不指脸。"}, {"text": "他的面前很白，一看就是北方人。", "explanation": "这里应该用〈皮肤〉。面前只表示位置，不能用来描写皮肤的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面前", "is_correct": true, "explanation": "正确：“一辆红色的车停在我面前”中表示车停靠的前方位置。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”不是人身旁可以停车的位置，“停在我大海”说不通。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：“脸”是身体部位，车不能停在人的脸上或脸处。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是地点，“停在我作业”说不通。"}], "explanations": {"面前": "正确：“一辆红色的车停在我面前”中表示车停靠的前方位置。", "大海": "语义：“大海”不是人身旁可以停车的位置，“停在我大海”说不通。", "脸": "体貌：“脸”是身体部位，车不能停在人的脸上或脸处。", "作业": "语义：“作业”不是地点，“停在我作业”说不通。"}, "sentence_index": 6, "correct_answer": "面前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他面前带着很多钱。", "explanation": "这里应该用〈身上〉。随身携带的东西要说“身上”，面前指前方位置。"}, {"text": "超市在马路面前。", "explanation": "这里应该用〈对面〉。隔着马路相对的另一侧要说“对面”，面前指同一侧的前方。"}, {"text": "我的面前很疼，可能是感冒了。", "explanation": "这里应该用〈头〉。疼的是身体部位，面前只表示前方位置，不指身体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他走到我面子，笑着说你好。", "corrected_sentence": "他走到我面前，笑着说你好。", "error_description": "错误：“面子”指体面，不表示位置。走到某人脸对着的前方要说“我面前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
