INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人或物的前面。", "primary_collocate": null, "pronunciation": "miàn qián", "ipa": "mi̯ɛn˥˩ tɕʰi̯ɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我们面前是一条大河。", "target_word": "面前", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他面前放着一杯热茶。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师面前有一大堆作业。", "target_word": "面前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李面前摆着很多书。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长面前站着几个学生。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子停在我们面前,门慢慢开了。", "target_word": "面前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理面前的桌子上都是文件。", "target_word": "面前", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着面前的那碗面,什么也没说。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生面前坐着一位老人。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们面前的路很窄,车开不过去。", "target_word": "面前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "面前:人或物所在位置的前面,指静态的方位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84adf9-f7e5-4676-ae12-1e74b754fae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90070, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面前", "is_correct": true, "explanation": "正确：面前 miàn qián，即题目所给词。"}, {"text": "免签", "is_correct": false, "explanation": "miǎn qiān 与 miàn qián 声母韵母相同，只是声调不同，意思是不用办签证。"}, {"text": "现钱", "is_correct": false, "explanation": "xiàn 与 miàn 只有声母不同（x 与 m），声调相同，意思是现金。"}, {"text": "棉签", "is_correct": false, "explanation": "mián 与 miàn 声调不同，qiān 与 qián 声调也不同，意思是棉花做的细棒。"}], "explanations": {"面前": "正确：面前 miàn qián，即题目所给词。", "免签": "miǎn qiān 与 miàn qián 声母韵母相同，只是声调不同，意思是不用办签证。", "现钱": "xiàn 与 miàn 只有声母不同（x 与 m），声调相同，意思是现金。", "棉签": "mián 与 miàn 声调不同，qiān 与 qián 声调也不同，意思是棉花做的细棒。"}, "sentence_index": null, "correct_answer": "面前"}, "level_3": {"options": [{"text": "面前", "is_correct": true, "explanation": "正确：“我们面前是一条大河”中的方位词，表示河流所在的位置。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：“孩子”指人，不是方位，“我们孩子是一条大河”说不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是河流所在的位置，“我们天空是一条大河”说不通。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能充当表示位置的名词，与“……是一条大河”的方位结构不搭。"}], "explanations": {"面前": "正确：“我们面前是一条大河”中的方位词，表示河流所在的位置。", "孩子": "语义：“孩子”指人，不是方位，“我们孩子是一条大河”说不通。", "天空": "语义：“天空”不是河流所在的位置，“我们天空是一条大河”说不通。", "作业": "搭配：“作业”不能充当表示位置的名词，与“……是一条大河”的方位结构不搭。"}, "sentence_index": 0, "correct_answer": "面前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事是在会议面前决定的。", "explanation": "这里应该用〈之前〉。面前只指人或物的前方位置，不表示时间先后。"}, {"text": "他很爱面前，不肯认错。", "explanation": "这里应该用〈面子〉。面子指体面和名誉，面前只表示位置。"}, {"text": "他用手捂住了面前。", "explanation": "这里应该用〈脸〉。面前只表示位置，不指脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面前", "is_correct": true, "explanation": "正确：“经理面前的桌子”中表示位置的词，与“桌子上都是文件”相符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”不是经理身旁的位置，“经理大海的桌子”说不通。"}, {"text": "鼻子", "is_correct": false, "explanation": "体貌：“鼻子”是身体部位，不能用来指桌子所在的位置。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是时间，不是空间位置，不能修饰桌子。"}], "explanations": {"面前": "正确：“经理面前的桌子”中表示位置的词，与“桌子上都是文件”相符。", "大海": "语义：“大海”不是经理身旁的位置，“经理大海的桌子”说不通。", "鼻子": "体貌：“鼻子”是身体部位，不能用来指桌子所在的位置。", "春天": "语义：“春天”是时间，不是空间位置，不能修饰桌子。"}, "sentence_index": 6, "correct_answer": "面前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "错别字在面前第三段。", "explanation": "这里应该用〈前面〉。表示文章中靠前的位置时用“前面”，面前只指眼前的空间。"}, {"text": "他面前戴着一块手表。", "explanation": "这里应该用〈手腕上〉。手表戴在手腕上，面前只表示位置，不能说明佩戴的部位。"}, {"text": "他面前穿着一件红衣服。", "explanation": "这里应该用〈身上〉。穿戴在身上的东西要说“身上”，面前指前方位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师站在我们面后，看着大家。", "corrected_sentence": "老师站在我们面前，看着大家。", "error_description": "错误：汉语没有“面后”这个词。表示人前方的位置要说“我们面前”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
