INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90073, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不知是没有弄明白,不明白。", "primary_collocate": null, "pronunciation": "bù zhī", "ipa": "pu˥˩ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他不知为什么哭了。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知该怎么回答。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不知如何是好。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不知危险，跑到了路上。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不知这件事的原因。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知自己错在哪里。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不知从哪里开始做。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不知老师为什么生气。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不知为什么，我今天很累。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不知这个字怎么读。", "target_word": "不知", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "不知：不明白、没弄清楚，后接疑问内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116634ea-fcb5-448e-abe0-203c2273568d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90073, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不知", "is_correct": true, "explanation": "不知：不明白、没弄清楚。"}, {"text": "不止", "is_correct": false, "explanation": "bù zhǐ（第三声）与 bù zhī（第一声）声调不同，意思是不只、不仅。"}, {"text": "布置", "is_correct": false, "explanation": "bù zhì（第四声）与 bù zhī（第一声）声调不同，意思是安排、陈设。"}, {"text": "不值", "is_correct": false, "explanation": "bù zhí（第二声）与 bù zhī（第一声）声调不同，意思是不值得。"}, {"text": "不吃", "is_correct": false, "explanation": "bù chī 与 bù zhī 声母不同（ch 与 zh），意思是不进食。"}], "explanations": {"不知": "不知：不明白、没弄清楚。", "不止": "bù zhǐ（第三声）与 bù zhī（第一声）声调不同，意思是不只、不仅。", "布置": "bù zhì（第四声）与 bù zhī（第一声）声调不同，意思是安排、陈设。", "不值": "bù zhí（第二声）与 bù zhī（第一声）声调不同，意思是不值得。", "不吃": "bù chī 与 bù zhī 声母不同（ch 与 zh），意思是不进食。"}, "sentence_index": null, "correct_answer": "不知"}, "level_3": {"options": [{"text": "不知", "is_correct": true, "explanation": "不知：没有弄清楚，后接“为什么”引出的疑问内容，符合句意。"}, {"text": "预料", "is_correct": false, "explanation": "语义：“预料”指对尚未发生的事作估计，而“哭了”已经发生，句意矛盾。"}, {"text": "见证", "is_correct": false, "explanation": "配价：“见证”带已经发生的事件或事物作宾语，不能直接接“为什么哭了”这样的疑问小句。"}, {"text": "感到", "is_correct": false, "explanation": "配价：“感到”后接感受或状态，不能接“为什么哭了”这样的疑问小句。"}], "explanations": {"不知": "不知：没有弄清楚，后接“为什么”引出的疑问内容，符合句意。", "预料": "语义：“预料”指对尚未发生的事作估计，而“哭了”已经发生，句意矛盾。", "见证": "配价：“见证”带已经发生的事件或事物作宾语，不能直接接“为什么哭了”这样的疑问小句。", "感到": "配价：“感到”后接感受或状态，不能接“为什么哭了”这样的疑问小句。"}, "sentence_index": 0, "correct_answer": "不知"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不知游泳，所以从来不敢下水。", "explanation": "这里应该用〈不会〉。不知表示没有弄清楚某件事，说自己不会做某种技能要用不会。"}, {"text": "我不知法语，所以看不懂那份合同。", "explanation": "这里应该用〈不会说〉。不知表示没弄清楚某件事，说对某种语言不熟悉要用不会说。"}, {"text": "我不知这个新同学，所以没有跟他打招呼。", "explanation": "这里应该用〈不认识〉。不知用于事情、消息或道理，指人要用不认识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不知", "is_correct": true, "explanation": "不知：没有弄清楚，后接疑问词短语“从哪里”，符合句意。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”与“开始”意思相反，“停止从哪里开始做”句意自相矛盾。"}, {"text": "完成", "is_correct": false, "explanation": "配价：“完成”后接具体的任务或事项，不能接“从哪里开始做”这样的疑问结构。"}, {"text": "证明", "is_correct": false, "explanation": "配价：“证明”后接命题或事实，不能接“从哪里开始做”这样的疑问结构。"}], "explanations": {"不知": "不知：没有弄清楚，后接疑问词短语“从哪里”，符合句意。", "停止": "语义：“停止”与“开始”意思相反，“停止从哪里开始做”句意自相矛盾。", "完成": "配价：“完成”后接具体的任务或事项，不能接“从哪里开始做”这样的疑问结构。", "证明": "配价：“证明”后接命题或事实，不能接“从哪里开始做”这样的疑问结构。"}, "sentence_index": 6, "correct_answer": "不知"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不知吃辣，所以点菜时从来不点辣的菜。", "explanation": "这里应该用〈不喜欢〉。不知表示没弄清楚某件事，说个人的口味或喜好要用不喜欢。"}, {"text": "这只小猫很怕水，站在岸边不知跳下去。", "explanation": "这里应该用〈不敢〉。不知表示没弄明白，因害怕而不去做某事要用不敢。"}, {"text": "爸爸劝了半天，他一直摇头，就是不知答应。", "explanation": "这里应该用〈不肯〉。不知表示没弄明白，拒绝答应、不同意要用不肯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不知了他为什么没来。", "corrected_sentence": "我不知他为什么没来。", "error_description": "错误：“不知”后面多加了“了”。“不知”表示没有弄清楚，是状态性的动词，不能带动态助词“了”，应改为“我不知他为什么没来。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不知清楚这件事的经过。", "corrected_sentence": "他不知这件事的经过。", "error_description": "错误：“不知”后面直接加了补语“清楚”。“不知”后不能接结果补语，应改为“他不知这件事的经过。”或“他不清楚这件事的经过。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0ffff9f-4f57-4342-9916-dec88de3e5ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
