INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90075, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "用来称东西有多重的一种单位。", "primary_collocate": null, "pronunciation": "gōng jīn", "ipa": "kʊŋ˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "这个西瓜有五公斤重。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了两公斤苹果。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行李有十公斤。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫三公斤重。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我称一公斤米。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋面粉是两公斤。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我比去年重了三公斤。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩出生时有三公斤多。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个箱子最多放二十公斤。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每周买五公斤水果。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公斤级", "label": "复合"}], "register": "中性", "sense_fingerprint": "称东西轻重时用的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公斤", "is_correct": true, "explanation": "公斤是称重量的单位，与“五”和“重”搭配，说明西瓜有五公斤重。"}, {"text": "米", "is_correct": false, "explanation": "语义：“米”是长度单位，不能用来说东西的重量。"}, {"text": "次", "is_correct": false, "explanation": "搭配：“次”表示次数，不能与“重”搭配来说西瓜的重量。"}, {"text": "年", "is_correct": false, "explanation": "语义：“年”是时间单位，与称重无关。"}], "explanations": {"公斤": "公斤是称重量的单位，与“五”和“重”搭配，说明西瓜有五公斤重。", "米": "语义：“米”是长度单位，不能用来说东西的重量。", "次": "搭配：“次”表示次数，不能与“重”搭配来说西瓜的重量。", "年": "语义：“年”是时间单位，与称重无关。"}, "sentence_index": 0, "correct_answer": "公斤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路有三公斤长。", "explanation": "这里应该用〈公里〉。公斤表示重量，描述长度要用公里。"}, {"text": "我昨晚睡了八公斤。", "explanation": "这里应该用〈小时〉。公斤是重量单位，表示睡眠时长要用小时。"}, {"text": "这块布有三公斤宽。", "explanation": "这里应该用〈米〉。公斤只用于称重，布料的宽度要用米或厘米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公斤", "is_correct": true, "explanation": "公斤是称重量的单位，与“重了”和“三”搭配，说明体重增加了三公斤。"}, {"text": "度", "is_correct": false, "explanation": "语义：“度”是温度、程度等的单位，不能用来表示体重增加。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”用于衣物、事情等，不与“重了”搭配。"}, {"text": "把", "is_correct": false, "explanation": "语义：“把”用于有柄的器具，不能用来说体重增加。"}], "explanations": {"公斤": "公斤是称重量的单位，与“重了”和“三”搭配，说明体重增加了三公斤。", "度": "语义：“度”是温度、程度等的单位，不能用来表示体重增加。", "件": "搭配：“件”用于衣物、事情等，不与“重了”搭配。", "把": "语义：“把”用于有柄的器具，不能用来说体重增加。"}, "sentence_index": 6, "correct_answer": "公斤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班里有三公斤学生。", "explanation": "这里应该用〈名〉。公斤只用来称东西的重量，学生是人，要用名来计数。"}, {"text": "他对我有五公斤感情。", "explanation": "这里应该用〈份〉。感情是抽象的，无法称重，公斤不能用来计量它。"}, {"text": "我有十公斤朋友。", "explanation": "这里应该用〈个〉。朋友是人，计数要用个，不能用公斤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这箱橘子重十个公斤。", "corrected_sentence": "这箱橘子重十公斤。", "error_description": "错误形式：“十个公斤”；正确形式：“十公斤”。公斤本身就是量词，数词后面不能再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的书包重八公斤重。", "corrected_sentence": "他的书包重八公斤。", "error_description": "错误形式：“八公斤重”后面多出一个“重”；正确形式：“重八公斤”。“重”已经出现在句中，不能在“公斤”后面重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
