INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90076, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90076, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "质量或重量单位，一公斤等于一千克。", "primary_collocate": null, "pronunciation": "gōng jīn", "ipa": "kʊŋ˥ tɕin˥", "syllable_count": 2, "sentences": [{"text": "一公斤等于一千克。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块肉重一公斤半。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器有五十公斤重。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一公斤水就是一升水。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包不能超过八公斤。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天要吃半公斤菜。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在店里买了一公斤牛肉。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书只有半公斤。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他减了五公斤体重。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些东西称一下，共三公斤。", "target_word": "公斤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公斤级", "label": "复合"}], "register": "中性", "sense_fingerprint": "质量或重量单位，等于一千克", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f5c63e9-0e4b-49d3-a0e2-d030fdf3d828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公斤", "is_correct": true, "explanation": "公斤是质量单位，一公斤与一千克等值，句子说的是这个换算关系。"}, {"text": "米", "is_correct": false, "explanation": "语义：“米”是长度单位，与“千克”无法换算。"}, {"text": "次", "is_correct": false, "explanation": "搭配：“次”表示次数，不能用在“等于一千克”这样的单位换算中。"}, {"text": "年", "is_correct": false, "explanation": "语义：“年”是时间单位，与质量换算无关。"}], "explanations": {"公斤": "公斤是质量单位，一公斤与一千克等值，句子说的是这个换算关系。", "米": "语义：“米”是长度单位，与“千克”无法换算。", "次": "搭配：“次”表示次数，不能用在“等于一千克”这样的单位换算中。", "年": "语义：“年”是时间单位，与质量换算无关。"}, "sentence_index": 0, "correct_answer": "公斤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥有两公斤长。", "explanation": "这里应该用〈公里〉。公斤表示质量，桥的长度要用公里。"}, {"text": "这张桌子有两公斤宽。", "explanation": "这里应该用〈厘米〉。公斤只用于质量，桌子的宽度要用厘米或米。"}, {"text": "这部电影放了两公斤。", "explanation": "这里应该用〈小时〉。公斤是质量单位，表示时长要用小时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公斤", "is_correct": true, "explanation": "公斤用来称牛肉的重量，“买一公斤牛肉”是常见说法。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”用于车辆，不能用来称牛肉。"}, {"text": "盏", "is_correct": false, "explanation": "语义：“盏”用于灯，不能用来称牛肉。"}, {"text": "节", "is_correct": false, "explanation": "搭配：“节”用于车厢、课程等分段的事物，不与“牛肉”搭配。"}], "explanations": {"公斤": "公斤用来称牛肉的重量，“买一公斤牛肉”是常见说法。", "辆": "语义：“辆”用于车辆，不能用来称牛肉。", "盏": "语义：“盏”用于灯，不能用来称牛肉。", "节": "搭配：“节”用于车厢、课程等分段的事物，不与“牛肉”搭配。"}, "sentence_index": 6, "correct_answer": "公斤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校里有五公斤老师。", "explanation": "这里应该用〈位〉。公斤用于称重，老师是人，要用位来计数。"}, {"text": "他心里有五公斤梦想。", "explanation": "这里应该用〈个〉。梦想是抽象的，无法称重，不能用公斤来计量。"}, {"text": "我们之间有三公斤友谊。", "explanation": "这里应该用〈份〉。友谊是抽象的，要说一份友谊，不能用公斤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这袋米一共五个公斤。", "corrected_sentence": "这袋米一共五公斤。", "error_description": "错误形式：“五个公斤”；正确形式：“五公斤”。公斤本身就是量词，数词后面不需要再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这箱书重八公斤重。", "corrected_sentence": "这箱书重八公斤。", "error_description": "错误形式：“八公斤重”后面多出一个“重”；正确形式：“重八公斤”。“重”已经出现在句中，不能在“公斤”后面重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd91cc536-3030-4ac5-9bf0-43d250a6d881') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90077, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
