INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90077, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事务是要做的事情。", "primary_collocate": null, "pronunciation": "shì wù", "ipa": "ʂɻ̩˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "他每天要处理很多事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一周公司的事务十分繁杂，工作量很大。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不想让工作事务影响家人。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张负责学校的行政事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把手上的事务都安排好了。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事务太多的时候，他会先写下来。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正忙着处理公司的事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太懂这些法律事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他退休后不再过问单位的事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些日常事务让他一天都没休息。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "行政事务", "label": "复合"}, {"form": "日常事务", "label": "复合"}, {"form": "事務", "label": "繁体"}], "register": "书面", "sense_fingerprint": "需要处理、要做的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90077, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事务", "is_correct": true, "explanation": "事务（shì wù）指需要处理的事情，是本题的正确答案。"}, {"text": "食物", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是食物。"}, {"text": "失误", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是失误、错误。"}, {"text": "实物", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是实际存在的物品。"}], "explanations": {"事务": "事务（shì wù）指需要处理的事情，是本题的正确答案。", "食物": "shí（第二声）与 shì（第四声）声调不同，意思是食物。", "失误": "shī（第一声）与 shì（第四声）声调不同，意思是失误、错误。", "实物": "shí（第二声）与 shì（第四声）声调不同，意思是实际存在的物品。"}, "sentence_index": null, "correct_answer": "事务"}, "level_3": {"options": [{"text": "事务", "is_correct": true, "explanation": "“处理很多事务”是常见说法，“事务”指要做的事，正好填入空格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以处理的对象，“处理很多天气”说不通。"}, {"text": "心愿", "is_correct": false, "explanation": "搭配：“心愿”通常说实现或满足，不说处理，与“处理很多”不搭配。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光是自然现象，不能被处理，放在这里意思不通。"}], "explanations": {"事务": "“处理很多事务”是常见说法，“事务”指要做的事，正好填入空格。", "天气": "语义：天气是自然现象，不是可以处理的对象，“处理很多天气”说不通。", "心愿": "搭配：“心愿”通常说实现或满足，不说处理，与“处理很多”不搭配。", "阳光": "语义：阳光是自然现象，不能被处理，放在这里意思不通。"}, "sentence_index": 0, "correct_answer": "事务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢仔细观察周围的事务。", "explanation": "这里应该用〈事物〉。事物指世上的各种东西或现象，可以被观察；事务指需要处理的工作，不指一般的东西。"}, {"text": "他找到了一份新事务，每天很忙。", "explanation": "这里应该用〈工作〉。“找到一份工作”指职业岗位，事务指需要处理的事情，不指职位。"}, {"text": "他说的每句话都是事务。", "explanation": "这里应该用〈事实〉。事实指真实存在的情况，可以作为说话的内容；事务指需要处理的工作，不能作为话的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事务", "is_correct": true, "explanation": "“处理公司的事务”是常见说法，填入空格后意思正确。"}, {"text": "小吃", "is_correct": false, "explanation": "语义：小吃是食品，不是需要处理的事务，“处理公司的小吃”不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”通常说迈步或加快，不说“处理”，与“忙着处理”不搭配。"}, {"text": "梦想", "is_correct": false, "explanation": "搭配：“梦想”通常说实现或追求，不能说处理，与“忙着处理”不搭配。"}], "explanations": {"事务": "“处理公司的事务”是常见说法，填入空格后意思正确。", "小吃": "语义：小吃是食品，不是需要处理的事务，“处理公司的小吃”不通。", "脚步": "搭配：“脚步”通常说迈步或加快，不说“处理”，与“忙着处理”不搭配。", "梦想": "搭配：“梦想”通常说实现或追求，不能说处理，与“忙着处理”不搭配。"}, "sentence_index": 6, "correct_answer": "事务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行是我最难忘的事务。", "explanation": "这里应该用〈经历〉。经历指亲身遇到的事情，可以“难忘”；事务指需要处理的工作，不指亲身的遭遇。"}, {"text": "这次事务引起了大家的关注。", "explanation": "这里应该用〈事件〉。事件指发生的具体情况，可以引起关注；事务指需要处理的工作，不能指发生的情况。"}, {"text": "他的先进事务感动了大家。", "explanation": "这里应该用〈事迹〉。事迹指人的具体行为或成就；事务指需要处理的工作，不能用来指人的先进行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天要处理三只事务。", "corrected_sentence": "我今天要处理三项事务。", "error_description": "量词错误：“事务”应该用量词“项”，不能用“只”（“只”多用于动物等）。应说“三项事务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司这一条事务很麻烦。", "corrected_sentence": "公司这一项事务很麻烦。", "error_description": "量词错误：“事务”用“项”计量，“条”用于细长的东西，不能用于“事务”。应说“这一项事务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
