INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "所做的或要做的事情;日常工作。", "primary_collocate": null, "pronunciation": "shì wù", "ipa": "ʂɻ̩˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "秘书每天做的是办公室的日常事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作就是处理各种事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李经理很少管具体事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的财务事务由小王负责。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子出生后，她的家庭事务多了很多。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他整天忙于单位的事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先把手头的事务做完。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对村里的事务很熟悉。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长不能把所有事务都交给别人。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作主要是跟客人联系和管理店里的事务。", "target_word": "事务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "日常事务", "label": "复合"}, {"form": "行政事务", "label": "复合"}, {"form": "事務", "label": "繁体"}], "register": "书面", "sense_fingerprint": "日常工作中的具体事项", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90078, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "事务", "is_correct": true, "explanation": "事务（shì wù）指需要处理的事情，是本题的正确答案。"}, {"text": "食物", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是食物。"}, {"text": "失误", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是失误、错误。"}, {"text": "实物", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是实际存在的物品。"}], "explanations": {"事务": "事务（shì wù）指需要处理的事情，是本题的正确答案。", "食物": "shí（第二声）与 shì（第四声）声调不同，意思是食物。", "失误": "shī（第一声）与 shì（第四声）声调不同，意思是失误、错误。", "实物": "shí（第二声）与 shì（第四声）声调不同，意思是实际存在的物品。"}, "sentence_index": null, "correct_answer": "事务"}, "level_3": {"options": [{"text": "事务", "is_correct": true, "explanation": "“办公室的日常事务”是常见说法，“事务”指要做的工作，正好填入空格。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是办公室的日常工作，放在这里说不通。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“呼吸”是身体的活动，不能说成“办公室的日常呼吸”。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”指留下的痕迹，不是要做的日常工作，放在这里意思不通。"}], "explanations": {"事务": "“办公室的日常事务”是常见说法，“事务”指要做的工作，正好填入空格。", "月亮": "语义：月亮是天体，不是办公室的日常工作，放在这里说不通。", "呼吸": "搭配：“呼吸”是身体的活动，不能说成“办公室的日常呼吸”。", "脚印": "语义：“脚印”指留下的痕迹，不是要做的日常工作，放在这里意思不通。"}, "sentence_index": 0, "correct_answer": "事务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他喜欢研究身边的事务。", "explanation": "这里应该用〈事物〉。事物指世上的各种东西或现象，可以被研究；事务指需要处理的工作。"}, {"text": "周末学校组织了一次大型事务。", "explanation": "这里应该用〈活动〉。活动指有组织的集体行动，可以“组织”和“举办”；事务指需要处理的工作，不指这类集体活动。"}, {"text": "这起交通事务造成了三人受伤。", "explanation": "这里应该用〈事故〉。事故指意外造成损失的事件，可以造成伤害；事务指需要处理的工作，不指意外事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事务", "is_correct": true, "explanation": "“把手头的事务做完”是自然的说法，“事务”指手上要做的工作，正好填入空格。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不是要做的事，“把手头的眼泪做完”说不通。"}, {"text": "皮肤", "is_correct": false, "explanation": "语义：皮肤是身体的一部分，不能被“做完”，放在这里意思不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“心情”通常说调整或保持，不说“做完”，与“把……做完”不搭配。"}], "explanations": {"事务": "“把手头的事务做完”是自然的说法，“事务”指手上要做的工作，正好填入空格。", "眼泪": "语义：眼泪不是要做的事，“把手头的眼泪做完”说不通。", "皮肤": "语义：皮肤是身体的一部分，不能被“做完”，放在这里意思不通。", "心情": "搭配：“心情”通常说调整或保持，不说“做完”，与“把……做完”不搭配。"}, "sentence_index": 6, "correct_answer": "事务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那次登山是我最难忘的事务。", "explanation": "这里应该用〈经历〉。经历指亲身遇到的事情，可以“难忘”；事务指需要处理的工作，不指亲身的遭遇。"}, {"text": "她的英雄事务被大家传颂。", "explanation": "这里应该用〈事迹〉。事迹指人的具体行为或成就，可以被传颂；事务指需要处理的工作，不能用来指英雄行为。"}, {"text": "孩子们在操场上玩了一场事务。", "explanation": "这里应该用〈游戏〉。游戏是供人娱乐的活动，可以“玩”；事务指需要处理的工作，不指游戏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小李负责两本财务事务。", "corrected_sentence": "小李负责两项财务事务。", "error_description": "量词错误：“事务”用“项”计量，“本”用于书籍、本子等，不能用来数“事务”。应说“两项财务事务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司下个月要完成三张行政事务。", "corrected_sentence": "我们公司下个月要完成三项行政事务。", "error_description": "量词错误：“张”用于平面的东西，不能用于“事务”。“事务”应该用量词“项”。应说“三项行政事务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
