INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90079, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刷子来回擦，让东西干净。", "primary_collocate": null, "pronunciation": "shuā", "ipa": "ʂwa˥", "syllable_count": 1, "sentences": [{"text": "我每天早上刷牙。", "target_word": "刷", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在厨房刷锅。", "target_word": "刷", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈正在刷我的白鞋。", "target_word": "刷", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这双鞋太脏了，你快去刷一刷。", "target_word": "刷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明刷完碗，就去写作业了。", "target_word": "刷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "浴缸很脏，我刷了半个小时才刷干净。", "target_word": "刷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他蹲在门口，刷着鞋底的泥。", "target_word": "刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完饭，爸爸把锅刷得很干净。", "target_word": "刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刷过这个厕所吗？", "target_word": "刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡以后，他又把浴室的地板刷了一遍。", "target_word": "刷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刷了", "label": "体标"}, {"form": "刷着", "label": "体标"}, {"form": "刷过", "label": "体标"}, {"form": "刷刷", "label": "重叠"}, {"form": "刷子", "label": "复合"}], "register": "口语", "sense_fingerprint": "用刷子来回擦洗，使物品变干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c8e5f0-0406-4b36-85f5-8cace11e88a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90079, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刷", "is_correct": true, "explanation": "刷 shuā（第一声），意思是用刷子擦洗或涂抹。"}, {"text": "耍", "is_correct": false, "explanation": "耍 shuǎ（第三声）与 shuā（第一声）声调不同，意思是玩耍、耍弄。"}, {"text": "抓", "is_correct": false, "explanation": "抓 zhuā 与 shuā 声母不同（zh 与 sh），意思是用手握住、抓取。"}, {"text": "说", "is_correct": false, "explanation": "说 shuō 与 shuā 韵母不同（o 与 a），意思是讲话。"}, {"text": "沙", "is_correct": false, "explanation": "沙 shā 比 shuā 少了介音 u，意思是沙子。"}], "explanations": {"刷": "刷 shuā（第一声），意思是用刷子擦洗或涂抹。", "耍": "耍 shuǎ（第三声）与 shuā（第一声）声调不同，意思是玩耍、耍弄。", "抓": "抓 zhuā 与 shuā 声母不同（zh 与 sh），意思是用手握住、抓取。", "说": "说 shuō 与 shuā 韵母不同（o 与 a），意思是讲话。", "沙": "沙 shā 比 shuā 少了介音 u，意思是沙子。"}, "sentence_index": null, "correct_answer": "刷"}, "level_3": {"options": [{"text": "刷", "is_correct": true, "explanation": "刷：用刷子擦洗，与“牙”搭配，句子通顺。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”是用气流推动物体，不能用来清洁牙齿。"}, {"text": "拔", "is_correct": false, "explanation": "语义：拔牙是治疗牙病才做的手术，不是每天早上都做的清洁动作。"}, {"text": "镶", "is_correct": false, "explanation": "语义：镶牙指安装牙套或假牙，不是日常清洁的动作。"}], "explanations": {"刷": "刷：用刷子擦洗，与“牙”搭配，句子通顺。", "吹": "搭配：“吹”是用气流推动物体，不能用来清洁牙齿。", "拔": "语义：拔牙是治疗牙病才做的手术，不是每天早上都做的清洁动作。", "镶": "语义：镶牙指安装牙套或假牙，不是日常清洁的动作。"}, "sentence_index": 0, "correct_answer": "刷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手绢刷眼泪。", "explanation": "这里应该用〈擦〉。擦眼泪是用手绢轻轻拭去，“刷”要用刷子来回擦洗物体，不能用在眼泪上。"}, {"text": "她用刀刷西瓜。", "explanation": "这里应该用〈切〉。切西瓜是用刀把瓜分开，“刷”是用刷子来回擦洗物体，不能用刀刷西瓜。"}, {"text": "他用毛巾刷汗。", "explanation": "这里应该用〈擦〉。擦汗是用毛巾轻抹去汗水，“刷”是用刷子擦洗，不能用来抹汗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90079, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "刷", "is_correct": true, "explanation": "刷 shuā（第一声），意思是用刷子擦洗或涂抹。"}, {"text": "花", "is_correct": false, "explanation": "花 huā 与 shuā 声母不同（h 与 sh），意思是花朵。"}, {"text": "夸", "is_correct": false, "explanation": "夸 kuā 与 shuā 声母不同（k 与 sh），意思是夸奖。"}, {"text": "摔", "is_correct": false, "explanation": "摔 shuāi 与 shuā 韵母不同（ai 与 a），意思是摔倒。"}], "explanations": {"刷": "刷 shuā（第一声），意思是用刷子擦洗或涂抹。", "花": "花 huā 与 shuā 声母不同（h 与 sh），意思是花朵。", "夸": "夸 kuā 与 shuā 声母不同（k 与 sh），意思是夸奖。", "摔": "摔 shuāi 与 shuā 韵母不同（ai 与 a），意思是摔倒。"}, "sentence_index": null, "correct_answer": "刷"}, "level_3": {"options": [{"text": "刷", "is_correct": true, "explanation": "刷：用刷子清除鞋底的泥，与“泥”搭配，句子通顺。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”的对象是布料或鞋底，不能缝泥。"}, {"text": "吃", "is_correct": false, "explanation": "语义：泥不能吃，“吃”不适用于清除鞋底的泥。"}, {"text": "写", "is_correct": false, "explanation": "语义：泥不是可以书写的东西，“写”与泥无关。"}], "explanations": {"刷": "刷：用刷子清除鞋底的泥，与“泥”搭配，句子通顺。", "缝": "搭配：“缝”的对象是布料或鞋底，不能缝泥。", "吃": "语义：泥不能吃，“吃”不适用于清除鞋底的泥。", "写": "语义：泥不是可以书写的东西，“写”与泥无关。"}, "sentence_index": 6, "correct_answer": "刷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把垃圾刷进了桶里。", "explanation": "这里应该用〈扔〉。扔是把东西丢出去，“刷”是用刷子擦洗物体，不能表示把垃圾丢进桶里。"}, {"text": "我每天晚上刷澡。", "explanation": "这里应该用〈洗〉。洗澡是用水清洁身体，“刷”是用刷子擦物体表面，不能说“刷澡”。"}, {"text": "他弯腰刷起了地上的纸。", "explanation": "这里应该用〈捡〉。捡是把地上的东西拾起来，“刷”是清洁或涂抹，不能用来拾纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把厨房刷很干净。", "corrected_sentence": "她把厨房刷得很干净。", "error_description": "“刷”后面接结果补语“干净”时，中间要用“得”连接，应说“刷得很干净”，漏掉“得”就不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把地板刷了两个遍。", "corrected_sentence": "他把地板刷了两遍。", "error_description": "动量词“遍”前面不能加“个”，表示刷的次数要说“刷了两遍”，说“两个遍”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
