INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90080, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用刷子把油漆、酱汁等涂抹在物体表面。", "primary_collocate": null, "pronunciation": "shuā", "ipa": "ʂwa˥", "syllable_count": 1, "sentences": [{"text": "他在刷墙。", "target_word": "刷", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人正在刷油漆。", "target_word": "刷", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们周末一起刷房间的墙。", "target_word": "刷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在木桌上刷了一层漆。", "target_word": "刷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给小船刷上了一层蓝漆。", "target_word": "刷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在面包上刷一点蛋液，再放进烤箱。", "target_word": "刷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙面太旧了，要重新刷一遍油漆。", "target_word": "刷", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸想把门刷成白色。", "target_word": "刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个栏杆刷过红漆，现在有点旧了。", "target_word": "刷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷墙以前，先把家具搬出去。", "target_word": "刷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "刷了", "label": "体标"}, {"form": "刷着", "label": "体标"}, {"form": "刷过", "label": "体标"}, {"form": "刷刷", "label": "重叠"}, {"form": "刷子", "label": "复合"}], "register": "口语", "sense_fingerprint": "用刷子把油漆、酱汁等涂抹在物体表面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8c8e5f0-0406-4b36-85f5-8cace11e88a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刷", "is_correct": true, "explanation": "刷 shuā（第一声），意思是用刷子涂抹。"}, {"text": "耍", "is_correct": false, "explanation": "耍 shuǎ（第三声）与 shuā（第一声）声调不同，意思是玩耍、耍弄。"}, {"text": "抓", "is_correct": false, "explanation": "抓 zhuā 与 shuā 声母不同（zh 与 sh），意思是用手握住、抓取。"}, {"text": "说", "is_correct": false, "explanation": "说 shuō 与 shuā 韵母不同（o 与 a），意思是讲话。"}, {"text": "沙", "is_correct": false, "explanation": "沙 shā 比 shuā 少了介音 u，意思是沙子。"}], "explanations": {"刷": "刷 shuā（第一声），意思是用刷子涂抹。", "耍": "耍 shuǎ（第三声）与 shuā（第一声）声调不同，意思是玩耍、耍弄。", "抓": "抓 zhuā 与 shuā 声母不同（zh 与 sh），意思是用手握住、抓取。", "说": "说 shuō 与 shuā 韵母不同（o 与 a），意思是讲话。", "沙": "沙 shā 比 shuā 少了介音 u，意思是沙子。"}, "sentence_index": null, "correct_answer": "刷"}, "level_3": {"options": [{"text": "刷", "is_correct": true, "explanation": "刷：用刷子涂抹墙面，与“墙”搭配，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：墙不能吃，“他在吃墙”不成立。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”要接可以搬动的东西，墙不能扛。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”说的是用牙齿咬东西，墙不能被咬。"}], "explanations": {"刷": "刷：用刷子涂抹墙面，与“墙”搭配，句子通顺。", "吃": "语义：墙不能吃，“他在吃墙”不成立。", "扛": "搭配：“扛”要接可以搬动的东西，墙不能扛。", "咬": "语义：“咬”说的是用牙齿咬东西，墙不能被咬。"}, "sentence_index": 0, "correct_answer": "刷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用铁锤刷钉子。", "explanation": "这里应该用〈敲〉。敲钉子是用锤子打进去，“刷”是用刷子涂抹，不能用铁锤刷钉子。"}, {"text": "他用纸巾刷鼻子。", "explanation": "这里应该用〈擦〉。擦鼻子是用纸巾轻轻拭去，“刷”是用刷子涂抹，不能用在鼻子上。"}, {"text": "他把行李刷上了车。", "explanation": "这里应该用〈装〉。装车是把东西放到车上，“刷”是用刷子涂抹，不能表示把行李放上车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90080, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "刷", "is_correct": true, "explanation": "刷 shuā（第一声），意思是用刷子涂抹。"}, {"text": "花", "is_correct": false, "explanation": "花 huā 与 shuā 声母不同（h 与 sh），意思是花朵。"}, {"text": "夸", "is_correct": false, "explanation": "夸 kuā 与 shuā 声母不同（k 与 sh），意思是夸奖。"}, {"text": "摔", "is_correct": false, "explanation": "摔 shuāi 与 shuā 韵母不同（ai 与 a），意思是摔倒。"}], "explanations": {"刷": "刷 shuā（第一声），意思是用刷子涂抹。", "花": "花 huā 与 shuā 声母不同（h 与 sh），意思是花朵。", "夸": "夸 kuā 与 shuā 声母不同（k 与 sh），意思是夸奖。", "摔": "摔 shuāi 与 shuā 韵母不同（ai 与 a），意思是摔倒。"}, "sentence_index": null, "correct_answer": "刷"}, "level_3": {"options": [{"text": "刷", "is_correct": true, "explanation": "刷：用刷子涂上油漆，与“油漆”搭配，句子通顺。"}, {"text": "砌", "is_correct": false, "explanation": "搭配：“砌”是用砖石垒起来，不能用来涂油漆。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”是把东西套在身上，不能用来涂油漆。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”用于食物，油漆不能煮。"}], "explanations": {"刷": "刷：用刷子涂上油漆，与“油漆”搭配，句子通顺。", "砌": "搭配：“砌”是用砖石垒起来，不能用来涂油漆。", "戴": "搭配：“戴”是把东西套在身上，不能用来涂油漆。", "煮": "语义：“煮”用于食物，油漆不能煮。"}, "sentence_index": 6, "correct_answer": "刷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用铲子刷了一个坑。", "explanation": "这里应该用〈挖〉。挖坑是用工具掘出洞，“刷”是用刷子涂抹，不能用来挖坑。"}, {"text": "他把垃圾刷进了桶里。", "explanation": "这里应该用〈扔〉。扔是把东西丢出去，“刷”是用刷子涂抹，不能表示把垃圾丢进桶里。"}, {"text": "他弯腰刷起了地上的纸。", "explanation": "这里应该用〈捡〉。捡是把地上的东西拾起来，“刷”是用刷子涂抹，不能用来拾纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
