INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙终于刷了好。", "corrected_sentence": "墙终于刷好了。", "error_description": "结果补语“好”要紧跟动词，应说“刷好了”，“了”放在补语后面；说“刷了好”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a784a93a-8411-4c0a-80f1-af622dfab2f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
