INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90081, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "份是数一份一份东西用的字。", "primary_collocate": null, "pronunciation": "fèn", "ipa": "fɣn˥˩", "syllable_count": 1, "sentences": [{"text": "我要一份牛肉面。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找到了一份新工作。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一份今天的报纸。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我两份米饭。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一份生日礼物。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每人要一份早饭。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作很忙,但是我喜欢。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那份文件放在桌子上。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个同学发了一份作业。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员给我们送来了两份汤。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "数饭、工作、报纸、礼物等一份一份的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e31bf265-f6b7-4c52-b5e9-a7a9c46a99af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "份", "is_correct": true, "explanation": "正确答案。听到的是“份”fèn，用于计量一份一份的食物、工作、报纸等。"}, {"text": "分", "is_correct": false, "explanation": "fēn（第一声）与 fèn（第四声）声调不同，意思是分开、分数。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 fèn 韵母不同（an/en），声调相同，意思是饭。"}, {"text": "废", "is_correct": false, "explanation": "fèi 与 fèn 韵尾不同（i/n），意思是废弃。"}], "explanations": {"份": "正确答案。听到的是“份”fèn，用于计量一份一份的食物、工作、报纸等。", "分": "fēn（第一声）与 fèn（第四声）声调不同，意思是分开、分数。", "饭": "fàn 与 fèn 韵母不同（an/en），声调相同，意思是饭。", "废": "fèi 与 fèn 韵尾不同（i/n），意思是废弃。"}, "sentence_index": null, "correct_answer": "份"}, "level_3": {"options": [{"text": "份", "is_correct": true, "explanation": "正确答案。“我要一份牛肉面”中，“份”计量食物。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物等，不能数“牛肉面”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸张、桌子等扁平的东西，不说“一张牛肉面”。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”用于车辆，牛肉面不是车辆。"}], "explanations": {"份": "正确答案。“我要一份牛肉面”中，“份”计量食物。", "只": "搭配：“只”用于动物等，不能数“牛肉面”。", "张": "搭配：“张”用于纸张、桌子等扁平的东西，不说“一张牛肉面”。", "辆": "语义：“辆”用于车辆，牛肉面不是车辆。"}, "sentence_index": 0, "correct_answer": "份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了一份猫。", "explanation": "这里应该用〈只〉。猫用“只”计算，“份”不用于动物。"}, {"text": "他买了一份钥匙。", "explanation": "这里应该用〈把〉。钥匙用“把”计算，“份”不用于钥匙。"}, {"text": "天上有一份飞机。", "explanation": "这里应该用〈架〉。飞机用“架”计算，“份”不用于交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90081, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "份", "is_correct": true, "explanation": "正确答案。听到的是“份”fèn，用于计量一份一份的东西。"}, {"text": "粉", "is_correct": false, "explanation": "fěn（第三声）与 fèn（第四声）声调不同，意思是粉末、粉色。"}, {"text": "风", "is_correct": false, "explanation": "fēng（第一声）与 fèn 韵尾不同（ng/n）且声调不同，意思是风。"}, {"text": "反", "is_correct": false, "explanation": "fǎn（第三声）与 fèn 韵母不同（an/en）且声调不同，意思是反对、反过来。"}], "explanations": {"份": "正确答案。听到的是“份”fèn，用于计量一份一份的东西。", "粉": "fěn（第三声）与 fèn（第四声）声调不同，意思是粉末、粉色。", "风": "fēng（第一声）与 fèn 韵尾不同（ng/n）且声调不同，意思是风。", "反": "fǎn（第三声）与 fèn 韵母不同（an/en）且声调不同，意思是反对、反过来。"}, "sentence_index": null, "correct_answer": "份"}, "level_3": {"options": [{"text": "份", "is_correct": true, "explanation": "正确答案。“这份工作很忙”中，“份”计量工作。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不说“这本工作”。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不修饰“工作”。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄的东西，不说“这把工作”。"}], "explanations": {"份": "正确答案。“这份工作很忙”中，“份”计量工作。", "本": "搭配：“本”用于书册，不说“这本工作”。", "条": "搭配：“条”用于细长的东西，不修饰“工作”。", "把": "搭配：“把”用于有柄的东西，不说“这把工作”。"}, "sentence_index": 6, "correct_answer": "份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一份电影票。", "explanation": "这里应该用〈张〉。电影票用“张”计算，“份”用于食物、工作、文件等，不说“一份电影票”。"}, {"text": "他买了一份鞋。", "explanation": "这里应该用〈双〉。鞋要成双计算，应说“一双鞋”，不说“一份鞋”。"}, {"text": "他家买了一份房子。", "explanation": "这里应该用〈套〉。房子用“套”计算，“份”不用于房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天早上都买一个份报纸。", "corrected_sentence": "他每天早上都买一份报纸。", "error_description": "量词错误：“份”前不能再加量词“个”，应说“一份报纸”。错误形式是“一个份报纸”，正确形式是“一份报纸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服务员给我们端来了两份份汤。", "corrected_sentence": "服务员给我们端来了两份汤。", "error_description": "重叠错误：“份”不能在数量短语中重复叠用，应说“两份汤”。错误形式是“两份份汤”，正确形式是“两份汤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
