INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90082, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词,用于整体中的一部分或成套的东西。", "primary_collocate": null, "pronunciation": "fèn", "ipa": "fɣn˥˩", "syllable_count": 1, "sentences": [{"text": "他把蛋糕分成了四份。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱我们三个人平分,每人一份。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把苹果分成两份,给我一份。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份套餐有汤、菜和饭。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把西瓜分成五份。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的奖金,你也有一份。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把工作分成三份,每人做一份。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文具套装里有铅笔和尺子。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每人出一份钱,一起买礼物。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份礼盒里有茶叶和点心。", "target_word": "份", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "整体中分出的一部分,或成套的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e31bf265-f6b7-4c52-b5e9-a7a9c46a99af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED