INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "份", "is_correct": true, "explanation": "正确答案。听到的是“份”fèn，指整体中分出的一部分或成套的东西。"}, {"text": "分", "is_correct": false, "explanation": "fēn（第一声）与 fèn（第四声）声调不同，意思是分开、分数。"}, {"text": "饭", "is_correct": false, "explanation": "fàn 与 fèn 韵母不同（an/en），声调相同，意思是饭。"}, {"text": "废", "is_correct": false, "explanation": "fèi 与 fèn 韵尾不同（i/n），意思是废弃。"}], "explanations": {"份": "正确答案。听到的是“份”fèn，指整体中分出的一部分或成套的东西。", "分": "fēn（第一声）与 fèn（第四声）声调不同，意思是分开、分数。", "饭": "fàn 与 fèn 韵母不同（an/en），声调相同，意思是饭。", "废": "fèi 与 fèn 韵尾不同（i/n），意思是废弃。"}, "sentence_index": null, "correct_answer": "份"}, "level_3": {"options": [{"text": "份", "is_correct": true, "explanation": "正确答案。“他把蛋糕分成了四份”中，“份”指分出的部分。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物，不说“分成了四只”来指蛋糕的部分。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于扁平的东西，蛋糕分成的部分不用“张”。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”用于车辆，蛋糕不能分成车辆。"}], "explanations": {"份": "正确答案。“他把蛋糕分成了四份”中，“份”指分出的部分。", "只": "搭配：“只”用于动物，不说“分成了四只”来指蛋糕的部分。", "张": "搭配：“张”用于扁平的东西，蛋糕分成的部分不用“张”。", "辆": "语义：“辆”用于车辆，蛋糕不能分成车辆。"}, "sentence_index": 0, "correct_answer": "份"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们家买了一份房子。", "explanation": "这里应该用〈套〉。房子用“套”计算，“份”不用于房屋。"}, {"text": "我丢了一份钥匙。", "explanation": "这里应该用〈把〉。钥匙用“把”计算，“份”不用于钥匙。"}, {"text": "天上有一份飞机。", "explanation": "这里应该用〈架〉。飞机用“架”计算，“份”不用于交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90082, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "份", "is_correct": true, "explanation": "正确答案。听到的是“份”fèn，指整体中分出的一部分或成套的东西。"}, {"text": "粉", "is_correct": false, "explanation": "fěn（第三声）与 fèn（第四声）声调不同，意思是粉末、粉色。"}, {"text": "风", "is_correct": false, "explanation": "fēng（第一声）与 fèn 韵尾不同（ng/n）且声调不同，意思是风。"}, {"text": "反", "is_correct": false, "explanation": "fǎn（第三声）与 fèn 韵母不同（an/en）且声调不同，意思是反对、反过来。"}], "explanations": {"份": "正确答案。听到的是“份”fèn，指整体中分出的一部分或成套的东西。", "粉": "fěn（第三声）与 fèn（第四声）声调不同，意思是粉末、粉色。", "风": "fēng（第一声）与 fèn 韵尾不同（ng/n）且声调不同，意思是风。", "反": "fǎn（第三声）与 fèn 韵母不同（an/en）且声调不同，意思是反对、反过来。"}, "sentence_index": null, "correct_answer": "份"}, "level_3": {"options": [{"text": "份", "is_correct": true, "explanation": "正确答案。“我们把工作分成三份”中，“份”指分出的部分。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，工作不用“本”计量。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，工作不用“条”计量。"}, {"text": "把", "is_correct": false, "explanation": "语义：“把”用于有柄的器具，工作不能说“三把”。"}], "explanations": {"份": "正确答案。“我们把工作分成三份”中，“份”指分出的部分。", "本": "搭配：“本”用于书册，工作不用“本”计量。", "条": "搭配：“条”用于细长的东西，工作不用“条”计量。", "把": "语义：“把”用于有柄的器具，工作不能说“三把”。"}, "sentence_index": 6, "correct_answer": "份"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一份手套。", "explanation": "这里应该用〈双〉。手套成双计算，应说“一双手套”，“份”不用于手套。"}, {"text": "他去看了一份电影。", "explanation": "这里应该用〈场〉。看电影用“场”计算，应说“看了一场电影”，不说“看了一份电影”。"}, {"text": "我们家养了一份猫。", "explanation": "这里应该用〈只〉。猫用“只”计算，“份”不用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把蛋糕分成了两个份。", "corrected_sentence": "他把蛋糕分成了两份。", "error_description": "量词错误：“份”前不能再加量词“个”，应直接说“两份”。错误形式是“两个份”，正确形式是“两份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把苹果分成两份份。", "corrected_sentence": "妈妈把苹果分成两份。", "error_description": "重叠错误：“份”不能在数量短语中重复叠用，应说“两份”。错误形式是“两份份”，正确形式是“两份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
