INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90083, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90083, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "来由是一件事为什么发生。", "primary_collocate": null, "pronunciation": "lái yóu", "ipa": "lai˧˥ iou˧˥", "syllable_count": 2, "sentences": [{"text": "这件事的来由，我真的不清楚。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察还在调查这场火灾的来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有来由地哭了，大家都很奇怪。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先说说事情的来由，我再帮你。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人讲了这个节日的来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们都想知道这个名字的来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我问了半天，也没问出他生气的来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个习惯有什么来由，没有人说得清。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他突然不来上班，大家都想知道来由。", "target_word": "来由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这个错误的来由讲给了大家听。", "target_word": "来由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情发生的原因、起因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来由", "is_correct": true, "explanation": "「来由」指事情发生的原因，与“我真的不清楚”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“这件事”没有颜色，不能说“这件事的颜色”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是钱的数目，事情的价格说不通，不能和“我真的不清楚”搭配成句。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：尺寸只用于可以度量的物体，不用来形容事情。"}], "explanations": {"来由": "「来由」指事情发生的原因，与“我真的不清楚”的语境相符。", "颜色": "搭配：“这件事”没有颜色，不能说“这件事的颜色”。", "价格": "语义：价格是钱的数目，事情的价格说不通，不能和“我真的不清楚”搭配成句。", "尺寸": "搭配：尺寸只用于可以度量的物体，不用来形容事情。"}, "sentence_index": 0, "correct_answer": "来由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事的来由很好。", "explanation": "这里应该用〈结果〉。来由指事情为什么发生，不能用来评价好坏，说“很好”要用〈结果〉。"}, {"text": "他的来由很神秘。", "explanation": "这里应该用〈来历〉。来历指人或物从哪里来、经历如何，来由只指事情的原因。"}, {"text": "这场比赛的来由很精彩。", "explanation": "这里应该用〈过程〉。来由指事情为什么发生，不指经过，说比赛“精彩”要用〈过程〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来由", "is_correct": true, "explanation": "「来由」指生气的原因，与“没问出”的语境相符。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址是住处的位置，生气不能有地址，“他生气的地址”句意不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不能说明生气的缘故，“他生气的年龄”说不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：面积只用于土地、房屋等，不能修饰“生气”。"}], "explanations": {"来由": "「来由」指生气的原因，与“没问出”的语境相符。", "地址": "语义：地址是住处的位置，生气不能有地址，“他生气的地址”句意不通。", "年龄": "语义：年龄不能说明生气的缘故，“他生气的年龄”说不通。", "面积": "搭配：面积只用于土地、房屋等，不能修饰“生气”。"}, "sentence_index": 6, "correct_answer": "来由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的来由很优秀。", "explanation": "这里应该用〈演员〉。来由指事情为什么发生，不能用来评价人员，说电影的主演“优秀”要用〈演员〉。"}, {"text": "这个实验的来由很先进。", "explanation": "这里应该用〈设备〉。来由指原因，不指仪器，说实验“先进”要用〈设备〉。"}, {"text": "他这次的来由很好。", "explanation": "这里应该用〈成绩〉。来由指原因，不能用来评价考试结果的好坏，说“很好”要用〈成绩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他解释了这次事故地来由。", "corrected_sentence": "他解释了这次事故的来由。", "error_description": "结构助词错误：修饰名词「来由」的定语后应用「的」，此处用「地」不对，应为「这次事故的来由」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想看这件事的来由。", "corrected_sentence": "我想知道这件事的来由。", "error_description": "搭配错误：“看”不能用来带“来由”。想弄清事情的原因要用“知道”或“了解”，正确为“我想知道这件事的来由”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
