INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90084, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "原因;缘由。", "primary_collocate": null, "pronunciation": "lái yóu", "ipa": "lai˧˥ iou˧˥", "syllable_count": 2, "sentences": [{"text": "他一直不说话，其中必有来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看他这么高兴，一定有来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这次迟到的来由很有意思。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他无缘无故生气，大家不知道来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈问清来由后，没有再批评我。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你把事情的来由从头说一遍。", "target_word": "来由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些奇怪的规定，都有各自的来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说不出自己为什么难过，好像没有来由。", "target_word": "来由", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不知道这件怪事的来由。", "target_word": "来由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听完他说的来由，老板笑着点了点头。", "target_word": "来由", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "原因、缘由", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56992c47-6832-429b-9ec5-b51f9d7bdb63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来由", "is_correct": true, "explanation": "「来由」指原因，“其中必有来由”表示一定有原因，句意通顺。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“必有”后面接的应是原因，尺寸不能存在于这样的语境中。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位与“一直不说话”没有关系，“其中必有座位”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能解释“一直不说话”的缘故，句意不通。"}], "explanations": {"来由": "「来由」指原因，“其中必有来由”表示一定有原因，句意通顺。", "尺寸": "搭配：“必有”后面接的应是原因，尺寸不能存在于这样的语境中。", "座位": "语义：座位与“一直不说话”没有关系，“其中必有座位”说不通。", "价格": "语义：价格不能解释“一直不说话”的缘故，句意不通。"}, "sentence_index": 0, "correct_answer": "来由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的来由很动听。", "explanation": "这里应该用〈旋律〉。来由指原因，不指音乐的曲调，说歌曲“动听”要用〈旋律〉。"}, {"text": "这位老人的来由很特殊。", "explanation": "这里应该用〈身份〉。来由指事情的起因，不指人的身份，说人“很特殊”要用〈身份〉。"}, {"text": "这个方案的来由很苛刻。", "explanation": "这里应该用〈条件〉。来由指原因，不指限制性要求，说方案“苛刻”要用〈条件〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来由", "is_correct": true, "explanation": "「来由」指规定产生的原因，与“都有各自的”搭配自然。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：面积只用于土地、房屋等，不能修饰“规定”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：规定没有年龄，“各自的年龄”不能解释这些规定，句意不通。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址是位置，规定没有住址，“各自的地址”句意不通。"}], "explanations": {"来由": "「来由」指规定产生的原因，与“都有各自的”搭配自然。", "面积": "搭配：面积只用于土地、房屋等，不能修饰“规定”。", "年龄": "语义：规定没有年龄，“各自的年龄”不能解释这些规定，句意不通。", "地址": "语义：地址是位置，规定没有住址，“各自的地址”句意不通。"}, "sentence_index": 6, "correct_answer": "来由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找到了一条来由。", "explanation": "这里应该用〈出路〉。来由指事情为什么发生，不指可以走的路，说找到“一条”要用〈出路〉。"}, {"text": "他走过的来由很长。", "explanation": "这里应该用〈历程〉。来由指原因，不指经历的过程或时间长度，说“走过的”要用〈历程〉。"}, {"text": "这项工作的来由很快。", "explanation": "这里应该用〈进展〉。来由指原因，不指推进速度，说工作“很快”要用〈进展〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事一定是来由，我们得查清楚。", "corrected_sentence": "这件事一定有来由，我们得查清楚。", "error_description": "搭配错误：表示“事情有原因”应说“有来由”，“是来由”意思不对，应改为“一定有来由”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把事情地来由讲清楚了。", "corrected_sentence": "他把事情的来由讲清楚了。", "error_description": "结构助词错误：修饰名词「来由」的定语后应用「的」，此处用「地」不对，应为「事情的来由」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fa2419f-6916-4083-b2a3-4f8725c24409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90085, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进来", "is_correct": true, "explanation": "正确：“进来”与“出去”方向相反，从外到里，互为反义。"}, {"text": "跳舞", "is_correct": false, "explanation": "与“出去”没有反义关系，跳舞与移动方向无关。"}, {"text": "看报", "is_correct": false, "explanation": "与“出去”没有反义关系，看报与方向无关。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“出去”没有反义关系，洗澡不是方向词。"}], "correct_answer": "进来", "explanations": {"进来": "正确：“进来”与“出去”方向相反，从外到里，互为反义。", "跳舞": "与“出去”没有反义关系，跳舞与移动方向无关。", "看报": "与“出去”没有反义关系，看报与方向无关。", "洗澡": "与“出去”没有反义关系，洗澡不是方向词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90085, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进来", "is_correct": true, "explanation": "正确：“进来”与“出去”方向相反，从外到里，互为反义。"}, {"text": "写字", "is_correct": false, "explanation": "与“出去”没有反义关系，写字是动作，不是方向。"}, {"text": "打篮球", "is_correct": false, "explanation": "与“出去”没有反义关系，打篮球与移动方向无关。"}, {"text": "画画", "is_correct": false, "explanation": "与“出去”没有反义关系，画画不是方向词。"}], "correct_answer": "进来", "explanations": {"进来": "正确：“进来”与“出去”方向相反，从外到里，互为反义。", "写字": "与“出去”没有反义关系，写字是动作，不是方向。", "打篮球": "与“出去”没有反义关系，打篮球与移动方向无关。", "画画": "与“出去”没有反义关系，画画不是方向词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90085, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出去是从里面走到外面。", "primary_collocate": null, "pronunciation": "chū qù", "ipa": "tʂʰu˥ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "客人吃完饭就出去了。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，孩子们跑着出去玩。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打开门，一个人出去了。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想出去买杯咖啡。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸穿上外套出去了。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说你可以出去晒太阳了。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上他没出去，在家看书。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她推开窗户，看见他出去了。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要出去的话，请关灯。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，弟弟还不想出去。", "target_word": "出去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出去了", "label": "体标"}, {"form": "出去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "从里面走到外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90085, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出去", "is_correct": true, "explanation": "正确答案：出去（chū qù），意思是从里面走到外面。"}, {"text": "除去", "is_correct": false, "explanation": "除去（chú qù）与出去（chū qù）第一音节声调不同，意思是去掉。"}, {"text": "出气", "is_correct": false, "explanation": "出气（chū qì）与出去（chū qù）韵母不同（i 对 ü），意思是发泄怒气。"}, {"text": "初具", "is_correct": false, "explanation": "初具（chū jù）与出去（chū qù）声母不同（j 对 q），意思是刚开始具有。"}], "explanations": {"出去": "正确答案：出去（chū qù），意思是从里面走到外面。", "除去": "除去（chú qù）与出去（chū qù）第一音节声调不同，意思是去掉。", "出气": "出气（chū qì）与出去（chū qù）韵母不同（i 对 ü），意思是发泄怒气。", "初具": "初具（chū jù）与出去（chū qù）声母不同（j 对 q），意思是刚开始具有。"}, "sentence_index": null, "correct_answer": "出去"}, "level_3": {"options": [{"text": "出去", "is_correct": true, "explanation": "正确：「客人吃完饭就出去了」中的“出去”表示离开，与语境相合。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“吃完饭就结婚”不合逻辑，与句子语境不符。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”通常要有对象（如门、窗），“吃完饭就打开了”缺少合适的对象，不通。"}, {"text": "长大", "is_correct": false, "explanation": "语义：“吃完饭就长大”不合常理。"}], "explanations": {"出去": "正确：「客人吃完饭就出去了」中的“出去”表示离开，与语境相合。", "结婚": "语义：“吃完饭就结婚”不合逻辑，与句子语境不符。", "打开": "搭配：“打开”通常要有对象（如门、窗），“吃完饭就打开了”缺少合适的对象，不通。", "长大": "语义：“吃完饭就长大”不合常理。"}, "sentence_index": 0, "correct_answer": "出去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这一周很快就出去了，时间过得真快。", "explanation": "这里应该用〈过去〉。出去表示从里到外移动，时间流逝要用过去。"}, {"text": "她一听到坏消息，脸上的笑容就出去了。", "explanation": "这里应该用〈消失〉。出去表示人从里到外移动，笑容没有了要用消失。"}, {"text": "这场雪下了一夜，早上就出去了。", "explanation": "这里应该用〈停〉。出去表示从里到外移动，雪停了要用停，不能说雪出去了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出去", "is_correct": true, "explanation": "正确：「昨天晚上他没出去，在家看书」中的“出去”表示外出，与“在家”形成对照。"}, {"text": "回家", "is_correct": false, "explanation": "语义：“没回家”与“在家看书”矛盾。"}, {"text": "进屋", "is_correct": false, "explanation": "语义：“进屋”指进到屋子里，“没进屋”说明人不在屋里，和“在家看书”相矛盾。"}, {"text": "回来", "is_correct": false, "explanation": "语义：“没回来”说明人不在，与“在家看书”矛盾。"}], "explanations": {"出去": "正确：「昨天晚上他没出去，在家看书」中的“出去”表示外出，与“在家”形成对照。", "回家": "语义：“没回家”与“在家看书”矛盾。", "进屋": "语义：“进屋”指进到屋子里，“没进屋”说明人不在屋里，和“在家看书”相矛盾。", "回来": "语义：“没回来”说明人不在，与“在家看书”矛盾。"}, "sentence_index": 6, "correct_answer": "出去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外面太冷了，你别在门口站着，快出去坐吧！", "explanation": "这里应该用〈进来〉。对方已经在外面，要请他从外面到说话人所在的屋里来，应说“进来”；出去是从里到外。"}, {"text": "这个苹果放了很久，已经出去了。", "explanation": "这里应该用〈坏〉。出去表示从里到外移动，苹果变质要用坏，不能说苹果出去了。"}, {"text": "这张照片放在阳光下太久，颜色已经出去了。", "explanation": "这里应该用〈褪〉。出去表示从里到外移动，颜色变淡要用褪，不能说颜色出去了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想出去了散步，你要不要一起？", "corrected_sentence": "我想出去散步，你要不要一起？", "error_description": "“了”放在“出去”后、宾语前不通，应说“想出去散步”，“了”不能插在这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚出去着，就有人来找他。", "corrected_sentence": "他刚出去，就有人来找他。", "error_description": "“出去”是复合趋向动词，后面不能直接接“着”，应说“刚出去”，不能说“刚出去着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
