INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90087, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "区别是两个东西不一样的地方。", "primary_collocate": null, "pronunciation": "qū bié", "ipa": "tɕʰy˥ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "这两个杯子的区别在哪儿？", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和弟弟的最大区别是个子。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能看出这两张图的区别吗？", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种茶有什么区别？", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到这两件衣服的区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果和梨的区别是味道不一样。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋和那双鞋只有一点区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说一说猫和狗的区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两本书的区别不大，价格也一样。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个字的区别在右边。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "區別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个具体东西之间不一样的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区别", "is_correct": true, "explanation": "正确：“区别”指两个东西不一样的地方，可以说“在哪儿”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：杯子没有年龄，不能说“年龄在哪儿”。"}, {"text": "作者", "is_correct": false, "explanation": "语义：杯子没有作者，不能说“作者在哪儿”。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”应说“多大”，不能与“在哪儿”搭配。"}], "explanations": {"区别": "正确：“区别”指两个东西不一样的地方，可以说“在哪儿”。", "年龄": "语义：杯子没有年龄，不能说“年龄在哪儿”。", "作者": "语义：杯子没有作者，不能说“作者在哪儿”。", "体积": "搭配：“体积”应说“多大”，不能与“在哪儿”搭配。"}, "sentence_index": 0, "correct_answer": "区别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他迟到的区别是堵车。", "explanation": "这里应该用〈原因〉。“区别”指两者之间的不同之处，说明事情为什么发生要用“原因”。"}, {"text": "我找到了两把区别。", "explanation": "量词用错：“区别”前应用“个”或“种”，“把”用于有柄的东西。"}, {"text": "他家和公司的区别很远。", "explanation": "这里应该用〈距离〉。说空间远近要用“距离”，“区别”指不同之处，不能用来形容远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区别", "is_correct": true, "explanation": "正确：“区别”指事物之间不一样的地方，与“只有一点”搭配自然。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：鞋子没有国籍，不能说“只有一点国籍”。"}, {"text": "作者", "is_correct": false, "explanation": "语义：鞋子没有作者，与“只有一点”的语境不合。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”一般说长短，不能用“只有一点”来修饰。"}], "explanations": {"区别": "正确：“区别”指事物之间不一样的地方，与“只有一点”搭配自然。", "国籍": "语义：鞋子没有国籍，不能说“只有一点国籍”。", "作者": "语义：鞋子没有作者，与“只有一点”的语境不合。", "寿命": "搭配：“寿命”一般说长短，不能用“只有一点”来修饰。"}, "sentence_index": 6, "correct_answer": "区别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们做了一次区别。", "explanation": "这里应该用〈对比〉。做比较要说“对比”或“比较”，“区别”不能作动作。"}, {"text": "这两个字有两块区别。", "explanation": "量词用错：“区别”前应用“个”或“种”，“块”用于块状的东西。"}, {"text": "这两件衣服的区别很亮。", "explanation": "这里应该用〈颜色〉。“亮”形容颜色，“区别”指不同之处，不能说“亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两张照片有一把明显的区别。", "corrected_sentence": "这两张照片有一个明显的区别。", "error_description": "量词错误：“区别”应用量词“个”，不能用“把”（“把”用于有柄的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两件外套有一根小小的区别。", "corrected_sentence": "这两件外套有一个小小的区别。", "error_description": "量词错误：“区别”应用量词“个”，不能用“根”（“根”用于细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
