INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90088, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物之间的不同点;差别。", "primary_collocate": null, "pronunciation": "qū bié", "ipa": "tɕʰy˥ pjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "中国和日本的文化有很多区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市和农村的生活有明显的区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这两种方法没有什么区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男孩和女孩的学习方式有很大区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新旧手机的区别越来越小了。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了中文和英文的区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道北方和南方饮食的区别吗？", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两家公司的区别主要在价格上。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩的性格有很大的区别。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作和学习的区别，我现在才明白。", "target_word": "区别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "區別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事物、情况之间的差别或不同点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42e56a80-f319-4a83-b29d-b93d5094fd86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区别", "is_correct": true, "explanation": "正确：“区别”指事物之间的不同点，与“有很多”搭配自然。"}, {"text": "距离", "is_correct": false, "explanation": "搭配：“距离”应说“一段距离”，不能说“有很多距离”。"}, {"text": "体积", "is_correct": false, "explanation": "语义：文化没有体积，不能说“文化有很多体积”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：文化没有体重，不能用“体重”来描述。"}], "explanations": {"区别": "正确：“区别”指事物之间的不同点，与“有很多”搭配自然。", "距离": "搭配：“距离”应说“一段距离”，不能说“有很多距离”。", "体积": "语义：文化没有体积，不能说“文化有很多体积”。", "体重": "语义：文化没有体重，不能用“体重”来描述。"}, "sentence_index": 0, "correct_answer": "区别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校和车站的区别很远。", "explanation": "这里应该用〈距离〉。说空间远近要用“距离”，“区别”指不同之处。"}, {"text": "我们学校有一颗区别。", "explanation": "量词用错：“区别”前应用“个”或“种”，“颗”用于颗粒状的东西。"}, {"text": "这两件事的区别很久了。", "explanation": "这里应该用〈时间〉。说时间长短要用“时间”，“区别”指不同之处，不能用来说时间的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区别", "is_correct": true, "explanation": "正确：“区别”指两地饮食之间的不同点，与“知道……吗”的语境搭配。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：饮食没有年龄，不能说“饮食的年龄”。"}, {"text": "人口", "is_correct": false, "explanation": "语义：饮食没有人口，与语境不合。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：说饮食时一般用“分量”，不说“饮食的重量”。"}], "explanations": {"区别": "正确：“区别”指两地饮食之间的不同点，与“知道……吗”的语境搭配。", "年龄": "语义：饮食没有年龄，不能说“饮食的年龄”。", "人口": "语义：饮食没有人口，与语境不合。", "重量": "搭配：说饮食时一般用“分量”，不说“饮食的重量”。"}, "sentence_index": 6, "correct_answer": "区别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他迟到的区别，我现在才明白。", "explanation": "这里应该用〈原因〉。“区别”指不同之处，说为什么发生要用“原因”。"}, {"text": "我们找到了两块区别。", "explanation": "量词用错：“区别”前应用“个”或“种”，“块”用于块状的东西。"}, {"text": "这件衣服的区别很亮。", "explanation": "这里应该用〈颜色〉。“亮”形容颜色，“区别”指不同之处，不能说“区别很亮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07c29b07-4c60-4710-bbc7-77c212ad97df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
