INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同父母(或同父异母、同母异父)而年纪比自己大的男子。", "primary_collocate": null, "pronunciation": "gē ge", "ipa": "kɤ˥ kɤ", "syllable_count": 2, "sentences": [{"text": "我的哥哥是一名医生。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥结婚以后搬到了上海。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥比我大八岁，已经工作了。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥和爸爸一样高。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的哥哥在大学教书。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我给哥哥打电话，告诉他这个好消息。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们兄妹三个，哥哥最大。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥每个月都给妈妈寄钱。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，哥哥从外地回家看爸爸妈妈。", "target_word": "哥哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥个子很高，还会打篮球。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "大哥", "label": "复合"}, {"form": "堂哥", "label": "复合"}], "register": "口语", "sense_fingerprint": "同父母年长男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e84adf9-f7e5-4676-ae12-1e74b754fae1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哥哥", "is_correct": true, "explanation": "哥哥是同父母而年长的男子，「我的哥哥是一名医生」句意通顺。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不能是医生，与「是一名医生」相矛盾。"}, {"text": "小孩子", "is_correct": false, "explanation": "语义：小孩子年纪还小，不可能是医生。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：〈是一名医生〉要求有职业的人作主语，〈桌子〉不能与之搭配。"}], "explanations": {"哥哥": "哥哥是同父母而年长的男子，「我的哥哥是一名医生」句意通顺。", "小狗": "语义：小狗是动物，不能是医生，与「是一名医生」相矛盾。", "小孩子": "语义：小孩子年纪还小，不可能是医生。", "桌子": "搭配：〈是一名医生〉要求有职业的人作主语，〈桌子〉不能与之搭配。"}, "sentence_index": 0, "correct_answer": "哥哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥比我小两岁，还在上学。", "explanation": "这里应该用〈弟弟〉。哥哥指年纪比自己大的同胞男子，比自己小的要说弟弟。"}, {"text": "她是我哥哥，正在读小学。", "explanation": "这里应该用〈妹妹〉或〈姐姐〉（视年龄而定）。哥哥只指男性，不能用来称呼女性。"}, {"text": "我哥哥是我爸爸的弟弟，今年四十岁，在上海工作。", "explanation": "这里应该用〈叔叔〉。叔叔指父亲的弟弟，不是同父母或同父异母、同母异父的哥哥，哥哥不能用来指父亲的弟弟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哥哥", "is_correct": true, "explanation": "哥哥是同父母而年长的男子，「我们兄妹三个，哥哥最大」句意通顺。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：妈妈是母亲，不是兄妹之一，句中「兄妹三个」里不会是她最大。"}, {"text": "叔叔", "is_correct": false, "explanation": "语义：叔叔是父亲的兄弟，不属于兄妹三个，与句意不符。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：〈兄妹三个〉指同辈的人，〈小猫〉不能与之搭配。"}], "explanations": {"哥哥": "哥哥是同父母而年长的男子，「我们兄妹三个，哥哥最大」句意通顺。", "妈妈": "语义：妈妈是母亲，不是兄妹之一，句中「兄妹三个」里不会是她最大。", "叔叔": "语义：叔叔是父亲的兄弟，不属于兄妹三个，与句意不符。", "小猫": "搭配：〈兄妹三个〉指同辈的人，〈小猫〉不能与之搭配。"}, "sentence_index": 6, "correct_answer": "哥哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我哥哥才五岁，是我的侄子，每天来我家玩。", "explanation": "这里应该用〈侄子〉。侄子指哥哥或弟弟的儿子，比自己低一辈，哥哥不能用来指侄子。"}, {"text": "她是我哥哥，个子很高，还会打篮球。", "explanation": "这里应该用〈姐姐〉或〈妹妹〉（视年龄而定）。哥哥只指男性，女性即使个子高也不能说哥哥。"}, {"text": "我哥哥是我爸爸的爸爸，今年八十岁了，身体很好。", "explanation": "这里应该用〈爷爷〉。爷爷指父亲的父亲，比自己高一辈，不是同父母或同父异母、同母异父的哥哥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有两只哥哥。", "corrected_sentence": "我有两个哥哥。", "error_description": "〈哥哥〉指人，量词应用〈个〉或〈位〉。〈只〉用于动物，不能用来数人，应说「两个哥哥」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有两哥哥，每天早上都跑步。", "corrected_sentence": "我家有两个哥哥，每天早上都跑步。", "error_description": "错误：数词“两”与“哥哥”之间需要量词，应说“两个哥哥”，不能省略量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16385115-d1fd-4a12-80b3-2bebd3737e5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
