INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90093, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "尽头是一条路或一件事最后到的地方。", "primary_collocate": null, "pronunciation": "jìn tóu", "ipa": "tɕin˥˩ tʰou̯˧˥", "syllable_count": 2, "sentences": [{"text": "小路的尽头是一片树林。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手间在楼道的尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园的尽头有一个小湖。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直往前走，到尽头再往右拐。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的尽头有一家书店。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车站在铁路的尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们走了很久，还没走到山路的尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的路到了尽头，前面是沙滩。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着河岸一直走，走到了码头的尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在山顶，望向远处山谷的尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盡頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一条路或一件事最后到的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能“是一片树林”，句子说的是一个地点。"}, {"text": "尽头", "is_correct": true, "explanation": "正确：“小路的尽头”是一个地点，可以是一片树林，符合语境。"}, {"text": "房间", "is_correct": false, "explanation": "语义：“小路”不是房间，不能说“小路的房间是一片树林”。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“高度”只用来说高低，不能与“是一片树林”搭配。"}], "explanations": {"颜色": "语义：“颜色”不能“是一片树林”，句子说的是一个地点。", "尽头": "正确：“小路的尽头”是一个地点，可以是一片树林，符合语境。", "房间": "语义：“小路”不是房间，不能说“小路的房间是一片树林”。", "高度": "搭配：“高度”只用来说高低，不能与“是一片树林”搭配。"}, "sentence_index": 0, "correct_answer": "尽头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用尽头洗了碗。", "explanation": "这里应该用〈洗洁精〉。“尽头”指路或事情最后到的地方，不是洗东西用的东西。"}, {"text": "小猫甩着尽头，高兴地跑来跑去。", "explanation": "这里应该用〈尾巴〉。“尽头”指路或事情最后到的地方，不能用来说动物的尾巴。"}, {"text": "他的尽头又黑又亮。", "explanation": "这里应该用〈眼睛〉。“尽头”指路或事情最后到的地方，不能用来说人的眼睛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：“时间”不能被“走到”，人走到的是某个地点。"}, {"text": "尽头", "is_correct": true, "explanation": "正确：“走到山路的尽头”是走到一个地点，符合语境。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“走到”要求地点作宾语，“声音”不是地点。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”不能被“走到”，人走到的是地方，不是地图。"}], "explanations": {"时间": "语义：“时间”不能被“走到”，人走到的是某个地点。", "尽头": "正确：“走到山路的尽头”是走到一个地点，符合语境。", "声音": "配价：“走到”要求地点作宾语，“声音”不是地点。", "地图": "语义：“地图”不能被“走到”，人走到的是地方，不是地图。"}, "sentence_index": 6, "correct_answer": "尽头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的尽头很疼。", "explanation": "这里应该用〈肚子〉。“尽头”指末端，不能用来说身体部位疼。"}, {"text": "我们从车站出发，车站是我们的尽头。", "explanation": "这里应该用〈出发点〉。句中是从车站出发，“尽头”指最后到达的地方，与“出发”矛盾。"}, {"text": "她的尽头很长。", "explanation": "这里应该用〈头发〉。“尽头”指末端，不能用来说人的头发长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们终于走了到小路的尽头。", "corrected_sentence": "我们终于走到了小路的尽头。", "error_description": "“走到”是动词加结果补语，“了”要放在“到”后面，应说“走到了”，不能说“走了到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天太黑了，我们看到不路的尽头。", "corrected_sentence": "天太黑了，我们看不到路的尽头。", "error_description": "可能补语的否定要说“看不到”，“不”放在“看”和“到”之间，不能说“看到不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90094, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起点", "is_correct": true, "explanation": "反义：“尽头”指路或事情的末端，“起点”指开始的地方，二者意义相对。"}, {"text": "桌子", "is_correct": false, "explanation": "无关：“桌子”与“尽头”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”与“尽头”的意义不相对。"}, {"text": "天气", "is_correct": false, "explanation": "无关：“天气”与“尽头”没有反义关系。"}], "correct_answer": "起点", "explanations": {"起点": "反义：“尽头”指路或事情的末端，“起点”指开始的地方，二者意义相对。", "桌子": "无关：“桌子”与“尽头”没有反义关系。", "河流": "无关：“河流”与“尽头”的意义不相对。", "天气": "无关：“天气”与“尽头”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90094, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起点", "is_correct": true, "explanation": "反义：“尽头”指路或事情的末端，“起点”指开始的地方，二者意义相对。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”与“尽头”没有反义关系。"}, {"text": "汽车", "is_correct": false, "explanation": "无关：“汽车”与“尽头”的意义不相对。"}, {"text": "春天", "is_correct": false, "explanation": "无关：“春天”与“尽头”没有反义关系。"}], "correct_answer": "起点", "explanations": {"起点": "反义：“尽头”指路或事情的末端，“起点”指开始的地方，二者意义相对。", "窗户": "无关：“窗户”与“尽头”没有反义关系。", "汽车": "无关：“汽车”与“尽头”的意义不相对。", "春天": "无关：“春天”与“尽头”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "末端，终点；也指事物发展的最后阶段。", "primary_collocate": null, "pronunciation": "jìn tóu", "ipa": "tɕin˥˩ tʰou̯˧˥", "syllable_count": 2, "sentences": [{"text": "这条路的尽头有一座小桥。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走到街道的尽头，你就能看到车站。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得人生没有尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隧道的尽头出现了一点光。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的尽头是大海。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走到了村子的尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得这份工作看不到尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路的尽头，有一间小房子。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的故事走到了尽头。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长长的走廊尽头有一扇门。", "target_word": "尽头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盡頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "末端、终点，也指事物发展的最后阶段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab6a104f-9e41-4abb-b0a8-5bf7f0fd431f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是处所，“这条路的颜色”不能“有一座小桥”。"}, {"text": "尽头", "is_correct": true, "explanation": "正确：“尽头”指路的末端，可以放一座小桥，符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是处所，“这条路的天气”说不通。"}, {"text": "方向", "is_correct": false, "explanation": "配价：“有”后面要接能放桥的处所，“方向”不能作存在的处所。"}], "explanations": {"颜色": "语义：“颜色”不是处所，“这条路的颜色”不能“有一座小桥”。", "尽头": "正确：“尽头”指路的末端，可以放一座小桥，符合语境。", "天气": "语义：“天气”不是处所，“这条路的天气”说不通。", "方向": "配价：“有”后面要接能放桥的处所，“方向”不能作存在的处所。"}, "sentence_index": 0, "correct_answer": "尽头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书放进了尽头里。", "explanation": "这里应该用〈书包〉。“尽头”指末端或终点，不是能装东西的东西。"}, {"text": "他的尽头很大。", "explanation": "这里应该用〈脑袋〉。“尽头”指末端，不能用来说人的头部。"}, {"text": "他的尽头考得很好。", "explanation": "这里应该用〈成绩〉。“尽头”指末端或终点，不能用来说考试的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "配价：“看”要求可见的宾语，“声音”不能被“看不到”。"}, {"text": "尽头", "is_correct": true, "explanation": "正确：“看不到尽头”说的是事情没有终点，符合“这份工作”的语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“看不到天空”说的是视野，和“这份工作”的语境对不上。"}, {"text": "味道", "is_correct": false, "explanation": "配价：“看”要求可见的宾语，“味道”不能被“看不到”。"}], "explanations": {"声音": "配价：“看”要求可见的宾语，“声音”不能被“看不到”。", "尽头": "正确：“看不到尽头”说的是事情没有终点，符合“这份工作”的语境。", "天空": "语义：“看不到天空”说的是视野，和“这份工作”的语境对不上。", "味道": "配价：“看”要求可见的宾语，“味道”不能被“看不到”。"}, "sentence_index": 6, "correct_answer": "尽头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗摇着尽头，高兴地跑来跑去。", "explanation": "这里应该用〈尾巴〉。“尽头”指末端，不能用来说小狗的尾巴。"}, {"text": "他用尽头擦干净了桌子。", "explanation": "这里应该用〈抹布〉。“尽头”指末端，不能用来当作擦东西的工具。"}, {"text": "她的尽头很红。", "explanation": "这里应该用〈脸〉。“尽头”不能用来形容人的脸色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们终于走了到这条路的尽头。", "corrected_sentence": "他们终于走到了这条路的尽头。", "error_description": "“走到”是动词加结果补语，“了”要放在“到”后面，应说“走到了”，不能说“走了到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雾太大了，我们看到不尽头。", "corrected_sentence": "雾太大了，我们看不到尽头。", "error_description": "可能补语的否定要放在“看”和“到”之间，应说“看不到”，不能说“看到不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a3ced41-e433-4d03-853b-d37aa552f87d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "好：与“坏”相对，指灯能正常使用。"}, {"text": "长", "is_correct": false, "explanation": "长指长度，与“坏”没有反义关系，它的反义词是“短”。"}, {"text": "新", "is_correct": false, "explanation": "新与“旧”相对，不是“坏”的反义词。"}, {"text": "大", "is_correct": false, "explanation": "大指体积或程度，与“坏”没有反义关系。"}], "correct_answer": "好", "explanations": {"好": "好：与“坏”相对，指灯能正常使用。", "长": "长指长度，与“坏”没有反义关系，它的反义词是“短”。", "新": "新与“旧”相对，不是“坏”的反义词。", "大": "大指体积或程度，与“坏”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "好：与“坏”相对，指东西没有毛病、能用。"}, {"text": "快", "is_correct": false, "explanation": "快指速度，与“坏”没有反义关系，它的反义词是“慢”。"}, {"text": "轻", "is_correct": false, "explanation": "轻指重量，与“坏”没有反义关系，它的反义词是“重”。"}, {"text": "高", "is_correct": false, "explanation": "高指高度，与“坏”没有反义关系，它的反义词是“低”。"}], "correct_answer": "好", "explanations": {"好": "好：与“坏”相对，指东西没有毛病、能用。", "快": "快指速度，与“坏”没有反义关系，它的反义词是“慢”。", "轻": "轻指重量，与“坏”没有反义关系，它的反义词是“重”。", "高": "高指高度，与“坏”没有反义关系，它的反义词是“低”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "坏是不好的,不能用了。", "primary_collocate": null, "pronunciation": "huài", "ipa": "xwaɪ⁵¹", "syllable_count": 1, "sentences": [{"text": "我的手机坏了，不能打电话。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯坏了，我们只能走楼梯上去。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子坏了，一坐就会倒。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯坏了，晚上屋里一点儿光都没有。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱坏了，里面的东西都不冷了。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔写不出字，是坏的。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的自行车坏了，今天走路上班。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机坏了三天，还没有人来修。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁坏了，我进不去家门。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧电脑坏了，我想买新的。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坏了", "label": "体标"}, {"form": "坏过", "label": "体标"}, {"form": "坏处", "label": "复合"}, {"form": "坏蛋", "label": "复合"}, {"form": "壞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西出了毛病，不能再用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62640798-92c2-46f8-9980-a0d08bce8395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏 huài：东西出了毛病、不能用了，是本题答案。"}, {"text": "快", "is_correct": false, "explanation": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是快。"}, {"text": "怪", "is_correct": false, "explanation": "guài 与 huài 声母不同（g 与 h），声调相同，意思是奇怪。"}, {"text": "怀", "is_correct": false, "explanation": "huái（第二声）与 huài（第四声）声调不同，意思是怀抱、怀念。"}, {"text": "换", "is_correct": false, "explanation": "huàn 与 huài 韵母不同（末尾 -n 与 -i），声调相同，意思是交换。"}], "explanations": {"坏": "坏 huài：东西出了毛病、不能用了，是本题答案。", "快": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是快。", "怪": "guài 与 huài 声母不同（g 与 h），声调相同，意思是奇怪。", "怀": "huái（第二声）与 huài（第四声）声调不同，意思是怀抱、怀念。", "换": "huàn 与 huài 韵母不同（末尾 -n 与 -i），声调相同，意思是交换。"}, "sentence_index": null, "correct_answer": "坏"}, "level_3": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏：东西出了毛病、不能用了，与“不能打电话”的原因相符。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，手机慢了并不会导致不能打电话。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说屏幕发光，与句中“不能打电话”的意思不合。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”用于食物或味道，不说手机甜了。"}], "explanations": {"坏": "坏：东西出了毛病、不能用了，与“不能打电话”的原因相符。", "慢": "语义：“慢”说速度，手机慢了并不会导致不能打电话。", "亮": "语义：“亮”说屏幕发光，与句中“不能打电话”的意思不合。", "甜": "搭配：“甜”用于食物或味道，不说手机甜了。"}, "sentence_index": 0, "correct_answer": "坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的会议坏了，改到明天再开。", "explanation": "这里应该用〈推迟〉。坏指东西出毛病，会议延期要用“推迟”，不说“会议坏了”。"}, {"text": "这张过期的优惠券早就坏了，不能用了。", "explanation": "这里应该用〈作废〉。坏指东西出毛病，优惠券、车票过期失去效力要用“作废”。"}, {"text": "地上的文件坏了一地，乱七八糟的。", "explanation": "这里应该用〈散〉。坏指东西出毛病，纸张、物品四处散落要用“散”，不说“坏了一地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏 huài：东西出了毛病、不能用了，是本题答案。"}, {"text": "块", "is_correct": false, "explanation": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是块状物。"}, {"text": "帅", "is_correct": false, "explanation": "shuài 与 huài 声母不同（sh 与 h），声调相同，意思是英俊。"}, {"text": "话", "is_correct": false, "explanation": "huà 与 huài 韵母不同（少了末尾的 -i），声调相同，意思是话语。"}], "explanations": {"坏": "坏 huài：东西出了毛病、不能用了，是本题答案。", "块": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是块状物。", "帅": "shuài 与 huài 声母不同（sh 与 h），声调相同，意思是英俊。", "话": "huà 与 huài 韵母不同（少了末尾的 -i），声调相同，意思是话语。"}, "sentence_index": null, "correct_answer": "坏"}, "level_3": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏：东西出了毛病、不能骑了，与“走路上班”的原因相符。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”说崭新，自行车新了与走路上班没有因果关系。"}, {"text": "凉", "is_correct": false, "explanation": "搭配：“凉”多用于水、饭菜、天气，不说自行车凉了。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说高度，自行车高了与走路上班之间没有因果。"}], "explanations": {"坏": "坏：东西出了毛病、不能骑了，与“走路上班”的原因相符。", "新": "语义：“新”说崭新，自行车新了与走路上班没有因果关系。", "凉": "搭配：“凉”多用于水、饭菜、天气，不说自行车凉了。", "高": "语义：“高”说高度，自行车高了与走路上班之间没有因果。"}, "sentence_index": 6, "correct_answer": "坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小店因为装修，暂时坏了。", "explanation": "这里应该用〈停业〉。坏指东西出毛病，店铺暂时关门不营业要用“停业”，不说“店坏了”。"}, {"text": "这门手艺已经坏了，没有人会做了。", "explanation": "这里应该用〈失传〉。坏指东西出毛病，技艺因无人继承而不再流传要用“失传”。"}, {"text": "炉子里的火坏了，屋里很冷。", "explanation": "这里应该用〈熄灭〉。坏指东西出毛病，火因没有燃料或风而灭掉要用“熄灭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 