INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90097, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "直接数据是自己亲自量出来、得到的数字资料。", "primary_collocate": null, "pronunciation": "zhí jiē shù jù", "ipa": "ʈʂɻ̩˧˥ tɕjɛ˥ ʂu˥˩ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "这些是我们自己量的直接数据。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，直接数据比网上的数字更可靠。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用尺子量桌子，记下了直接数据。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把量出来的直接数据写在本子上。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做实验时，要认真记录直接数据。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里的直接数据都是我们自己量的。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有直接数据，只能用别人的资料。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天量体温，得到了很多直接数据。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这组直接数据是在教室里量出来的。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了得到直接数据，他们走了很多地方。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "组", "label": "量词"}, {"form": "直接數據", "label": "繁体"}], "register": "书面", "sense_fingerprint": "自己亲自量出来的数字资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是用尺子或仪器量出来的，与“自己量的”不符。"}, {"text": "直接数据", "is_correct": true, "explanation": "正确。直接数据是自己亲自量出来的数字资料，与句意相符。"}, {"text": "问题", "is_correct": false, "explanation": "搭配：“量”的对象是长度、重量等可以测量的东西，不说“量问题”。"}, {"text": "典籍", "is_correct": false, "explanation": "语域：典籍是古代书籍的书面语，与“自己量的”这样的口语化说法不协调，且典籍不是量出来的。"}], "explanations": {"饼干": "语义：饼干不是用尺子或仪器量出来的，与“自己量的”不符。", "直接数据": "正确。直接数据是自己亲自量出来的数字资料，与句意相符。", "问题": "搭配：“量”的对象是长度、重量等可以测量的东西，不说“量问题”。", "典籍": "语域：典籍是古代书籍的书面语，与“自己量的”这样的口语化说法不协调，且典籍不是量出来的。"}, "sentence_index": 0, "correct_answer": "直接数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份直接数据可以坐人，很结实。", "explanation": "这里应该用〈椅子〉。直接数据是测得的数字资料，不能“坐人”，也谈不上结实。"}, {"text": "这份直接数据是别人写的，我们只是引用。", "explanation": "这里应该用〈资料〉。直接数据指亲自量得的数据，别人写的材料不算直接数据。"}, {"text": "这份直接数据很好听，我常常唱给妈妈听。", "explanation": "这里应该用〈歌曲〉。直接数据是测得的数字资料，不能唱，也谈不上好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直接数据", "is_correct": true, "explanation": "正确。直接数据指亲自量出来的数据，没有它只能用别人的资料，与句意相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：没有冰箱和“只能用别人的资料”毫无关系，句意不通。"}, {"text": "足球", "is_correct": false, "explanation": "语义：没有足球和“只能用别人的资料”毫无关系，句意不通。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：没有海浪和“只能用别人的资料”毫无关系，句意不通。"}], "explanations": {"直接数据": "正确。直接数据指亲自量出来的数据，没有它只能用别人的资料，与句意相符。", "冰箱": "语义：没有冰箱和“只能用别人的资料”毫无关系，句意不通。", "足球": "语义：没有足球和“只能用别人的资料”毫无关系，句意不通。", "海浪": "语义：没有海浪和“只能用别人的资料”毫无关系，句意不通。"}, "sentence_index": 6, "correct_answer": "直接数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天吃直接数据，吃得很饱。", "explanation": "这里应该用〈米饭〉。直接数据是测得的数字资料，不能吃，也吃不饱。"}, {"text": "这份直接数据是老师从图书馆借来的。", "explanation": "这里应该用〈材料〉。直接数据是亲自测得的数据，不会从图书馆借来。"}, {"text": "这份直接数据开了两年，还很新。", "explanation": "这里应该用〈汽车〉。直接数据是测得的数字资料，不能驾驶，也谈不上“开了两年还很新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在操场上测了三遍，得到了一只直接数据。", "corrected_sentence": "我们在操场上测了三遍，得到了一组直接数据。", "error_description": "量词错误：“只”用于动物等，不能用来计量数据。“直接数据”的量词应为“组”，正确说法是“得到了一组直接数据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去河边取了水样，得到了直接数据着。", "corrected_sentence": "我们去河边取了水样，得到了直接数据。", "error_description": "体标错误：“着”表示动作的持续或状态，不能加在名词“直接数据”之后。正确说法是“得到了直接数据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
