INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通过观测、调查等方式直接获得的第一手数据。", "primary_collocate": null, "pronunciation": "zhí jiē shù jù", "ipa": "ʈʂɻ̩˧˥ tɕjɛ˥ ʂu˥˩ tɕy˥˩", "syllable_count": 4, "sentences": [{"text": "记者去村里调查，拿到了直接数据。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气站每天观测，收集直接数据。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些直接数据来自上千份问卷。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究者先看直接数据，再写文章。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把调查得到的直接数据放进了电脑。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有直接数据，研究结果就不可信。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的直接数据是工作人员亲自记录的。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们去公园数人，收集直接数据。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用问卷收集到了直接数据。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看了直接数据，大家才相信这个结论。", "target_word": "直接数据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批", "label": "量词"}, {"form": "直接數據", "label": "繁体"}], "register": "书面", "sense_fingerprint": "观测调查直接得到的第一手数据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是天空中的光现象，调查中不可能拿到。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪不是调查中能拿到的东西，句意不通。"}, {"text": "圣旨", "is_correct": false, "explanation": "语域：圣旨是古代的文书，用在现代调查的语境里不协调，且调查不会拿到圣旨。"}, {"text": "直接数据", "is_correct": true, "explanation": "正确。直接数据是调查中直接获得的第一手数据，与“拿到了”相符。"}], "explanations": {"彩虹": "语义：彩虹是天空中的光现象，调查中不可能拿到。", "海浪": "语义：海浪不是调查中能拿到的东西，句意不通。", "圣旨": "语域：圣旨是古代的文书，用在现代调查的语境里不协调，且调查不会拿到圣旨。", "直接数据": "正确。直接数据是调查中直接获得的第一手数据，与“拿到了”相符。"}, "sentence_index": 0, "correct_answer": "直接数据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些直接数据是转引自别的研究的。", "explanation": "这里应该用〈间接数据〉。直接数据指亲自观测、调查得来的第一手数据，转引自别处的数据不是直接数据。"}, {"text": "这份直接数据写得很感人，我读了好几遍。", "explanation": "这里应该用〈散文〉。直接数据是观测得来的数字资料，不能用“写得很感人”来形容。"}, {"text": "这是我小时候的直接数据。", "explanation": "这里应该用〈照片〉。直接数据是观测或调查得来的数字资料，不是照片，不能用来回忆童年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是工作人员记录的对象，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能由工作人员记录，句意不通。"}, {"text": "直接数据", "is_correct": true, "explanation": "正确。直接数据是工作人员亲自记录的第一手数据，与句意相符。"}, {"text": "墨宝", "is_correct": false, "explanation": "语域：墨宝是文雅的书面用语，与这样的现代记录语境不协调，且墨宝不是工作人员记录的。"}], "explanations": {"月亮": "语义：月亮不是工作人员记录的对象，句意不通。", "桌子": "语义：桌子不能由工作人员记录，句意不通。", "直接数据": "正确。直接数据是工作人员亲自记录的第一手数据，与句意相符。", "墨宝": "语域：墨宝是文雅的书面用语，与这样的现代记录语境不协调，且墨宝不是工作人员记录的。"}, "sentence_index": 6, "correct_answer": "直接数据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老人给孙子讲了一个直接数据。", "explanation": "这里应该用〈故事〉。直接数据是观测得来的数字资料，不能拿来讲给孙子听。"}, {"text": "这份直接数据很暖和，我每天穿在身上。", "explanation": "这里应该用〈毛衣〉。直接数据是数字资料，不能穿在身上，也谈不上暖和。"}, {"text": "这份直接数据有三斤重。", "explanation": "这里应该用〈鱼〉。直接数据是数字资料，没有重量，不能用“三斤重”来说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学生们在河边测了水温，得到了一只直接数据。", "corrected_sentence": "学生们在河边测了水温，得到了一批直接数据。", "error_description": "量词错误：“只”用于动物等，不能用来计量数据。“直接数据”应用量词“批”，正确说法是“得到了一批直接数据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员在工厂里亲自测量，得到了直接数据着。", "corrected_sentence": "工作人员在工厂里亲自测量，得到了直接数据。", "error_description": "体标错误：“着”表示动作的持续或状态，不能加在名词“直接数据”之后。正确说法是“得到了直接数据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
