INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90099, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "形象是一个人或东西看起来的样子。", "primary_collocate": null, "pronunciation": "xíng xiàng", "ipa": "ɕiŋ˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "面试的时候,要注意自己的形象。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿上西装,形象一下子变好了。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要给学生树立好形象。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的形象很好,大家都喜欢她。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司在顾客心里的形象很好。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把头发剪短了,形象完全不同了。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的形象能帮你找到好工作。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样大声说话,会影响你的形象。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市干净漂亮,在游客心中的形象很好。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想改变自己在大家心中的形象。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "形象设计", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或事物给别人的外表印象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e31bf265-f6b7-4c52-b5e9-a7a9c46a99af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形象", "is_correct": true, "explanation": "形象指人或事物给别人看到的样子，面试时要注意自己的形象。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是面试时需要注意的对象，句子不通。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，与面试时的注意事项无关，句子不通。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“形状”指物体的轮廓，不用来指人给别人的外在印象，与“自己的”搭配不当。"}], "explanations": {"形象": "形象指人或事物给别人看到的样子，面试时要注意自己的形象。", "厨房": "语义：厨房是做饭的地方，不是面试时需要注意的对象，句子不通。", "作业": "语义：作业是学习任务，与面试时的注意事项无关，句子不通。", "形状": "搭配：“形状”指物体的轮廓，不用来指人给别人的外在印象，与“自己的”搭配不当。"}, "sentence_index": 0, "correct_answer": "形象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "当前的形象很好，经济正在恢复。", "explanation": "这里应该用〈形势〉。“形势”指局面和发展情况，“形象”指人或事物的外在样子，不用于说经济局面。"}, {"text": "这份合同的形象很规范，条款都清楚。", "explanation": "这里应该用〈形式〉。“形式”指事物的格式、样式，合同的格式应说“形式”；“形象”指人或事物给人的外在样子，不用于说合同格式。"}, {"text": "他有一只好形象，同事们都很佩服他。", "explanation": "量词用错：“形象”应搭配〈个〉，“只”多用于动物或成对物件中的一个，不能计量“形象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形象", "is_correct": true, "explanation": "形象指人给别人的外在印象，好的形象有助于找到好工作。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能帮人找工作，“好的天气”与句子的意思不相合。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“好”不能修饰“感冒”，“好的感冒”不成词组。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址只是位置信息，不能帮人找到工作，句子不通。"}], "explanations": {"形象": "形象指人给别人的外在印象，好的形象有助于找到好工作。", "天气": "语义：天气不能帮人找工作，“好的天气”与句子的意思不相合。", "感冒": "搭配：“好”不能修饰“感冒”，“好的感冒”不成词组。", "地址": "语义：地址只是位置信息，不能帮人找到工作，句子不通。"}, "sentence_index": 6, "correct_answer": "形象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "眼下的形象很紧张，大家都很担心。", "explanation": "这里应该用〈形势〉。“形势”指局面和发展情况，“形象”指人或事物的外在样子，不用于说局面。"}, {"text": "他有一把好形象，同事们都很佩服他。", "explanation": "量词用错：“形象”应搭配〈个〉，“把”用于有柄的器具，不能计量“形象”。"}, {"text": "这家公司有一条好形象，客户都很信任。", "explanation": "量词用错：“形象”应搭配〈个〉，“条”多用于细长之物，不能计量“形象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有只好形象，大家都愿意和他合作。", "corrected_sentence": "他有个好形象，大家都愿意和他合作。", "error_description": "“形象”的量词应用“个”，“只”不能计量“形象”，应说“有个好形象”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想在同事中间建造一个好形象。", "corrected_sentence": "他想在同事中间树立一个好形象。", "error_description": "“形象”常与“树立”搭配，说“树立好形象”；“建造”用于房屋、桥梁等实物，不能和“形象”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
