INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文学艺术作品中塑造出的人物或事物形态。", "primary_collocate": null, "pronunciation": "xíng xiàng", "ipa": "ɕiŋ˧˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这本小说里的人物形象很生动。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的老师形象让我很感动。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在书里塑造了一个勇敢的女孩形象。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个雕像的形象是一位年轻的战士。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅壁画中的神仙形象栩栩如生。", "target_word": "形象", "complexity_tier": "T3", "furigana": "zhè fú bì huà zhōng de shén xiān xíng xiàng xǔ xǔ rú shēng", "sentence_source": "generated"}, {"text": "孙悟空是中国文学里最有名的形象之一。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张画里的母亲形象非常温暖。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电视剧中的形象和现实中不一样。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画片里的熊猫形象非常可爱。", "target_word": "形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位演员在剧中塑造的老人形象非常逼真。", "target_word": "形象", "complexity_tier": "T3", "furigana": "zhè wèi yǎn yuán zài jù zhōng sù zào de lǎo rén xíng xiàng fēi cháng bī zhēn", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "形象设计", "label": "复合"}], "register": "中性", "sense_fingerprint": "文学艺术作品中塑造的人物或事物形态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e31bf265-f6b7-4c52-b5e9-a7a9c46a99af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形象", "is_correct": true, "explanation": "形象指作品中塑造的人物形态，与“人物”搭配，“很生动”描述它正合适。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人物的特征，“人物天气很生动”不成立。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“生动”不能用来形容“价格”，与“人物”也不能组合。"}, {"text": "地址", "is_correct": false, "explanation": "语义：地址不是人物的特征，“人物地址很生动”说不通。"}], "explanations": {"形象": "形象指作品中塑造的人物形态，与“人物”搭配，“很生动”描述它正合适。", "天气": "语义：天气不是人物的特征，“人物天气很生动”不成立。", "价格": "搭配：“生动”不能用来形容“价格”，与“人物”也不能组合。", "地址": "语义：地址不是人物的特征，“人物地址很生动”说不通。"}, "sentence_index": 0, "correct_answer": "形象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "眼下的形象很复杂，各方都在观望。", "explanation": "这里应该用〈形势〉。“形势”指局面的发展情况，“形象”指人物或作品中塑造的形态，不能用来说局面。"}, {"text": "作者为这本书设计了一本生动的形象。", "explanation": "量词用错：“形象”应搭配〈个〉，“本”用于书籍，不能计量“形象”。"}, {"text": "这种教学的形象很新颖，学生很感兴趣。", "explanation": "这里应该用〈形式〉。“形式”指教学的方式、样式，“形象”指人物或作品中塑造的形态，不用于说教学方式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形象", "is_correct": true, "explanation": "形象指人物在作品中的形态，“非常温暖”形容它正合适。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不能是“非常温暖”的，“母亲作业”也不成立。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是出门带的物品，不能“非常温暖”，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“温暖”不能用来形容“体重”，两者搭配不当。"}], "explanations": {"形象": "形象指人物在作品中的形态，“非常温暖”形容它正合适。", "作业": "语义：作业不能是“非常温暖”的，“母亲作业”也不成立。", "行李": "语义：行李是出门带的物品，不能“非常温暖”，句子不通。", "体重": "搭配：“温暖”不能用来形容“体重”，两者搭配不当。"}, "sentence_index": 6, "correct_answer": "形象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位演员在剧中塑造了一条老人形象，看起来很逼真。", "explanation": "量词用错：“形象”应搭配〈个〉，“条”多用于细长之物，不能计量“形象”。"}, {"text": "作者在诗里写出了一朵动人的爱人形象。", "explanation": "量词用错：“形象”应搭配〈个〉，“朵”多用于花、云等，不能计量“形象”。"}, {"text": "当前的形象很严峻，各方都很担心。", "explanation": "这里应该用〈形势〉。“形势”指局面的发展情况，“形象”指人物或作品中塑造的形态，不能用来说局面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家画出了一部温柔的形象。", "corrected_sentence": "这位画家画出了一个温柔的形象。", "error_description": "“形象”指画中塑造的形态，量词应用“个”；“部”用于作品，不能计量“形象”，应说“一个温柔的形象”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作者笔下有一块感人的老人形象。", "corrected_sentence": "作者笔下有一个感人的老人形象。", "error_description": "“形象”的量词应用“个”，“块”多用于成块的东西，不能计量“形象”，应说“一个感人的老人形象”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
