INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90101, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盾是打仗时拿在手里，挡住刀和箭的东西。", "primary_collocate": null, "pronunciation": "dùn", "ipa": "tuən⁵¹", "syllable_count": 1, "sentences": [{"text": "战士左手拿着盾，右手拿着刀。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起盾，挡住了飞来的箭。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的士兵一手拿盾，一手拿剑。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那面盾很重，小孩拿不动。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的箭都打在他的盾上。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打仗时，他用盾保护自己。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一面很旧的盾。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盾放在地上，坐下来休息。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的人拿着盾，后面的人拿着弓。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里的战士有一把剑和一面盾。", "target_word": "盾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "打仗时手里拿的、挡刀箭的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc84aebc-8278-4ecb-bb1f-1683bde98033') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90101, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盾", "is_correct": true, "explanation": "盾（dùn）：打仗时拿在手里、挡住刀和箭的东西"}, {"text": "吨", "is_correct": false, "explanation": "吨（dūn，第一声）与盾（dùn，第四声）声调不同，意思是重量单位“吨”"}, {"text": "蹲", "is_correct": false, "explanation": "蹲（dūn，第一声）与盾（dùn，第四声）声调不同，意思是蹲下"}, {"text": "墩", "is_correct": false, "explanation": "墩（dūn，第一声）与盾（dùn，第四声）声调不同，意思是墩子、土墩"}], "explanations": {"盾": "盾（dùn）：打仗时拿在手里、挡住刀和箭的东西", "吨": "吨（dūn，第一声）与盾（dùn，第四声）声调不同，意思是重量单位“吨”", "蹲": "蹲（dūn，第一声）与盾（dùn，第四声）声调不同，意思是蹲下", "墩": "墩（dūn，第一声）与盾（dùn，第四声）声调不同，意思是墩子、土墩"}, "sentence_index": null, "correct_answer": "盾"}, "level_3": {"options": [{"text": "盾", "is_correct": true, "explanation": "盾：打仗时拿在手里挡刀箭的东西，此处是战士左手拿的武器"}, {"text": "梦想", "is_correct": false, "explanation": "语义：梦想是抽象的，看不见摸不着，不能拿在手里"}, {"text": "力气", "is_correct": false, "explanation": "搭配：“拿着”后要接具体的物件，不能拿“力气”"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见摸不着，不能被拿在手里"}], "explanations": {"盾": "盾：打仗时拿在手里挡刀箭的东西，此处是战士左手拿的武器", "梦想": "语义：梦想是抽象的，看不见摸不着，不能拿在手里", "力气": "搭配：“拿着”后要接具体的物件，不能拿“力气”", "声音": "语义：声音看不见摸不着，不能被拿在手里"}, "sentence_index": 0, "correct_answer": "盾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个士兵穿着盾上战场。", "explanation": "这里应该用〈护甲〉。盾是拿在手里挡刀箭的，不能“穿”；“穿”用于护甲这类穿在身上的装备"}, {"text": "他戴着盾冲上了战场。", "explanation": "这里应该用〈头盔〉。盾要拿在手里，不能“戴”；“戴”用于头盔、帽子这类东西"}, {"text": "那位将军穿着盾去打仗。", "explanation": "这里应该用〈盔甲〉。盾不能“穿”，“穿”用于盔甲这类穿在身上的防护装备"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90101, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盾", "is_correct": true, "explanation": "盾（dùn）：打仗时拿在手里、挡住刀和箭的东西"}, {"text": "盹", "is_correct": false, "explanation": "盹（dǔn，第三声）与盾（dùn，第四声）声调不同，意思是打盹"}, {"text": "敦", "is_correct": false, "explanation": "敦（dūn，第一声）与盾（dùn，第四声）声调不同，意思是敦厚、诚恳"}, {"text": "吨", "is_correct": false, "explanation": "吨（dūn，第一声）与盾（dùn，第四声）声调不同，意思是重量单位“吨”"}], "explanations": {"盾": "盾（dùn）：打仗时拿在手里、挡住刀和箭的东西", "盹": "盹（dǔn，第三声）与盾（dùn，第四声）声调不同，意思是打盹", "敦": "敦（dūn，第一声）与盾（dùn，第四声）声调不同，意思是敦厚、诚恳", "吨": "吨（dūn，第一声）与盾（dùn，第四声）声调不同，意思是重量单位“吨”"}, "sentence_index": null, "correct_answer": "盾"}, "level_3": {"options": [{"text": "盾", "is_correct": true, "explanation": "盾：此处指博物馆里一件很旧的盾，量词“面”搭配平面的盾"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌是唱出来的，不是能在博物馆里陈列的物件"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是博物馆里可以陈列的物品，“很旧的天空”说不通"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“一面”和“很旧的”都不修饰脾气，脾气不用量词“面”"}], "explanations": {"盾": "盾：此处指博物馆里一件很旧的盾，量词“面”搭配平面的盾", "歌": "语义：歌是唱出来的，不是能在博物馆里陈列的物件", "天空": "语义：天空不是博物馆里可以陈列的物品，“很旧的天空”说不通", "脾气": "搭配：“一面”和“很旧的”都不修饰脾气，脾气不用量词“面”"}, "sentence_index": 6, "correct_answer": "盾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个游戏里的战士有一把剑和一只盾。", "explanation": "这里应该用〈面〉。“只”用于动物或成对物中的一个，盾应用“面”"}, {"text": "这个游戏里的战士有一把剑和一条盾。", "explanation": "这里应该用〈面〉。“条”用于细长的东西，盾应用“面”"}, {"text": "这个游戏里的战士有一把剑和一头盾。", "explanation": "这里应该用〈面〉。“头”用于牲畜等大型动物，盾应用“面”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵扛着一只盾走进了营帐。", "corrected_sentence": "士兵扛着一面盾走进了营帐。", "error_description": "量词错误：盾应搭配量词“面”，说“一面盾”；“只”用于动物或成对物中的一个，不能用来数盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵把盾举，挡住了箭。", "corrected_sentence": "士兵把盾举起来，挡住了箭。", "error_description": "把字句不完整：“把”字句的动词后通常要带补语或其他成分，应说“把盾举起来”，不能只说“把盾举”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '008017d8-a348-454a-a183-6707c1c721d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
