INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90105, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接是用手承接飞来或落下的东西。", "primary_collocate": null, "pronunciation": "jiē", "ipa": "tɕjɛ˥", "syllable_count": 1, "sentences": [{"text": "妈妈把苹果扔过来，他张开双手去接。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在下面，举起双手去接从楼上扔下来的书。", "target_word": "接", "complexity_tier": "T3", "furigana": "tā zhàn zài xià miàn jǔ qǐ shuāng shǒu qù jiē cóng lóu shàng rēng xià lái de shū", "sentence_source": "generated"}, {"text": "球飞来了，快用手接！", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子从树上跳下来，爸爸赶紧张开手臂去接。", "target_word": "接", "complexity_tier": "T3", "furigana": "hái zi cóng shù shàng tiào xià lái bà ba gǎn jǐn zhāng kāi shǒu bì qù jiē", "sentence_source": "generated"}, {"text": "她把钥匙扔过来，我眼疾手快地去接。", "target_word": "接", "complexity_tier": "T3", "furigana": "tā bǎ yào shi rēng guò lái wǒ yǎn jí shǒu kuài de qù jiē", "sentence_source": "generated"}, {"text": "守门员扑过去，伸手去接对方踢来的球。", "target_word": "接", "complexity_tier": "T3", "furigana": "shǒu mén yuán pū guò qù shēn shǒu qù jiē duì fāng tī lái de qiú", "sentence_source": "generated"}, {"text": "雨滴落下来，他伸出手去接。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈从楼上扔下钥匙，我在楼下伸手去接。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥扔球，弟弟用两只手接。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球飞过来，他伸手去接，球却掉在了地上。", "target_word": "接", "complexity_tier": "T3", "furigana": "qiú fēi guò lái tā shēn shǒu qù jiē qiú què diào zài le dì shàng", "sentence_source": "generated"}], "morphological_forms": [{"form": "接了", "label": "体标"}, {"form": "接着", "label": "体标"}, {"form": "接过", "label": "体标"}, {"form": "接住", "label": "复合"}], "register": "通用", "sense_fingerprint": "用手接住飞来或落下的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e31bf265-f6b7-4c52-b5e9-a7a9c46a99af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90105, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "接", "is_correct": true, "explanation": "接（jiē）：用手承接飞来或落下的东西。"}, {"text": "借", "is_correct": false, "explanation": "“借”（jiè，第四声）与“接”（jiē，第一声）声调不同，意思是借出或借入。"}, {"text": "结", "is_correct": false, "explanation": "“结”（jié，第二声）与“接”声调不同，意思是打结或结束。"}, {"text": "切", "is_correct": false, "explanation": "“切”（qiē）与“接”（jiē）声母不同，意思是用刀切开。"}, {"text": "些", "is_correct": false, "explanation": "“些”（xiē）与“接”（jiē）声母不同，意思是一些。"}], "explanations": {"接": "接（jiē）：用手承接飞来或落下的东西。", "借": "“借”（jiè，第四声）与“接”（jiē，第一声）声调不同，意思是借出或借入。", "结": "“结”（jié，第二声）与“接”声调不同，意思是打结或结束。", "切": "“切”（qiē）与“接”（jiē）声母不同，意思是用刀切开。", "些": "“些”（xiē）与“接”（jiē）声母不同，意思是一些。"}, "sentence_index": null, "correct_answer": "接"}, "level_3": {"options": [{"text": "接", "is_correct": true, "explanation": "接表示用手承接飞来的东西，与“扔过来”“张开双手”相合。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”要用脚完成，不能用双手，与“双手张开”搭配不当。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是避开，与“双手张开”去接东西的意思相反。"}, {"text": "抛", "is_correct": false, "explanation": "语义：“抛”是把东西扔出去，苹果正飞过来，张开双手是为了接住，不是抛。"}], "explanations": {"接": "接表示用手承接飞来的东西，与“扔过来”“张开双手”相合。", "踢": "搭配：“踢”要用脚完成，不能用双手，与“双手张开”搭配不当。", "躲": "语义：“躲”是避开，与“双手张开”去接东西的意思相反。", "抛": "语义：“抛”是把东西扔出去，苹果正飞过来，张开双手是为了接住，不是抛。"}, "sentence_index": 0, "correct_answer": "接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把哭闹的孩子接在怀里，轻轻地哄。", "explanation": "这里应该用〈抱〉。“抱”指用双臂环住，“接”指用手承接飞来或落下的东西，不用于抱人。"}, {"text": "他把信接进了抽屉里。", "explanation": "这里应该用〈收〉。“收”指把东西收拾、放好，“接”指用手承接飞来或递来的东西，不用于放进抽屉。"}, {"text": "他弯腰接起了地上的钥匙。", "explanation": "这里应该用〈捡〉。“捡”指从地上拾起东西，“接”指用手承接飞来或落下的东西，不用于从地上拾取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90105, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "接", "is_correct": true, "explanation": "接（jiē）：用手承接飞来或落下的东西。"}, {"text": "姐", "is_correct": false, "explanation": "“姐”（jiě，第三声）与“接”声调不同，意思是姐姐。"}, {"text": "节", "is_correct": false, "explanation": "“节”（jié，第二声）与“接”声调不同，意思是节日。"}, {"text": "界", "is_correct": false, "explanation": "“界”（jiè，第四声）与“接”声调不同，意思是界限。"}], "explanations": {"接": "接（jiē）：用手承接飞来或落下的东西。", "姐": "“姐”（jiě，第三声）与“接”声调不同，意思是姐姐。", "节": "“节”（jié，第二声）与“接”声调不同，意思是节日。", "界": "“界”（jiè，第四声）与“接”声调不同，意思是界限。"}, "sentence_index": null, "correct_answer": "接"}, "level_3": {"options": [{"text": "接", "is_correct": true, "explanation": "接表示伸手承接落下的雨滴，与句意相合。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：手不能用来“咬”，“伸出手去咬”不成立。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”指从枝头取下，不用于落下的雨滴，句意不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与伸手承接东西的动作无关，句子不通。"}], "explanations": {"接": "接表示伸手承接落下的雨滴，与句意相合。", "咬": "搭配：手不能用来“咬”，“伸出手去咬”不成立。", "摘": "语义：“摘”指从枝头取下，不用于落下的雨滴，句意不符。", "唱": "语义：“唱”与伸手承接东西的动作无关，句子不通。"}, "sentence_index": 6, "correct_answer": "接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从柜台上接起一杯水，递给了我。", "explanation": "这里应该用〈拿〉。“拿”指用手把东西取到手中，从柜台取水不用“接”。"}, {"text": "他从柜子里接出了一件旧外套。", "explanation": "这里应该用〈取〉。“取”指从某处拿出东西，“接”指用手承接飞来或递来的东西，不用于从柜子里拿取。"}, {"text": "他把钥匙接回了口袋。", "explanation": "这里应该用〈放〉。“放”指把东西置于某处，“接”指用手承接，不用于把钥匙放回口袋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "球飞过来，他一下子住接了。", "corrected_sentence": "球飞过来，他一下子接住了。", "error_description": "结果补语“住”应放在动词“接”后面，说“接住了”，不能说“住接了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他伸出手，可是没接住了球。", "corrected_sentence": "他伸出手，可是没接住球。", "error_description": "用“没”否定“接住”时，后面不能再加“了”，应说“没接住球”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8d28479-b496-4c2c-b7a7-fde0e604f3e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90107, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "费心", "is_correct": true, "explanation": "反义：「费心」指耗费心思、操心，与「省心」意思相对。"}, {"text": "温暖", "is_correct": false, "explanation": "无关：「温暖」形容温度或感觉，与「省心」没有近义或反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：「安静」形容没有声音或喧闹，与「省心」没有近义或反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：「清楚」形容明白、不模糊，与「省心」没有近义或反义关系。"}], "correct_answer": "费心", "explanations": {"费心": "反义：「费心」指耗费心思、操心，与「省心」意思相对。", "温暖": "无关：「温暖」形容温度或感觉，与「省心」没有近义或反义关系。", "安静": "无关：「安静」形容没有声音或喧闹，与「省心」没有近义或反义关系。", "清楚": "无关：「清楚」形容明白、不模糊，与「省心」没有近义或反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
