INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90107, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "省心是说不用操心，事情很顺利。", "primary_collocate": null, "pronunciation": "shěng xīn", "ipa": "ʂɤŋ˨˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这次搬家公司全包了，一切都很省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情办得很顺利，大家都省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年一切顺利，我过得很省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西选大店，售后也省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子租给他，我真的很省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有朋友帮忙，这次旅行很省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "儿子考上了大学，我们终于省心了。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请了律师，官司的事就省心了。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上办手续，又快又省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事很稳，跟他合作很省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不省心", "label": "否定"}, {"form": "省心省力", "label": "复合"}], "register": "口语", "sense_fingerprint": "事情进展顺利，不需要自己操心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90107, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省心", "is_correct": true, "explanation": "省心 shěng xīn：不用操心，事情顺利，即本词的意思。"}, {"text": "身心", "is_correct": false, "explanation": "shēn（第一声）与 shěng（第三声）韵母与声调不同，身心指身体和心灵。"}, {"text": "伤心", "is_correct": false, "explanation": "shāng（第一声）与 shěng（第三声）元音不同（a 与 e），伤心指悲痛。"}, {"text": "省亲", "is_correct": false, "explanation": "shěng qīn 与 shěng xīn 只差声母（q 与 x），省亲指回家看望父母。"}], "explanations": {"省心": "省心 shěng xīn：不用操心，事情顺利，即本词的意思。", "身心": "shēn（第一声）与 shěng（第三声）韵母与声调不同，身心指身体和心灵。", "伤心": "shāng（第一声）与 shěng（第三声）元音不同（a 与 e），伤心指悲痛。", "省亲": "shěng qīn 与 shěng xīn 只差声母（q 与 x），省亲指回家看望父母。"}, "sentence_index": null, "correct_answer": "省心"}, "level_3": {"options": [{"text": "省心", "is_correct": true, "explanation": "正确：「一切都很省心」指事情不用操心，与「全包了」相合。"}, {"text": "费力", "is_correct": false, "explanation": "语义：「费力」与「全包了」意思相反，说事情很耗力。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：「吵闹」形容声音或环境，不用来形容「一切」。"}, {"text": "丑", "is_correct": false, "explanation": "体貌：「丑」形容外貌，不能用来说「一切都很丑」。"}], "explanations": {"省心": "正确：「一切都很省心」指事情不用操心，与「全包了」相合。", "费力": "语义：「费力」与「全包了」意思相反，说事情很耗力。", "吵闹": "搭配：「吵闹」形容声音或环境，不用来形容「一切」。", "丑": "体貌：「丑」形容外貌，不能用来说「一切都很丑」。"}, "sentence_index": 0, "correct_answer": "省心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人把这台钢琴搬上三楼，真省心。", "explanation": "这里应该用〈省力〉。省心说的是不用操心，搬运费力少要用省力。"}, {"text": "这套房子的租金很省心，每月只要两千元。", "explanation": "这里应该用〈便宜〉。省心不用来形容租金，说价格低要用便宜。"}, {"text": "这台冰箱一个月能省心不少电。", "explanation": "这里应该用〈省〉。省心是不用操心，不能带「电」作宾语；节约用电要说省电。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省心", "is_correct": true, "explanation": "正确：「终于省心了」指心里踏实、不用操心，与好消息相合。"}, {"text": "闹心", "is_correct": false, "explanation": "语义：「闹心」指烦恼，与「考上了大学」的好消息相反。"}, {"text": "难过", "is_correct": false, "explanation": "语义：「难过」指悲伤，与「考上了大学」的好消息相反。"}, {"text": "省力", "is_correct": false, "explanation": "搭配：「省力」说事情费力少，不用来说人的心情。"}], "explanations": {"省心": "正确：「终于省心了」指心里踏实、不用操心，与好消息相合。", "闹心": "语义：「闹心」指烦恼，与「考上了大学」的好消息相反。", "难过": "语义：「难过」指悲伤，与「考上了大学」的好消息相反。", "省力": "搭配：「省力」说事情费力少，不用来说人的心情。"}, "sentence_index": 6, "correct_answer": "省心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆摩托车每百公里能省心一升油。", "explanation": "这里应该用〈省〉。省心不能带「油」作宾语，说油耗少要用省油。"}, {"text": "这次装修省心了很多木料。", "explanation": "这里应该用〈省〉。省心不能带「木料」作宾语，节约材料要说省料。"}, {"text": "这个水龙头每次能省心半升水。", "explanation": "这里应该用〈省〉。省心不能带「水」作宾语，用水少要说省水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的服务很周到，买东西很省心极了。", "corrected_sentence": "这家店的服务很周到，买东西省心极了。", "error_description": "错误在程度表达：「省心极了」已表示程度很高，前面不能再加「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
