INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90108, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不用多费心思，没有烦恼。", "primary_collocate": null, "pronunciation": "shěng xīn", "ipa": "ʂɤŋ˨˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "这个孩子很听话，爸妈都很省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找个靠谱的人帮忙，你就省心多了。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就很省心，作业从来不用父母催。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把家交给保姆，我们真省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机很好用，用起来特别省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作认真，老板用他很省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用管，让他们自己做，多省心。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人身体好，儿女就省心了。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种洗衣机自己会洗，省心极了。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不省心，妈妈总是很累。", "target_word": "省心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不省心", "label": "否定"}, {"form": "省心省力", "label": "复合"}], "register": "口语", "sense_fingerprint": "人或事让人不必多费心思、没有烦恼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b0e4be8-25eb-4115-9c6a-5a16b534add7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90108, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省心", "is_correct": true, "explanation": "省心 shěng xīn：不用多费心思，没有烦恼，即本词的意思。"}, {"text": "身心", "is_correct": false, "explanation": "shēn（第一声）与 shěng（第三声）韵母与声调不同，身心指身体和心灵。"}, {"text": "伤心", "is_correct": false, "explanation": "shāng（第一声）与 shěng（第三声）元音不同（a 与 e），伤心指悲痛。"}, {"text": "省亲", "is_correct": false, "explanation": "shěng qīn 与 shěng xīn 只差声母（q 与 x），省亲指回家看望父母。"}], "explanations": {"省心": "省心 shěng xīn：不用多费心思，没有烦恼，即本词的意思。", "身心": "shēn（第一声）与 shěng（第三声）韵母与声调不同，身心指身体和心灵。", "伤心": "shāng（第一声）与 shěng（第三声）元音不同（a 与 e），伤心指悲痛。", "省亲": "shěng qīn 与 shěng xīn 只差声母（q 与 x），省亲指回家看望父母。"}, "sentence_index": null, "correct_answer": "省心"}, "level_3": {"options": [{"text": "省心", "is_correct": true, "explanation": "正确：「省心」指不用多费心思，与「很听话」「都很」相合。"}, {"text": "叛逆", "is_correct": false, "explanation": "语义：「叛逆」指不服管教，与「很听话」意思相反，且不用来形容父母。"}, {"text": "省力", "is_correct": false, "explanation": "搭配：「省力」说事情或工具费力少，不用来形容父母的心态。"}, {"text": "难看", "is_correct": false, "explanation": "体貌：「难看」形容外貌，不能说父母「都很难看」，与句意不合。"}], "explanations": {"省心": "正确：「省心」指不用多费心思，与「很听话」「都很」相合。", "叛逆": "语义：「叛逆」指不服管教，与「很听话」意思相反，且不用来形容父母。", "省力": "搭配：「省力」说事情或工具费力少，不用来形容父母的心态。", "难看": "体貌：「难看」形容外貌，不能说父母「都很难看」，与句意不合。"}, "sentence_index": 0, "correct_answer": "省心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人扛起两袋大米，真省心。", "explanation": "这里应该用〈省力〉。省心说的是不用操心，搬东西费力少要用省力。"}, {"text": "这件衣服的价格很省心。", "explanation": "这里应该用〈便宜〉。省心不用来形容价格，说价格低要用便宜。"}, {"text": "这个设计裁剪时能省心很多布。", "explanation": "这里应该用〈省〉。省心不能带「布」作宾语，节约材料要说省料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省心", "is_correct": true, "explanation": "正确：「多省心」指让人不用操心，与「你不用管」相合。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」形容场所没人气，与「让他们自己做」的语境不合。"}, {"text": "丑", "is_correct": false, "explanation": "体貌：「丑」形容外貌，不能说做事情「多丑」。"}, {"text": "松软", "is_correct": false, "explanation": "搭配：「松软」形容食物、床铺等，不用来说做事的感受。"}], "explanations": {"省心": "正确：「多省心」指让人不用操心，与「你不用管」相合。", "冷清": "语义：「冷清」形容场所没人气，与「让他们自己做」的语境不合。", "丑": "体貌：「丑」形容外貌，不能说做事情「多丑」。", "松软": "搭配：「松软」形容食物、床铺等，不用来说做事的感受。"}, "sentence_index": 6, "correct_answer": "省心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆小车每百公里能省心两升油。", "explanation": "这里应该用〈省〉。省心不能带「油」作宾语，说油耗少要用省油。"}, {"text": "这台空调一个月能省心不少电。", "explanation": "这里应该用〈省〉。省心不能带「电」作宾语，用电少要说省电。"}, {"text": "这种马桶每次冲水能省心三升水。", "explanation": "这里应该用〈省〉。省心不能带「水」作宾语，用水少要说省水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4dd8254-9d04-4477-a6ef-c26538d3ae10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
