INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90109, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "三面是海，一面连着大地的陆地。", "primary_collocate": null, "pronunciation": "bàn dǎo", "ipa": "pan˥˩ tau˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个半岛三面都是海。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半岛的一面连着大陆，三面是海水。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船去了那个小半岛。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从地图上看，这个半岛像一只靴子。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半岛上的天气很好，夏天不太热。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个半岛上有一个安静的小渔村。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半岛三面有海，所以鱼很多。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在海边的半岛上住了十年。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客坐车沿着半岛走了一圈。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个半岛只有一条路通向大陆。", "target_word": "半岛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "半岛国家", "label": "复合"}, {"form": "半島", "label": "繁体"}], "register": "中性", "sense_fingerprint": "三面临海、一面连着大陆的地理陆地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f596c5e-c3d7-46bf-a6c0-de9768bc6679') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90109, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "半岛", "is_correct": true, "explanation": "正确：半岛，三面临海、一面连着大陆的陆地。"}, {"text": "办到", "is_correct": false, "explanation": "dào（第四声）与 dǎo（第三声）声调不同，“办到”指做到某事，不是陆地。"}, {"text": "搬到", "is_correct": false, "explanation": "bān（第一声）、dào（第四声）与 bàn（第四声）、dǎo（第三声）声调都不同，“搬到”指把东西或人移到某处。"}, {"text": "半饱", "is_correct": false, "explanation": "bǎo 与 dǎo 声母不同（b 与 d），“半饱”指吃得差不多饱，不是陆地。"}], "explanations": {"半岛": "正确：半岛，三面临海、一面连着大陆的陆地。", "办到": "dào（第四声）与 dǎo（第三声）声调不同，“办到”指做到某事，不是陆地。", "搬到": "bān（第一声）、dào（第四声）与 bàn（第四声）、dǎo（第三声）声调都不同，“搬到”指把东西或人移到某处。", "半饱": "bǎo 与 dǎo 声母不同（b 与 d），“半饱”指吃得差不多饱，不是陆地。"}, "sentence_index": null, "correct_answer": "半岛"}, "level_3": {"options": [{"text": "半岛", "is_correct": true, "explanation": "正确：半岛，三面临海的陆地，句中的描述相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是内陆的水道，不会三面都是海。"}, {"text": "大陆", "is_correct": false, "explanation": "语义：大陆是连成一大片的陆地，不是三面临海、一面相连的地形。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“三面都是海”描述地形，不能用来描述教室。"}], "explanations": {"半岛": "正确：半岛，三面临海的陆地，句中的描述相符。", "河流": "语义：河流是内陆的水道，不会三面都是海。", "大陆": "语义：大陆是连成一大片的陆地，不是三面临海、一面相连的地形。", "教室": "搭配：“三面都是海”描述地形，不能用来描述教室。"}, "sentence_index": 0, "correct_answer": "半岛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个半岛在太平洋上，周围全是海。", "explanation": "这里应该用〈岛屿〉。岛屿四面环水；半岛一面与大陆相连，不会周围全是海。"}, {"text": "渔船停在半岛里。", "explanation": "这里应该用〈海湾〉。渔船停在水域里，半岛是陆地，不能说“停在半岛里”。"}, {"text": "这片半岛一望无际，连一滴水都看不到。", "explanation": "这里应该用〈沙漠〉。沙漠干旱少水；半岛三面临海，不可能看不到水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90109, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "半岛", "is_correct": true, "explanation": "正确：半岛，三面有海的陆地，与“鱼很多”相符。"}, {"text": "湖", "is_correct": false, "explanation": "语义：湖在内陆，不会三面有海。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠干燥，没有海，“三面有海”的说法不成立。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“三面有海”说的是地形，不能用来描述公园。"}], "explanations": {"半岛": "正确：半岛，三面有海的陆地，与“鱼很多”相符。", "湖": "语义：湖在内陆，不会三面有海。", "沙漠": "语义：沙漠干燥，没有海，“三面有海”的说法不成立。", "公园": "搭配：“三面有海”说的是地形，不能用来描述公园。"}, "sentence_index": 6, "correct_answer": "半岛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片半岛由几十个小岛组成。", "explanation": "这里应该用〈群岛〉。群岛由许多岛屿组成；半岛是一块与大陆相连的陆地。"}, {"text": "我们沿着半岛顺流而下，一直到大海。", "explanation": "这里应该用〈河流〉。河流有水流，能够顺流而下；半岛是陆地，不能顺流。"}, {"text": "我们坐船穿过半岛，去对岸的城市。", "explanation": "这里应该用〈海峡〉。海峡是水道，船可以穿过；半岛是陆地，不能坐船穿过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90109, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵半岛的北面连着大陆。", "corrected_sentence": "这个半岛的北面连着大陆。", "error_description": "量词错误：“半岛”是陆地地形，量词用“个”，不能用“棵”（“棵”用于树木）。正确说法是“这个半岛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90109, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只半岛上有很多游客。", "corrected_sentence": "那个半岛上有很多游客。", "error_description": "量词错误：“半岛”是地形，量词用“个”，不用“只”（“只”多用于动物）。正确说法是“那个半岛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
