INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90111, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收到是别人给的东西,你拿到了。", "primary_collocate": null, "pronunciation": "shōu dào", "ipa": "ʂoʊ˥˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "过生日那天，她收到一束花。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子收到新玩具，高兴极了。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没有收到过这么大的礼物。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收到红包后说了谢谢。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶收到孙子送的茶，笑了。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我收到了三张请帖。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你收到的第一份礼物是什么？", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师收到学生写的卡片，很感动。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明收到爸爸买的新书包。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她收到了朋友送的苹果。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收到了", "label": "体标"}, {"form": "收到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "收到：拿到别人送给自己的礼物或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62640798-92c2-46f8-9980-a0d08bce8395') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90111, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收到", "is_correct": true, "explanation": "收到：拿到别人送给自己的礼物或东西，是本义。"}, {"text": "受到", "is_correct": false, "explanation": "shòu（第四声）与 shōu（第一声）声调不同，意思是遭受、承受，不是拿到礼物。"}, {"text": "搜到", "is_correct": false, "explanation": "sōu 与 shōu 声母不同（s 与 sh），意思是通过查找而找到。"}, {"text": "守到", "is_correct": false, "explanation": "shǒu（第三声）与 shōu（第一声）声调不同，意思是守候到某个时候。"}], "explanations": {"收到": "收到：拿到别人送给自己的礼物或东西，是本义。", "受到": "shòu（第四声）与 shōu（第一声）声调不同，意思是遭受、承受，不是拿到礼物。", "搜到": "sōu 与 shōu 声母不同（s 与 sh），意思是通过查找而找到。", "守到": "shǒu（第三声）与 shōu（第一声）声调不同，意思是守候到某个时候。"}, "sentence_index": null, "correct_answer": "收到"}, "level_3": {"options": [{"text": "收到", "is_correct": true, "explanation": "收到：过生日时拿到别人送的花，符合句子的语境。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示厌恶，不表示拿到礼物。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”是毁坏的动作，与接受礼物的语境相反。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”多接申请、计划，不接“花”这类礼物。"}], "explanations": {"收到": "收到：过生日时拿到别人送的花，符合句子的语境。", "嫌弃": "语义：“嫌弃”表示厌恶，不表示拿到礼物。", "撕碎": "语义：“撕碎”是毁坏的动作，与接受礼物的语境相反。", "批准": "搭配：“批准”多接申请、计划，不接“花”这类礼物。"}, "sentence_index": 0, "correct_answer": "收到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为投资失误，收到了很大的损失。", "explanation": "这里应该用〈遭受〉。收到用于接到东西或消息，损失、伤害这类遭遇要用遭受。"}, {"text": "这个计划收到了很大的成功。", "explanation": "这里应该用〈取得〉。收到用于接到东西或消息，成功这类结果要用取得。"}, {"text": "她收到了比赛的冠军。", "explanation": "这里应该用〈赢得〉。收到用于接到东西，比赛的名次、冠军要用赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收到", "is_correct": true, "explanation": "收到：接受别人送给你的礼物，符合“第一份礼物”的语境。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”后面要带接收人和物品，这里“送给”之后缺少接收人，结构不完整。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清理场所，不能接“礼物”。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，不能带“礼物”。"}], "explanations": {"收到": "收到：接受别人送给你的礼物，符合“第一份礼物”的语境。", "送给": "配价：“送给”后面要带接收人和物品，这里“送给”之后缺少接收人，结构不完整。", "打扫": "语义：“打扫”是清理场所，不能接“礼物”。", "毕业": "配价：“毕业”是不及物动词，不能带“礼物”。"}, "sentence_index": 6, "correct_answer": "收到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我收到了这次会议。", "explanation": "这里应该用〈参加〉。收到用于接到东西或消息，会议要用参加。"}, {"text": "她收到了一个朋友。", "explanation": "这里应该用〈结交〉。收到用于接到东西或消息，结识人要用结交。"}, {"text": "她收到了大家的欢迎。", "explanation": "这里应该用〈受到〉。收到用于接到具体的东西，欢迎、表扬这类对待要用受到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74a9564e-4e20-4548-ab93-dcfcfc25bdb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
