INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90115, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "这样做就行了。", "primary_collocate": null, "pronunciation": "jí kě", "ipa": "tɕi˧˥ kʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "水开了以后，放入面条即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填好表格，交给老师即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把菜洗干净，切成小块即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您只需致电告知即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "茶叶用热水泡三分钟即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上八点到公司即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门票不贵，在网上买即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服脏了，用水洗一下即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用来，发邮件告诉我即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开应用程序，在菜单中选择该项即可。", "target_word": "即可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在动作之后，表示这样做就行了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f596c5e-c3d7-46bf-a6c0-de9768bc6679') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90115, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即可", "is_correct": true, "explanation": "即可：表示这样做就行了，是本题的目标词。"}, {"text": "饥渴", "is_correct": false, "explanation": "声调：“饥”是第一声 jī，与“即”（第二声 jí）声调不同，意思是饥饿口渴，与“这样做就行了”无关。"}, {"text": "即刻", "is_correct": false, "explanation": "声调：“刻”是第四声 kè，与“可”（第三声 kě）声调不同，意思是立刻，与本义无关。"}, {"text": "极客", "is_correct": false, "explanation": "声调：“客”是第四声 kè，与“可”（第三声 kě）声调不同，意思是指痴迷技术的人，与本义无关。"}], "explanations": {"即可": "即可：表示这样做就行了，是本题的目标词。", "饥渴": "声调：“饥”是第一声 jī，与“即”（第二声 jí）声调不同，意思是饥饿口渴，与“这样做就行了”无关。", "即刻": "声调：“刻”是第四声 kè，与“可”（第三声 kě）声调不同，意思是立刻，与本义无关。", "极客": "声调：“客”是第四声 kè，与“可”（第三声 kě）声调不同，意思是指痴迷技术的人，与本义无关。"}, "sentence_index": null, "correct_answer": "即可"}, "level_3": {"options": [{"text": "即可", "is_correct": true, "explanation": "即可：表示放入面条这一步做完就够了，与句意相符。"}, {"text": "才", "is_correct": false, "explanation": "语义：“才”表示条件满足后才如何，需要后续结果，句末单用不成立。"}, {"text": "再", "is_correct": false, "explanation": "配价：“再”要求后面接动作或结果，“放入面条再”不能收尾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即发生，不表示“这样做就够了”，且不能止于此处。"}], "explanations": {"即可": "即可：表示放入面条这一步做完就够了，与句意相符。", "才": "语义：“才”表示条件满足后才如何，需要后续结果，句末单用不成立。", "再": "配价：“再”要求后面接动作或结果，“放入面条再”不能收尾。", "马上": "语义：“马上”表示立即发生，不表示“这样做就够了”，且不能止于此处。"}, "sentence_index": 0, "correct_answer": "即可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的爸爸即可是老师。", "explanation": "这里应该用〈即是〉。即可表示“这样做就够了”，不能充当判断动词；表示“就是”要用〈即是〉。"}, {"text": "即可下雨，我们也要去爬山。", "explanation": "这里应该用〈即使〉。即可表示“这样就够了”，不表示让步，不能引出“下雨也要去”这类让步语气。"}, {"text": "这里即可是我的家。", "explanation": "这里应该用〈即是〉。即可表示“这样做就够了”，不能充当判断动词；此处表示判断，要用〈即是〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即可", "is_correct": true, "explanation": "即可：表示在网上买这一步做了就够了，与句意相符。"}, {"text": "都", "is_correct": false, "explanation": "配价：“都”需要前面有全部或复数成分，此处没有，句末单用不成立。"}, {"text": "也", "is_correct": false, "explanation": "配价：“也”需要与前文同类情况相呼应，此处没有可呼应的成分，句末单用不成立。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示重复或累加，与“门票不贵”的说明不合，句末单用不成立。"}], "explanations": {"即可": "即可：表示在网上买这一步做了就够了，与句意相符。", "都": "配价：“都”需要前面有全部或复数成分，此处没有，句末单用不成立。", "也": "配价：“也”需要与前文同类情况相呼应，此处没有可呼应的成分，句末单用不成立。", "又": "语义：“又”表示重复或累加，与“门票不贵”的说明不合，句末单用不成立。"}, "sentence_index": 6, "correct_answer": "即可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事即可有误，请再核对一遍。", "explanation": "这里应该用〈可能〉。即可表示“这样就够了”，没有推测“也许”的意思，不能用来说事情可能有误。"}, {"text": "这本书即可贵，我买不起。", "explanation": "这里应该用〈太〉。即可表示“这样做就够了”，不能表示程度，不能修饰形容词“贵”。"}, {"text": "即可失败，我也不后悔。", "explanation": "这里应该用〈即便〉。即可表示“这样就够了”，不表示让步，不能引出“失败也不后悔”的让步语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末你给我发条信息即可了。", "corrected_sentence": "周末你给我发条信息即可。", "error_description": "“即可”是副词，表示“这样做就够了”，句末不能再加“了”。正确的说法是“周末你给我发条信息即可。”，错误之处在于“即可”后多加了“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "进门以后，直接刷卡不即可。", "corrected_sentence": "进门以后，直接刷卡即可。", "error_description": "否定错误：“即可”表示“这样做就够了”，本身是肯定的，前面不能加“不”。正确的说法是“直接刷卡即可”，错误之处在于“即可”前多加了“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90117, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明天", "is_correct": true, "explanation": "明天是今天的后一天，与“昨天”（今天的前一天）构成反义。"}, {"text": "下午", "is_correct": false, "explanation": "下午指一天中的时段，与“昨天”不是反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "清晨指一天中的时段，与“昨天”不构成反义。"}, {"text": "周六", "is_correct": false, "explanation": "周六指一周中的一天，与“昨天”不构成对立。"}], "correct_answer": "明天", "explanations": {"明天": "明天是今天的后一天，与“昨天”（今天的前一天）构成反义。", "下午": "下午指一天中的时段，与“昨天”不是反义关系。", "清晨": "清晨指一天中的时段，与“昨天”不构成反义。", "周六": "周六指一周中的一天，与“昨天”不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90117, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明天", "is_correct": true, "explanation": "明天是今天的后一天，与“昨天”（今天的前一天）构成反义。"}, {"text": "傍晚", "is_correct": false, "explanation": "傍晚指一天中的时段，与“昨天”不是反义关系。"}, {"text": "周日", "is_correct": false, "explanation": "周日指一周中的一天，与“昨天”不构成反义。"}, {"text": "凌晨", "is_correct": false, "explanation": "凌晨指一天中的时段，与“昨天”不构成对立。"}], "correct_answer": "明天", "explanations": {"明天": "明天是今天的后一天，与“昨天”（今天的前一天）构成反义。", "傍晚": "傍晚指一天中的时段，与“昨天”不是反义关系。", "周日": "周日指一周中的一天，与“昨天”不构成反义。", "凌晨": "凌晨指一天中的时段，与“昨天”不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90117, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "昨天是今天的前一天。", "primary_collocate": null, "pronunciation": "zuó tiān", "ipa": "tsuɔ˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "今天是五号，昨天是四号。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我们一起吃了饭。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天打电话给我了。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的天气比今天好。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天老师教了十个新词。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天几点回家的？", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天爸爸在家休息。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天跑了五公里。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的会开了两个小时。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天她穿着一件红衣服。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "昨天晚上", "label": "复合"}, {"form": "昨天早上", "label": "复合"}], "register": "中性", "sense_fingerprint": "今天的前一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨天", "is_correct": true, "explanation": "昨天是今天的前一天，五号的前一天是四号，正好填入空格。"}, {"text": "明天", "is_correct": false, "explanation": "语义：明天是今天的后一天，今天五号时明天应是六号，不是四号。"}, {"text": "前天", "is_correct": false, "explanation": "语义：前天是今天的前两天，今天五号时前天应是三号，不是四号。"}, {"text": "下午", "is_correct": false, "explanation": "搭配：“下午”指一天中的时段，不能用来说“是四号”这样的日期。"}], "explanations": {"昨天": "昨天是今天的前一天，五号的前一天是四号，正好填入空格。", "明天": "语义：明天是今天的后一天，今天五号时明天应是六号，不是四号。", "前天": "语义：前天是今天的前两天，今天五号时前天应是三号，不是四号。", "下午": "搭配：“下午”指一天中的时段，不能用来说“是四号”这样的日期。"}, "sentence_index": 0, "correct_answer": "昨天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你昨天给我打个电话。", "explanation": "这里应该用〈明天〉。请别人做事要用将来的时间；“昨天”指已经过去的一天，不能用来提出要求。"}, {"text": "我昨天常常去公园跑步。", "explanation": "这里应该用〈以前〉。“常常”表示一段时间里反复发生，“昨天”只指一天，不能和“常常”一起用；说过去经常做的事要用以前。"}, {"text": "昨天下了整整一个星期的雨。", "explanation": "这里应该用〈前几天〉。“昨天”只指一天，不能表示整整一个星期的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨天", "is_correct": true, "explanation": "“昨天”指今天的前一天，与“爸爸在家休息”的过去时间相符，正好填入空格。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“教室”是学习的场所，不能放在这里说明“爸爸在家休息”的时间。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不是时间，放在这里意思不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”指建筑上的开口，与“爸爸在家休息”的时间没有关系。"}], "explanations": {"昨天": "“昨天”指今天的前一天，与“爸爸在家休息”的过去时间相符，正好填入空格。", "教室": "搭配：“教室”是学习的场所，不能放在这里说明“爸爸在家休息”的时间。", "桌子": "语义：“桌子”是家具，不是时间，放在这里意思不通。", "窗户": "语义：“窗户”指建筑上的开口，与“爸爸在家休息”的时间没有关系。"}, "sentence_index": 6, "correct_answer": "昨天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天是我的好朋友，他很爱笑。", "explanation": "这里应该用〈他〉。“昨天”是时间，不能指人。"}, {"text": "我们一起吃了昨天，味道很好。", "explanation": "这里应该用〈饭〉。“吃”的对象应是食物，“昨天”是时间，不能吃。"}, {"text": "我买了一本昨天。", "explanation": "这里应该用〈书〉之类的具体物品名词。“昨天”是时间，却被当作可以买的东西来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天的去了医院。", "corrected_sentence": "我昨天去了医院。", "error_description": "多加了“的”：时间词“昨天”后面不能直接加“的”接动词，“的”会把“昨天”变成修饰语，动词“去”前应直接说“昨天去了”。应说“我昨天去了医院”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在昨天吃了三个苹果。", "corrected_sentence": "他昨天吃了三个苹果。", "error_description": "多加了“在”：时间词“昨天”前面不用“在”。应说“他昨天吃了三个苹果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90118, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明天", "is_correct": true, "explanation": "明天是今天的后一天，与“昨天”（今天的前一天）构成反义。"}, {"text": "早上", "is_correct": false, "explanation": "早上指一天中的一个时段，与“昨天”不是反义关系。"}, {"text": "周末", "is_correct": false, "explanation": "周末指一周中的两天，与“昨天”不构成反义。"}, {"text": "夜晚", "is_correct": false, "explanation": "夜晚指一天中的时段，与“昨天”不构成对立。"}], "correct_answer": "明天", "explanations": {"明天": "明天是今天的后一天，与“昨天”（今天的前一天）构成反义。", "早上": "早上指一天中的一个时段，与“昨天”不是反义关系。", "周末": "周末指一周中的两天，与“昨天”不构成反义。", "夜晚": "夜晚指一天中的时段，与“昨天”不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
