INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今天的前一天。", "primary_collocate": null, "pronunciation": "zuó tiān", "ipa": "tsuɔ˧˥ tʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "昨天我和朋友去看电影了。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天是星期六，不用上班。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下了一天雨。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上我睡得很早。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天买的书今天就到了。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的作业你做完了吗？", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天妈妈给我做了鱼。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天没来学校，因为生病了。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天很冷，今天暖和多了。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我在公园里遇到了老同学。", "target_word": "昨天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "昨天晚上", "label": "复合"}, {"form": "昨天下午", "label": "复合"}], "register": "中性", "sense_fingerprint": "今天的前一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '133a0cf0-cdf6-4e93-b59b-2c72829dec62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨天", "is_correct": true, "explanation": "“昨天”指今天的前一天，与“去看电影了”已发生的事相符，正好填入空格。"}, {"text": "明天", "is_correct": false, "explanation": "体貌：“了”表示动作已经完成，与尚未到来的“明天”不搭配。"}, {"text": "下个月", "is_correct": false, "explanation": "体貌：“去看电影了”是已完成的事，不能与“下个月”这种未来时间搭配。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指尚未发生的时间，与句中已经完成的“去看电影了”矛盾。"}], "explanations": {"昨天": "“昨天”指今天的前一天，与“去看电影了”已发生的事相符，正好填入空格。", "明天": "体貌：“了”表示动作已经完成，与尚未到来的“明天”不搭配。", "下个月": "体貌：“去看电影了”是已完成的事，不能与“下个月”这种未来时间搭配。", "将来": "语义：“将来”指尚未发生的时间，与句中已经完成的“去看电影了”矛盾。"}, "sentence_index": 0, "correct_answer": "昨天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你昨天把钥匙还给我。", "explanation": "这里应该用〈明天〉。请别人做事要用将来的时间；“昨天”指已经过去的一天，不能用来提出要求。"}, {"text": "我们昨天马上去机场。", "explanation": "这里应该用〈明天〉。“马上”表示即将发生，要用将来的时间；“昨天”指已经过去的一天，不能与“马上”搭配。"}, {"text": "昨天下了三天雨，路上全是水。", "explanation": "这里应该用〈前几天〉。“昨天”只指今天的前一天这一天，不能表示连续好几天的雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昨天", "is_correct": true, "explanation": "“昨天”指今天的前一天，与“做了鱼”已发生的事相符，正好填入空格。"}, {"text": "后天", "is_correct": false, "explanation": "体貌：“做了”表示已完成，与尚未到来的“后天”矛盾。"}, {"text": "下周", "is_correct": false, "explanation": "语义：“下周”是未来的一段时间，句子叙述的是已经做了鱼，时间自相矛盾。"}, {"text": "明年", "is_correct": false, "explanation": "体貌：“做了”的动作已完成，不能与将来的“明年”搭配。"}], "explanations": {"昨天": "“昨天”指今天的前一天，与“做了鱼”已发生的事相符，正好填入空格。", "后天": "体貌：“做了”表示已完成，与尚未到来的“后天”矛盾。", "下周": "语义：“下周”是未来的一段时间，句子叙述的是已经做了鱼，时间自相矛盾。", "明年": "体貌：“做了”的动作已完成，不能与将来的“明年”搭配。"}, "sentence_index": 6, "correct_answer": "昨天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天是我最好的朋友。", "explanation": "“昨天”是时间，不能指人。这里说的是朋友，应该用人名或人称。"}, {"text": "周末我们一起去昨天玩。", "explanation": "“去”后面要接地点，“昨天”是时间，不能当作目的地。"}, {"text": "妈妈给我买了一件昨天。", "explanation": "这里应该用〈礼物〉之类的具体物品名词。“昨天”是时间，却被当作买的东西来用，这样说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在昨天去了书店，买了两本书。", "corrected_sentence": "我昨天去了书店，买了两本书。", "error_description": "多加了“在”：时间词“昨天”前面不用“在”。应说“我昨天去了书店”，不说“我在昨天去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天的买了一条新裙子。", "corrected_sentence": "我昨天买了一条新裙子。", "error_description": "多加了“的”：时间词“昨天”后面不能直接加“的”接动词，“的”会把“昨天”变成修饰语，动词“买”前应直接说“昨天买了”。应说“我昨天买了一条新裙子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b7c349d-c446-4fdf-88f3-0f981d7ee991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
