INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90119, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空白是纸上或地方里还没有写、没有放东西的部分。", "primary_collocate": null, "pronunciation": "kòng bái", "ipa": "kʰʊŋ˥˩ paɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这页纸上有一大片空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把名字写在表格的空白上。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上还有一块空白，我想挂一张画。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸上的空白很大，可以画画。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡片的右下角还留着一片空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在书的空白上写了几句话。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片旁边留着一点空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸太满了，没有空白了。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用彩笔把空白涂满了颜色。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸的下面还有一点空白，可以写名字。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "纸上或地方里没有写、没有放东西的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空白", "is_correct": true, "explanation": "“空白”指纸面上还没有写字画的部分，能和“一大片”搭配，符合这里的语境。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：纸面上铺不开一大片海洋，这里说的是纸上没写字的部分。"}, {"text": "树林", "is_correct": false, "explanation": "语义：纸面是平的，不可能有一大片树林，句子描述的是纸上的留白。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：纸面上不会有一大片云朵，句子说的是纸上没写字画的部分。"}], "explanations": {"空白": "“空白”指纸面上还没有写字画的部分，能和“一大片”搭配，符合这里的语境。", "海洋": "语义：纸面上铺不开一大片海洋，这里说的是纸上没写字的部分。", "树林": "语义：纸面是平的，不可能有一大片树林，句子描述的是纸上的留白。", "云朵": "语义：纸面上不会有一大片云朵，句子说的是纸上没写字画的部分。"}, "sentence_index": 0, "correct_answer": "空白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把空白放进书包里，带去学校。", "explanation": "这里应该用〈本子〉。空白是纸上没写东西的部分，不能单独放进书包。"}, {"text": "空白在天上飞来飞去。", "explanation": "这里应该用〈小鸟〉。空白是纸上或地方里没有东西的部分，不会飞。"}, {"text": "这块空白很好吃，是妈妈做的。", "explanation": "这里应该用〈蛋糕〉。空白不是食物，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空白", "is_correct": true, "explanation": "“空白”指照片旁边没有东西的地方，与“留着一点”搭配，符合语境。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电一闪即逝，留不住，不能留在照片旁边。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋体积庞大，照片旁边不可能留着一点海洋。"}, {"text": "山脉", "is_correct": false, "explanation": "语义：山脉体积庞大，照片旁边不可能留着一点山脉。"}], "explanations": {"空白": "“空白”指照片旁边没有东西的地方，与“留着一点”搭配，符合语境。", "闪电": "语义：闪电一闪即逝，留不住，不能留在照片旁边。", "海洋": "语义：海洋体积庞大，照片旁边不可能留着一点海洋。", "山脉": "语义：山脉体积庞大，照片旁边不可能留着一点山脉。"}, "sentence_index": 6, "correct_answer": "空白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛还有一个空白，还能报名。", "explanation": "这里应该用〈空缺〉。空缺指名额、职位等空着、待补的位置，“空白”指纸面或地方上没有写画或放东西的部分，不用来指比赛的名额。"}, {"text": "这根木棍是空白的，一敲就碎。", "explanation": "这里应该用〈空心〉。空心指中间是空的，“空白”指纸面或地方上没有东西的部分，不用来形容木棍中间是空的。"}, {"text": "这块空白很甜，我吃了两口。", "explanation": "这里应该用〈糖〉。空白是纸上或地方里没有东西的部分，不能吃，也谈不上甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌子角上还留着一小只空白。", "corrected_sentence": "桌子角上还留着一小块空白。", "error_description": "错误：“一小只空白”。正确：“一小块空白”。“空白”指纸面上没有写画的部分，量词用“块”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子把墙角的空白涂了满。", "corrected_sentence": "孩子把墙角的空白涂满了。", "error_description": "错误：“涂了满”。正确：“涂满了”。结果补语“满”要紧跟动词，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
