INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指某一领域中尚未涉及或尚未研究的部分。", "primary_collocate": null, "pronunciation": "kòng bái", "ipa": "kʰʊŋ˥˩ paɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这个领域还有很多空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的历史知识有一大片空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项研究填补了国内的空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个问题上，学界的研究还是一片空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市在这方面还是空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套教材对近代史的讲解还有不少空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司想填补市场的空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书填补了儿童文学的一个空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于这种病，医学上还有空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们对海底世界的了解还有很多空白。", "target_word": "空白", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "尚未涉及或研究的领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fcba9692-cced-4943-a1b3-313ddd5c52a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空白", "is_correct": true, "explanation": "“空白”指尚未涉及的领域，与“还有很多”搭配，符合这里的语境。"}, {"text": "食物", "is_correct": false, "explanation": "语义：领域是抽象的范围，不会还剩很多食物。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：领域里说不上还有很多颜色，句子说的是尚未涉及的部分。"}, {"text": "鲜花", "is_correct": false, "explanation": "语义：领域是抽象的范围，不会还剩很多鲜花。"}], "explanations": {"空白": "“空白”指尚未涉及的领域，与“还有很多”搭配，符合这里的语境。", "食物": "语义：领域是抽象的范围，不会还剩很多食物。", "颜色": "语义：领域里说不上还有很多颜色，句子说的是尚未涉及的部分。", "鲜花": "语义：领域是抽象的范围，不会还剩很多鲜花。"}, "sentence_index": 0, "correct_answer": "空白"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个职位还有一个空白，等着招人。", "explanation": "这里应该用〈空缺〉。空缺指职位等还没有人的位置；“空白”指某一领域尚未涉及的部分，不指职位。"}, {"text": "车厢里还有一个空白。", "explanation": "这里应该用〈空位〉。空位指座位空着，空白不指座位。"}, {"text": "他的空白每月都按时发。", "explanation": "这里应该用〈工资〉。工资是按月发给人的报酬，“空白”不指钱，不能说按时发空白。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空白", "is_correct": true, "explanation": "“空白”指市场上尚未被占据的领域，与“填补”搭配，符合语境。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“填补”的对象是空缺或领域，脚步不能被填补。"}, {"text": "体温", "is_correct": false, "explanation": "语义：市场上不存在可以填补的体温，这个词与商业语境不相关。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：“填补”的对象是空缺或领域，海浪不能被填补，句意不通。"}], "explanations": {"空白": "“空白”指市场上尚未被占据的领域，与“填补”搭配，符合语境。", "脚步": "语义：“填补”的对象是空缺或领域，脚步不能被填补。", "体温": "语义：市场上不存在可以填补的体温，这个词与商业语境不相关。", "海浪": "语义：“填补”的对象是空缺或领域，海浪不能被填补，句意不通。"}, "sentence_index": 6, "correct_answer": "空白"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个账户还有很多空白，可以随时取钱。", "explanation": "这里应该用〈余额〉。余额指账户里剩下的钱数，“空白”不指钱数。"}, {"text": "这笔空白每个月都要按时交。", "explanation": "这里应该用〈房租〉。房租是每月要交的钱，“空白”不指钱，不能说按时交空白。"}, {"text": "他的空白一天比一天多，可以买房了。", "explanation": "这里应该用〈存款〉。存款是存在银行里的钱，“空白”不指钱，不能说空白一天比一天多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学界对这个问题的研究还有一大只空白。", "corrected_sentence": "学界对这个问题的研究还有一大片空白。", "error_description": "错误：“一大只空白”。正确：“一大片空白”。指尚未涉及的领域时，“空白”的量词用“片”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项研究填补了国内的一只空白。", "corrected_sentence": "这项研究填补了国内的一项空白。", "error_description": "错误：“一只空白”。正确：“一项空白”。“只”用于动物等；指尚未研究的领域时，“空白”常用量词“项”或“片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4f3a545-acd4-4e5b-a4c7-b3b26174d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
