INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90122, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家的政权、主权、领土等不受侵害的状态。", "primary_collocate": null, "pronunciation": "guó jiā ān quán", "ipa": "ku̯o˧˥ tɕja˥ an˥ tɕʰɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "这个事件影响了国家安全。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家安全的底线是领土完整。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络安全也是国家安全的一部分。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家安全得到了保障。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条消息会威胁国家安全。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家安全是国家发展的基础。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争会破坏国家安全。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国都很重视国家安全。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，当前国家安全形势总体稳定。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家安全受到威胁时，政府会行动。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國家安全", "label": "繁体"}], "register": "正式", "sense_fingerprint": "国家政权、主权、领土不受侵害的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '624b5296-b316-469e-b898-2490f7fe2795') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家安全", "is_correct": true, "explanation": "正确。「影响了」的宾语是「国家安全」，指国家政权、领土不受侵害的状态，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：「影响」的对象通常是事情或状况，不能说「影响桌子」。"}, {"text": "石头", "is_correct": false, "explanation": "语义：「影响」用于情况或事情，石头这类具体物体不符合句意。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：「影响」不与具体家具搭配，「窗帘」不能作为宾语。"}], "explanations": {"国家安全": "正确。「影响了」的宾语是「国家安全」，指国家政权、领土不受侵害的状态，符合句意。", "桌子": "搭配：「影响」的对象通常是事情或状况，不能说「影响桌子」。", "石头": "语义：「影响」用于情况或事情，石头这类具体物体不符合句意。", "窗帘": "搭配：「影响」不与具体家具搭配，「窗帘」不能作为宾语。"}, "sentence_index": 0, "correct_answer": "国家安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工地的国家安全得到了保障，工人很放心。", "explanation": "这里应该用〈工地安全〉。「国家安全」指国家的政权、主权状态，工地的安全状况要用〈工地安全〉。"}, {"text": "大门口的国家安全很负责，每个人进出都要登记。", "explanation": "这里应该用〈保安〉。「国家安全」指国家层面，门口值守的人员要用〈保安〉。"}, {"text": "我的国家安全得到了保障，我很放心。", "explanation": "这里应该用〈人身安全〉。「国家安全」指国家层面，说个人的安全状况要用〈人身安全〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家安全", "is_correct": true, "explanation": "正确。「破坏」的对象是「国家安全」这种抽象的状态，符合句意。"}, {"text": "星期", "is_correct": false, "explanation": "语义：「星期」是时间单位，不是可以被破坏的对象。"}, {"text": "眼神", "is_correct": false, "explanation": "搭配：「破坏」不与「眼神」搭配，人们不说「破坏眼神」。"}, {"text": "月份", "is_correct": false, "explanation": "语义：「月份」是时间概念，不能被破坏，句意不通。"}], "explanations": {"国家安全": "正确。「破坏」的对象是「国家安全」这种抽象的状态，符合句意。", "星期": "语义：「星期」是时间单位，不是可以被破坏的对象。", "眼神": "搭配：「破坏」不与「眼神」搭配，人们不说「破坏眼神」。", "月份": "语义：「月份」是时间概念，不能被破坏，句意不通。"}, "sentence_index": 6, "correct_answer": "国家安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "餐厅后厨的国家安全由专人负责。", "explanation": "这里应该用〈饮食安全〉。「国家安全」指国家层面，后厨的饮食卫生要用〈饮食安全〉。"}, {"text": "他买了保险，保障自己的国家安全。", "explanation": "这里应该用〈财产安全〉。「国家安全」指国家层面，个人的财物安全要用〈财产安全〉。"}, {"text": "这栋楼的国家安全受到威胁，居民们很担心。", "explanation": "这里应该用〈建筑安全〉。「国家安全」指国家政权、主权、领土的状态，说一栋楼是否牢固安全要用〈建筑安全〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事威胁到着国家安全。", "corrected_sentence": "这件事威胁到了国家安全。", "error_description": "错误形式「威胁到着国家安全」；正确形式「威胁到了国家安全」。「到」表示结果，已经实现的结果要用动态助词「了」，「着」表示持续，与句意不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "战争曾经破坏得国家安全。", "corrected_sentence": "战争曾经破坏过国家安全。", "error_description": "错误形式「破坏得国家安全」；正确形式「破坏过国家安全」。表示经历的「过」须紧跟动词，「得」后需要补语，不能直接带宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d301648-2d0a-4643-8afe-abf33b9150a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
