INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90125, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "糖果是甜甜的小零食，放在嘴里会慢慢化。", "primary_collocate": null, "pronunciation": "táng guǒ", "ipa": "tʰɑŋ˧˥ kuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "这颗糖果放在嘴里慢慢化了。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明口袋里有一颗糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖果很甜，小孩都爱吃。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发给每个同学一颗糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从包里拿出一块糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我嘴里含着糖果，不能说话。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看电影时，弟弟想吃糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的糖果是红色的。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶总是在家里放着糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别吃太多糖果，晚上要刷牙。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "块", "label": "量词"}], "register": "口语", "sense_fingerprint": "甜甜的、含在嘴里慢慢化开的小零食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90125, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "糖果", "is_correct": true, "explanation": "糖果：甜甜的、放在嘴里慢慢化开的小零食，正确答案。"}, {"text": "汤锅", "is_correct": false, "explanation": "tāng（第一声）与 táng（第二声）声调不同，guō（第一声）与 guǒ（第三声）声调也不同，意思是汤锅，不是糖果。"}, {"text": "躺过", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，“过”在这里读轻声 guo，与 guǒ（第三声）不同，意思是躺过，不是糖果。"}, {"text": "烫过", "is_correct": false, "explanation": "tàng（第四声）与 táng（第二声）声调不同，“过”在这里读轻声 guo，与 guǒ（第三声）不同，意思是烫过，不是糖果。"}], "explanations": {"糖果": "糖果：甜甜的、放在嘴里慢慢化开的小零食，正确答案。", "汤锅": "tāng（第一声）与 táng（第二声）声调不同，guō（第一声）与 guǒ（第三声）声调也不同，意思是汤锅，不是糖果。", "躺过": "tǎng（第三声）与 táng（第二声）声调不同，“过”在这里读轻声 guo，与 guǒ（第三声）不同，意思是躺过，不是糖果。", "烫过": "tàng（第四声）与 táng（第二声）声调不同，“过”在这里读轻声 guo，与 guǒ（第三声）不同，意思是烫过，不是糖果。"}, "sentence_index": null, "correct_answer": "糖果"}, "level_3": {"options": [{"text": "糖果", "is_correct": true, "explanation": "糖果能在嘴里慢慢化开，符合句子的语境。"}, {"text": "纽扣", "is_correct": false, "explanation": "语义：纽扣不会在嘴里化开，也不是能放进嘴里的东西。"}, {"text": "种子", "is_correct": false, "explanation": "语义：种子不会在嘴里化开，也不是甜的小零食。"}, {"text": "明珠", "is_correct": false, "explanation": "语义：明珠是珠宝，不能含在嘴里慢慢化开，放进这个句子说不通。"}], "explanations": {"糖果": "糖果能在嘴里慢慢化开，符合句子的语境。", "纽扣": "语义：纽扣不会在嘴里化开，也不是能放进嘴里的东西。", "种子": "语义：种子不会在嘴里化开，也不是甜的小零食。", "明珠": "语义：明珠是珠宝，不能含在嘴里慢慢化开，放进这个句子说不通。"}, "sentence_index": 0, "correct_answer": "糖果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈做菜时放了一块糖果。", "explanation": "这里应该用〈糖〉。糖是调味料，可以放进菜里；糖果是小零食，不用来调味。"}, {"text": "我买了一台糖果。", "explanation": "这里量词用错了。「台」用于机器、电器等，糖果应该用「颗」「块」「包」等。"}, {"text": "他戴上了糖果。", "explanation": "这里应该用〈帽子〉。“戴”只用于帽子、眼镜等，糖果不能戴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "糖果", "is_correct": true, "explanation": "糖果符合“想吃”的语境，是可以吃的零食。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不说“吃作业”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是食物，不能吃，句子意思说不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能吃，这里的“想吃”指的是想吃东西。"}], "explanations": {"糖果": "糖果符合“想吃”的语境，是可以吃的零食。", "作业": "搭配：“吃”的对象是食物，不说“吃作业”。", "钥匙": "语义：钥匙不是食物，不能吃，句子意思说不通。", "书": "语义：书不能吃，这里的“想吃”指的是想吃东西。"}, "sentence_index": 6, "correct_answer": "糖果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他早上喝了一杯糖果。", "explanation": "这里应该用〈牛奶〉。糖果是固体零食，不能用“喝”。"}, {"text": "妈妈削了一个糖果。", "explanation": "这里应该用〈苹果〉。“削”用于去皮的水果，糖果不能用“削”。"}, {"text": "他穿上了糖果。", "explanation": "这里应该用〈鞋〉。“穿”用于衣服、鞋子等，糖果不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一次吃了三只糖果。", "corrected_sentence": "他一次吃了三颗糖果。", "error_description": "量词错误：“糖果”应说“三颗糖果”，不能说“三只糖果”。“只”多用于动物，颗粒状的糖果应用“颗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从包里拿出一条糖果给我。", "corrected_sentence": "她从包里拿出一颗糖果给我。", "error_description": "量词错误：“糖果”应说“一颗糖果”，不能说“一条糖果”。“条”用于细长的东西，糖果是小颗粒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
