INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以糖为主要原料制成的食品，如硬糖、软糖等。", "primary_collocate": null, "pronunciation": "táng guǒ", "ipa": "tʰɑŋ˧˥ kuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "商店里卖很多种糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都喜欢吃糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候我们买了糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给朋友一包糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种糖果是用牛奶做的。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把糖果放在桌子上。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖果吃多了牙会不好。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在超市买了两袋糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每天做很多糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日会上有蛋糕和糖果。", "target_word": "糖果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包", "label": "量词"}, {"form": "袋", "label": "量词"}], "register": "中性", "sense_fingerprint": "以糖为主料制成的食品类别，如硬糖、软糖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '507d993d-83f4-4b0f-871f-33290f029136') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "糖果", "is_correct": true, "explanation": "糖果：以糖为主料制成的食品，正确答案。"}, {"text": "汤锅", "is_correct": false, "explanation": "tāng（第一声）与 táng（第二声）声调不同，guō（第一声）与 guǒ（第三声）声调也不同，意思是汤锅，不是糖果。"}, {"text": "躺过", "is_correct": false, "explanation": "tǎng（第三声）与 táng（第二声）声调不同，“过”在这里读轻声 guo，与 guǒ（第三声）不同，意思是躺过，不是糖果。"}, {"text": "烫过", "is_correct": false, "explanation": "tàng（第四声）与 táng（第二声）声调不同，“过”在这里读轻声 guo，与 guǒ（第三声）不同，意思是烫过，不是糖果。"}], "explanations": {"糖果": "糖果：以糖为主料制成的食品，正确答案。", "汤锅": "tāng（第一声）与 táng（第二声）声调不同，guō（第一声）与 guǒ（第三声）声调也不同，意思是汤锅，不是糖果。", "躺过": "tǎng（第三声）与 táng（第二声）声调不同，“过”在这里读轻声 guo，与 guǒ（第三声）不同，意思是躺过，不是糖果。", "烫过": "tàng（第四声）与 táng（第二声）声调不同，“过”在这里读轻声 guo，与 guǒ（第三声）不同，意思是烫过，不是糖果。"}, "sentence_index": null, "correct_answer": "糖果"}, "level_3": {"options": [{"text": "糖果", "is_correct": true, "explanation": "糖果是商店里常见的商品，符合语境。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师是人，不是能在商店里陈列出售的商品。"}, {"text": "道理", "is_correct": false, "explanation": "搭配：“卖”的对象是货物，不说“卖道理”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能在商店里出售。"}], "explanations": {"糖果": "糖果是商店里常见的商品，符合语境。", "老师": "语义：老师是人，不是能在商店里陈列出售的商品。", "道理": "搭配：“卖”的对象是货物，不说“卖道理”。", "月亮": "语义：月亮是天体，不能在商店里出售。"}, "sentence_index": 0, "correct_answer": "糖果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈做汤时放了一勺糖果。", "explanation": "这里应该用〈糖〉。糖是调味料，可以一勺一勺放进汤里；糖果是制成的小零食，不能当调料用。"}, {"text": "我买了一张糖果。", "explanation": "这里量词用错了。「张」用于纸、票等扁平的东西，糖果应该用「颗」「包」「袋」等。"}, {"text": "他每天吃三顿糖果。", "explanation": "这里应该用〈饭〉。「顿」用于正餐，糖果是零食，不能用来计算一日三餐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "糖果", "is_correct": true, "explanation": "糖果吃多了伤牙，符合句子的语境。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能吃，也不是食物，句子意思说不通。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不是食物，不能被“吃”，句子的意思说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是食物，没有甜味，不能拿来吃。"}], "explanations": {"糖果": "糖果吃多了伤牙，符合句子的语境。", "汽油": "语义：汽油不能吃，也不是食物，句子意思说不通。", "玩具": "语义：玩具不是食物，不能被“吃”，句子的意思说不通。", "石头": "语义：石头不是食物，没有甜味，不能拿来吃。"}, "sentence_index": 6, "correct_answer": "糖果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他渴了，喝了一杯糖果。", "explanation": "这里应该用〈水〉。糖果是固体食品，不能用“喝”。"}, {"text": "妈妈洗了一个糖果。", "explanation": "这里应该用〈苹果〉。“洗”用于需要清洗的新鲜水果、蔬菜，糖果是包装好的零食，不用洗。"}, {"text": "他穿上了糖果。", "explanation": "这里应该用〈衣服〉。“穿”只用于衣服、鞋帽等，糖果不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了两只糖果。", "corrected_sentence": "我买了两包糖果。", "error_description": "量词错误：“糖果”应说“两包糖果”，不能说“两只糖果”。“只”多用于动物或单个的物品，糖果应用“包”“袋”“颗”等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吃了一条糖果。", "corrected_sentence": "他吃了一袋糖果。", "error_description": "量词错误：“糖果”应说“一袋糖果”，不能说“一条糖果”。“条”用于细长的东西，如鱼、裤子等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '439b3646-d8a6-48bb-a622-7a87053d8fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
