INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90127, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "故事里说人死后坏人去的、很可怕的地方。", "primary_collocate": null, "pronunciation": "dì yù", "ipa": "ti˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "故事里说，坏人死后会下地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，做坏事的人会去地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的地狱有很多可怕的鬼。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我很怕听地狱的故事。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里，地狱的门口有一只大狗。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的地狱又黑又热。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说坏人死了以后要进地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“地狱真的有吗？”", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给我们讲了地狱的故事。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的坏人最后掉进了地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "十八层地狱", "label": "复合"}, {"form": "地獄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "故事传说中坏人死后去的可怕之地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f596c5e-c3d7-46bf-a6c0-de9768bc6679') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地狱", "is_correct": true, "explanation": "地狱：故事中坏人死后受苦的地方，与句意相符。"}, {"text": "天堂", "is_correct": false, "explanation": "搭配：“下”与“天堂”搭配不当，去天堂应说“上天堂”，且与“坏人”的语境相反。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，与坏人死后受罚的语境不符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是人死后要去的地方，与“故事里说”的死后情境不符。"}], "explanations": {"地狱": "地狱：故事中坏人死后受苦的地方，与句意相符。", "天堂": "搭配：“下”与“天堂”搭配不当，去天堂应说“上天堂”，且与“坏人”的语境相反。", "医院": "语义：医院是治病的地方，与坏人死后受罚的语境不符。", "学校": "语义：学校不是人死后要去的地方，与“故事里说”的死后情境不符。"}, "sentence_index": 0, "correct_answer": "地狱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把旧书都放在地狱里。", "explanation": "这里应该用〈地下室〉。地狱指传说中坏人死后受苦的地方，不表示地下储藏室。"}, {"text": "他们在地狱里躲了一夜。", "explanation": "这里应该用〈山洞〉。地狱指受苦的地方，不表示可以躲藏的洞穴。"}, {"text": "他每天在地狱里游泳。", "explanation": "这里应该用〈游泳池〉。地狱指受苦的地方，不是游泳的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地狱", "is_correct": true, "explanation": "地狱：坏人死后受苦的地方，与句中“坏人死了以后”的说法相符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，人死后不会去教室，与句意不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，与坏人死后的情境不符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“进”后多接具体的处所，“天空”一般说“飞上天空”，不说“进天空”。"}], "explanations": {"地狱": "地狱：坏人死后受苦的地方，与句中“坏人死了以后”的说法相符。", "教室": "语义：教室是上课的地方，人死后不会去教室，与句意不符。", "厨房": "语义：厨房是做饭的地方，与坏人死后的情境不符。", "天空": "搭配：“进”后多接具体的处所，“天空”一般说“飞上天空”，不说“进天空”。"}, "sentence_index": 6, "correct_answer": "地狱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每个星期天都去地狱祭扫。", "explanation": "这里应该用〈墓地〉。地狱是传说中的地方，不是可以去祭扫的地点。"}, {"text": "我在地狱买了一本书。", "explanation": "这里应该用〈书店〉。地狱指受苦的地方，不是买书的场所。"}, {"text": "我昨晚做了一个地狱。", "explanation": "这里应该用〈噩梦〉。地狱是传说中的地方，不是可以“做”的东西，应说“做了一个噩梦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "传说那里是一只可怕的地狱。", "corrected_sentence": "传说那里是一个可怕的地狱。", "error_description": "“地狱”作场所名词，应用量词“个”，不能用“只”（“只”多用于动物或成对物品中的一件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个可怕得地狱在山底下。", "corrected_sentence": "那个可怕的地狱在山底下。", "error_description": "结构助词错误：“可怕”修饰名词“地狱”时要用“的”，不能用“得”（“得”用于动词或形容词后引出补语）。正确的说法是“那个可怕的地狱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90128, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "天堂", "is_correct": true, "explanation": "天堂：与“地狱”互为反义，常说“人间天堂”对“人间地狱”，指极幸福的境地，与“极痛苦的境地”相对。"}, {"text": "森林", "is_correct": false, "explanation": "森林：与“地狱”不构成反义关系，两者语义无关。"}, {"text": "银行", "is_correct": false, "explanation": "银行：与“地狱”不构成反义关系，两者语义无关。"}, {"text": "厨房", "is_correct": false, "explanation": "厨房：与“地狱”不构成反义关系，两者语义无关。"}], "correct_answer": "天堂", "explanations": {"天堂": "天堂：与“地狱”互为反义，常说“人间天堂”对“人间地狱”，指极幸福的境地，与“极痛苦的境地”相对。", "森林": "森林：与“地狱”不构成反义关系，两者语义无关。", "银行": "银行：与“地狱”不构成反义关系，两者语义无关。", "厨房": "厨房：与“地狱”不构成反义关系，两者语义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90128, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "天堂", "is_correct": true, "explanation": "天堂：与“地狱”互为反义，常说“人间天堂”对“人间地狱”，指极幸福的境地，与“极痛苦的境地”相对。"}, {"text": "图书馆", "is_correct": false, "explanation": "图书馆：与“地狱”不构成反义关系，两者语义无关。"}, {"text": "公园", "is_correct": false, "explanation": "公园：与“地狱”不构成反义关系，两者语义无关。"}, {"text": "超市", "is_correct": false, "explanation": "超市：与“地狱”不构成反义关系，两者语义无关。"}], "correct_answer": "天堂", "explanations": {"天堂": "天堂：与“地狱”互为反义，常说“人间天堂”对“人间地狱”，指极幸福的境地，与“极痛苦的境地”相对。", "图书馆": "图书馆：与“地狱”不构成反义关系，两者语义无关。", "公园": "公园：与“地狱”不构成反义关系，两者语义无关。", "超市": "超市：与“地狱”不构成反义关系，两者语义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宗教中人死后受苦的地方；比喻极痛苦的境地。", "primary_collocate": null, "pronunciation": "dì yù", "ipa": "ti˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "很多宗教都说，坏人死后会受苦，那里叫地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他们的宗教里，地狱是受苦的地方。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个城市变成了地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那几年的生活对她来说就是地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前一个月，我们像在地狱里一样。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在那家公司上班，每天都像在地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对孩子来说，没有朋友的学校就是地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大火让这里变成了地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父说，做坏事的人会下地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那段日子太痛苦了，简直是地狱。", "target_word": "地狱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人间地狱", "label": "复合"}, {"form": "十八层地狱", "label": "复合"}, {"form": "地獄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "宗教中死后受苦之地，也比喻极痛苦的处境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f596c5e-c3d7-46bf-a6c0-de9768bc6679') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地狱", "is_correct": true, "explanation": "地狱：宗教中人死后受苦的地方，与句意相符。"}, {"text": "乐园", "is_correct": false, "explanation": "语义：乐园是令人快乐的地方，与“坏人死后会受苦”的说法相反。"}, {"text": "人间", "is_correct": false, "explanation": "语义：人间指人类居住的世界，不是宗教中坏人死后受苦的地方，句意不通。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：“那里叫”后接的应是地方的名称，“幸福”不是地点名称，不能这样称呼。"}], "explanations": {"地狱": "地狱：宗教中人死后受苦的地方，与句意相符。", "乐园": "语义：乐园是令人快乐的地方，与“坏人死后会受苦”的说法相反。", "人间": "语义：人间指人类居住的世界，不是宗教中坏人死后受苦的地方，句意不通。", "幸福": "搭配：“那里叫”后接的应是地方的名称，“幸福”不是地点名称，不能这样称呼。"}, "sentence_index": 0, "correct_answer": "地狱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把土豆存在地狱里了。", "explanation": "这里应该用〈地窖〉。地狱指受苦的地方或极痛苦的境地，不表示用来存放东西的地窖。"}, {"text": "他每天早上都把一个地狱装进书包里。", "explanation": "这里应该用〈课本〉。地狱指受苦的地方或极痛苦的境地，不是可以装进书包的东西。"}, {"text": "我昨晚做了一个地狱。", "explanation": "这里应该用〈噩梦〉。地狱表示极痛苦的境地，不是可以“做”的东西，应说“做了一个噩梦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6263ee22-7c8a-498c-8c83-ccf0e8fce560') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
